        DESCRICAO          NVARCHAR(400)  NOT NULL CONSTRAINT DF_Grupo_Email_DESCRICAO       DEFAULT (N''),
        ATIVO              BIT            NOT NULL CONSTRAINT DF_Grupo_Email_ATIVO           DEFAULT (1),
