        USUARIO_CRIACAO    NVARCHAR(100)  NOT NULL CONSTRAINT DF_Grupo_Email_USUARIO_CRIACAO DEFAULT (ISNULL(CONVERT(NVARCHAR(100), SESSION_CONTEXT(N'USUARIO')), SUSER_SNAME())),
        DT_ALTERACAO       DATETIME2(0)   NULL,
