IF COL_LENGTH(N'CAD.Empresa', N'RODAPE_EMAIL') IS NULL
    ALTER TABLE [CAD].[Empresa] ADD RODAPE_EMAIL NVARCHAR(1000) NOT NULL CONSTRAINT DF_Empresa_RODAPE_EMAIL DEFAULT (N'');
GO
