    ALTER TABLE [CAD].[Empresa] ADD CONSTRAINT FK_Empresa_Conta_Padrao
        FOREIGN KEY (ID_CONTA_BANCARIA_PADRAO) REFERENCES [BANCO].[Conta] (ID_CONTA);
