    (
        ID_HISTORICO_PADRAO  INT            IDENTITY(1,1) NOT NULL,
        DESCRICAO            NVARCHAR(80)   NOT NULL,
        ATIVO                BIT            NOT NULL CONSTRAINT DF_Historico_Padrao_ATIVO DEFAULT (1),
        CODIGO_ACCESS        INT            NULL,
