        DT_ALTERACAO       DATETIME2(0)   NULL,
        USUARIO_ALTERACAO  NVARCHAR(100)  NULL,
        CONSTRAINT PK_Comunicado_Item            PRIMARY KEY CLUSTERED (ID_COMUNICADO_ITEM),
        CONSTRAINT FK_Comunicado_Item_Comunicado FOREIGN KEY (ID_COMUNICADO) REFERENCES [SIS].[Comunicado] (ID_COMUNICADO),
        CONSTRAINT CK_Comunicado_Item_SECAO      CHECK (SECAO IN ('IMPLANTADO', 'EM_TESTE', 'PROXIMA_FASE')),
        CONSTRAINT CK_Comunicado_Item_TEXTO      CHECK (TEXTO <> N'')
    );
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Comunicado_Edicao.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Comunicado_Edicao]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : Cada edição semanal do comunicado: período (segunda a sexta),
                assunto e HTML montados na prévia. O e-mail oficial leva
                exatamente o que foi aprovado. SITUACAO: PREVIA (aguardando
                aprovação) -> ENVIADA, ou DESCARTADA (substituída por prévia nova ou
                descartada na tela). Uma edição ENVIADA por comunicado e semana.

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c, boletim semanal da implantação).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[SIS].[Comunicado_Edicao]', N'U') IS NULL
BEGIN
    CREATE TABLE [SIS].[Comunicado_Edicao]
    (
        ID_COMUNICADO_EDICAO  BIGINT         IDENTITY(1,1) NOT NULL,
        ID_COMUNICADO         INT            NOT NULL,
        DT_INICIO             DATE           NOT NULL,
        DT_FIM                DATE           NOT NULL,
        ASSUNTO               NVARCHAR(400)  NOT NULL,
        CORPO_HTML            NVARCHAR(MAX)  NOT NULL,
        SITUACAO              VARCHAR(10)    NOT NULL CONSTRAINT DF_Comunicado_Edicao_SITUACAO DEFAULT ('PREVIA'),
        ID_EMAIL_PREVIA       BIGINT         NULL,
        ID_EMAIL_OFICIAL      BIGINT         NULL,
        DT_APROVACAO          DATETIME2(0)   NULL,
        USUARIO_APROVACAO     NVARCHAR(100)  NOT NULL CONSTRAINT DF_Comunicado_Edicao_USUARIO_APROVACAO DEFAULT (N''),
        DT_CRIACAO         DATETIME2(0)   NOT NULL CONSTRAINT DF_Comunicado_Edicao_DT_CRIACAO      DEFAULT (SYSDATETIME()),
        USUARIO_CRIACAO    NVARCHAR(100)  NOT NULL CONSTRAINT DF_Comunicado_Edicao_USUARIO_CRIACAO DEFAULT (ISNULL(CONVERT(NVARCHAR(100), SESSION_CONTEXT(N'USUARIO')), SUSER_SNAME())),
        DT_ALTERACAO       DATETIME2(0)   NULL,
        USUARIO_ALTERACAO  NVARCHAR(100)  NULL,
        CONSTRAINT PK_Comunicado_Edicao            PRIMARY KEY CLUSTERED (ID_COMUNICADO_EDICAO),
        CONSTRAINT FK_Comunicado_Edicao_Comunicado FOREIGN KEY (ID_COMUNICADO) REFERENCES [SIS].[Comunicado] (ID_COMUNICADO),
        CONSTRAINT CK_Comunicado_Edicao_SITUACAO   CHECK (SITUACAO IN ('PREVIA', 'ENVIADA', 'DESCARTADA')),
        CONSTRAINT CK_Comunicado_Edicao_PERIODO    CHECK (DT_FIM >= DT_INICIO)
    );
    CREATE UNIQUE INDEX UQ_Comunicado_Edicao_ENVIADA ON [SIS].[Comunicado_Edicao] (ID_COMUNICADO, DT_INICIO) WHERE SITUACAO = 'ENVIADA';
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Versao_Banco.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Versao_Banco]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Histórico das instalações do banco: cada vez que o MASTER (ou o
                pacote do desenvolvimento) roda, grava a versão instalada, quando
                e por quem. A versão atual é a do registro mais recente
                (SIS.fn_SIS_Versao_Banco). A API confere essa versão ao subir:
                programa e banco têm de estar na mesma versão (CLAUDE.md seção 7,
                fase 3d). Nunca é apagado.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[SIS].[Versao_Banco]', N'U') IS NULL
    CREATE TABLE [SIS].[Versao_Banco]
    (
        ID_VERSAO_BANCO  INT            IDENTITY(1,1) NOT NULL,
        VERSAO           VARCHAR(20)    NOT NULL,
        ORIGEM           VARCHAR(20)    NOT NULL,
        DT_INSTALACAO    DATETIME2(0)   NOT NULL CONSTRAINT DF_Versao_Banco_DT_INSTALACAO DEFAULT (SYSDATETIME()),
        USUARIO          NVARCHAR(128)  NOT NULL CONSTRAINT DF_Versao_Banco_USUARIO       DEFAULT (SUSER_SNAME()),
        ESTACAO          NVARCHAR(128)  NOT NULL CONSTRAINT DF_Versao_Banco_ESTACAO       DEFAULT (ISNULL(HOST_NAME(), N'')),
        CONSTRAINT PK_Versao_Banco        PRIMARY KEY CLUSTERED (ID_VERSAO_BANCO),
        CONSTRAINT CK_Versao_Banco_ORIGEM CHECK (ORIGEM IN ('MASTER', 'PACOTE_LOCAL'))
    );
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Backup_Execucao.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Backup_Execucao]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Registro de cada backup feito pelo script do servidor
                (instalacao\backup_servidor.ps1, tarefas agendadas do Windows):
                COMPLETO (diário), LOG (de hora em hora), TESTE (restauração de
                conferência, semanal) e SEGURANCA (feito logo antes de uma
                restauração pedida pela tela). Serve para a tela de backups e
                restauração, para os avisos de atraso/falha
                (SIS_Backup_Conferir_Processar) e para a auditoria.
                Os arquivos ficam no disco (parâmetro BACKUP_PASTA); aqui só a
                referência. Nunca é apagado (o arquivo pode ser, pela retenção:
                ARQUIVO_EXISTE = 0).

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d, backup no servidor). Nome com sufixo:
                        BACKUP é palavra reservada do SQL Server.
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

-- Nome antigo (BACKUP é palavra reservada do SQL): apaga se ficou vazio de um ensaio de 20/11/2026
IF OBJECT_ID(N'[SIS].[Backup]', N'U') IS NOT NULL
BEGIN
    IF NOT EXISTS (SELECT 1 FROM [SIS].[Backup])
        DROP TABLE [SIS].[Backup];
END;
GO

IF OBJECT_ID(N'[SIS].[Backup_Execucao]', N'U') IS NULL
    CREATE TABLE [SIS].[Backup_Execucao]
    (
        ID_BACKUP        BIGINT          IDENTITY(1,1) NOT NULL,
        TIPO             VARCHAR(10)     NOT NULL,
        ARQUIVO          NVARCHAR(400)   NOT NULL CONSTRAINT DF_Backup_Execucao_ARQUIVO        DEFAULT (N''),
        DT_INICIO        DATETIME2(0)    NOT NULL,
        DT_FIM           DATETIME2(0)    NULL,
        TAMANHO_MB       DECIMAL(12,1)   NOT NULL CONSTRAINT DF_Backup_Execucao_TAMANHO_MB     DEFAULT (0),
        SITUACAO         VARCHAR(10)     NOT NULL,
        MENSAGEM         NVARCHAR(2000)  NOT NULL CONSTRAINT DF_Backup_Execucao_MENSAGEM       DEFAULT (N''),
        COPIA_NUVEM      BIT             NOT NULL CONSTRAINT DF_Backup_Execucao_COPIA_NUVEM    DEFAULT (0),
        ARQUIVO_EXISTE   BIT             NOT NULL CONSTRAINT DF_Backup_Execucao_ARQUIVO_EXISTE DEFAULT (1),
        SERVIDOR         NVARCHAR(128)   NOT NULL CONSTRAINT DF_Backup_Execucao_SERVIDOR       DEFAULT (ISNULL(HOST_NAME(), N'')),
        DT_REGISTRO      DATETIME2(0)    NOT NULL CONSTRAINT DF_Backup_Execucao_DT_REGISTRO    DEFAULT (SYSDATETIME()),
        CONSTRAINT PK_Backup_Execucao          PRIMARY KEY CLUSTERED (ID_BACKUP),
        CONSTRAINT CK_Backup_Execucao_TIPO     CHECK (TIPO IN ('COMPLETO', 'LOG', 'TESTE', 'SEGURANCA')),
        CONSTRAINT CK_Backup_Execucao_SITUACAO CHECK (SITUACAO IN ('OK', 'ERRO'))
    );
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes i WHERE i.object_id = OBJECT_ID(N'[SIS].[Backup_Execucao]') AND i.name = N'IX_Backup_Execucao_TIPO_DT')
    CREATE NONCLUSTERED INDEX IX_Backup_Execucao_TIPO_DT ON [SIS].[Backup_Execucao] (TIPO, SITUACAO, DT_INICIO);
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Backup_Restauracao.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Backup_Restauracao]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Pedidos de restauração do banco feitos pela tela Sistema >
                Backups (SIS_BACKUP, ação RESTAURAR). A tela só registra o
                pedido (PENDENTE); quem restaura é a tarefa do Windows
                "Restauração (pedidos)" (instalacao\backup_servidor.ps1, como
                SYSTEM), que captura o pedido (EXECUTANDO), faz o backup de
                segurança, restaura e grava o resultado (OK ou ERRO).
                Como a restauração volta esta tabela ao passado, o script
                regrava o pedido no banco restaurado com o mesmo ID
                (SIS_Backup_Restauracao_Resultado, IDENTITY_INSERT).
                TIPO_PONTO: BACKUP (volta para um backup completo ou de
                segurança, ID_BACKUP) ou DATA_HORA (volta para um dia e hora,
                DT_PONTO, com os backups do log de hora em hora).
                Nunca é apagado.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d2, restauração pela tela).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[SIS].[Backup_Restauracao]', N'U') IS NULL
    CREATE TABLE [SIS].[Backup_Restauracao]
    (
        ID_RESTAURACAO       INT             IDENTITY(1,1) NOT NULL,
        TIPO_PONTO           VARCHAR(10)     NOT NULL,
        ID_BACKUP            BIGINT          NULL,
        DT_PONTO             DATETIME2(0)    NULL,
        MOTIVO               NVARCHAR(400)   NOT NULL,
        SITUACAO             VARCHAR(12)     NOT NULL CONSTRAINT DF_Backup_Restauracao_SITUACAO  DEFAULT ('PENDENTE'),
        ID_USUARIO_PEDIDO    INT             NOT NULL,
        USUARIO_PEDIDO       NVARCHAR(100)   NOT NULL CONSTRAINT DF_Backup_Restauracao_USUARIO_PEDIDO DEFAULT (N''),
        DT_PEDIDO            DATETIME2(0)    NOT NULL CONSTRAINT DF_Backup_Restauracao_DT_PEDIDO DEFAULT (SYSDATETIME()),
        DT_INICIO            DATETIME2(0)    NULL,
        DT_FIM               DATETIME2(0)    NULL,
        PLANO                NVARCHAR(4000)  NOT NULL CONSTRAINT DF_Backup_Restauracao_PLANO     DEFAULT (N''),
        ARQUIVO_SEGURANCA    NVARCHAR(400)   NOT NULL CONSTRAINT DF_Backup_Restauracao_ARQUIVO_SEGURANCA DEFAULT (N''),
        MENSAGEM             NVARCHAR(2000)  NOT NULL CONSTRAINT DF_Backup_Restauracao_MENSAGEM  DEFAULT (N''),
        SERVIDOR             NVARCHAR(128)   NOT NULL CONSTRAINT DF_Backup_Restauracao_SERVIDOR  DEFAULT (ISNULL(HOST_NAME(), N'')),
        DT_CRIACAO           DATETIME2(0)    NOT NULL CONSTRAINT DF_Backup_Restauracao_DT_CRIACAO DEFAULT (SYSDATETIME()),
        USUARIO_CRIACAO      NVARCHAR(100)   NOT NULL CONSTRAINT DF_Backup_Restauracao_USUARIO_CRIACAO DEFAULT (ISNULL(CONVERT(NVARCHAR(100), SESSION_CONTEXT(N'USUARIO')), SUSER_SNAME())),
        DT_ALTERACAO         DATETIME2(0)    NULL,
        USUARIO_ALTERACAO    NVARCHAR(100)   NULL,
        CONSTRAINT PK_Backup_Restauracao            PRIMARY KEY CLUSTERED (ID_RESTAURACAO),
        CONSTRAINT FK_Backup_Restauracao_Backup     FOREIGN KEY (ID_BACKUP) REFERENCES [SIS].[Backup_Execucao] (ID_BACKUP),
        CONSTRAINT CK_Backup_Restauracao_TIPO_PONTO CHECK (TIPO_PONTO IN ('BACKUP', 'DATA_HORA')),
        CONSTRAINT CK_Backup_Restauracao_PONTO      CHECK ((TIPO_PONTO = 'BACKUP' AND ID_BACKUP IS NOT NULL) OR (TIPO_PONTO = 'DATA_HORA' AND DT_PONTO IS NOT NULL)),
        CONSTRAINT CK_Backup_Restauracao_SITUACAO   CHECK (SITUACAO IN ('PENDENTE', 'EXECUTANDO', 'OK', 'ERRO', 'CANCELADO'))
    );
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes i WHERE i.object_id = OBJECT_ID(N'[SIS].[Backup_Restauracao]') AND i.name = N'IX_Backup_Restauracao_SITUACAO')
    CREATE NONCLUSTERED INDEX IX_Backup_Restauracao_SITUACAO ON [SIS].[Backup_Restauracao] (SITUACAO, DT_PEDIDO);
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Atualizacao.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Atualizacao]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Histórico das atualizações de versão feitas pelo atualizar.cmd do
                pacote (atualização em um clique, conversa 03h): versões de/para
                do programa e do banco, quando, quanto tempo o sistema ficou fora,
                resultado (CONCLUIDA, DESFEITA = deu erro e voltou sozinho,
                ERRO = deu erro e não conseguiu voltar) e a nota da versão
                (NOTAS_DA_VERSAO.txt do pacote: o que foi corrigido e o que é
                novo). Base da futura tela Sistema › Versões (pedido P22).
                Gravado só por SIS.SIS_Atualizacao_Registrar. Nunca é apagado.

  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 03h, banco 1.8).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[SIS].[Atualizacao]', N'U') IS NULL
    CREATE TABLE [SIS].[Atualizacao]
    (
        ID_ATUALIZACAO        INT             IDENTITY(1,1) NOT NULL,
        VERSAO_PROGRAMA_DE    VARCHAR(20)     NOT NULL CONSTRAINT DF_Atualizacao_VERSAO_PROGRAMA_DE DEFAULT (''),
        VERSAO_PROGRAMA_PARA  VARCHAR(20)     NOT NULL,
        VERSAO_BANCO_DE       VARCHAR(20)     NOT NULL CONSTRAINT DF_Atualizacao_VERSAO_BANCO_DE    DEFAULT (''),
        VERSAO_BANCO_PARA     VARCHAR(20)     NOT NULL,
        DT_INICIO             DATETIME2(0)    NOT NULL,
        DT_FIM                DATETIME2(0)    NOT NULL,
        SEGUNDOS_FORA         INT             NOT NULL CONSTRAINT DF_Atualizacao_SEGUNDOS_FORA      DEFAULT (0),
        SITUACAO              VARCHAR(10)     NOT NULL,
        MENSAGEM              NVARCHAR(2000)  NOT NULL CONSTRAINT DF_Atualizacao_MENSAGEM           DEFAULT (N''),
        NOTAS                 NVARCHAR(MAX)   NOT NULL CONSTRAINT DF_Atualizacao_NOTAS              DEFAULT (N''),
        PACOTE                NVARCHAR(260)   NOT NULL CONSTRAINT DF_Atualizacao_PACOTE             DEFAULT (N''),
        USUARIO               NVARCHAR(128)   NOT NULL CONSTRAINT DF_Atualizacao_USUARIO            DEFAULT (SUSER_SNAME()),
        ESTACAO               NVARCHAR(128)   NOT NULL CONSTRAINT DF_Atualizacao_ESTACAO            DEFAULT (ISNULL(HOST_NAME(), N'')),
        DT_REGISTRO           DATETIME2(0)    NOT NULL CONSTRAINT DF_Atualizacao_DT_REGISTRO        DEFAULT (SYSDATETIME()),
        CONSTRAINT PK_Atualizacao          PRIMARY KEY CLUSTERED (ID_ATUALIZACAO),
        CONSTRAINT CK_Atualizacao_SITUACAO CHECK (SITUACAO IN ('CONCLUIDA', 'DESFEITA', 'ERRO'))
    );
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Tabela_Config.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Tabela_Config]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Configuração, por tabela, do desfazer pelo histórico e da
                lixeira (P20, docs/requisitos/Lixeira_Desfazer.md). Nada fixo
                no código: cada tabela diz o que pode e o que não pode.
                  PERMITE_DESFAZER   voltar campos pelo histórico
                  PERMITE_LIXEIRA    botão Excluir manda para a lixeira (a
                                     tabela precisa ter ATIVO, DT_EXCLUSAO e
                                     USUARIO_EXCLUSAO)
                  DIAS_GUARDA        prazo próprio da lixeira (NULL = vale o
                                     parâmetro LIXEIRA_DIAS_GUARDA); única
                                     coluna que a CMJ muda (tela da Lixeira)
                  CAMPOS_BLOQUEADOS  campos que nunca são desfeitos (saldos,
                                     calculados, senha), separados por vírgula
                  CAMPOS_UNICOS      conferidos na recuperação contra os
                                     registros vivos (ex.: CPF_CNPJ)
                  TABELAS_FILHAS     registros que "vão junto":
                                     SCHEMA.Tabela.COLUNA_FK, separados por
                                     vírgula (voltar a uma data e apagar de vez)
                  DESFAZER_INCLUSAO  o que fazer ao desfazer uma inclusão:
                                     LIXEIRA, DESATIVAR (ATIVO = 0), APAGAR
                                     (só tabelas de ligação, ex.: permissões)
                                     ou RECUSAR
                  DESFAZER_EXCLUSAO  o que fazer ao desfazer uma exclusão
                                     definitiva: REINSERIR (só tabelas de
                                     ligação: volta com a foto da auditoria,
                                     com ID novo) ou RECUSAR
                  DESCRICAO_SQL      expressão com as colunas da tabela que
                                     descreve o registro na lixeira e na prévia
                                     (só pela carga da instalação, nunca pela
                                     tela)
                  COLUNA_EMPRESA +
                  COLUNA_DATA_MES    trava de mês fechado (FIN.Mes_Fechado)
                  PROC_VALIDAR       procedure própria de trava (ex.: boleto no
                                     banco, P16): recebe @Tabela, @IdRegistro,
                                     @Operacao e devolve @Mensagem OUTPUT
                                     (vazia = pode)
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b, P20).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[SIS].[Tabela_Config]', N'U') IS NULL
BEGIN
    CREATE TABLE [SIS].[Tabela_Config]
    (
        ID_TABELA_CONFIG   INT            IDENTITY(1,1) NOT NULL,
        TABELA             NVARCHAR(256)  NOT NULL,
        PERMITE_DESFAZER   BIT            NOT NULL CONSTRAINT DF_Tabela_Config_PERMITE_DESFAZER  DEFAULT (1),
        PERMITE_LIXEIRA    BIT            NOT NULL CONSTRAINT DF_Tabela_Config_PERMITE_LIXEIRA   DEFAULT (0),
        DIAS_GUARDA        INT            NULL,
        CAMPOS_BLOQUEADOS  NVARCHAR(1000) NOT NULL CONSTRAINT DF_Tabela_Config_CAMPOS_BLOQUEADOS DEFAULT (N''),
        CAMPOS_UNICOS      NVARCHAR(400)  NOT NULL CONSTRAINT DF_Tabela_Config_CAMPOS_UNICOS     DEFAULT (N''),
        TABELAS_FILHAS     NVARCHAR(1000) NOT NULL CONSTRAINT DF_Tabela_Config_TABELAS_FILHAS    DEFAULT (N''),
        DESFAZER_INCLUSAO  VARCHAR(10)    NOT NULL CONSTRAINT DF_Tabela_Config_DESFAZER_INCLUSAO DEFAULT ('RECUSAR'),
        DESFAZER_EXCLUSAO  VARCHAR(10)    NOT NULL CONSTRAINT DF_Tabela_Config_DESFAZER_EXCLUSAO DEFAULT ('RECUSAR'),
        DESCRICAO_SQL      NVARCHAR(1000) NOT NULL CONSTRAINT DF_Tabela_Config_DESCRICAO_SQL     DEFAULT (N''),
        COLUNA_EMPRESA     NVARCHAR(128)  NOT NULL CONSTRAINT DF_Tabela_Config_COLUNA_EMPRESA    DEFAULT (N''),
        COLUNA_DATA_MES    NVARCHAR(128)  NOT NULL CONSTRAINT DF_Tabela_Config_COLUNA_DATA_MES   DEFAULT (N''),
        PROC_VALIDAR       NVARCHAR(256)  NOT NULL CONSTRAINT DF_Tabela_Config_PROC_VALIDAR      DEFAULT (N''),
        ATIVO              BIT            NOT NULL CONSTRAINT DF_Tabela_Config_ATIVO             DEFAULT (1),
        DT_CRIACAO         DATETIME2(0)   NOT NULL CONSTRAINT DF_Tabela_Config_DT_CRIACAO        DEFAULT (SYSDATETIME()),
        USUARIO_CRIACAO    NVARCHAR(100)  NOT NULL CONSTRAINT DF_Tabela_Config_USUARIO_CRIACAO   DEFAULT (ISNULL(CONVERT(NVARCHAR(100), SESSION_CONTEXT(N'USUARIO')), SUSER_SNAME())),
        DT_ALTERACAO       DATETIME2(0)   NULL,
        USUARIO_ALTERACAO  NVARCHAR(100)  NULL,
        CONSTRAINT PK_Tabela_Config                   PRIMARY KEY CLUSTERED (ID_TABELA_CONFIG),
        CONSTRAINT UQ_Tabela_Config_TABELA            UNIQUE (TABELA),
        CONSTRAINT CK_Tabela_Config_DESFAZER_INCLUSAO CHECK (DESFAZER_INCLUSAO IN ('LIXEIRA', 'DESATIVAR', 'APAGAR', 'RECUSAR')),
        CONSTRAINT CK_Tabela_Config_DESFAZER_EXCLUSAO CHECK (DESFAZER_EXCLUSAO IN ('REINSERIR', 'RECUSAR')),
        CONSTRAINT CK_Tabela_Config_DIAS_GUARDA       CHECK (DIAS_GUARDA IS NULL OR DIAS_GUARDA BETWEEN 1 AND 3650)
    );
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Lixeira.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Lixeira]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Registros mandados para a lixeira pelo botão Excluir das telas
                (P20). O registro continua na tabela dele, desativado e com
                DT_EXCLUSAO preenchida; esta tabela guarda de onde veio (tela),
                quem excluiu, o motivo, como estava o ATIVO antes e até quando
                fica guardado (DT_APAGAR).
                SITUACAO: LIXEIRA (pode recuperar), RECUPERADO (voltou) ou
                APAGADO (apagado de vez pela rotina diária ou pelo botão
                Esvaziar agora; a cópia completa fica em SIS.Auditoria).
                DT_AVISO: quando saiu o e-mail avisando que vai ser apagado.
                Nunca é apagada: é o histórico da lixeira.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b, P20).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[SIS].[Lixeira]', N'U') IS NULL
BEGIN
    CREATE TABLE [SIS].[Lixeira]
    (
        ID_LIXEIRA           BIGINT         IDENTITY(1,1) NOT NULL,
        TABELA               NVARCHAR(256)  NOT NULL,
        ID_REGISTRO          BIGINT         NOT NULL,
        ITEM_CODIGO          VARCHAR(40)    NOT NULL,
        DESCRICAO            NVARCHAR(400)  NOT NULL CONSTRAINT DF_Lixeira_DESCRICAO       DEFAULT (N''),
        MOTIVO               NVARCHAR(400)  NOT NULL CONSTRAINT DF_Lixeira_MOTIVO          DEFAULT (N''),
        ATIVO_ANTES          BIT            NOT NULL CONSTRAINT DF_Lixeira_ATIVO_ANTES     DEFAULT (1),
        DT_EXCLUSAO          DATETIME2(0)   NOT NULL CONSTRAINT DF_Lixeira_DT_EXCLUSAO     DEFAULT (SYSDATETIME()),
        USUARIO_EXCLUSAO     NVARCHAR(100)  NOT NULL CONSTRAINT DF_Lixeira_USUARIO_EXCLUSAO DEFAULT (N''),
        ID_USUARIO_EXCLUSAO  INT            NULL,
        DT_APAGAR            DATE           NOT NULL,
        SITUACAO             VARCHAR(12)    NOT NULL CONSTRAINT DF_Lixeira_SITUACAO        DEFAULT ('LIXEIRA'),
        DT_SITUACAO          DATETIME2(0)   NULL,
        USUARIO_SITUACAO     NVARCHAR(100)  NOT NULL CONSTRAINT DF_Lixeira_USUARIO_SITUACAO DEFAULT (N''),
        MOTIVO_SITUACAO      NVARCHAR(400)  NOT NULL CONSTRAINT DF_Lixeira_MOTIVO_SITUACAO DEFAULT (N''),
        DT_AVISO             DATETIME2(0)   NULL,
        DT_CRIACAO           DATETIME2(0)   NOT NULL CONSTRAINT DF_Lixeira_DT_CRIACAO      DEFAULT (SYSDATETIME()),
        USUARIO_CRIACAO      NVARCHAR(100)  NOT NULL CONSTRAINT DF_Lixeira_USUARIO_CRIACAO DEFAULT (ISNULL(CONVERT(NVARCHAR(100), SESSION_CONTEXT(N'USUARIO')), SUSER_SNAME())),
        DT_ALTERACAO         DATETIME2(0)   NULL,
        USUARIO_ALTERACAO    NVARCHAR(100)  NULL,
        CONSTRAINT PK_Lixeira          PRIMARY KEY CLUSTERED (ID_LIXEIRA),
        CONSTRAINT CK_Lixeira_SITUACAO CHECK (SITUACAO IN ('LIXEIRA', 'RECUPERADO', 'APAGADO'))
    );
END;
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes i WHERE i.object_id = OBJECT_ID(N'[SIS].[Lixeira]') AND i.name = N'UQ_Lixeira_TABELA_REGISTRO')
    CREATE UNIQUE NONCLUSTERED INDEX UQ_Lixeira_TABELA_REGISTRO ON [SIS].[Lixeira] (TABELA, ID_REGISTRO) WHERE SITUACAO = 'LIXEIRA';
GO
IF NOT EXISTS (SELECT 1 FROM sys.indexes i WHERE i.object_id = OBJECT_ID(N'[SIS].[Lixeira]') AND i.name = N'IX_Lixeira_SITUACAO_DT_APAGAR')
    CREATE NONCLUSTERED INDEX IX_Lixeira_SITUACAO_DT_APAGAR ON [SIS].[Lixeira] (SITUACAO, DT_APAGAR) INCLUDE (TABELA, ID_REGISTRO, ITEM_CODIGO);
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Desfazer.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Desfazer]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Registro de cada desfazer feito pelo histórico (P20): o que foi
                pedido, por quem, com que motivo (obrigatório) e o que mudou.
                TIPO: REGISTRO (voltar um registro, com os filhos que vão
                junto, para como estava depois de uma operação ou numa
                data/hora), OPERACAO (desfazer uma operação = uma transação) ou
                LOTE (desfazer tudo o que um lote fez).
                TRANSACAO: a transação do próprio desfazer, que liga este
                registro às linhas novas da SIS.Auditoria.
                Nunca é alterada nem apagada.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b, P20).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[SIS].[Desfazer]', N'U') IS NULL
BEGIN
    CREATE TABLE [SIS].[Desfazer]
    (
        ID_DESFAZER     BIGINT         IDENTITY(1,1) NOT NULL,
        TIPO            VARCHAR(10)    NOT NULL,
        ITEM_CODIGO     VARCHAR(40)    NOT NULL CONSTRAINT DF_Desfazer_ITEM_CODIGO   DEFAULT (''),
        TABELA          NVARCHAR(256)  NOT NULL CONSTRAINT DF_Desfazer_TABELA        DEFAULT (N''),
        ID_REGISTRO     BIGINT         NULL,
        ID_AUDITORIA    BIGINT         NULL,
        DT_ALVO         DATETIME2(0)   NULL,
        TRANSACAO_ALVO  BIGINT         NULL,
        ID_LOTE_ALVO    BIGINT         NULL,
        MOTIVO          NVARCHAR(400)  NOT NULL,
        QTD_REGISTROS   INT            NOT NULL CONSTRAINT DF_Desfazer_QTD_REGISTROS DEFAULT (0),
        QTD_CAMPOS      INT            NOT NULL CONSTRAINT DF_Desfazer_QTD_CAMPOS    DEFAULT (0),
        QTD_LIXEIRA     INT            NOT NULL CONSTRAINT DF_Desfazer_QTD_LIXEIRA   DEFAULT (0),
        TRANSACAO       BIGINT         NULL,
        ID_USUARIO      INT            NULL,
        USUARIO         NVARCHAR(100)  NOT NULL CONSTRAINT DF_Desfazer_USUARIO       DEFAULT (N''),
        DT_CRIACAO      DATETIME2(0)   NOT NULL CONSTRAINT DF_Desfazer_DT_CRIACAO    DEFAULT (SYSDATETIME()),
        CONSTRAINT PK_Desfazer      PRIMARY KEY CLUSTERED (ID_DESFAZER),
        CONSTRAINT CK_Desfazer_TIPO CHECK (TIPO IN ('REGISTRO', 'OPERACAO', 'LOTE'))
    );
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.Versao_Nota.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[Versao_Nota]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 23/11/2026
  Descrição   : Notas de cada versão do sistema, um item por linha (o que é
                novo, o que melhorou, o que foi corrigido), para a tela
                Sistema › Versões, o aviso "O que há de novo" e o e-mail da
                nota depois de cada atualização (pedido P22).
                Fonte única: docs/NOTAS_DA_VERSAO.md, convertido em
                Carga_SIS_Versao_Nota.sql por sql/ferramentas/montar_notas.py
                e carregado pelo MASTER (toda instalação já nasce com o
                histórico completo das notas). Não tem tela de manutenção.
                PUBLICO: TODOS ou GERAL (só o administrador geral vê).
                TEXTO = texto puro (busca); TEXTO_HTML = com <b> e <code>,
                gerado pelo montar_notas.py (já escapado).
  Changelog:
    v1.0 (23/11/2026) - Criação (etapa 04c, P22).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

IF OBJECT_ID(N'[SIS].[Versao_Nota]', N'U') IS NULL
    CREATE TABLE [SIS].[Versao_Nota]
    (
        ID_VERSAO_NOTA  INT             IDENTITY(1,1) NOT NULL,
        VERSAO          VARCHAR(20)     NOT NULL,
        VERSAO_NUMERO   INT             NOT NULL,
        DT_VERSAO       DATE            NULL,
        ORDEM           SMALLINT        NOT NULL,
        TIPO            VARCHAR(10)     NOT NULL,
        PUBLICO         VARCHAR(10)     NOT NULL CONSTRAINT DF_Versao_Nota_PUBLICO    DEFAULT ('TODOS'),
        TEXTO           NVARCHAR(2000)  NOT NULL,
        TEXTO_HTML      NVARCHAR(4000)  NOT NULL,
        DT_CRIACAO      DATETIME2(0)    NOT NULL CONSTRAINT DF_Versao_Nota_DT_CRIACAO DEFAULT (SYSDATETIME()),
        CONSTRAINT PK_Versao_Nota               PRIMARY KEY CLUSTERED (ID_VERSAO_NOTA),
        CONSTRAINT UQ_Versao_Nota_VERSAO_ORDEM  UNIQUE (VERSAO, ORDEM),
        CONSTRAINT CK_Versao_Nota_TIPO          CHECK (TIPO IN ('NOVO', 'MELHORIA', 'CORRECAO')),
        CONSTRAINT CK_Versao_Nota_PUBLICO       CHECK (PUBLICO IN ('TODOS', 'GERAL'))
    );
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_Versao_Nota_VERSAO_NUMERO' AND object_id = OBJECT_ID(N'[SIS].[Versao_Nota]'))
    CREATE NONCLUSTERED INDEX IX_Versao_Nota_VERSAO_NUMERO ON [SIS].[Versao_Nota] (VERSAO_NUMERO DESC, ORDEM);
GO
GO

