  Homologação:
    -- SELECT SIS.fn_SIS_Formatar_Data('2026-12-10');   -- 10/12/2026
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER FUNCTION [SIS].[fn_SIS_Formatar_Data] (@Data DATE)
RETURNS NVARCHAR(10)
AS
BEGIN
    IF @Data IS NULL RETURN N'';
