-- Arquivo: sql/objetos/CAD/CAD.CAD_Plano_Conta_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [CAD].[CAD_Plano_Conta_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 16/11/2026
  Descrição   : Inclui (@IdPlanoConta NULL) ou altera uma conta (nível 3, a que recebe
                lançamento), sempre dentro de um subgrupo. @Numero NULL = próximo livre
                no subgrupo. Número (1 a 999) e descrição não repetem dentro do
                subgrupo. CONTABIL e CONTA_CONTABIL_REF: pedido 10 / contabilidade.
                Permissão: INCLUIR ou ALTERAR em CAD_PLANO_CONTA. Devolve SUCESSO, MENSAGEM, ID.

  Changelog:
    v1.0 (16/11/2026) - Criação (etapa 03a).
    v1.1 (22/11/2026) - Etapa 04b (P20): recusa alterar registro que está na lixeira e escolher registro ligado que está na lixeira.
    v1.2 (25/11/2026) - Etapa 04e: conta com lançamentos não muda de subgrupo
                        (mudaria o grupo e o tipo dos lançamentos já feitos).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [CAD].[CAD_Plano_Conta_Gravar]
    @IdUsuario     INT,
    @IdPlanoConta      INT          = NULL,
    @IdPlanoSubgrupo   INT,
    @Numero            SMALLINT     = NULL,
    @Descricao         NVARCHAR(80),
    @Contabil          BIT          = 0,
    @ContaContabilRef  VARCHAR(30)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[CAD].[CAD_Plano_Conta_Gravar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Usuario    NVARCHAR(100);

    BEGIN TRY
        SET @Descricao = LTRIM(RTRIM(ISNULL(@Descricao, N'')));
        SET @Contabil         = ISNULL(@Contabil, 0);
        SET @ContaContabilRef = LTRIM(RTRIM(ISNULL(@ContaContabilRef, '')));

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_PLANO_CONTA', CASE WHEN @IdPlanoConta IS NULL THEN 'INCLUIR' ELSE 'ALTERAR' END) = 0
            SET @Recusa = N'Você não tem permissão para gravar o plano de contas.';
        IF @Recusa = N'' AND @IdPlanoConta IS NOT NULL AND SIS.fn_SIS_Na_Lixeira(N'CAD.Plano_Conta', @IdPlanoConta) = 1
            SET @Recusa = N'O registro está na lixeira: recupere-o antes de alterar (Sistema › Lixeira).';
        IF @Recusa = N'' AND @IdPlanoConta IS NOT NULL AND NOT EXISTS (SELECT 1 FROM CAD.Plano_Conta x WHERE x.ID_PLANO_CONTA = @IdPlanoConta)
            SET @Recusa = N'Registro do plano de contas não encontrado.';
        IF @Recusa = N'' AND @Descricao = N''
            SET @Recusa = N'Informe a descrição.';
        IF @Recusa = N'' AND NOT EXISTS (SELECT 1 FROM CAD.Plano_Subgrupo s WHERE s.ID_PLANO_SUBGRUPO = @IdPlanoSubgrupo AND s.DT_EXCLUSAO IS NULL)
            SET @Recusa = N'Escolha o subgrupo da conta.';
        IF @Recusa = N'' AND @IdPlanoConta IS NOT NULL
           AND EXISTS (SELECT 1 FROM CAD.Plano_Conta x WHERE x.ID_PLANO_CONTA = @IdPlanoConta AND x.ID_PLANO_SUBGRUPO <> @IdPlanoSubgrupo)
           AND EXISTS (SELECT 1 FROM FIN.Lancamento l WHERE l.ID_PLANO_CONTA = @IdPlanoConta)
            SET @Recusa = N'A conta já tem lançamentos: não pode mudar de subgrupo. Crie uma conta nova no subgrupo certo e desative esta.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM CAD.Plano_Conta c WHERE c.ID_PLANO_SUBGRUPO = @IdPlanoSubgrupo AND c.DESCRICAO = @Descricao
                                     AND c.ID_PLANO_CONTA <> ISNULL(@IdPlanoConta, 0))
            SET @Recusa = N'Já existe uma conta com esta descrição neste subgrupo.';
        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdPlanoConta AS ID;
            RETURN;
        END;

        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        -- Número: escolhido ou o próximo livre (leitura travada até o COMMIT)
        IF @Numero IS NULL
            SELECT @Numero = ISNULL(MAX(x.NUMERO), 0) + 1 FROM CAD.Plano_Conta x WITH (UPDLOCK, HOLDLOCK) WHERE x.ID_PLANO_SUBGRUPO = @IdPlanoSubgrupo;

        IF @Numero NOT BETWEEN 1 AND 999
            SET @Recusa = N'Número do conta fora da faixa (1 a 999).';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM CAD.Plano_Conta x WITH (UPDLOCK, HOLDLOCK) WHERE x.ID_PLANO_SUBGRUPO = @IdPlanoSubgrupo AND x.NUMERO = @Numero AND x.ID_PLANO_CONTA <> ISNULL(@IdPlanoConta, 0))
            SET @Recusa = N'Este número já está em uso. Escolha outro ou deixe em branco para usar o próximo livre.';

        IF @Recusa <> N''
        BEGIN
            COMMIT TRANSACTION;   -- nada foi gravado (COMMIT em vez de ROLLBACK: funciona dentro de INSERT ... EXEC)
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdPlanoConta AS ID;
            RETURN;
        END;

        IF @IdPlanoConta IS NULL
        BEGIN
            INSERT INTO CAD.Plano_Conta (ID_PLANO_SUBGRUPO, NUMERO, DESCRICAO, CONTABIL, CONTA_CONTABIL_REF, USUARIO_CRIACAO)
            VALUES (@IdPlanoSubgrupo, @Numero, @Descricao, @Contabil, @ContaContabilRef, @Usuario);
            SET @IdPlanoConta = SCOPE_IDENTITY();
        END
        ELSE
            UPDATE c
               SET c.ID_PLANO_SUBGRUPO = @IdPlanoSubgrupo, c.NUMERO = @Numero, c.DESCRICAO = @Descricao, c.CONTABIL = @Contabil,
                   c.CONTA_CONTABIL_REF = @ContaContabilRef, c.DT_ALTERACAO = SYSDATETIME(), c.USUARIO_ALTERACAO = @Usuario
            FROM CAD.Plano_Conta c
            WHERE c.ID_PLANO_CONTA = @IdPlanoConta;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Plano de contas gravado.' AS NVARCHAR(400)) AS MENSAGEM, @IdPlanoConta AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar o plano de contas. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, @IdPlanoConta AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/CAD/CAD.CAD_Plano_Excluir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [CAD].[CAD_Plano_Excluir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 16/11/2026
  Descrição   : Desativa (ou reativa, @Reativar = 1) um grupo (@Nivel 1), subgrupo (2)
                ou conta (3) do plano. Nada é apagado: desativar o grupo ou o subgrupo
                esconde tudo abaixo dele das listas de escolha (ATIVO_EFETIVO), sem
                mexer nos filhos. Permissão: DESATIVAR em CAD_PLANO_CONTA.

  Changelog:
    v1.0 (16/11/2026) - Criação (etapa 03a).
    v1.1 (22/11/2026) - Etapa 04b (P20): permissão DESATIVAR (o botão Excluir
                        passa a mandar para a lixeira) e recusa se o registro
                        estiver na lixeira.

  Homologação (LOCAL):
    -- EXEC CAD.CAD_Plano_Excluir @IdUsuario = 2, @Nivel = 3, @Id = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [CAD].[CAD_Plano_Excluir]
    @IdUsuario  INT,
    @Nivel      TINYINT,
    @Id         INT,
    @Reativar   BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[CAD].[CAD_Plano_Excluir]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Usuario    NVARCHAR(100);
    DECLARE @Ativo      BIT;

    BEGIN TRY
        SET @Reativar = ISNULL(@Reativar, 0);

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_PLANO_CONTA', 'DESATIVAR') = 0
            SET @Recusa = N'Você não tem permissão para desativar ou reativar o plano de contas.';
        IF @Recusa = N'' AND SIS.fn_SIS_Na_Lixeira(CASE @Nivel WHEN 1 THEN N'CAD.Plano_Grupo' WHEN 2 THEN N'CAD.Plano_Subgrupo' ELSE N'CAD.Plano_Conta' END, @Id) = 1
            SET @Recusa = N'O registro está na lixeira: recupere-o antes (Sistema › Lixeira).';
        IF @Recusa = N'' AND ISNULL(@Nivel, 0) NOT IN (1, 2, 3)
            SET @Recusa = N'Nível inválido (1 grupo, 2 subgrupo, 3 conta).';

        IF @Recusa = N''
        BEGIN
            SELECT @Ativo = CASE @Nivel WHEN 1 THEN (SELECT g.ATIVO FROM CAD.Plano_Grupo g WHERE g.ID_PLANO_GRUPO = @Id)
                                        WHEN 2 THEN (SELECT s.ATIVO FROM CAD.Plano_Subgrupo s WHERE s.ID_PLANO_SUBGRUPO = @Id)
                                        ELSE (SELECT c.ATIVO FROM CAD.Plano_Conta c WHERE c.ID_PLANO_CONTA = @Id) END;
            IF @Ativo IS NULL SET @Recusa = N'Registro do plano de contas não encontrado.';
            ELSE IF @Ativo = 1 AND @Reativar = 1 SET @Recusa = N'O registro já está ativo.';
            ELSE IF @Ativo = 0 AND @Reativar = 0 SET @Recusa = N'O registro já está desativado.';
        END;
        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @Id AS ID;
            RETURN;
        END;

        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);

        SET @EtapaAtual = 'Gravação';
        IF @Nivel = 1
            UPDATE g SET g.ATIVO = @Reativar, g.DT_ALTERACAO = SYSDATETIME(), g.USUARIO_ALTERACAO = @Usuario
            FROM CAD.Plano_Grupo g WHERE g.ID_PLANO_GRUPO = @Id AND g.ATIVO <> @Reativar;
        IF @Nivel = 2
            UPDATE s SET s.ATIVO = @Reativar, s.DT_ALTERACAO = SYSDATETIME(), s.USUARIO_ALTERACAO = @Usuario
            FROM CAD.Plano_Subgrupo s WHERE s.ID_PLANO_SUBGRUPO = @Id AND s.ATIVO <> @Reativar;
        IF @Nivel = 3
            UPDATE c SET c.ATIVO = @Reativar, c.DT_ALTERACAO = SYSDATETIME(), c.USUARIO_ALTERACAO = @Usuario
            FROM CAD.Plano_Conta c WHERE c.ID_PLANO_CONTA = @Id AND c.ATIVO <> @Reativar;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(CASE WHEN @Reativar = 1 THEN N'Registro reativado.' ELSE N'Registro desativado (continua no histórico).' END AS NVARCHAR(400)) AS MENSAGEM,
               @Id AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível alterar a situação do registro. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, @Id AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Arquivo_Morto_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Arquivo_Morto_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : Consulta do arquivo morto (só leitura): período, conta, busca por
                parte do texto (pessoa, obra, empresa, complemento, documento, nota
                ou plano) e valor exato. Permissão: VER em FIN_ARQUIVO_MORTO.
                Devolve até @Limite linhas, mais recentes primeiro.

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Arquivo_Morto_Listar @IdUsuario = 2, @Busca = N'pintor', @DtInicio = '2010-01-01', @DtFim = '2010-12-31';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Arquivo_Morto_Listar]
    @IdUsuario  INT,
    @Busca      NVARCHAR(100) = NULL,
    @DtInicio   DATE          = NULL,
    @DtFim      DATE          = NULL,
    @Conta      NVARCHAR(80)  = NULL,
    @Limite     INT           = 1000
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[FIN].[FIN_Arquivo_Morto_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Like       NVARCHAR(110);
    DECLARE @Valor      DECIMAL(18,2);

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_ARQUIVO_MORTO', 'VER') = 0
            THROW 50001, N'Você não tem permissão para consultar o arquivo morto.', 1;

        SET @Busca  = LTRIM(RTRIM(ISNULL(@Busca, N'')));
        SET @Conta  = LTRIM(RTRIM(ISNULL(@Conta, N'')));
        SET @Limite = CASE WHEN ISNULL(@Limite, 0) BETWEEN 1 AND 20000 THEN @Limite ELSE 1000 END;
        SET @Like   = N'%' + REPLACE(REPLACE(REPLACE(@Busca, N'[', N'[[]'), N'%', N'[%]'), N'_', N'[_]') + N'%';
        SET @Valor  = TRY_CONVERT(DECIMAL(18,2), REPLACE(REPLACE(@Busca, N'.', N''), N',', N'.'));

        SET @EtapaAtual = 'Consulta';
        SELECT TOP (@Limite)
               a.ID_ARQUIVO_MORTO, a.DT_MOVIMENTO, a.DT_VENCIMENTO, a.DT_PAGAMENTO,
               a.EMPRESA, a.OBRA, a.PESSOA, a.CONTA, a.PLANO1, a.PLANO2, a.PLANO3,
               a.HISTORICO, a.COMPLEMENTO, a.DOCUMENTO, a.NOTA_FISCAL, a.IMOVEL,
               a.VALOR_DEBITO, a.VALOR_CREDITO, a.CONFIRMADO, a.ORIGEM_ACCESS, a.CODIGO_ACCESS
        FROM FIN.Arquivo_Morto a WITH (NOLOCK)
        WHERE (@DtInicio IS NULL OR a.DT_MOVIMENTO >= @DtInicio)
          AND (@DtFim    IS NULL OR a.DT_MOVIMENTO <= @DtFim)
          AND (@Conta = N'' OR a.CONTA = @Conta)
          AND (   @Busca = N''
               OR a.PESSOA LIKE @Like OR a.OBRA LIKE @Like OR a.EMPRESA LIKE @Like
               OR a.COMPLEMENTO LIKE @Like OR a.DOCUMENTO LIKE @Like OR a.NOTA_FISCAL LIKE @Like
               OR a.PLANO3 LIKE @Like OR a.HISTORICO LIKE @Like
               OR (@Valor IS NOT NULL AND (a.VALOR_DEBITO = @Valor OR a.VALOR_CREDITO = @Valor)))
        ORDER BY a.DT_MOVIMENTO DESC, a.ID_ARQUIVO_MORTO DESC;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível consultar o arquivo morto. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Comunicado_Previa_Gerar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Comunicado_Previa_Gerar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : Monta a edição da semana (segunda a sexta da data de hoje) com os
                itens ativos e manda a PRÉVIA só para o grupo de aprovação. Prévias
                anteriores ainda pendentes viram DESCARTADA (não acumulam). Semana
                que já teve envio oficial: recusa. Chamada pela rotina (@IdUsuario
                NULL, sem conferir permissão) ou pelo botão "Gerar prévia agora"
                (permissão ENVIAR em SIS_COMUNICADO). Devolve SUCESSO, MENSAGEM, ID
                (ID = ID_COMUNICADO_EDICAO).

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c, boletim semanal da implantação).
    v1.1 (17/11/2026) - Nome do sistema no aviso da prévia pelo parâmetro SISTEMA_NOME.

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Comunicado_Previa_Gerar @IdUsuario = 2, @IdComunicado = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Comunicado_Previa_Gerar]
    @IdUsuario     INT = NULL,
    @IdComunicado  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Comunicado_Previa_Gerar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Hoje       DATE          = CAST(SYSDATETIME() AS DATE);
    DECLARE @Inicio     DATE;
    DECLARE @Fim        DATE;
    DECLARE @Titulo     NVARCHAR(150);
    DECLARE @GrupoAprov VARCHAR(30);
    DECLARE @Para       NVARCHAR(MAX);
    DECLARE @Assunto    NVARCHAR(400);
    DECLARE @AssuntoPv  NVARCHAR(400);
    DECLARE @Conteudo   NVARCHAR(MAX);
    DECLARE @Corpo      NVARCHAR(MAX);
    DECLARE @CorpoPv    NVARCHAR(MAX);
    DECLARE @Aviso      NVARCHAR(MAX);
    DECLARE @IdEdicao   BIGINT;
    DECLARE @IdEmail    BIGINT;
    DECLARE @Chave      NVARCHAR(200);
    DECLARE @Usuario    NVARCHAR(100);

    BEGIN TRY
        -- segunda-feira da semana, sem depender de SET DATEFIRST (01/01/1900 foi segunda)
        SET @Inicio = DATEADD(DAY, -(DATEDIFF(DAY, '19000101', @Hoje) % 7), @Hoje);
        SET @Fim    = DATEADD(DAY, 4, @Inicio);

        IF @IdUsuario IS NOT NULL AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_COMUNICADO', 'ENVIAR') = 0
            SET @Recusa = N'Você não tem permissão para gerar a prévia do comunicado.';

        SELECT @Titulo = c.TITULO, @GrupoAprov = g.CODIGO
        FROM SIS.Comunicado c
        INNER JOIN SIS.Grupo_Email g ON g.ID_GRUPO_EMAIL = c.ID_GRUPO_EMAIL_APROVACAO
        WHERE c.ID_COMUNICADO = @IdComunicado AND c.ATIVO = 1;

        IF @Recusa = N'' AND @Titulo IS NULL
            SET @Recusa = N'Comunicado não encontrado ou desligado.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM SIS.Comunicado_Edicao e
                                     WHERE e.ID_COMUNICADO = @IdComunicado AND e.DT_INICIO = @Inicio AND e.SITUACAO = 'ENVIADA')
            SET @Recusa = N'O comunicado desta semana já foi enviado.';
        SET @Para = ISNULL(SIS.fn_SIS_Emails_Do_Grupo(@GrupoAprov), N'');
        IF @Recusa = N'' AND @Para = N''
            SET @Recusa = N'O grupo de aprovação do comunicado não tem e-mail ativo.';
        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID;
            RETURN;
        END;

        SET @EtapaAtual = 'Montagem';
        SET @Usuario   = ISNULL(SIS.fn_SIS_Usuario_Login(@IdUsuario), N'rotina');
        SET @Assunto   = N'CMJ - ' + @Titulo + N' - semana de ' + LEFT(SIS.fn_SIS_Formatar_Data(@Inicio), 5)
                       + N' a ' + SIS.fn_SIS_Formatar_Data(@Fim);
        SET @Conteudo  = SIS.fn_SIS_Comunicado_Conteudo(@IdComunicado);
        SET @Corpo     = SIS.fn_SIS_Email_HTML(@Titulo, 'INFO', @Conteudo, NULL, NULL, 1);
        SET @AssuntoPv = N'[PRÉVIA] ' + @Assunto;
        SET @Aviso     = N'<div style="background:#FFF3E0;border-left:4px solid #E65100;padding:10px 14px;margin-bottom:16px;">'
                       + N'<b>Prévia para aprovação.</b> Este e-mail ainda não foi enviado aos destinatários. '
                       + N'Para liberar, abra o ' + SIS.fn_SIS_Texto_HTML(ISNULL(NULLIF(SIS.fn_SIS_Parametro('SISTEMA_NOME'), N''), N'SistemaCMJ')) + N', menu Sistema &gt; E-mails &gt; Comunicados, e clique em "Aprovar e enviar".</div>';
        SET @CorpoPv   = SIS.fn_SIS_Email_HTML(N'Prévia - ' + @Titulo, 'INFO', @Aviso + @Conteudo, @NomeProc, @GrupoAprov, 0);

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        UPDATE e
           SET e.SITUACAO = 'DESCARTADA', e.DT_ALTERACAO = SYSDATETIME(), e.USUARIO_ALTERACAO = @Usuario
        FROM SIS.Comunicado_Edicao e WITH (UPDLOCK, HOLDLOCK)
        WHERE e.ID_COMUNICADO = @IdComunicado AND e.SITUACAO = 'PREVIA';

        INSERT INTO SIS.Comunicado_Edicao (ID_COMUNICADO, DT_INICIO, DT_FIM, ASSUNTO, CORPO_HTML, SITUACAO, USUARIO_CRIACAO)
        VALUES (@IdComunicado, @Inicio, @Fim, @Assunto, @Corpo, 'PREVIA', @Usuario);
        SET @IdEdicao = SCOPE_IDENTITY();

        SET @Chave = N'COMUNICADO_PREVIA:' + CONVERT(NVARCHAR(30), @IdEdicao);
        EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = @AssuntoPv, @CorpoHTML = @CorpoPv, @Tipo = 'COMUNICADO_PREVIA',
             @Origem = @NomeProc, @ChaveOrigem = @Chave, @Grupo = @GrupoAprov, @Conta = 'INTERNA', @IdEmail = @IdEmail OUTPUT;

        IF @IdEmail IS NULL
            THROW 50001, N'A prévia não entrou na fila de e-mails (veja o log de erros).', 1;

        UPDATE SIS.Comunicado_Edicao SET ID_EMAIL_PREVIA = @IdEmail WHERE ID_COMUNICADO_EDICAO = @IdEdicao;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Prévia gerada e enviada para aprovação.' AS NVARCHAR(400)) AS MENSAGEM, @IdEdicao AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gerar a prévia do comunicado. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Comunicado_Previa_Processar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Comunicado_Previa_Processar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : Rotina semanal (SIS.Rotina COMUNICADO_PREVIA, sexta 9h): gera a
                prévia de cada comunicado ativo. Um comunicado com problema não
                impede os outros (laço isolado, regra 13); no fim, se algum falhou,
                relança um erro agregado para a rotina registrar ERRO.

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c, boletim semanal da implantação).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Comunicado_Previa_Processar]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Comunicado_Previa_Processar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Laço';
    DECLARE @Id         INT           = 0;
    DECLARE @Proximo    INT;
    DECLARE @Falhas     NVARCHAR(MAX) = N'';
    DECLARE @Res        TABLE (SUCESSO BIT, MENSAGEM NVARCHAR(400), ID BIGINT);

    WHILE 1 = 1
    BEGIN
        SET @Proximo = NULL;
        SELECT TOP (1) @Proximo = c.ID_COMUNICADO
        FROM SIS.Comunicado c
        WHERE c.ATIVO = 1 AND c.ID_COMUNICADO > @Id
        ORDER BY c.ID_COMUNICADO;
        IF @Proximo IS NULL BREAK;
        SET @Id = @Proximo;

        BEGIN TRY
            DELETE FROM @Res;
            INSERT INTO @Res (SUCESSO, MENSAGEM, ID)
            EXEC SIS.SIS_Comunicado_Previa_Gerar @IdUsuario = NULL, @IdComunicado = @Id;

            SELECT @Falhas = @Falhas + N' [' + CONVERT(NVARCHAR(10), @Id) + N'] ' + r.MENSAGEM
            FROM @Res r
            WHERE r.SUCESSO = 0;
        END TRY
        BEGIN CATCH
            IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
            SET @Falhas = @Falhas + N' [' + CONVERT(NVARCHAR(10), @Id) + N'] ' + ERROR_MESSAGE();
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        END CATCH;
    END;

    IF @Falhas <> N''
    BEGIN
        SET @Falhas = LEFT(N'Comunicados com problema:' + @Falhas, 2000);
        THROW 50001, @Falhas, 1;
    END;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Comunicado_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Comunicado_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : Dados da tela Comunicados: o comunicado (o primeiro, ativo antes,
                quando @IdComunicado vier vazio), os itens (ITENS_JSON), as últimas
                20 edições (EDICOES_JSON, sem o HTML), os destinatários dos dois
                grupos e a agenda da rotina. Permissão: VER em SIS_COMUNICADO.

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c, boletim semanal da implantação).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Comunicado_Obter]
    @IdUsuario     INT,
    @IdComunicado  INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Comunicado_Obter]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_COMUNICADO', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver os comunicados.', 1;

        IF @IdComunicado IS NULL
            SELECT TOP (1) @IdComunicado = c.ID_COMUNICADO FROM SIS.Comunicado c ORDER BY c.ATIVO DESC, c.ID_COMUNICADO;

        SET @EtapaAtual = 'Consulta';
        SELECT c.ID_COMUNICADO, c.CODIGO, c.TITULO, c.INTRODUCAO, c.EXIGE_APROVACAO, c.ATIVO,
               g.CODIGO AS GRUPO, ga.CODIGO AS GRUPO_APROVACAO,
               ISNULL(SIS.fn_SIS_Emails_Do_Grupo(g.CODIGO), N'')  AS DESTINATARIOS,
               ISNULL(SIS.fn_SIS_Emails_Do_Grupo(ga.CODIGO), N'') AS DESTINATARIOS_APROVACAO,
               ISNULL(CONVERT(VARCHAR(5), r.HORARIO, 108), '') AS ROTINA_HORARIO, ISNULL(r.DIAS_SEMANA, '') AS ROTINA_DIAS,
               r.PROXIMA_EXECUCAO AS ROTINA_PROXIMA, ISNULL(r.ATIVA, CAST(0 AS BIT)) AS ROTINA_ATIVA,
               ISNULL((SELECT i.ID_COMUNICADO_ITEM AS id, i.SECAO AS secao, i.TEXTO AS texto, i.ORDEM AS ordem, i.ATIVO AS ativo
                       FROM SIS.Comunicado_Item i
                       WHERE i.ID_COMUNICADO = c.ID_COMUNICADO AND i.ATIVO = 1
                       ORDER BY i.SECAO, i.ORDEM, i.ID_COMUNICADO_ITEM
                       FOR JSON PATH), N'[]') AS ITENS_JSON,
               ISNULL((SELECT TOP (20) e.ID_COMUNICADO_EDICAO AS id, e.DT_INICIO AS inicio, e.DT_FIM AS fim, e.ASSUNTO AS assunto,
                              e.SITUACAO AS situacao, e.DT_CRIACAO AS criada, e.DT_APROVACAO AS aprovada, e.USUARIO_APROVACAO AS aprovadaPor
                       FROM SIS.Comunicado_Edicao e
                       WHERE e.ID_COMUNICADO = c.ID_COMUNICADO
                       ORDER BY e.ID_COMUNICADO_EDICAO DESC
                       FOR JSON PATH), N'[]') AS EDICOES_JSON
        FROM SIS.Comunicado c
        INNER JOIN SIS.Grupo_Email g  ON g.ID_GRUPO_EMAIL  = c.ID_GRUPO_EMAIL
        INNER JOIN SIS.Grupo_Email ga ON ga.ID_GRUPO_EMAIL = c.ID_GRUPO_EMAIL_APROVACAO
        LEFT  JOIN SIS.Rotina r ON r.CODIGO = 'COMUNICADO_PREVIA'
        WHERE c.ID_COMUNICADO = @IdComunicado;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar o comunicado. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Comunicado_Edicao_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Comunicado_Edicao_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : Uma edição com o HTML, para a tela mostrar exatamente o que será
                (ou foi) enviado. Permissão: VER em SIS_COMUNICADO.

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c, boletim semanal da implantação).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Comunicado_Edicao_Obter]
    @IdUsuario  INT,
    @IdEdicao   BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_COMUNICADO', 'VER') = 0
        THROW 50001, N'Você não tem permissão para ver os comunicados.', 1;

    SELECT e.ID_COMUNICADO_EDICAO, e.ID_COMUNICADO, e.DT_INICIO, e.DT_FIM, e.ASSUNTO, e.CORPO_HTML, e.SITUACAO,
           e.DT_APROVACAO, e.USUARIO_APROVACAO, e.DT_CRIACAO, e.USUARIO_CRIACAO
    FROM SIS.Comunicado_Edicao e WITH (NOLOCK)
    WHERE e.ID_COMUNICADO_EDICAO = @IdEdicao;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Comunicado_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Comunicado_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : Grava a introdução e a lista inteira de itens do comunicado
                (tudo-ou-nada). @ItensJson: [{"id":null|n,"secao":"EM_TESTE",
                "texto":"...","ordem":1}]. Item que sumiu da lista é DESATIVADO
                (nunca apagado). Permissão: ALTERAR em SIS_COMUNICADO. Não gera
                prévia: a tela oferece "Gerar prévia agora".

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c, boletim semanal da implantação).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Comunicado_Gravar @IdUsuario = 2, @IdComunicado = 1, @Introducao = N'Olá', @ItensJson = N'[{"secao":"EM_TESTE","texto":"Teste","ordem":1}]';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Comunicado_Gravar]
    @IdUsuario     INT,
    @IdComunicado  INT,
    @Introducao    NVARCHAR(1000) = NULL,
    @ItensJson     NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Comunicado_Gravar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Usuario    NVARCHAR(100);

    BEGIN TRY
        DROP TABLE IF EXISTS #Itens;
        SET @Introducao = LTRIM(RTRIM(ISNULL(@Introducao, N'')));

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_COMUNICADO', 'ALTERAR') = 0
            SET @Recusa = N'Você não tem permissão para alterar comunicados.';
        IF @Recusa = N'' AND NOT EXISTS (SELECT 1 FROM SIS.Comunicado c WHERE c.ID_COMUNICADO = @IdComunicado)
            SET @Recusa = N'Comunicado não encontrado.';
        IF @Recusa = N'' AND ISJSON(ISNULL(@ItensJson, N'')) = 0
            SET @Recusa = N'Lista de itens inválida.';
        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(@IdComunicado AS BIGINT) AS ID;
            RETURN;
        END;

        SELECT j.id AS ID_ITEM, UPPER(LTRIM(RTRIM(ISNULL(j.secao, '')))) AS SECAO,
               LTRIM(RTRIM(ISNULL(j.texto, N''))) AS TEXTO, ISNULL(j.ordem, 0) AS ORDEM
        INTO #Itens
        FROM OPENJSON(@ItensJson) WITH (id INT '$.id', secao VARCHAR(15) '$.secao', texto NVARCHAR(400) '$.texto', ordem SMALLINT '$.ordem') j;

        IF EXISTS (SELECT 1 FROM #Itens WHERE SECAO NOT IN ('IMPLANTADO', 'EM_TESTE', 'PROXIMA_FASE'))
            SET @Recusa = N'Seção inválida num dos itens.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #Itens WHERE TEXTO = N'')
            SET @Recusa = N'Há item sem texto. Preencha ou remova a linha.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #Itens WHERE LEN(TEXTO) > 300)
            SET @Recusa = N'Cada item pode ter no máximo 300 caracteres.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #Itens i WHERE i.ID_ITEM IS NOT NULL
                                     AND NOT EXISTS (SELECT 1 FROM SIS.Comunicado_Item ci WHERE ci.ID_COMUNICADO_ITEM = i.ID_ITEM AND ci.ID_COMUNICADO = @IdComunicado))
            SET @Recusa = N'Um dos itens não pertence a este comunicado.';
        IF @Recusa <> N''
        BEGIN
            DROP TABLE IF EXISTS #Itens;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(@IdComunicado AS BIGINT) AS ID;
            RETURN;
        END;

        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        UPDATE c
           SET c.INTRODUCAO = @Introducao, c.DT_ALTERACAO = SYSDATETIME(), c.USUARIO_ALTERACAO = @Usuario
        FROM SIS.Comunicado c
        WHERE c.ID_COMUNICADO = @IdComunicado AND c.INTRODUCAO <> @Introducao;

        UPDATE ci
           SET ci.SECAO = i.SECAO, ci.TEXTO = i.TEXTO, ci.ORDEM = i.ORDEM, ci.ATIVO = 1,
               ci.DT_ALTERACAO = SYSDATETIME(), ci.USUARIO_ALTERACAO = @Usuario
        FROM SIS.Comunicado_Item ci
        INNER JOIN #Itens i ON i.ID_ITEM = ci.ID_COMUNICADO_ITEM
        WHERE ci.SECAO <> i.SECAO OR ci.TEXTO <> i.TEXTO OR ci.ORDEM <> i.ORDEM OR ci.ATIVO = 0;

        UPDATE ci
           SET ci.ATIVO = 0, ci.DT_ALTERACAO = SYSDATETIME(), ci.USUARIO_ALTERACAO = @Usuario
        FROM SIS.Comunicado_Item ci
        WHERE ci.ID_COMUNICADO = @IdComunicado AND ci.ATIVO = 1
          AND NOT EXISTS (SELECT 1 FROM #Itens i WHERE i.ID_ITEM = ci.ID_COMUNICADO_ITEM);

        INSERT INTO SIS.Comunicado_Item (ID_COMUNICADO, SECAO, TEXTO, ORDEM, USUARIO_CRIACAO)
        SELECT @IdComunicado, i.SECAO, i.TEXTO, i.ORDEM, @Usuario
        FROM #Itens i
        WHERE i.ID_ITEM IS NULL;

        COMMIT TRANSACTION;
        DROP TABLE IF EXISTS #Itens;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Comunicado gravado.' AS NVARCHAR(400)) AS MENSAGEM, CAST(@IdComunicado AS BIGINT) AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
        BEGIN
            DROP TABLE IF EXISTS #Itens;
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        END;

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar o comunicado. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, CAST(@IdComunicado AS BIGINT) AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Comunicado_Edicao_Aprovar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Comunicado_Edicao_Aprovar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : "Aprovar e enviar": manda ao grupo oficial exatamente o que foi
                aprovado na prévia (assunto e HTML da edição) e marca ENVIADA, tudo
                na mesma transação. Só edição em PREVIA. Permissão: APROVAR em
                SIS_COMUNICADO. Conta EXTERNA (destinatários de fora). No banco
                _LOCAL a fila manda para o EMAIL_TESTE (proteção da 02d).

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c, boletim semanal da implantação).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Comunicado_Edicao_Aprovar @IdUsuario = 2, @IdEdicao = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Comunicado_Edicao_Aprovar]
    @IdUsuario  INT,
    @IdEdicao   BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Comunicado_Edicao_Aprovar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Situacao   VARCHAR(10);
    DECLARE @Grupo      VARCHAR(30);
    DECLARE @Para       NVARCHAR(MAX);
    DECLARE @Assunto    NVARCHAR(400);
    DECLARE @Corpo      NVARCHAR(MAX);
    DECLARE @IdEmail    BIGINT;
    DECLARE @Chave      NVARCHAR(200);
    DECLARE @Usuario    NVARCHAR(100);

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_COMUNICADO', 'APROVAR') = 0
            SET @Recusa = N'Você não tem permissão para aprovar comunicados.';

        SET @EtapaAtual = 'Envio';
        BEGIN TRANSACTION;

        SELECT @Situacao = e.SITUACAO, @Grupo = g.CODIGO, @Assunto = e.ASSUNTO, @Corpo = e.CORPO_HTML
        FROM SIS.Comunicado_Edicao e WITH (UPDLOCK, HOLDLOCK)
        INNER JOIN SIS.Comunicado c ON c.ID_COMUNICADO = e.ID_COMUNICADO
        INNER JOIN SIS.Grupo_Email g ON g.ID_GRUPO_EMAIL = c.ID_GRUPO_EMAIL
        WHERE e.ID_COMUNICADO_EDICAO = @IdEdicao;

        IF @Recusa = N'' AND @Situacao IS NULL
            SET @Recusa = N'Edição do comunicado não encontrada.';
        IF @Recusa = N'' AND @Situacao <> 'PREVIA'
            SET @Recusa = CASE @Situacao WHEN 'ENVIADA' THEN N'Este comunicado já foi enviado.'
                                         ELSE N'Esta prévia foi descartada. Gere uma prévia nova.' END;
        SET @Para = ISNULL(SIS.fn_SIS_Emails_Do_Grupo(@Grupo), N'');
        IF @Recusa = N'' AND @Para = N''
            SET @Recusa = N'O grupo de destinatários do comunicado não tem e-mail ativo.';
        IF @Recusa <> N''
        BEGIN
            COMMIT TRANSACTION;   -- nada foi alterado; COMMIT (e não ROLLBACK) funciona também dentro de INSERT-EXEC
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(@IdEdicao AS BIGINT) AS ID;
            RETURN;
        END;

        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        SET @Chave   = N'COMUNICADO:' + CONVERT(NVARCHAR(30), @IdEdicao);
        EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = @Assunto, @CorpoHTML = @Corpo, @Tipo = 'COMUNICADO',
             @Origem = @NomeProc, @ChaveOrigem = @Chave, @Grupo = @Grupo, @Conta = 'EXTERNA', @IdEmail = @IdEmail OUTPUT;

        IF @IdEmail IS NULL
            THROW 50001, N'O comunicado não entrou na fila de e-mails (veja o log de erros).', 1;

        UPDATE SIS.Comunicado_Edicao
           SET SITUACAO = 'ENVIADA', ID_EMAIL_OFICIAL = @IdEmail, DT_APROVACAO = SYSDATETIME(), USUARIO_APROVACAO = @Usuario,
               DT_ALTERACAO = SYSDATETIME(), USUARIO_ALTERACAO = @Usuario
         WHERE ID_COMUNICADO_EDICAO = @IdEdicao;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Comunicado aprovado. O e-mail foi para a fila de envio.' AS NVARCHAR(400)) AS MENSAGEM, CAST(@IdEdicao AS BIGINT) AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível aprovar o comunicado. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Comunicado_Edicao_Descartar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Comunicado_Edicao_Descartar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 17/11/2026
  Descrição   : Descarta uma prévia (nada é enviado). Permissão: APROVAR em
                SIS_COMUNICADO.

  Changelog:
    v1.0 (17/11/2026) - Criação (etapa 03c, boletim semanal da implantação).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Comunicado_Edicao_Descartar]
    @IdUsuario  INT,
    @IdEdicao   BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Comunicado_Edicao_Descartar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Usuario    NVARCHAR(100);

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_COMUNICADO', 'APROVAR') = 0
            SET @Recusa = N'Você não tem permissão para descartar comunicados.';
        IF @Recusa = N'' AND NOT EXISTS (SELECT 1 FROM SIS.Comunicado_Edicao e WHERE e.ID_COMUNICADO_EDICAO = @IdEdicao AND e.SITUACAO = 'PREVIA')
            SET @Recusa = N'Só uma prévia pendente pode ser descartada.';
        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        UPDATE SIS.Comunicado_Edicao
           SET SITUACAO = 'DESCARTADA', DT_ALTERACAO = SYSDATETIME(), USUARIO_ALTERACAO = @Usuario
         WHERE ID_COMUNICADO_EDICAO = @IdEdicao AND SITUACAO = 'PREVIA';

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Prévia descartada. Nada foi enviado.' AS NVARCHAR(400)) AS MENSAGEM, CAST(@IdEdicao AS BIGINT) AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível descartar a prévia. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Instalacao_Situacao.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Instalacao_Situacao]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Diz se o banco está esperando o PRIMEIRO ACESSO da instalação:
                nenhum usuário administrador (perfil de nível 1 ou 2, ativo, não
                interno) tem senha definida. Só nesse caso a tela de instalação
                (que a API abre apenas no próprio servidor) pode definir as
                senhas do administrador geral e do administrador da empresa.
                Devolve 1 linha: PENDENTE, LOGIN_GERAL, LOGIN_EMPRESA.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d).

  Homologação (LOCAL): ver sql/testes/SIS/03d_Homologacao_Instalacao.sql.
    -- EXEC SIS.SIS_Instalacao_Situacao;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Instalacao_Situacao]
AS
BEGIN
    SET NOCOUNT ON;
    SELECT CAST(CASE WHEN EXISTS (SELECT 1 FROM SIS.Usuario u INNER JOIN SIS.Perfil p ON p.ID_PERFIL = u.ID_PERFIL
                                  WHERE p.NIVEL_ADMIN >= 1 AND u.INTERNO = 0 AND u.ATIVO = 1 AND u.SENHA_HASH IS NOT NULL)
                     THEN 0 ELSE 1 END AS BIT) AS PENDENTE,
           ISNULL((SELECT TOP (1) u.LOGIN FROM SIS.Usuario u INNER JOIN SIS.Perfil p ON p.ID_PERFIL = u.ID_PERFIL
                   WHERE p.NIVEL_ADMIN = 2 AND u.INTERNO = 0 AND u.ATIVO = 1 ORDER BY u.ID_USUARIO), '') AS LOGIN_GERAL,
           ISNULL((SELECT TOP (1) u.LOGIN FROM SIS.Usuario u INNER JOIN SIS.Perfil p ON p.ID_PERFIL = u.ID_PERFIL
                   WHERE p.NIVEL_ADMIN = 1 AND u.INTERNO = 0 AND u.ATIVO = 1 ORDER BY u.ID_USUARIO), '') AS LOGIN_EMPRESA;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Instalacao_Senha_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Instalacao_Senha_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : PRIMEIRO ACESSO da instalação (uso exclusivo da API, tela que só
                abre no próprio servidor): grava de uma vez (tudo-ou-nada) a
                senha do administrador geral (nível 2) e a do administrador da
                empresa (nível 1). O banco recebe só o PBKDF2-SHA256 calculado
                pela API (como em SIS_Usuario_Senha_Gravar).
                Só funciona enquanto NENHUM administrador tem senha
                (SIS_Instalacao_Situacao.PENDENTE = 1); depois disso recusa
                sempre: senha nova passa pelo caminho normal (tela Usuários).
                Administrador geral: TROCAR_SENHA = 0 (ele mesmo digitou).
                Administrador da empresa: TROCAR_SENHA = 1 (senha provisória,
                troca no primeiro login).
                Gravado em nome do usuário "sistema" (auditoria), estação
                "Instalação (servidor)".
                Devolve 1 linha: SUCESSO, MENSAGEM.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d).

  Homologação (LOCAL): ver sql/testes/SIS/03d_Homologacao_Instalacao.sql.
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Instalacao_Senha_Gravar]
    @HashGeral     VARBINARY(64),
    @SaltGeral     VARBINARY(64),
    @HashEmpresa   VARBINARY(64),
    @SaltEmpresa   VARBINARY(64),
    @Iteracoes     INT,
    @Algoritmo     VARCHAR(30),
    @Ip            VARCHAR(45)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc      NVARCHAR(128) = N'[SIS].[SIS_Instalacao_Senha_Gravar]';
    DECLARE @EtapaAtual    VARCHAR(100)  = 'Validação';
    DECLARE @Recusa        NVARCHAR(400) = N'';
    DECLARE @MinIteracoes  INT;
    DECLARE @IdSistema     INT;
    DECLARE @IdGeral       INT;
    DECLARE @IdEmpresa     INT;

    BEGIN TRY
        SET @MinIteracoes = ISNULL(SIS.fn_SIS_Parametro_Inteiro('SENHA_PBKDF2_ITERACOES'), 600000);
        IF @MinIteracoes < 100000 SET @MinIteracoes = 100000;
        SET @IdSistema = (SELECT u.ID_USUARIO FROM SIS.Usuario u WHERE u.LOGIN = 'sistema' AND u.INTERNO = 1);

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

            IF EXISTS (SELECT 1 FROM SIS.Usuario u WITH (UPDLOCK, HOLDLOCK) INNER JOIN SIS.Perfil p ON p.ID_PERFIL = u.ID_PERFIL
                       WHERE p.NIVEL_ADMIN >= 1 AND u.INTERNO = 0 AND u.ATIVO = 1 AND u.SENHA_HASH IS NOT NULL)
                SET @Recusa = N'A instalação já foi concluída: os administradores já têm senha. Para trocar uma senha, use a tela de usuários.';

            SELECT TOP (1) @IdGeral = u.ID_USUARIO FROM SIS.Usuario u INNER JOIN SIS.Perfil p ON p.ID_PERFIL = u.ID_PERFIL
            WHERE p.NIVEL_ADMIN = 2 AND u.INTERNO = 0 AND u.ATIVO = 1 ORDER BY u.ID_USUARIO;
            SELECT TOP (1) @IdEmpresa = u.ID_USUARIO FROM SIS.Usuario u INNER JOIN SIS.Perfil p ON p.ID_PERFIL = u.ID_PERFIL
            WHERE p.NIVEL_ADMIN = 1 AND u.INTERNO = 0 AND u.ATIVO = 1 ORDER BY u.ID_USUARIO;

            IF @Recusa = N'' AND (@IdGeral IS NULL OR @IdEmpresa IS NULL OR @IdSistema IS NULL)
                SET @Recusa = N'Faltam os usuários iniciais no banco (rode o MASTER).';
            IF @Recusa = N'' AND ISNULL(@Algoritmo, '') <> 'PBKDF2-SHA256'
                SET @Recusa = N'Falha técnica: algoritmo de senha não suportado.';
            IF @Recusa = N'' AND (DATALENGTH(ISNULL(@HashGeral, 0x)) <> 32 OR DATALENGTH(ISNULL(@HashEmpresa, 0x)) <> 32)
                SET @Recusa = N'Falha técnica: hash de senha inválido.';
            IF @Recusa = N'' AND (DATALENGTH(ISNULL(@SaltGeral, 0x)) < 16 OR DATALENGTH(ISNULL(@SaltEmpresa, 0x)) < 16)
                SET @Recusa = N'Falha técnica: salt de senha inválido.';
            IF @Recusa = N'' AND ISNULL(@Iteracoes, 0) < @MinIteracoes
                SET @Recusa = N'Falha técnica: quantidade de iterações da senha abaixo do mínimo.';

            IF @Recusa <> N''
            BEGIN
                COMMIT TRANSACTION;
                SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM;
                RETURN;
            END;

            EXEC SIS.SIS_Contexto_Gravar @IdUsuario = @IdSistema, @Estacao = N'Instalação (servidor)', @Origem = N'Tela de primeiro acesso';

            UPDATE u
               SET u.SENHA_HASH         = CASE WHEN u.ID_USUARIO = @IdGeral THEN @HashGeral ELSE @HashEmpresa END,
                   u.SENHA_SALT         = CASE WHEN u.ID_USUARIO = @IdGeral THEN @SaltGeral ELSE @SaltEmpresa END,
                   u.SENHA_ITERACOES    = @Iteracoes,
                   u.SENHA_ALGORITMO    = @Algoritmo,
                   u.DT_SENHA           = SYSDATETIME(),
                   u.TROCAR_SENHA       = CASE WHEN u.ID_USUARIO = @IdGeral THEN 0 ELSE 1 END,
                   u.TENTATIVAS_ERRADAS = 0,
                   u.BLOQUEADO          = 0,
                   u.DT_BLOQUEIO        = NULL,
                   u.DT_ALTERACAO       = SYSDATETIME(),
                   u.USUARIO_ALTERACAO  = N'instalacao'
            FROM SIS.Usuario u
            WHERE u.ID_USUARIO IN (@IdGeral, @IdEmpresa);

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(N'Senhas gravadas. Entre com o administrador geral; o administrador da empresa troca a senha no primeiro acesso.' AS NVARCHAR(400)) AS MENSAGEM;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar as senhas. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Registro_Existe.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Registro_Existe]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Diz se existe o registro @Id (chave primária de uma coluna) na
                tabela @Tabela, que precisa estar entre as TABELAS_DA_TELA do
                item @Item (SIS.fn_SIS_Item_Tem_Tabela); qualquer outra tabela
                devolve 0. Usada por quem precisa conferir um registro de
                tabela variável (ex.: SIS_Anexo_Gravar).
                Roda com a permissão do dono do banco (EXECUTE AS OWNER) porque
                a consulta é montada na hora (SQL dinâmico) e, no servidor, o
                login da API só executa procedures (papel rl_sistemacmj_api):
                sem isso o SELECT seria recusado. O escopo elevado fica só nesta
                consulta; nomes vêm do catálogo e vão com QUOTENAME.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d; achado no ensaio do serviço).

  Homologação (LOCAL e ensaio): sql/testes/SIS/03d_Homologacao_Registro_Existe.sql.
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Registro_Existe]
    @Item    VARCHAR(40),
    @Tabela  NVARCHAR(256),
    @Id      BIGINT,
    @Existe  BIT OUTPUT
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @ObjId INT, @Pk SYSNAME, @Qtd INT, @Achou INT, @Sql NVARCHAR(MAX);
    SET @Existe = 0;

    IF SIS.fn_SIS_Item_Tem_Tabela(@Item, @Tabela) = 0 OR @Id IS NULL
        RETURN;

    SET @ObjId = OBJECT_ID(@Tabela, N'U');
    SELECT @Pk = MAX(c.name), @Qtd = COUNT(*)
    FROM sys.indexes ix
    INNER JOIN sys.index_columns ic ON ic.object_id = ix.object_id AND ic.index_id = ix.index_id
    INNER JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id
    WHERE ix.object_id = @ObjId AND ix.is_primary_key = 1;

    IF @ObjId IS NULL OR @Pk IS NULL OR @Qtd <> 1
        RETURN;

    SET @Sql = N'SELECT @Achou = 1 FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId))
             + N' WHERE ' + QUOTENAME(@Pk) + N' = @Id;';
    EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @Achou INT OUTPUT', @Id = @Id, @Achou = @Achou OUTPUT;
    SET @Existe = CASE WHEN @Achou = 1 THEN 1 ELSE 0 END;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Registrar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Registrar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Registra um backup em SIS.Backup_Execucao. Chamada SÓ pelo script de
                backup do servidor (instalacao\backup_servidor.ps1), que roda
                pelas tarefas do Windows; o login da API não pode executar
                (DENY no papel rl_sistemacmj_api).
                Situação ERRO: manda aviso por e-mail para o parâmetro
                EMAIL_ADMIN_ALERTA (se preenchido), uma vez por backup.
                @ArquivosExistentes (opcional): lista separada por "|" com os
                arquivos que ainda existem na pasta depois da limpeza; os
                demais registros ficam com ARQUIVO_EXISTE = 0.
                Devolve 1 linha: ID_BACKUP.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d, backup no servidor).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Registrar]
    @Tipo                VARCHAR(10),
    @Arquivo             NVARCHAR(400),
    @DtInicio            DATETIME2(0),
    @DtFim               DATETIME2(0)   = NULL,
    @TamanhoMb           DECIMAL(12,1)  = 0,
    @Situacao            VARCHAR(10),
    @Mensagem            NVARCHAR(2000) = N'',
    @CopiaNuvem          BIT            = 0,
    @ArquivosExistentes  NVARCHAR(MAX)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Id BIGINT, @Para NVARCHAR(400), @IdEmail BIGINT, @Corpo NVARCHAR(MAX), @Chave NVARCHAR(200);

    INSERT INTO SIS.Backup_Execucao (TIPO, ARQUIVO, DT_INICIO, DT_FIM, TAMANHO_MB, SITUACAO, MENSAGEM, COPIA_NUVEM)
    VALUES (@Tipo, ISNULL(@Arquivo, N''), @DtInicio, @DtFim, ISNULL(@TamanhoMb, 0), @Situacao, LEFT(ISNULL(@Mensagem, N''), 2000), ISNULL(@CopiaNuvem, 0));
    SET @Id = CAST(SCOPE_IDENTITY() AS BIGINT);

    IF @ArquivosExistentes IS NOT NULL
        UPDATE b SET b.ARQUIVO_EXISTE = 0
        FROM SIS.Backup_Execucao b
        WHERE b.ARQUIVO_EXISTE = 1 AND b.ARQUIVO <> N''
          AND NOT EXISTS (SELECT 1 FROM STRING_SPLIT(@ArquivosExistentes, '|') s WHERE LTRIM(RTRIM(s.value)) = b.ARQUIVO);

    IF @Situacao = 'ERRO'
    BEGIN
        SET @Para = LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Parametro('EMAIL_ADMIN_ALERTA'), N'')));
        IF @Para <> N''
        BEGIN
            SET @Corpo = SIS.fn_SIS_Email_HTML(N'Falha no backup', 'ALERTA',
                N'<p>O backup <b>' + SIS.fn_SIS_Texto_HTML(@Tipo) + N'</b> do banco <b>' + SIS.fn_SIS_Texto_HTML(DB_NAME()) + N'</b> falhou em '
                + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(@DtInicio), N'') + N'.</p><p>Mensagem: ' + SIS.fn_SIS_Texto_HTML(ISNULL(@Mensagem, N'')) + N'</p>'
                + N'<p>Confira o servidor e o registro do backup (pasta do backup, arquivo backup.log).</p>',
                N'[SIS].[SIS_Backup_Registrar]', NULL, 0);
            SET @Chave = N'BACKUP_ERRO_' + CONVERT(NVARCHAR(20), @Id);
            EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = N'ALERTA: falha no backup do sistema', @CorpoHTML = @Corpo,
                 @Tipo = 'ALERTA', @Origem = N'[SIS].[SIS_Backup_Registrar]', @ChaveOrigem = @Chave, @IdEmail = @IdEmail OUTPUT;
        END;
    END;

    SELECT @Id AS ID_BACKUP;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Conferir_Processar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Conferir_Processar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Rotina agendada (BACKUP_CONFERIR, de hora em hora): avisa por
                e-mail (parâmetro EMAIL_ADMIN_ALERTA) quando o backup ATRASA:
                  - último backup COMPLETO ok há mais de BACKUP_HORAS_ALERTA_COMPLETO;
                  - último backup do LOG ok há mais de BACKUP_HORAS_ALERTA_LOG
                    (só depois do primeiro completo);
                  - último TESTE de restauração ok há mais de BACKUP_DIAS_ALERTA_TESTE.
                Cada aviso sai no máximo uma vez por dia (chave de origem com a
                data). Sem nenhum backup registrado ainda: não avisa (servidor
                recém-instalado).

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d, backup no servidor).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Conferir_Processar]
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @Para NVARCHAR(400) = LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Parametro('EMAIL_ADMIN_ALERTA'), N'')));
    DECLARE @HorasCompleto INT = ISNULL(SIS.fn_SIS_Parametro_Inteiro('BACKUP_HORAS_ALERTA_COMPLETO'), 26);
    DECLARE @HorasLog INT = ISNULL(SIS.fn_SIS_Parametro_Inteiro('BACKUP_HORAS_ALERTA_LOG'), 3);
    DECLARE @DiasTeste INT = ISNULL(SIS.fn_SIS_Parametro_Inteiro('BACKUP_DIAS_ALERTA_TESTE'), 8);
    DECLARE @UltCompleto DATETIME2(0) = (SELECT MAX(b.DT_INICIO) FROM SIS.Backup_Execucao b WHERE b.TIPO = 'COMPLETO' AND b.SITUACAO = 'OK');
    DECLARE @UltLog DATETIME2(0) = (SELECT MAX(b.DT_INICIO) FROM SIS.Backup_Execucao b WHERE b.TIPO IN ('LOG', 'COMPLETO') AND b.SITUACAO = 'OK');
    DECLARE @UltTeste DATETIME2(0) = (SELECT MAX(b.DT_INICIO) FROM SIS.Backup_Execucao b WHERE b.TIPO = 'TESTE' AND b.SITUACAO = 'OK');
    DECLARE @Agora DATETIME2(0) = SYSDATETIME();
    DECLARE @Problemas NVARCHAR(MAX) = N'';
    DECLARE @Corpo NVARCHAR(MAX), @IdEmail BIGINT, @Chave NVARCHAR(200);

    IF @Para = N'' OR NOT EXISTS (SELECT 1 FROM SIS.Backup_Execucao) RETURN;

    IF @UltCompleto IS NULL OR @UltCompleto < DATEADD(HOUR, -@HorasCompleto, @Agora)
        SET @Problemas += N'<li>Backup completo: o último sem erro foi em ' + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(@UltCompleto), N'(nenhum)') + N'.</li>';
    IF @UltCompleto IS NOT NULL AND @UltLog < DATEADD(HOUR, -@HorasLog, @Agora)
        SET @Problemas += N'<li>Backup do log (de hora em hora): o último sem erro foi em ' + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(@UltLog), N'(nenhum)') + N'.</li>';
    -- teste: só cobra depois que o servidor tem backups há mais de @DiasTeste dias
    IF (SELECT MIN(b.DT_INICIO) FROM SIS.Backup_Execucao b WHERE b.TIPO = 'COMPLETO' AND b.SITUACAO = 'OK') < DATEADD(DAY, -@DiasTeste, @Agora)
       AND (@UltTeste IS NULL OR @UltTeste < DATEADD(DAY, -@DiasTeste, @Agora))
        SET @Problemas += N'<li>Teste de restauração: o último sem erro foi em ' + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(@UltTeste), N'(nenhum)') + N'.</li>';

    IF @Problemas = N'' RETURN;

    SET @Corpo = SIS.fn_SIS_Email_HTML(N'Backup atrasado', 'ALERTA',
        N'<p>O backup do banco <b>' + SIS.fn_SIS_Texto_HTML(DB_NAME()) + N'</b> está atrasado:</p><ul>' + @Problemas + N'</ul>'
        + N'<p>Confira se o servidor ficou desligado, se as tarefas "SisCMJ - Backup" estão ativas no Agendador de Tarefas e o arquivo backup.log na pasta do backup.</p>',
        N'[SIS].[SIS_Backup_Conferir_Processar]', NULL, 0);
    SET @Chave = N'BACKUP_ATRASO_' + CONVERT(NVARCHAR(8), @Agora, 112);
    EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = N'ALERTA: backup do sistema atrasado', @CorpoHTML = @Corpo,
         @Tipo = 'ALERTA', @Origem = N'[SIS].[SIS_Backup_Conferir_Processar]',
         @ChaveOrigem = @Chave, @IdEmail = @IdEmail OUTPUT;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Lista dos backups para a tela Sistema > Backups (SIS_BACKUP,
                ação VER): completos, do log de hora em hora, testes de
                restauração e backups de segurança, do mais novo para o mais
                antigo, com a indicação de que o arquivo ainda existe.
                Mostra os dos últimos @Dias dias (padrão: parâmetro
                BACKUP_DIAS_MANTER + 7) e qualquer um cujo arquivo ainda exista.
                Ponto de restauração (pedido do Celso, 20/11/2026: a aba Restaurar
                é uma lista, sem digitar dia e hora): backup COMPLETO ou de
                SEGURANCA volta para o próprio backup (TIPO_PONTO BACKUP); backup
                do LOG volta para o fim dele (TIPO_PONTO DATA_HORA, DT_PONTO =
                DT_FIM), com o completo anterior e os logs até ele.
                PODE_ESCOLHER = 1 só quando dá para restaurar; senão
                MOTIVO_INDISPONIVEL diz por quê (versão diferente, arquivo
                apagado, arquivo do plano apagado, com erro, teste).
                VERSAO: versão do banco quando o backup foi feito.
                Sem permissão: erro 50001 (a tela mostra a mensagem).

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d2, restauração pela tela).
    v1.1 (20/11/2026) - PODE_ESCOLHER só para backup feito depois da atualização
                        para a versão atual (fn_SIS_Backup_Limite_Versao).
    v1.2 (20/11/2026) - Backups do log também são pontos de restauração (plano
                        completo); colunas VERSAO, MOTIVO_INDISPONIVEL, TIPO_PONTO
                        e DT_PONTO (pedido do Celso).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Backup_Listar @IdUsuario = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Listar]
    @IdUsuario  INT,
    @Dias       INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Backup_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Desde      DATETIME2(0);
    DECLARE @DtLimite   DATETIME2(0)  = SIS.fn_SIS_Backup_Limite_Versao();

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_BACKUP', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver os backups.', 1;

        SET @Dias = ISNULL(@Dias, ISNULL(TRY_CONVERT(INT, SIS.fn_SIS_Parametro('BACKUP_DIAS_MANTER')), 7) + 7);
        IF @Dias < 1 SET @Dias = 1;
        IF @Dias > 3650 SET @Dias = 3650;
        SET @Desde = DATEADD(DAY, -@Dias, SYSDATETIME());

        SET @EtapaAtual = 'Consulta';
        SELECT b.ID_BACKUP,
               b.TIPO,
               CAST(CASE b.TIPO WHEN 'COMPLETO' THEN N'Completo' WHEN 'LOG' THEN N'De hora em hora (log)'
                                WHEN 'TESTE' THEN N'Teste de restauração' WHEN 'SEGURANCA' THEN N'Segurança (antes de restaurar)'
                                ELSE N'' END AS NVARCHAR(40)) AS TIPO_NOME,
               b.ARQUIVO,
               CAST(ISNULL(RIGHT(b.ARQUIVO, CHARINDEX(N'\', REVERSE(b.ARQUIVO) + N'\') - 1), N'') AS NVARCHAR(260)) AS ARQUIVO_NOME,
               b.DT_INICIO,
               b.DT_FIM,
               b.TAMANHO_MB,
               b.SITUACAO,
               b.MENSAGEM,
               b.COPIA_NUVEM,
               b.ARQUIVO_EXISTE,
               CAST(ISNULL(v.VERSAO, '') AS VARCHAR(20)) AS VERSAO,
               CAST(CASE WHEN m.MOTIVO = N'' THEN 1 ELSE 0 END AS BIT) AS PODE_ESCOLHER,
               m.MOTIVO AS MOTIVO_INDISPONIVEL,
               CAST(CASE b.TIPO WHEN 'LOG' THEN 'DATA_HORA' WHEN 'TESTE' THEN '' ELSE 'BACKUP' END AS VARCHAR(10)) AS TIPO_PONTO,
               CASE WHEN b.TIPO = 'LOG' THEN b.DT_FIM END AS DT_PONTO,
               b.SERVIDOR
        FROM SIS.Backup_Execucao b WITH (NOLOCK)
        OUTER APPLY (SELECT TOP (1) vb.VERSAO FROM SIS.Versao_Banco vb WITH (NOLOCK)
                     WHERE vb.DT_INSTALACAO <= ISNULL(b.DT_FIM, b.DT_INICIO) ORDER BY vb.DT_INSTALACAO DESC, vb.ID_VERSAO_BANCO DESC) v
        OUTER APPLY (SELECT COUNT(*) AS QTD, SUM(CASE WHEN p.ARQUIVO_EXISTE = 0 THEN 1 ELSE 0 END) AS SEM_ARQUIVO, MAX(CAST(p.ALCANCA_PONTO AS INT)) AS ALCANCA
                     FROM SIS.fn_SIS_Backup_Plano(NULL, b.DT_FIM) p
                     WHERE b.TIPO = 'LOG' AND b.SITUACAO = 'OK' AND b.ARQUIVO_EXISTE = 1) pl
        CROSS APPLY (SELECT CAST(CASE
                         WHEN b.TIPO = 'TESTE'                          THEN N'Teste: não é ponto de restauração'
                         WHEN b.SITUACAO <> 'OK'                        THEN N'Backup com erro'
                         WHEN b.ARQUIVO_EXISTE = 0 OR b.ARQUIVO = N''   THEN N'Arquivo apagado pela limpeza'
                         WHEN b.DT_FIM IS NULL OR b.DT_FIM < @DtLimite  THEN N'Versão ' + ISNULL(v.VERSAO, N'anterior') + N' diferente da atual (' + SIS.fn_SIS_Versao_Banco() + N')'
                         WHEN b.TIPO = 'LOG' AND (ISNULL(pl.QTD, 0) = 0 OR ISNULL(pl.ALCANCA, 0) = 0)
                                                                        THEN N'Sem backup completo antes dele'
                         WHEN b.TIPO = 'LOG' AND ISNULL(pl.SEM_ARQUIVO, 0) > 0
                                                                        THEN N'Depende de arquivo já apagado'
                         ELSE N'' END AS NVARCHAR(100)) AS MOTIVO) m
        WHERE b.DT_INICIO >= @Desde
           OR (b.ARQUIVO_EXISTE = 1 AND b.ARQUIVO <> N'' AND b.TIPO <> 'TESTE')
        ORDER BY b.DT_INICIO DESC, b.ID_BACKUP DESC;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível listar os backups. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Situacao_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Situacao_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Resumo do topo da tela Sistema > Backups (SIS_BACKUP, VER),
                1 linha: até onde dá para voltar (do backup completo mais
                antigo que ainda existe até o último backup do log ou
                completo), último completo, último log, último teste, pedido
                de restauração em aberto e se o usuário pode restaurar.
                Sem permissão: erro 50001.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d2, restauração pela tela).
    v1.1 (20/11/2026) - "De" respeita a última atualização de versão
                        (fn_SIS_Backup_Limite_Versao); DT_PODE_VOLTAR_ATE_HORA
                        (último backup do log: limite do "dia e hora"),
                        DT_LIMITE_VERSAO e VERSAO. Achados no ensaio.

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Backup_Situacao_Obter @IdUsuario = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Situacao_Obter]
    @IdUsuario  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[SIS].[SIS_Backup_Situacao_Obter]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Validação';
    DECLARE @DtMaisAntigo DATETIME2(0), @DtInicioAntigo DATETIME2(0), @DtMaisRecente DATETIME2(0), @DtAteHora DATETIME2(0);
    DECLARE @DtLimite     DATETIME2(0) = SIS.fn_SIS_Backup_Limite_Versao();

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_BACKUP', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver os backups.', 1;

        SET @EtapaAtual = 'Consulta';
        SELECT TOP (1) @DtMaisAntigo = b.DT_FIM, @DtInicioAntigo = b.DT_INICIO
        FROM SIS.Backup_Execucao b WITH (NOLOCK)
        WHERE b.TIPO = 'COMPLETO' AND b.SITUACAO = 'OK' AND b.ARQUIVO_EXISTE = 1 AND b.ARQUIVO <> N'' AND b.DT_FIM IS NOT NULL
        ORDER BY b.DT_FIM, b.ID_BACKUP;

        SELECT @DtMaisRecente = MAX(b.DT_FIM)
        FROM SIS.Backup_Execucao b WITH (NOLOCK)
        WHERE b.TIPO IN ('COMPLETO', 'LOG') AND b.SITUACAO = 'OK' AND b.ARQUIVO_EXISTE = 1 AND b.ARQUIVO <> N''
          AND b.DT_INICIO >= @DtInicioAntigo;

        SELECT @DtAteHora = MAX(b.DT_FIM)
        FROM SIS.Backup_Execucao b WITH (NOLOCK)
        WHERE b.TIPO = 'LOG' AND b.SITUACAO = 'OK' AND b.ARQUIVO_EXISTE = 1 AND b.ARQUIVO <> N''
          AND b.DT_INICIO >= @DtInicioAntigo;

        IF @DtMaisAntigo < @DtLimite SET @DtMaisAntigo = @DtLimite;
        IF @DtMaisRecente < @DtMaisAntigo SET @DtMaisRecente = NULL;
        IF @DtAteHora < @DtMaisAntigo SET @DtAteHora = NULL;

        SELECT @DtMaisAntigo  AS DT_PODE_VOLTAR_DE,
               @DtMaisRecente AS DT_PODE_VOLTAR_ATE,
               @DtAteHora     AS DT_PODE_VOLTAR_ATE_HORA,
               CASE WHEN @DtLimite > '1900-01-01' THEN @DtLimite END AS DT_LIMITE_VERSAO,
               CAST(SIS.fn_SIS_Versao_Banco() AS VARCHAR(20)) AS VERSAO,
               (SELECT MAX(b.DT_FIM) FROM SIS.Backup_Execucao b WITH (NOLOCK) WHERE b.TIPO = 'COMPLETO' AND b.SITUACAO = 'OK') AS DT_ULTIMO_COMPLETO,
               (SELECT MAX(b.DT_FIM) FROM SIS.Backup_Execucao b WITH (NOLOCK) WHERE b.TIPO = 'LOG'      AND b.SITUACAO = 'OK') AS DT_ULTIMO_LOG,
               (SELECT MAX(b.DT_FIM) FROM SIS.Backup_Execucao b WITH (NOLOCK) WHERE b.TIPO = 'TESTE'    AND b.SITUACAO = 'OK') AS DT_ULTIMO_TESTE,
               CAST(ISNULL((SELECT COUNT(*) FROM SIS.Backup_Execucao b WITH (NOLOCK)
                            WHERE b.SITUACAO = 'ERRO' AND b.DT_INICIO >= DATEADD(DAY, -7, SYSDATETIME())), 0) AS INT) AS QTD_ERROS_7_DIAS,
               CAST(ISNULL((SELECT TOP (1) r.ID_RESTAURACAO FROM SIS.Backup_Restauracao r WITH (NOLOCK)
                            WHERE r.SITUACAO IN ('PENDENTE', 'EXECUTANDO') ORDER BY r.ID_RESTAURACAO), 0) AS INT) AS ID_RESTAURACAO_ABERTA,
               CAST(ISNULL((SELECT TOP (1) r.SITUACAO FROM SIS.Backup_Restauracao r WITH (NOLOCK)
                            WHERE r.SITUACAO IN ('PENDENTE', 'EXECUTANDO') ORDER BY r.ID_RESTAURACAO), '') AS VARCHAR(12)) AS SITUACAO_ABERTA,
               SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_BACKUP', 'RESTAURAR') AS PODE_RESTAURAR,
               CAST(DB_NAME() AS NVARCHAR(128)) AS BANCO,
               SYSDATETIME() AS DT_AGORA;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível carregar a situação dos backups. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Restauracao_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Restauracao_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Pedidos de restauração e o resultado de cada um, do mais novo
                para o mais antigo (tela Sistema > Backups, SIS_BACKUP, VER).
                Sem permissão: erro 50001.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d2, restauração pela tela).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Backup_Restauracao_Listar @IdUsuario = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Restauracao_Listar]
    @IdUsuario  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Backup_Restauracao_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_BACKUP', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver os backups.', 1;

        SET @EtapaAtual = 'Consulta';
        SELECT r.ID_RESTAURACAO,
               r.TIPO_PONTO,
               CAST(CASE r.TIPO_PONTO WHEN 'BACKUP' THEN N'Backup escolhido' ELSE N'Dia e hora' END AS NVARCHAR(30)) AS TIPO_PONTO_NOME,
               r.ID_BACKUP,
               CAST(ISNULL(b.ARQUIVO, N'') AS NVARCHAR(400)) AS ARQUIVO_BACKUP,
               ISNULL(r.DT_PONTO, b.DT_FIM) AS DT_VOLTA_PARA,
               r.MOTIVO,
               r.SITUACAO,
               CAST(CASE r.SITUACAO WHEN 'PENDENTE' THEN N'Aguardando' WHEN 'EXECUTANDO' THEN N'Restaurando'
                                    WHEN 'OK' THEN N'Concluída' WHEN 'ERRO' THEN N'Com erro' WHEN 'CANCELADO' THEN N'Cancelada'
                                    ELSE N'' END AS NVARCHAR(20)) AS SITUACAO_NOME,
               r.USUARIO_PEDIDO,
               r.DT_PEDIDO,
               r.DT_INICIO,
               r.DT_FIM,
               r.PLANO,
               r.ARQUIVO_SEGURANCA,
               r.MENSAGEM,
               CAST(CASE WHEN r.SITUACAO = 'PENDENTE' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_BACKUP', 'RESTAURAR') = 1
                         THEN 1 ELSE 0 END AS BIT) AS PODE_CANCELAR
        FROM SIS.Backup_Restauracao r WITH (NOLOCK)
        LEFT JOIN SIS.Backup_Execucao b WITH (NOLOCK) ON b.ID_BACKUP = r.ID_BACKUP
        ORDER BY r.ID_RESTAURACAO DESC;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível listar os pedidos de restauração. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Restauracao_Solicitar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Restauracao_Solicitar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Registra um pedido de restauração do banco (tela Sistema >
                Backups, SIS_BACKUP, ação RESTAURAR). Não restaura nada: a
                tarefa do Windows "Restauração (pedidos)" confere os pedidos a
                cada minuto e faz a restauração (o login da API não tem
                permissão para restaurar).
                Confirmação forte: a API confere a senha do usuário
                (@SenhaConferida = 1), o usuário escreve RESTAURAR
                (@Confirmacao) e informa o motivo (mínimo no parâmetro
                BACKUP_RESTAURACAO_MOTIVO_MINIMO).
                @TipoPonto BACKUP: volta para o backup completo ou de
                segurança @IdBackup. DATA_HORA: volta para @DtPonto, com o
                último completo antes dele e os backups do log seguintes
                (fn_SIS_Backup_Plano).
                Um pedido em aberto (PENDENTE ou EXECUTANDO) por vez.
                Avisa por e-mail o EMAIL_ADMIN_ALERTA (se preenchido).
                Devolve 1 linha: SUCESSO, MENSAGEM, ID_RESTAURACAO.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d2, restauração pela tela).
    v1.1 (20/11/2026) - Recusa ponto anterior à atualização para a versão atual
                        do banco (fn_SIS_Backup_Limite_Versao): achado no ensaio.

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Backup_Restauracao_Solicitar @IdUsuario = 1, @TipoPonto = 'DATA_HORA', @DtPonto = '2026-11-20 14:25',
    --      @Motivo = N'teste de homologação', @Confirmacao = N'RESTAURAR', @SenhaConferida = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Restauracao_Solicitar]
    @IdUsuario       INT,
    @TipoPonto       VARCHAR(10),
    @IdBackup        BIGINT        = NULL,
    @DtPonto         DATETIME2(0)  = NULL,
    @Motivo          NVARCHAR(400) = NULL,
    @Confirmacao     NVARCHAR(20)  = NULL,
    @SenhaConferida  BIT           = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[SIS].[SIS_Backup_Restauracao_Solicitar]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Validação';
    DECLARE @Recusa       NVARCHAR(400) = N'';
    DECLARE @MotivoMin    INT;
    DECLARE @Login        NVARCHAR(100);
    DECLARE @Plano        NVARCHAR(4000) = N'';
    DECLARE @QtdLinhas    INT, @QtdSemArquivo INT, @Alcanca INT;
    DECLARE @DtVolta      DATETIME2(0);
    DECLARE @DtLimite     DATETIME2(0)  = SIS.fn_SIS_Backup_Limite_Versao();
    DECLARE @IdRestauracao INT;
    DECLARE @Para NVARCHAR(400), @Corpo NVARCHAR(MAX), @Chave NVARCHAR(200), @IdEmail BIGINT;

    BEGIN TRY
        SET @TipoPonto = UPPER(LTRIM(RTRIM(ISNULL(@TipoPonto, ''))));
        SET @Motivo    = LTRIM(RTRIM(ISNULL(@Motivo, N'')));
        SET @MotivoMin = ISNULL(TRY_CONVERT(INT, SIS.fn_SIS_Parametro('BACKUP_RESTAURACAO_MOTIVO_MINIMO')), 10);

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_BACKUP', 'RESTAURAR') = 0
            SET @Recusa = N'Você não tem permissão para restaurar backup.';
        ELSE IF ISNULL(@SenhaConferida, 0) = 0
            SET @Recusa = N'A senha não confere.';
        ELSE IF UPPER(LTRIM(RTRIM(ISNULL(@Confirmacao, N'')))) <> N'RESTAURAR'
            SET @Recusa = N'Para confirmar, escreva a palavra RESTAURAR.';
        ELSE IF LEN(@Motivo) < @MotivoMin
            SET @Recusa = N'Informe o motivo da restauração (pelo menos ' + CONVERT(NVARCHAR(10), @MotivoMin) + N' letras).';
        ELSE IF @TipoPonto NOT IN ('BACKUP', 'DATA_HORA')
            SET @Recusa = N'Escolha um backup ou um dia e hora para voltar.';
        ELSE IF @TipoPonto = 'BACKUP' AND @IdBackup IS NULL
            SET @Recusa = N'Escolha o backup para voltar.';
        ELSE IF @TipoPonto = 'DATA_HORA' AND @DtPonto IS NULL
            SET @Recusa = N'Informe o dia e a hora para voltar.';
        ELSE IF @TipoPonto = 'DATA_HORA' AND @DtPonto >= SYSDATETIME()
            SET @Recusa = N'O dia e a hora para voltar precisam estar no passado.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS INT) AS ID_RESTAURACAO;
            RETURN;
        END;

        IF @TipoPonto = 'BACKUP' SET @DtPonto = NULL;
        IF @TipoPonto = 'DATA_HORA' SET @IdBackup = NULL;

        SET @EtapaAtual = 'Plano';
        SELECT @QtdLinhas     = COUNT(*),
               @QtdSemArquivo = SUM(CASE WHEN p.ARQUIVO_EXISTE = 0 THEN 1 ELSE 0 END),
               @Alcanca       = MAX(CAST(p.ALCANCA_PONTO AS INT)),
               @DtVolta       = MAX(CASE WHEN p.ORDEM = 0 THEN p.DT_FIM END)
        FROM SIS.fn_SIS_Backup_Plano(@IdBackup, @DtPonto) p;

        SET @Plano = ISNULL(STUFF((SELECT N' | ' + CONVERT(NVARCHAR(10), p.ORDEM) + N': ' + p.ARQUIVO
                                   FROM SIS.fn_SIS_Backup_Plano(@IdBackup, @DtPonto) p
                                   ORDER BY p.ORDEM
                                   FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(MAX)'), 1, 3, N''), N'');

        IF ISNULL(@QtdLinhas, 0) = 0
            SET @Recusa = CASE WHEN @TipoPonto = 'BACKUP' THEN N'Backup não encontrado ou não serve para restaurar. Atualize a lista.'
                               ELSE N'Não há backup completo antes desse dia e hora. Escolha um ponto dentro do período mostrado em "Dá para voltar".' END;
        ELSE IF ISNULL(@QtdSemArquivo, 0) > 0
            SET @Recusa = N'Algum arquivo de backup necessário já foi apagado pela limpeza. Escolha um ponto mais recente.';
        ELSE IF ISNULL(@Alcanca, 0) = 0
            SET @Recusa = N'Ainda não há backup de hora em hora depois desse dia e hora. Escolha um ponto até o último backup ou espere o próximo backup de hora em hora.';
        ELSE IF ISNULL(@DtPonto, @DtVolta) < @DtLimite
            SET @Recusa = N'Não dá para voltar para antes de ' + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(@DtLimite), N'') + N', quando o sistema foi atualizado para a versão '
                        + SIS.fn_SIS_Versao_Banco() + N': o banco ficaria numa versão diferente do programa e o sistema pararia.';
        ELSE IF LEN(@Plano) > 3900
            SET @Recusa = N'O ponto escolhido usa backups demais. Escolha um ponto mais perto de um backup completo.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS INT) AS ID_RESTAURACAO;
            RETURN;
        END;

        SELECT @Login = u.LOGIN FROM SIS.Usuario u WITH (NOLOCK) WHERE u.ID_USUARIO = @IdUsuario;

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

            -- sem ROLLBACK na recusa: nada foi gravado e a rotina pode ser chamada por INSERT ... EXEC (teste)
            IF EXISTS (SELECT 1 FROM SIS.Backup_Restauracao r WITH (UPDLOCK, HOLDLOCK) WHERE r.SITUACAO IN ('PENDENTE', 'EXECUTANDO'))
                SET @Recusa = N'Já existe um pedido de restauração em andamento. Espere terminar ou cancele o pedido que está aguardando.';

            IF @Recusa = N''
            BEGIN
                INSERT INTO SIS.Backup_Restauracao (TIPO_PONTO, ID_BACKUP, DT_PONTO, MOTIVO, SITUACAO, ID_USUARIO_PEDIDO, USUARIO_PEDIDO, PLANO)
                VALUES (@TipoPonto, @IdBackup, @DtPonto, @Motivo, 'PENDENTE', @IdUsuario, ISNULL(@Login, N''), ISNULL(@Plano, N''));
                SET @IdRestauracao = CAST(SCOPE_IDENTITY() AS INT);
            END;

        COMMIT TRANSACTION;

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS INT) AS ID_RESTAURACAO;
            RETURN;
        END;

        SET @EtapaAtual = 'Aviso por e-mail';
        BEGIN TRY
            SET @Para = LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Parametro('EMAIL_ADMIN_ALERTA'), N'')));
            IF @Para <> N''
            BEGIN
                SET @Corpo = SIS.fn_SIS_Email_HTML(N'Pedido de restauração do banco', 'ALERTA',
                    N'<p><b>' + SIS.fn_SIS_Texto_HTML(ISNULL(@Login, N'')) + N'</b> pediu para restaurar o banco <b>' + SIS.fn_SIS_Texto_HTML(DB_NAME())
                    + N'</b>, voltando para <b>' + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(ISNULL(@DtPonto, @DtVolta)), N'') + N'</b>.</p>'
                    + N'<p>Motivo: ' + SIS.fn_SIS_Texto_HTML(@Motivo) + N'</p>'
                    + N'<p>Pedido nº ' + CONVERT(NVARCHAR(10), @IdRestauracao) + N'. O sistema fica fora do ar por alguns minutos durante a restauração.</p>',
                    @NomeProc, NULL, 0);
                SET @Chave = N'RESTAURACAO_PEDIDO_' + CONVERT(NVARCHAR(10), @IdRestauracao);
                EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = N'ALERTA: pedido de restauração do banco', @CorpoHTML = @Corpo,
                     @Tipo = 'ALERTA', @Origem = @NomeProc, @ChaveOrigem = @Chave, @IdEmail = @IdEmail OUTPUT;
            END;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> -1
                INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
                VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        END CATCH;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(N'Pedido de restauração nº ' + CONVERT(NVARCHAR(10), @IdRestauracao)
                    + N' registrado. Em até 1 minuto o sistema sai do ar por alguns minutos para restaurar; depois, entre de novo.' AS NVARCHAR(400)) AS MENSAGEM,
               @IdRestauracao AS ID_RESTAURACAO;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        SELECT CAST(0 AS BIT) AS SUCESSO,
               CAST(N'Não foi possível registrar o pedido de restauração. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(NULL AS INT) AS ID_RESTAURACAO;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Restauracao_Cancelar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Restauracao_Cancelar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Cancela um pedido de restauração que ainda está aguardando
                (PENDENTE), antes de a tarefa do Windows começar (tela
                Sistema > Backups, SIS_BACKUP, ação RESTAURAR). Depois de
                EXECUTANDO não dá mais para cancelar.
                Devolve 1 linha: SUCESSO, MENSAGEM, ID_RESTAURACAO.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d2, restauração pela tela).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Backup_Restauracao_Cancelar @IdUsuario = 1, @IdRestauracao = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Restauracao_Cancelar]
    @IdUsuario      INT,
    @IdRestauracao  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Backup_Restauracao_Cancelar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Linhas     INT;
    DECLARE @Login      NVARCHAR(100);

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_BACKUP', 'RESTAURAR') = 0
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Você não tem permissão para restaurar backup.' AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS INT) AS ID_RESTAURACAO;
            RETURN;
        END;

        SELECT @Login = u.LOGIN FROM SIS.Usuario u WITH (NOLOCK) WHERE u.ID_USUARIO = @IdUsuario;

        SET @EtapaAtual = 'Gravação';
        UPDATE r
           SET r.SITUACAO          = 'CANCELADO',
               r.DT_FIM            = SYSDATETIME(),
               r.MENSAGEM          = LEFT(N'Cancelado por ' + ISNULL(@Login, N'') + N' antes de começar.', 2000),
               r.DT_ALTERACAO      = SYSDATETIME(),
               r.USUARIO_ALTERACAO = ISNULL(@Login, N'')
        FROM SIS.Backup_Restauracao r
        WHERE r.ID_RESTAURACAO = @IdRestauracao
          AND r.SITUACAO = 'PENDENTE';
        SET @Linhas = @@ROWCOUNT;

        IF @Linhas = 0
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO,
                   CAST(N'Este pedido não está mais aguardando (já começou, terminou ou foi cancelado). Atualize a lista.' AS NVARCHAR(400)) AS MENSAGEM,
                   CAST(NULL AS INT) AS ID_RESTAURACAO;
            RETURN;
        END;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Pedido de restauração cancelado.' AS NVARCHAR(400)) AS MENSAGEM, @IdRestauracao AS ID_RESTAURACAO;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        SELECT CAST(0 AS BIT) AS SUCESSO,
               CAST(N'Não foi possível cancelar o pedido. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(NULL AS INT) AS ID_RESTAURACAO;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Restauracao_Resultado.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Restauracao_Resultado]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Grava o resultado (OK ou ERRO) de um pedido de restauração.
                Chamada SÓ pelo script do servidor (e pela Capturar); o login
                da API não pode executar (DENY).
                Depois da restauração o banco volta ao passado e o pedido pode
                não existir mais nele (ou estar como PENDENTE): por isso o
                script manda todos os dados do pedido, e esta rotina grava de
                novo a linha com o MESMO ID (IDENTITY_INSERT), ou atualiza a
                que existe. Os dados que vierem vazios ficam como estão.
                @ArquivoBackup: o backup escolhido (TIPO_PONTO BACKUP) é
                localizado pelo arquivo, porque o ID dele pode ter mudado
                quando o script registrou de novo os backups que faltavam.
                Avisa por e-mail o EMAIL_ADMIN_ALERTA e quem pediu.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d2, restauração pela tela).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Restauracao_Resultado]
    @IdRestauracao     INT,
    @Situacao          VARCHAR(12),
    @Mensagem          NVARCHAR(2000) = N'',
    @TipoPonto         VARCHAR(10)    = NULL,
    @ArquivoBackup     NVARCHAR(400)  = NULL,
    @DtPonto           DATETIME2(0)   = NULL,
    @Motivo            NVARCHAR(400)  = NULL,
    @IdUsuarioPedido   INT            = NULL,
    @UsuarioPedido     NVARCHAR(100)  = NULL,
    @DtPedido          DATETIME2(0)   = NULL,
    @DtInicio          DATETIME2(0)   = NULL,
    @Plano             NVARCHAR(4000) = NULL,
    @ArquivoSeguranca  NVARCHAR(400)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Backup_Restauracao_Resultado]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @IdBackup   BIGINT;
    DECLARE @Agora      DATETIME2(0)  = SYSDATETIME();
    DECLARE @Para NVARCHAR(400), @EmailPedido NVARCHAR(200), @Corpo NVARCHAR(MAX), @Chave NVARCHAR(200), @IdEmail BIGINT;
    DECLARE @Titulo NVARCHAR(200), @Texto NVARCHAR(MAX);
    DECLARE @r TABLE (TIPO_PONTO VARCHAR(10), DT_PONTO DATETIME2(0), ID_BACKUP BIGINT, MOTIVO NVARCHAR(400),
                      ID_USUARIO_PEDIDO INT, USUARIO_PEDIDO NVARCHAR(100), ARQUIVO_SEGURANCA NVARCHAR(400));

    BEGIN TRY
        IF @IdRestauracao IS NULL OR ISNULL(@Situacao, '') NOT IN ('OK', 'ERRO')
            THROW 50000, N'Informe o pedido e a situação (OK ou ERRO).', 1;

        IF NULLIF(LTRIM(RTRIM(ISNULL(@ArquivoBackup, N''))), N'') IS NOT NULL
            SELECT TOP (1) @IdBackup = b.ID_BACKUP
            FROM SIS.Backup_Execucao b
            WHERE b.ARQUIVO = @ArquivoBackup AND b.TIPO IN ('COMPLETO', 'SEGURANCA')
            ORDER BY b.ID_BACKUP DESC;

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

            IF NOT EXISTS (SELECT 1 FROM SIS.Backup_Restauracao r WITH (UPDLOCK, HOLDLOCK) WHERE r.ID_RESTAURACAO = @IdRestauracao)
            BEGIN
                IF ISNULL(@TipoPonto, '') NOT IN ('BACKUP', 'DATA_HORA')
                   OR (@TipoPonto = 'BACKUP' AND @IdBackup IS NULL)
                   OR (@TipoPonto = 'DATA_HORA' AND @DtPonto IS NULL)
                    THROW 50000, N'Pedido não existe no banco restaurado e faltam os dados para gravar de novo (tipo, backup ou dia e hora).', 1;

                SET IDENTITY_INSERT SIS.Backup_Restauracao ON;
                INSERT INTO SIS.Backup_Restauracao (ID_RESTAURACAO, TIPO_PONTO, ID_BACKUP, DT_PONTO, MOTIVO, SITUACAO, ID_USUARIO_PEDIDO, USUARIO_PEDIDO,
                                                    DT_PEDIDO, DT_INICIO, DT_FIM, PLANO, ARQUIVO_SEGURANCA, MENSAGEM, USUARIO_CRIACAO)
                VALUES (@IdRestauracao, @TipoPonto, CASE WHEN @TipoPonto = 'BACKUP' THEN @IdBackup END, CASE WHEN @TipoPonto = 'DATA_HORA' THEN @DtPonto END,
                        ISNULL(@Motivo, N''), @Situacao, ISNULL(@IdUsuarioPedido, 0), ISNULL(@UsuarioPedido, N''),
                        ISNULL(@DtPedido, @Agora), ISNULL(@DtInicio, @Agora), @Agora, ISNULL(@Plano, N''), ISNULL(@ArquivoSeguranca, N''),
                        LEFT(ISNULL(@Mensagem, N''), 2000), N'restauracao');
                SET IDENTITY_INSERT SIS.Backup_Restauracao OFF;
            END;

            UPDATE r
               SET r.SITUACAO          = @Situacao,
                   r.ID_BACKUP         = CASE WHEN r.TIPO_PONTO = 'BACKUP' THEN ISNULL(@IdBackup, r.ID_BACKUP) ELSE r.ID_BACKUP END,
                   r.DT_INICIO         = ISNULL(r.DT_INICIO, ISNULL(@DtInicio, @Agora)),
                   r.DT_FIM            = @Agora,
                   r.PLANO             = CASE WHEN ISNULL(@Plano, N'') <> N'' THEN @Plano ELSE r.PLANO END,
                   r.ARQUIVO_SEGURANCA = CASE WHEN ISNULL(@ArquivoSeguranca, N'') <> N'' THEN @ArquivoSeguranca ELSE r.ARQUIVO_SEGURANCA END,
                   r.MENSAGEM          = LEFT(ISNULL(@Mensagem, N''), 2000),
                   r.DT_ALTERACAO      = @Agora,
                   r.USUARIO_ALTERACAO = N'restauracao'
            OUTPUT inserted.TIPO_PONTO, inserted.DT_PONTO, inserted.ID_BACKUP, inserted.MOTIVO, inserted.ID_USUARIO_PEDIDO, inserted.USUARIO_PEDIDO, inserted.ARQUIVO_SEGURANCA
            INTO @r
            FROM SIS.Backup_Restauracao r
            WHERE r.ID_RESTAURACAO = @IdRestauracao;

        COMMIT TRANSACTION;

        SET @EtapaAtual = 'Aviso por e-mail';
        BEGIN TRY
            SET @Para = LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Parametro('EMAIL_ADMIN_ALERTA'), N'')));
            SELECT @EmailPedido = LTRIM(RTRIM(ISNULL(u.EMAIL, N'')))
            FROM @r x INNER JOIN SIS.Usuario u ON u.ID_USUARIO = x.ID_USUARIO_PEDIDO;
            IF ISNULL(@EmailPedido, N'') <> N'' AND CHARINDEX(@EmailPedido, @Para) = 0
                SET @Para = CASE WHEN @Para = N'' THEN @EmailPedido ELSE @Para + N';' + @EmailPedido END;

            IF @Para <> N''
            BEGIN
                SET @Titulo = CASE WHEN @Situacao = 'OK' THEN N'Restauração do banco concluída' ELSE N'Falha na restauração do banco' END;
                SELECT @Texto = N'<p>Pedido nº ' + CONVERT(NVARCHAR(10), @IdRestauracao) + N', feito por <b>' + SIS.fn_SIS_Texto_HTML(ISNULL(x.USUARIO_PEDIDO, N''))
                              + N'</b>, banco <b>' + SIS.fn_SIS_Texto_HTML(DB_NAME()) + N'</b>.</p>'
                              + N'<p>Voltar para: <b>' + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(ISNULL(x.DT_PONTO, b.DT_FIM)), N'') + N'</b>.</p>'
                              + N'<p>Motivo: ' + SIS.fn_SIS_Texto_HTML(ISNULL(x.MOTIVO, N'')) + N'</p>'
                              + N'<p>Resultado: ' + SIS.fn_SIS_Texto_HTML(ISNULL(@Mensagem, N'')) + N'</p>'
                              + CASE WHEN ISNULL(x.ARQUIVO_SEGURANCA, N'') <> N''
                                     THEN N'<p>Backup de segurança feito antes (para desfazer, se preciso): ' + SIS.fn_SIS_Texto_HTML(x.ARQUIVO_SEGURANCA) + N'</p>' ELSE N'' END
                FROM @r x
                LEFT JOIN SIS.Backup_Execucao b ON b.ID_BACKUP = x.ID_BACKUP;

                SET @Corpo = SIS.fn_SIS_Email_HTML(@Titulo, 'ALERTA', ISNULL(@Texto, N''), @NomeProc, NULL, 0);
                SET @Chave = N'RESTAURACAO_RESULTADO_' + CONVERT(NVARCHAR(10), @IdRestauracao) + N'_' + @Situacao;
                SET @Titulo = CASE WHEN @Situacao = 'OK' THEN N'AVISO: restauração do banco concluída' ELSE N'ALERTA: falha na restauração do banco' END;
                EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = @Titulo, @CorpoHTML = @Corpo,
                     @Tipo = 'ALERTA', @Origem = @NomeProc, @ChaveOrigem = @Chave, @IdEmail = @IdEmail OUTPUT;
            END;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> -1
                INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
                VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        END CATCH;

        SELECT @IdRestauracao AS ID_RESTAURACAO, @Situacao AS SITUACAO;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Backup_Restauracao_Capturar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Backup_Restauracao_Capturar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 20/11/2026
  Descrição   : Chamada SÓ pelo script do servidor (instalacao\backup_servidor.ps1,
                tarefa "Restauração (pedidos)", a cada minuto, como SYSTEM). O
                login da API não pode executar (DENY no papel rl_sistemacmj_api).
                Pega o pedido PENDENTE mais antigo, marca EXECUTANDO e devolve o
                plano: uma linha por arquivo a aplicar, na ordem (ORDEM 0 = o
                backup completo; 1, 2... = os backups do log; ULTIMO = 1 na
                última linha, aplicada com STOPAT quando TIPO_PONTO = DATA_HORA).
                Sem pedido, ou com outro pedido já EXECUTANDO: devolve 0 linhas.
                Se o plano não fecha mais (arquivo apagado pela limpeza), marca
                o pedido como ERRO, avisa por e-mail e devolve 0 linhas.

  Changelog:
    v1.0 (20/11/2026) - Criação (etapa 03d2, restauração pela tela).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Backup_Restauracao_Capturar]
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Backup_Restauracao_Capturar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Captura';
    DECLARE @Capturado  TABLE (ID_RESTAURACAO INT NOT NULL);
    DECLARE @Id INT, @IdBackup BIGINT, @DtPonto DATETIME2(0);
    DECLARE @QtdLinhas INT, @QtdSemArquivo INT, @Alcanca INT;
    DECLARE @Erro NVARCHAR(400) = N'';
    DECLARE @Resultado  TABLE (ID_RESTAURACAO INT, SITUACAO VARCHAR(12));

    BEGIN TRY
        IF EXISTS (SELECT 1 FROM SIS.Backup_Restauracao r WHERE r.SITUACAO = 'EXECUTANDO')
            RETURN;

        BEGIN TRANSACTION;
            WITH Proximo AS
            (
                SELECT TOP (1) r.*
                FROM SIS.Backup_Restauracao r WITH (UPDLOCK, READPAST, ROWLOCK)
                WHERE r.SITUACAO = 'PENDENTE'
                ORDER BY r.ID_RESTAURACAO
            )
            UPDATE Proximo
               SET SITUACAO          = 'EXECUTANDO',
                   DT_INICIO         = SYSDATETIME(),
                   MENSAGEM          = N'',
                   DT_ALTERACAO      = SYSDATETIME(),
                   USUARIO_ALTERACAO = N'restauracao'
            OUTPUT inserted.ID_RESTAURACAO INTO @Capturado (ID_RESTAURACAO);
        COMMIT TRANSACTION;

        SELECT @Id = c.ID_RESTAURACAO FROM @Capturado c;
        IF @Id IS NULL RETURN;

        SELECT @IdBackup = r.ID_BACKUP, @DtPonto = r.DT_PONTO FROM SIS.Backup_Restauracao r WHERE r.ID_RESTAURACAO = @Id;

        SET @EtapaAtual = 'Plano';
        SELECT @QtdLinhas     = COUNT(*),
               @QtdSemArquivo = SUM(CASE WHEN p.ARQUIVO_EXISTE = 0 THEN 1 ELSE 0 END),
               @Alcanca       = MAX(CAST(p.ALCANCA_PONTO AS INT))
        FROM SIS.fn_SIS_Backup_Plano(@IdBackup, @DtPonto) p;

        IF ISNULL(@QtdLinhas, 0) = 0 OR ISNULL(@QtdSemArquivo, 0) > 0 OR ISNULL(@Alcanca, 0) = 0
            SET @Erro = N'O plano da restauração não fecha mais (backup não encontrado ou arquivo apagado pela limpeza). Nada foi restaurado; faça um pedido novo.';

        IF @Erro <> N''
        BEGIN
            INSERT INTO @Resultado (ID_RESTAURACAO, SITUACAO)
            EXEC SIS.SIS_Backup_Restauracao_Resultado @IdRestauracao = @Id, @Situacao = 'ERRO', @Mensagem = @Erro;
            RETURN;
        END;

        SELECT r.ID_RESTAURACAO, r.TIPO_PONTO, r.DT_PONTO, r.ID_BACKUP, r.MOTIVO, r.USUARIO_PEDIDO, r.ID_USUARIO_PEDIDO, r.DT_PEDIDO, r.DT_INICIO,
               p.ORDEM, p.ID_BACKUP AS ID_BACKUP_ARQUIVO, p.TIPO, p.ARQUIVO, p.DT_INICIO AS DT_INICIO_ARQUIVO, p.DT_FIM AS DT_FIM_ARQUIVO,
               CAST(CASE WHEN p.ORDEM = MAX(p.ORDEM) OVER () THEN 1 ELSE 0 END AS BIT) AS ULTIMO
        FROM SIS.Backup_Restauracao r
        CROSS JOIN SIS.fn_SIS_Backup_Plano(@IdBackup, @DtPonto) p
        WHERE r.ID_RESTAURACAO = @Id
        ORDER BY p.ORDEM;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Ajuda_Geral_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Ajuda_Geral_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Porta de entrada da ajuda exclusiva do administrador geral
                (pedido 3 de 16/11/2026; CLAUDE.md seção 3.8). A API chama
                antes de entregar o índice ou uma página da pasta AjudaGeral
                (embutida no executável, sem endereço direto).
                Permissão: SIS_AJUDA_GERAL / VER. A tela é EXCLUSIVO_GERAL,
                então só o nível 2 passa (vw_SIS_Permissao_Efetiva).
                Toda consulta fica registrada em SIS.Log_Passo (ROTINA desta
                procedure): STATUS OK = entregue, AVISO = recusada.
                Recusa devolve a mesma mensagem de "página não encontrada",
                para não revelar que a página existe.
                Devolve 1 linha: SUCESSO, MENSAGEM (regra 18).
                @Pagina vazia = índice.

  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 03g, ajuda do administrador geral).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Ajuda_Geral_Obter @IdUsuario = 2, @Pagina = 'licenca', @Estacao = N'127.0.0.1';
    -- SELECT TOP 10 * FROM SIS.Log_Passo WHERE ROTINA = N'[SIS].[SIS_Ajuda_Geral_Obter]' ORDER BY ID_LOG_PASSO DESC;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Ajuda_Geral_Obter]
    @IdUsuario  INT,
    @Pagina     VARCHAR(60)    = NULL,
    @Estacao    NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Ajuda_Geral_Obter]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Login      NVARCHAR(100) = N'';
    DECLARE @Pode       BIT;
    DECLARE @Detalhe    NVARCHAR(4000);

    BEGIN TRY
        SET @Pagina  = ISNULL(LTRIM(RTRIM(@Pagina)), '');
        SET @Estacao = ISNULL(LTRIM(RTRIM(@Estacao)), N'');
        SET @Pode    = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_AJUDA_GERAL', 'VER');

        SELECT @Login = u.LOGIN FROM SIS.Usuario u WITH (NOLOCK) WHERE u.ID_USUARIO = @IdUsuario;
        SET @Detalhe = LEFT(N'Usuário ' + ISNULL(@Login, N'') + N' (ID ' + ISNULL(CAST(@IdUsuario AS NVARCHAR(12)), N'') + N')'
                          + CASE WHEN @Estacao <> N'' THEN N', estação ' + @Estacao ELSE N'' END, 4000);

        SET @EtapaAtual = 'Registro';
        INSERT INTO SIS.Log_Passo (RUN_ID, ROTINA, ETAPA, STATUS, DETALHE, DT_PASSO)
        VALUES (NEWID(), @NomeProc,
                LEFT(CASE WHEN @Pode = 1 THEN N'Consulta: ' ELSE N'Recusada: ' END + CASE WHEN @Pagina = '' THEN N'(índice)' ELSE CAST(@Pagina AS NVARCHAR(60)) END, 200),
                CASE WHEN @Pode = 1 THEN 'OK' ELSE 'AVISO' END,
                ISNULL(@Detalhe, N''), SYSDATETIME());

        IF @Pode = 0
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Página não encontrada.' AS NVARCHAR(400)) AS MENSAGEM;
            RETURN;
        END;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'' AS NVARCHAR(400)) AS MENSAGEM;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        SELECT CAST(0 AS BIT) AS SUCESSO,
               CAST(N'Não foi possível abrir a ajuda. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Atualizacao_Registrar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Atualizacao_Registrar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Registra uma atualização de versão em SIS.Atualizacao. Chamada SÓ
                pelo atualizar.ps1 do pacote (atualização em um clique, 03h),
                rodado pelo administrador do Windows; o login da API não pode
                executar (DENY no papel rl_sistemacmj_api).
                Situação DESFEITA ou ERRO: manda aviso por e-mail para o
                parâmetro EMAIL_ADMIN_ALERTA (se preenchido).
                Situação CONCLUIDA: manda a nota da versão ao grupo
                VERSAO_AVISO_GRUPO (se VERSAO_AVISO_EMAIL_ATIVO = S).
                Devolve 1 linha: SUCESSO, MENSAGEM, ID_GERADO.

  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 03h, banco 1.8).
    v1.1 (23/11/2026) - Etapa 04c (P22): atualização CONCLUIDA manda a nota das
                        versões novas (SIS.Versao_Nota, só itens para todos)
                        por e-mail ao grupo do parâmetro VERSAO_AVISO_GRUPO,
                        se VERSAO_AVISO_EMAIL_ATIVO = S. Falha no e-mail não
                        desfaz o registro (só vai para o log).

  Homologação:
    -- sql/testes/SIS/03h_Homologacao_Atualizacao.sql
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Atualizacao_Registrar]
    @VersaoProgramaDe    VARCHAR(20)    = '',
    @VersaoProgramaPara  VARCHAR(20),
    @VersaoBancoDe       VARCHAR(20)    = '',
    @VersaoBancoPara     VARCHAR(20),
    @DtInicio            DATETIME2(0),
    @DtFim               DATETIME2(0)   = NULL,
    @SegundosFora        INT            = 0,
    @Situacao            VARCHAR(10),
    @Mensagem            NVARCHAR(2000) = N'',
    @Notas               NVARCHAR(MAX)  = N'',
    @Pacote              NVARCHAR(260)  = N''
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @EtapaAtual VARCHAR(100) = 'Conferência', @Id INT, @Para NVARCHAR(400), @Corpo NVARCHAR(MAX),
            @Chave NVARCHAR(200), @IdEmail BIGINT, @Agora DATETIME2(0) = SYSDATETIME(),
            @Grupo VARCHAR(30), @Itens NVARCHAR(MAX), @De INT, @Ate INT, @Sistema NVARCHAR(100);

    BEGIN TRY
        IF ISNULL(@Situacao, '') NOT IN ('CONCLUIDA', 'DESFEITA', 'ERRO')
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Situação inválida: use CONCLUIDA, DESFEITA ou ERRO.' AS NVARCHAR(400)) AS MENSAGEM, CAST(0 AS INT) AS ID_GERADO;
            RETURN;
        END;
        IF LTRIM(RTRIM(ISNULL(@VersaoProgramaPara, ''))) = '' OR LTRIM(RTRIM(ISNULL(@VersaoBancoPara, ''))) = '' OR @DtInicio IS NULL
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Informe as versões novas e o início da atualização.' AS NVARCHAR(400)) AS MENSAGEM, CAST(0 AS INT) AS ID_GERADO;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        INSERT INTO SIS.Atualizacao (VERSAO_PROGRAMA_DE, VERSAO_PROGRAMA_PARA, VERSAO_BANCO_DE, VERSAO_BANCO_PARA, DT_INICIO, DT_FIM,
                                     SEGUNDOS_FORA, SITUACAO, MENSAGEM, NOTAS, PACOTE)
        VALUES (ISNULL(@VersaoProgramaDe, ''), @VersaoProgramaPara, ISNULL(@VersaoBancoDe, ''), @VersaoBancoPara, @DtInicio, ISNULL(@DtFim, @Agora),
                ISNULL(@SegundosFora, 0), @Situacao, LEFT(ISNULL(@Mensagem, N''), 2000), ISNULL(@Notas, N''), LEFT(ISNULL(@Pacote, N''), 260));
        SET @Id = CAST(SCOPE_IDENTITY() AS INT);

        SET @EtapaAtual = 'Aviso por e-mail';
        IF @Situacao IN ('DESFEITA', 'ERRO')
        BEGIN
            SET @Para = LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Parametro('EMAIL_ADMIN_ALERTA'), N'')));
            IF @Para <> N''
            BEGIN
                SET @Corpo = SIS.fn_SIS_Email_HTML(N'Atualização de versão ' + CASE @Situacao WHEN 'DESFEITA' THEN N'desfeita' ELSE N'com erro' END, 'ALERTA',
                    N'<p>A atualização do sistema para a versão <b>' + SIS.fn_SIS_Texto_HTML(@VersaoBancoPara) + N'</b> (a versão era '
                    + SIS.fn_SIS_Texto_HTML(ISNULL(@VersaoBancoDe, '')) + N') no banco <b>' + SIS.fn_SIS_Texto_HTML(DB_NAME()) + N'</b> terminou como <b>'
                    + CASE @Situacao WHEN 'DESFEITA' THEN N'DESFEITA (voltou sozinha para a versão anterior)' ELSE N'ERRO (não conseguiu voltar sozinha: conferir o servidor)' END
                    + N'</b> em ' + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(ISNULL(@DtFim, @Agora)), N'') + N'.</p><p>Motivo: ' + SIS.fn_SIS_Texto_HTML(ISNULL(@Mensagem, N'')) + N'</p>',
                    N'[SIS].[SIS_Atualizacao_Registrar]', NULL, 0);
                SET @Chave = N'ATUALIZACAO_' + CONVERT(NVARCHAR(20), @Id);
                EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = N'ALERTA: atualização do sistema não concluída', @CorpoHTML = @Corpo,
                     @Tipo = 'ALERTA', @Origem = N'[SIS].[SIS_Atualizacao_Registrar]', @ChaveOrigem = @Chave, @IdEmail = @IdEmail OUTPUT;
            END;
        END;

        IF @Situacao = 'CONCLUIDA' AND SIS.fn_SIS_Parametro_SN('VERSAO_AVISO_EMAIL_ATIVO') = 1
        BEGIN
        BEGIN TRY
            SET @EtapaAtual = 'Nota da versão por e-mail';
            SET @Grupo = CONVERT(VARCHAR(30), LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Parametro('VERSAO_AVISO_GRUPO'), N''))));
            SET @Para  = CASE WHEN @Grupo = '' THEN N'' ELSE LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Emails_Do_Grupo(@Grupo), N''))) END;
            SET @De    = SIS.fn_SIS_Versao_Numero(@VersaoBancoDe);
            SET @Ate   = SIS.fn_SIS_Versao_Numero(@VersaoBancoPara);

            SELECT @Itens = STRING_AGG(CAST(N'<p style="margin:16px 0 4px 0;font-weight:bold;">Versão ' + SIS.fn_SIS_Texto_HTML(v.VERSAO)
                                            + CASE WHEN v.DT_VERSAO IS NULL THEN N'' ELSE N' (' + CONVERT(NVARCHAR(10), v.DT_VERSAO, 103) + N')' END
                                            + N'</p><ul style="margin:0;padding-left:20px;">' + v.ITENS + N'</ul>' AS NVARCHAR(MAX)), N'')
                          WITHIN GROUP (ORDER BY v.VERSAO_NUMERO DESC)
            FROM (SELECT n.VERSAO, n.VERSAO_NUMERO, MAX(n.DT_VERSAO) AS DT_VERSAO,
                         STRING_AGG(CAST(N'<li style="margin-bottom:6px;"><b>' + CASE n.TIPO WHEN 'NOVO' THEN N'Novo' WHEN 'MELHORIA' THEN N'Melhoria' ELSE N'Correção' END
                                         + N':</b> ' + ISNULL(n.TEXTO_HTML, N'') + N'</li>' AS NVARCHAR(MAX)), N'') WITHIN GROUP (ORDER BY n.ORDEM) AS ITENS
                  FROM SIS.Versao_Nota n WITH (NOLOCK)
                  WHERE n.PUBLICO = 'TODOS' AND n.VERSAO_NUMERO > @De AND n.VERSAO_NUMERO <= @Ate
                  GROUP BY n.VERSAO, n.VERSAO_NUMERO) v;

            IF @Para = N''
                INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
                VALUES (N'[SIS].[SIS_Atualizacao_Registrar]', @EtapaAtual, 0, N'Nota da versão não enviada: o grupo de e-mail do parâmetro VERSAO_AVISO_GRUPO está vazio ou sem destinatário.', 0, SYSDATETIME());

            IF @Para <> N'' AND ISNULL(@Itens, N'') <> N''
            BEGIN
                SET @Sistema = ISNULL(NULLIF(LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Parametro('SISTEMA_NOME'), N''))), N''), N'sistema');
                SET @Corpo = SIS.fn_SIS_Email_HTML(N'Nova versão do ' + @Sistema + N': ' + ISNULL(@VersaoBancoPara, ''), 'INFO',
                    N'<p>O ' + SIS.fn_SIS_Texto_HTML(@Sistema) + N' foi atualizado para a versão <b>' + SIS.fn_SIS_Texto_HTML(@VersaoBancoPara) + N'</b> em '
                    + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(ISNULL(@DtFim, @Agora)), N'') + N'. O sistema ficou fora do ar por '
                    + CONVERT(NVARCHAR(10), ISNULL(@SegundosFora, 0)) + N' segundo(s).</p><p>Veja o que mudou:</p>' + @Itens
                    + N'<p style="margin-top:16px;">As notas de todas as versões ficam em Sistema › Versões.</p>',
                    N'[SIS].[SIS_Atualizacao_Registrar]', @Grupo, 0);
                SET @Chave = N'VERSAO_NOTA_' + CONVERT(NVARCHAR(20), @Id);
                EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = N'Nova versão do sistema instalada', @CorpoHTML = @Corpo,
                     @Tipo = 'NOTA_VERSAO', @Origem = N'[SIS].[SIS_Atualizacao_Registrar]', @ChaveOrigem = @Chave, @IdEmail = @IdEmail OUTPUT;
            END;
        END TRY
        BEGIN CATCH
            IF XACT_STATE() <> -1
                INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
                VALUES (N'[SIS].[SIS_Atualizacao_Registrar]', @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        END CATCH;
        END;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Atualização registrada.' AS NVARCHAR(400)) AS MENSAGEM, CAST(@Id AS INT) AS ID_GERADO;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (N'[SIS].[SIS_Atualizacao_Registrar]', @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Erro ao registrar a atualização: o erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, CAST(ISNULL(@Id, 0) AS INT) AS ID_GERADO;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Tabela_Trava_Conferir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Tabela_Trava_Conferir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Travas configuradas em SIS.Tabela_Config para mexer num
                registro pela lixeira ou pelo desfazer (P20):
                  1) mês fechado: com COLUNA_EMPRESA e COLUNA_DATA_MES
                     preenchidas, recusa se o mês da data do registro (ou da
                     data nova, @DataNova) estiver fechado em FIN.Mes_Fechado;
                  2) PROC_VALIDAR: chama a procedure própria da tabela
                     (@Tabela, @IdRegistro, @Operacao, @Mensagem OUTPUT).
                @Mensagem vazia = pode. Uso interno (chamada pelas procedures
                da lixeira e do desfazer); a API não chama (DENY).
                @Operacao: LIXEIRA, RECUPERAR, APAGAR ou DESFAZER.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Tabela_Trava_Conferir]
    @Tabela      NVARCHAR(256),
    @IdRegistro  BIGINT,
    @Operacao    VARCHAR(20),
    @DataNova    DATE = NULL,
    @Mensagem    NVARCHAR(400) OUTPUT
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ColEmpresa NVARCHAR(128), @ColData NVARCHAR(128), @Proc NVARCHAR(256);
    DECLARE @ObjId INT = OBJECT_ID(@Tabela, N'U');
    DECLARE @Pk NVARCHAR(128) = SIS.fn_SIS_Tabela_PK(@Tabela);
    DECLARE @Sql NVARCHAR(MAX), @IdEmpresa INT, @Data DATE, @Mes DATE, @Msg NVARCHAR(400);

    SET @Mensagem = N'';

    SELECT @ColEmpresa = c.COLUNA_EMPRESA, @ColData = c.COLUNA_DATA_MES, @Proc = c.PROC_VALIDAR
    FROM SIS.Tabela_Config c
    WHERE c.TABELA = @Tabela AND c.ATIVO = 1;

    IF @ObjId IS NULL OR @Pk = N'' RETURN;

    -- 1) Mês fechado
    IF ISNULL(@ColEmpresa, N'') <> N'' AND ISNULL(@ColData, N'') <> N''
    BEGIN
        SET @Sql = N'SELECT @e = TRY_CONVERT(INT, t.' + QUOTENAME(@ColEmpresa) + N'), @d = TRY_CONVERT(DATE, t.' + QUOTENAME(@ColData) + N')'
                 + N' FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId)) + N' t'
                 + N' WHERE t.' + QUOTENAME(@Pk) + N' = @Id;';
        EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @e INT OUTPUT, @d DATE OUTPUT', @Id = @IdRegistro, @e = @IdEmpresa OUTPUT, @d = @Data OUTPUT;

        SELECT TOP 1 @Mes = m.MES
        FROM FIN.Mes_Fechado m
        WHERE m.ID_EMPRESA = @IdEmpresa
          AND m.FECHADO = 1
          AND (   (@Data IS NOT NULL     AND m.MES = DATEFROMPARTS(YEAR(@Data), MONTH(@Data), 1))
               OR (@DataNova IS NOT NULL AND m.MES = DATEFROMPARTS(YEAR(@DataNova), MONTH(@DataNova), 1)))
        ORDER BY m.MES;

        IF @Mes IS NOT NULL
        BEGIN
            SET @Mensagem = N'O mês ' + RIGHT(N'0' + CAST(MONTH(@Mes) AS NVARCHAR(2)), 2) + N'/' + CAST(YEAR(@Mes) AS NVARCHAR(4))
                          + N' está fechado para esta empresa. Reabra o mês antes.';
            RETURN;
        END;
    END;

    -- 2) Trava própria da tabela
    IF ISNULL(@Proc, N'') <> N'' AND OBJECT_ID(@Proc, N'P') IS NOT NULL
    BEGIN
        SET @Sql = N'EXEC ' + QUOTENAME(OBJECT_SCHEMA_NAME(OBJECT_ID(@Proc, N'P'))) + N'.' + QUOTENAME(OBJECT_NAME(OBJECT_ID(@Proc, N'P')))
                 + N' @Tabela = @Tabela, @IdRegistro = @IdRegistro, @Operacao = @Operacao, @Mensagem = @Msg OUTPUT;';
        EXEC sys.sp_executesql @Sql, N'@Tabela NVARCHAR(256), @IdRegistro BIGINT, @Operacao VARCHAR(20), @Msg NVARCHAR(400) OUTPUT',
             @Tabela = @Tabela, @IdRegistro = @IdRegistro, @Operacao = @Operacao, @Msg = @Msg OUTPUT;
        SET @Mensagem = ISNULL(@Msg, N'');
    END;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Referencias.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Referencias]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Conta onde um registro é usado, para saber se pode ir para a
                lixeira e se pode ser apagado de vez (P20). Lê as chaves
                estrangeiras do próprio banco (nada fixo no código):
                  - linhas de outras tabelas que apontam para o registro,
                    menos as tabelas filhas que "vão junto"
                    (SIS.Tabela_Config.TABELAS_FILHAS);
                  - linhas que apontam para as filhas deste registro;
                  - anexos ativos (SIS.Anexo) do registro.
                @Qtd = total de usos; @Onde = nome da tela (ou tabela) do
                primeiro uso encontrado. Uso interno (DENY para a API).
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- DECLARE @q INT, @o NVARCHAR(400);
    -- EXEC SIS.SIS_Lixeira_Referencias @Tabela = N'CAD.Empresa', @IdRegistro = 1, @Qtd = @q OUTPUT, @Onde = @o OUTPUT; SELECT @q, @o;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Referencias]
    @Tabela      NVARCHAR(256),
    @IdRegistro  BIGINT,
    @Qtd         INT           OUTPUT,
    @Onde        NVARCHAR(400) OUTPUT
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ObjId INT = OBJECT_ID(@Tabela, N'U');
    DECLARE @Filhas TABLE (TABELA NVARCHAR(256) NOT NULL, COLUNA NVARCHAR(128) NOT NULL, OBJ INT NULL, PK NVARCHAR(128) NULL);
    DECLARE @Refs   TABLE (ORDEM INT IDENTITY(1,1) NOT NULL, COMANDO NVARCHAR(MAX) NOT NULL, TABELA NVARCHAR(256) NOT NULL);
    DECLARE @i INT = 1, @Total INT, @n BIGINT, @Cmd NVARCHAR(MAX), @TabRef NVARCHAR(256);

    SET @Qtd = 0;
    SET @Onde = N'';
    IF @ObjId IS NULL OR @IdRegistro IS NULL RETURN;

    INSERT INTO @Filhas (TABELA, COLUNA)
    SELECT LEFT(x.v, LEN(x.v) - CHARINDEX(N'.', REVERSE(x.v))), RIGHT(x.v, CHARINDEX(N'.', REVERSE(x.v)) - 1)
    FROM SIS.Tabela_Config c
    CROSS APPLY (SELECT LTRIM(RTRIM(s.value)) AS v FROM STRING_SPLIT(c.TABELAS_FILHAS, N',') s) x
    WHERE c.TABELA = @Tabela
      AND x.v LIKE N'%_._%._%';

    UPDATE f SET f.OBJ = OBJECT_ID(f.TABELA, N'U'), f.PK = SIS.fn_SIS_Tabela_PK(f.TABELA) FROM @Filhas f;
    DELETE FROM @Filhas WHERE OBJ IS NULL OR ISNULL(PK, N'') = N'';

    -- Quem aponta direto para o registro (menos as filhas que vão junto)
    INSERT INTO @Refs (COMANDO, TABELA)
    SELECT N'SELECT @n = COUNT_BIG(*) FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(fk.parent_object_id)) + N'.' + QUOTENAME(OBJECT_NAME(fk.parent_object_id))
         + N' WITH (NOLOCK) WHERE ' + QUOTENAME(pc.name) + N' = @Id;',
           OBJECT_SCHEMA_NAME(fk.parent_object_id) + N'.' + OBJECT_NAME(fk.parent_object_id)
    FROM sys.foreign_keys fk
    INNER JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id = fk.object_id
    INNER JOIN sys.columns pc ON pc.object_id = fkc.parent_object_id AND pc.column_id = fkc.parent_column_id
    WHERE fk.referenced_object_id = @ObjId
      AND (SELECT COUNT(*) FROM sys.foreign_key_columns x WHERE x.constraint_object_id = fk.object_id) = 1
      AND NOT EXISTS (SELECT 1 FROM @Filhas f WHERE f.OBJ = fk.parent_object_id AND f.COLUNA = pc.name)
    ORDER BY fk.name;

    -- Quem aponta para as filhas deste registro
    INSERT INTO @Refs (COMANDO, TABELA)
    SELECT N'SELECT @n = COUNT_BIG(*) FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(fk.parent_object_id)) + N'.' + QUOTENAME(OBJECT_NAME(fk.parent_object_id))
         + N' r WITH (NOLOCK) WHERE r.' + QUOTENAME(pc.name) + N' IN (SELECT f.' + QUOTENAME(f.PK)
         + N' FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(f.OBJ)) + N'.' + QUOTENAME(OBJECT_NAME(f.OBJ)) + N' f WITH (NOLOCK) WHERE f.' + QUOTENAME(f.COLUNA) + N' = @Id);',
           OBJECT_SCHEMA_NAME(fk.parent_object_id) + N'.' + OBJECT_NAME(fk.parent_object_id)
    FROM @Filhas f
    INNER JOIN sys.foreign_keys fk ON fk.referenced_object_id = f.OBJ
    INNER JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id = fk.object_id
    INNER JOIN sys.columns pc ON pc.object_id = fkc.parent_object_id AND pc.column_id = fkc.parent_column_id
    WHERE (SELECT COUNT(*) FROM sys.foreign_key_columns x WHERE x.constraint_object_id = fk.object_id) = 1
      AND fk.parent_object_id <> @ObjId
    ORDER BY fk.name;

    SELECT @Total = COUNT(*) FROM @Refs;
    WHILE @i <= @Total
    BEGIN
        SELECT @Cmd = r.COMANDO, @TabRef = r.TABELA FROM @Refs r WHERE r.ORDEM = @i;
        SET @n = 0;
        EXEC sys.sp_executesql @Cmd, N'@Id BIGINT, @n BIGINT OUTPUT', @Id = @IdRegistro, @n = @n OUTPUT;
        IF ISNULL(@n, 0) > 0
        BEGIN
            IF @Onde = N''
                SET @Onde = ISNULL((SELECT TOP 1 i.NOME FROM SIS.Item i WHERE i.CODIGO = SIS.fn_SIS_Item_Da_Tabela(@TabRef)), @TabRef);
            SET @Qtd = @Qtd + CAST(@n AS INT);
        END;
        SET @i = @i + 1;
    END;

    -- Anexos ativos do registro
    SELECT @n = COUNT_BIG(*)
    FROM SIS.Anexo a WITH (NOLOCK)
    WHERE a.TABELA_REFERENCIA = @Tabela AND a.ID_REFERENCIA = @IdRegistro AND a.SITUACAO = 'ATIVO';
    IF ISNULL(@n, 0) > 0
    BEGIN
        IF @Onde = N'' SET @Onde = N'anexos';
        SET @Qtd = @Qtd + CAST(@n AS INT);
    END;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Marcar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Marcar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Manda um registro para a lixeira (P20): confere a
                configuração da tabela, o parâmetro LIXEIRA_ATIVA, se o
                registro existe e não está na lixeira, se nada usa o registro
                (SIS_Lixeira_Referencias) e as travas (mês fechado e trava
                própria); então desativa o registro, preenche DT_EXCLUSAO e
                USUARIO_EXCLUSAO e grava a linha em SIS.Lixeira com o prazo
                (fn_SIS_Lixeira_Dias).
                Recusa = @Mensagem preenchida, sem gravar nada. Quem chama
                cuida da transação. Uso interno (DENY para a API): chamada
                por SIS_Lixeira_Excluir e pelo desfazer de uma inclusão.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Marcar]
    @IdUsuario   INT,
    @Tabela      NVARCHAR(256),
    @IdRegistro  BIGINT,
    @Item        VARCHAR(40),
    @Motivo      NVARCHAR(400),
    @IdLixeira   BIGINT        OUTPUT,
    @Mensagem    NVARCHAR(400) OUTPUT
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @ObjId INT = OBJECT_ID(@Tabela, N'U');
    DECLARE @Pk NVARCHAR(128) = SIS.fn_SIS_Tabela_PK(@Tabela);
    DECLARE @Nome NVARCHAR(300), @DescSql NVARCHAR(1000), @Sql NVARCHAR(MAX), @Usuario NVARCHAR(100);
    DECLARE @Existe INT = 0, @Ativo BIT, @JaExcluido BIT, @Descricao NVARCHAR(400), @Qtd INT, @Onde NVARCHAR(400);
    DECLARE @TemAlteracao BIT;

    SET @IdLixeira = NULL;
    SET @Mensagem = N'';

    IF NOT EXISTS (SELECT 1 FROM SIS.Tabela_Config c WHERE c.TABELA = @Tabela AND c.ATIVO = 1 AND c.PERMITE_LIXEIRA = 1)
       OR @ObjId IS NULL OR @Pk = N''
       OR COL_LENGTH(@Tabela, N'ATIVO') IS NULL OR COL_LENGTH(@Tabela, N'DT_EXCLUSAO') IS NULL OR COL_LENGTH(@Tabela, N'USUARIO_EXCLUSAO') IS NULL
    BEGIN
        SET @Mensagem = N'Este tipo de registro não vai para a lixeira: use Desativar.';
        RETURN;
    END;

    IF SIS.fn_SIS_Parametro_SN('LIXEIRA_ATIVA') = 0
    BEGIN
        SET @Mensagem = N'A lixeira está desligada (parâmetro LIXEIRA_ATIVA): use Desativar.';
        RETURN;
    END;

    SET @Nome = QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId));
    SELECT @DescSql = NULLIF(LTRIM(RTRIM(c.DESCRICAO_SQL)), N'') FROM SIS.Tabela_Config c WHERE c.TABELA = @Tabela;

    SET @Sql = N'SELECT @Existe = 1, @Ativo = t.ATIVO, @JaExcluido = CASE WHEN t.DT_EXCLUSAO IS NULL THEN 0 ELSE 1 END, '
             + N'@Descricao = LEFT(CONVERT(NVARCHAR(MAX), ' + ISNULL(@DescSql, N'CAST(t.' + QUOTENAME(@Pk) + N' AS NVARCHAR(30))') + N'), 400) '
             + N'FROM ' + @Nome + N' t WITH (UPDLOCK, HOLDLOCK) WHERE t.' + QUOTENAME(@Pk) + N' = @Id;';
    EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @Existe INT OUTPUT, @Ativo BIT OUTPUT, @JaExcluido BIT OUTPUT, @Descricao NVARCHAR(400) OUTPUT',
         @Id = @IdRegistro, @Existe = @Existe OUTPUT, @Ativo = @Ativo OUTPUT, @JaExcluido = @JaExcluido OUTPUT, @Descricao = @Descricao OUTPUT;

    IF ISNULL(@Existe, 0) = 0
    BEGIN
        SET @Mensagem = N'Registro não encontrado.';
        RETURN;
    END;

    IF @JaExcluido = 1 OR SIS.fn_SIS_Na_Lixeira(@Tabela, @IdRegistro) = 1
    BEGIN
        SET @Mensagem = N'O registro já está na lixeira.';
        RETURN;
    END;

    EXEC SIS.SIS_Lixeira_Referencias @Tabela = @Tabela, @IdRegistro = @IdRegistro, @Qtd = @Qtd OUTPUT, @Onde = @Onde OUTPUT;
    IF ISNULL(@Qtd, 0) > 0
    BEGIN
        SET @Mensagem = N'Não dá para excluir: o registro é usado em ' + ISNULL(@Onde, N'outro cadastro')
                      + CASE WHEN @Qtd > 1 THEN N' e em mais ' + CAST(@Qtd - 1 AS NVARCHAR(10)) + N' lugar(es)' ELSE N'' END
                      + N'. Use Desativar.';
        RETURN;
    END;

    EXEC SIS.SIS_Tabela_Trava_Conferir @Tabela = @Tabela, @IdRegistro = @IdRegistro, @Operacao = 'LIXEIRA', @Mensagem = @Mensagem OUTPUT;
    IF ISNULL(@Mensagem, N'') <> N'' RETURN;
    SET @Mensagem = N'';

    SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
    SET @TemAlteracao = CASE WHEN COL_LENGTH(@Tabela, N'DT_ALTERACAO') IS NOT NULL AND COL_LENGTH(@Tabela, N'USUARIO_ALTERACAO') IS NOT NULL THEN 1 ELSE 0 END;

    SET @Sql = N'UPDATE t SET t.ATIVO = 0, t.DT_EXCLUSAO = SYSDATETIME(), t.USUARIO_EXCLUSAO = @Usuario'
             + CASE WHEN @TemAlteracao = 1 THEN N', t.DT_ALTERACAO = SYSDATETIME(), t.USUARIO_ALTERACAO = @Usuario' ELSE N'' END
             + N' FROM ' + @Nome + N' t WHERE t.' + QUOTENAME(@Pk) + N' = @Id AND t.DT_EXCLUSAO IS NULL;';
    EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @Usuario NVARCHAR(100)', @Id = @IdRegistro, @Usuario = @Usuario;

    INSERT INTO SIS.Lixeira (TABELA, ID_REGISTRO, ITEM_CODIGO, DESCRICAO, MOTIVO, ATIVO_ANTES, DT_EXCLUSAO, USUARIO_EXCLUSAO, ID_USUARIO_EXCLUSAO, DT_APAGAR, SITUACAO)
    VALUES (@Tabela, @IdRegistro, ISNULL(NULLIF(@Item, ''), SIS.fn_SIS_Item_Da_Tabela(@Tabela)), ISNULL(@Descricao, N''), ISNULL(@Motivo, N''),
            ISNULL(@Ativo, 1), SYSDATETIME(), ISNULL(@Usuario, N''), @IdUsuario,
            DATEADD(DAY, SIS.fn_SIS_Lixeira_Dias(@Tabela), CAST(SYSDATETIME() AS DATE)), 'LIXEIRA');
    SET @IdLixeira = SCOPE_IDENTITY();
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Apagar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Apagar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Apaga de vez um registro que está na lixeira (P20), com as
                filhas que vão junto (SIS.Tabela_Config.TABELAS_FILHAS).
                Antes confere de novo se nada passou a usar o registro e as
                travas; se algo usar, não apaga e devolve o motivo. A trigger
                de auditoria guarda a cópia completa de tudo o que for apagado.
                Marca a linha da SIS.Lixeira como APAGADO.
                Recusa = @Mensagem preenchida, sem apagar nada. Quem chama
                cuida da transação. Uso interno (DENY para a API): chamada por
                SIS_Lixeira_Esvaziar e SIS_Lixeira_Processar.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Apagar]
    @IdLixeira  BIGINT,
    @Usuario    NVARCHAR(100),
    @Motivo     NVARCHAR(400),
    @Mensagem   NVARCHAR(400) OUTPUT
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Tabela NVARCHAR(256), @IdRegistro BIGINT, @ObjId INT, @Pk NVARCHAR(128), @Nome NVARCHAR(300);
    DECLARE @Qtd INT, @Onde NVARCHAR(400), @Sql NVARCHAR(MAX), @Apagados INT;

    SET @Mensagem = N'';

    SELECT @Tabela = l.TABELA, @IdRegistro = l.ID_REGISTRO
    FROM SIS.Lixeira l WITH (UPDLOCK, HOLDLOCK)
    WHERE l.ID_LIXEIRA = @IdLixeira AND l.SITUACAO = 'LIXEIRA';

    IF @Tabela IS NULL
    BEGIN
        SET @Mensagem = N'O registro não está mais na lixeira.';
        RETURN;
    END;

    SET @ObjId = OBJECT_ID(@Tabela, N'U');
    SET @Pk = SIS.fn_SIS_Tabela_PK(@Tabela);
    IF @ObjId IS NULL OR @Pk = N''
    BEGIN
        SET @Mensagem = N'Tabela do registro não encontrada.';
        RETURN;
    END;
    SET @Nome = QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId));

    EXEC SIS.SIS_Lixeira_Referencias @Tabela = @Tabela, @IdRegistro = @IdRegistro, @Qtd = @Qtd OUTPUT, @Onde = @Onde OUTPUT;
    IF ISNULL(@Qtd, 0) > 0
    BEGIN
        SET @Mensagem = N'Não foi apagado: o registro passou a ser usado em ' + ISNULL(@Onde, N'outro cadastro') + N'. Recupere-o ou tire o uso antes.';
        RETURN;
    END;

    EXEC SIS.SIS_Tabela_Trava_Conferir @Tabela = @Tabela, @IdRegistro = @IdRegistro, @Operacao = 'APAGAR', @Mensagem = @Mensagem OUTPUT;
    IF ISNULL(@Mensagem, N'') <> N'' RETURN;
    SET @Mensagem = N'';

    -- Filhas que vão junto
    SET @Sql = N'';
    SELECT @Sql = @Sql + N'DELETE FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(OBJECT_ID(f.TABELA, N'U'))) + N'.' + QUOTENAME(OBJECT_NAME(OBJECT_ID(f.TABELA, N'U')))
                + N' WHERE ' + QUOTENAME(f.COLUNA) + N' = @Id;' + NCHAR(13) + NCHAR(10)
    FROM (SELECT LEFT(x.v, LEN(x.v) - CHARINDEX(N'.', REVERSE(x.v))) AS TABELA, RIGHT(x.v, CHARINDEX(N'.', REVERSE(x.v)) - 1) AS COLUNA
          FROM SIS.Tabela_Config c
          CROSS APPLY (SELECT LTRIM(RTRIM(s.value)) AS v FROM STRING_SPLIT(c.TABELAS_FILHAS, N',') s) x
          WHERE c.TABELA = @Tabela AND x.v LIKE N'%_._%._%') f
    WHERE OBJECT_ID(f.TABELA, N'U') IS NOT NULL
      AND COL_LENGTH(f.TABELA, f.COLUNA) IS NOT NULL;

    IF @Sql <> N''
        EXEC sys.sp_executesql @Sql, N'@Id BIGINT', @Id = @IdRegistro;

    SET @Sql = N'DELETE FROM ' + @Nome + N' WHERE ' + QUOTENAME(@Pk) + N' = @Id AND DT_EXCLUSAO IS NOT NULL; SET @n = @@ROWCOUNT;';
    EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @n INT OUTPUT', @Id = @IdRegistro, @n = @Apagados OUTPUT;

    UPDATE l
       SET l.SITUACAO = 'APAGADO', l.DT_SITUACAO = SYSDATETIME(), l.USUARIO_SITUACAO = ISNULL(@Usuario, N''),
           l.MOTIVO_SITUACAO = LEFT(ISNULL(@Motivo, N'') + CASE WHEN ISNULL(@Apagados, 0) = 0 THEN N' (o registro já não existia)' ELSE N'' END, 400),
           l.DT_ALTERACAO = SYSDATETIME(), l.USUARIO_ALTERACAO = ISNULL(@Usuario, N'')
    FROM SIS.Lixeira l
    WHERE l.ID_LIXEIRA = @IdLixeira AND l.SITUACAO = 'LIXEIRA';
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Excluir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Excluir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Botão Excluir das telas (P20): manda o registro para a
                lixeira, de onde pode ser recuperado até o fim do prazo
                (LIXEIRA_DIAS_GUARDA ou o prazo próprio da tela). Só exclui o
                que nada usa; senão recusa e sugere Desativar.
                Permissão: EXCLUIR na tela (@Item), e a tela precisa mostrar
                a tabela (SIS.Item.TABELAS_DA_TELA).
                Devolve 1 linha: SUCESSO, MENSAGEM, ID_LIXEIRA, DT_APAGAR.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Lixeira_Excluir @IdUsuario = 2, @Item = 'CAD_PESSOA', @Tabela = N'CAD.Pessoa', @IdRegistro = 1, @Motivo = N'cadastro em dobro';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Excluir]
    @IdUsuario   INT,
    @Item        VARCHAR(40),
    @Tabela      NVARCHAR(256),
    @IdRegistro  BIGINT,
    @Motivo      NVARCHAR(400) = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Lixeira_Excluir]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @TranCountEntrada INT = @@TRANCOUNT;
    DECLARE @Recusa NVARCHAR(400) = N'', @IdLixeira BIGINT, @DtApagar DATE;

    BEGIN TRY
        SET @Tabela = LTRIM(RTRIM(ISNULL(@Tabela, N'')));
        SET @Motivo = LTRIM(RTRIM(ISNULL(@Motivo, N'')));

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'EXCLUIR') = 0
            SET @Recusa = N'Você não tem permissão para excluir nesta tela.';
        ELSE IF SIS.fn_SIS_Item_Tem_Tabela(@Item, @Tabela) = 0
            SET @Recusa = N'Esta tela não exclui esse tipo de registro.';
        ELSE IF @IdRegistro IS NULL
            SET @Recusa = N'Escolha o registro a excluir.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID_LIXEIRA, CAST(NULL AS DATE) AS DT_APAGAR;
            RETURN;
        END;

        SET @EtapaAtual = 'Lixeira';
        IF @TranCountEntrada = 0 BEGIN TRANSACTION;
            EXEC SIS.SIS_Lixeira_Marcar @IdUsuario = @IdUsuario, @Tabela = @Tabela, @IdRegistro = @IdRegistro, @Item = @Item,
                 @Motivo = @Motivo, @IdLixeira = @IdLixeira OUTPUT, @Mensagem = @Recusa OUTPUT;
        IF @TranCountEntrada = 0 COMMIT TRANSACTION;

        IF ISNULL(@Recusa, N'') <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID_LIXEIRA, CAST(NULL AS DATE) AS DT_APAGAR;
            RETURN;
        END;

        SELECT @DtApagar = l.DT_APAGAR FROM SIS.Lixeira l WHERE l.ID_LIXEIRA = @IdLixeira;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(N'Registro enviado para a lixeira. Pode ser recuperado até ' + ISNULL(SIS.fn_SIS_Formatar_Data(@DtApagar), N'') + N' (Sistema › Lixeira).' AS NVARCHAR(400)) AS MENSAGEM,
               @IdLixeira AS ID_LIXEIRA, @DtApagar AS DT_APAGAR;
    END TRY
    BEGIN CATCH
        IF @TranCountEntrada = 0 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível excluir o registro. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(NULL AS BIGINT) AS ID_LIXEIRA, CAST(NULL AS DATE) AS DT_APAGAR;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Recuperar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Recuperar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Botão Recuperar da tela Sistema › Lixeira (P20): o registro
                volta como estava antes de ir para a lixeira (ativo ou
                desativado). Antes confere:
                  - os campos únicos configurados (SIS.Tabela_Config.
                    CAMPOS_UNICOS, ex.: CPF/CNPJ): se outro registro vivo tiver
                    o mesmo valor, recusa e mostra qual é;
                  - se algum registro ligado (chave estrangeira) está na
                    lixeira: recupere esse antes;
                  - as travas (mês fechado e trava própria).
                Permissão: RECUPERAR em SIS_LIXEIRA e VER na tela do registro.
                Devolve 1 linha: SUCESSO, MENSAGEM, TABELA, ID_REGISTRO.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Lixeira_Recuperar @IdUsuario = 2, @IdLixeira = 1, @Motivo = N'excluído por engano';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Recuperar]
    @IdUsuario  INT,
    @IdLixeira  BIGINT,
    @Motivo     NVARCHAR(400) = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Lixeira_Recuperar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @TranCountEntrada INT = @@TRANCOUNT;
    DECLARE @Recusa NVARCHAR(400) = N'', @Tabela NVARCHAR(256), @IdRegistro BIGINT, @Item VARCHAR(40), @AtivoAntes BIT;
    DECLARE @ObjId INT, @Pk NVARCHAR(128), @Nome NVARCHAR(300), @Sql NVARCHAR(MAX), @Usuario NVARCHAR(100);
    DECLARE @Campos TABLE (ORDEM INT IDENTITY(1,1), CAMPO NVARCHAR(128));
    DECLARE @Fks TABLE (ORDEM INT IDENTITY(1,1), COLUNA NVARCHAR(128), TABELA_REF NVARCHAR(256));
    DECLARE @i INT, @Total INT, @Campo NVARCHAR(128), @Outro BIGINT, @Ref BIGINT, @TabRef NVARCHAR(256), @DescSql NVARCHAR(1000), @DescOutro NVARCHAR(400);
    DECLARE @TemAlteracao BIT, @Linhas INT;

    BEGIN TRY
        SET @Motivo = LTRIM(RTRIM(ISNULL(@Motivo, N'')));

        SELECT @Tabela = l.TABELA, @IdRegistro = l.ID_REGISTRO, @Item = l.ITEM_CODIGO, @AtivoAntes = l.ATIVO_ANTES
        FROM SIS.Lixeira l
        WHERE l.ID_LIXEIRA = @IdLixeira;

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_LIXEIRA', 'RECUPERAR') = 0
            SET @Recusa = N'Você não tem permissão para recuperar registros da lixeira.';
        ELSE IF @Tabela IS NULL
            SET @Recusa = N'Registro da lixeira não encontrado.';
        ELSE IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'VER') = 0
            SET @Recusa = N'Você não tem permissão para ver a tela deste registro.';
        ELSE IF NOT EXISTS (SELECT 1 FROM SIS.Lixeira l WHERE l.ID_LIXEIRA = @IdLixeira AND l.SITUACAO = 'LIXEIRA')
            SET @Recusa = N'O registro não está mais na lixeira.';

        SET @ObjId = OBJECT_ID(@Tabela, N'U');
        SET @Pk = SIS.fn_SIS_Tabela_PK(@Tabela);
        IF @Recusa = N'' AND (@ObjId IS NULL OR @Pk = N'')
            SET @Recusa = N'Tabela do registro não encontrada.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(@Tabela AS NVARCHAR(256)) AS TABELA, @IdRegistro AS ID_REGISTRO;
            RETURN;
        END;

        SET @Nome = QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId));
        SELECT @DescSql = NULLIF(LTRIM(RTRIM(c.DESCRICAO_SQL)), N'') FROM SIS.Tabela_Config c WHERE c.TABELA = @Tabela;

        -- Campos únicos contra os registros vivos
        SET @EtapaAtual = 'Campos únicos';
        INSERT INTO @Campos (CAMPO)
        SELECT LTRIM(RTRIM(s.value))
        FROM SIS.Tabela_Config c
        CROSS APPLY STRING_SPLIT(c.CAMPOS_UNICOS, N',') s
        WHERE c.TABELA = @Tabela AND LTRIM(RTRIM(s.value)) <> N'' AND COL_LENGTH(@Tabela, LTRIM(RTRIM(s.value))) IS NOT NULL;

        SELECT @i = 1, @Total = COUNT(*) FROM @Campos;
        WHILE @i <= @Total AND @Recusa = N''
        BEGIN
            SELECT @Campo = c.CAMPO FROM @Campos c WHERE c.ORDEM = @i;
            SET @Outro = NULL;
            SET @Sql = N'SELECT TOP 1 @Outro = o.' + QUOTENAME(@Pk) + N', @Desc = LEFT(CONVERT(NVARCHAR(MAX), '
                     + ISNULL(REPLACE(@DescSql, N't.', N'o.'), N'CAST(o.' + QUOTENAME(@Pk) + N' AS NVARCHAR(30))') + N'), 400)'
                     + N' FROM ' + @Nome + N' o INNER JOIN ' + @Nome + N' t ON t.' + QUOTENAME(@Pk) + N' = @Id'
                     + N' WHERE o.' + QUOTENAME(@Pk) + N' <> @Id AND o.DT_EXCLUSAO IS NULL'
                     + N' AND ISNULL(CONVERT(NVARCHAR(MAX), t.' + QUOTENAME(@Campo) + N'), N'''') <> N'''''
                     + N' AND o.' + QUOTENAME(@Campo) + N' = t.' + QUOTENAME(@Campo)
                     + N' ORDER BY o.' + QUOTENAME(@Pk) + N';';
            EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @Outro BIGINT OUTPUT, @Desc NVARCHAR(400) OUTPUT', @Id = @IdRegistro, @Outro = @Outro OUTPUT, @Desc = @DescOutro OUTPUT;
            IF @Outro IS NOT NULL
                SET @Recusa = LEFT(N'Já existe outro cadastro com o mesmo ' + @Campo + N': ' + ISNULL(@DescOutro, N'') + N' (código ' + CAST(@Outro AS NVARCHAR(20))
                            + N'). Confira se é o mesmo antes de recuperar.', 400);
            SET @i = @i + 1;
        END;

        -- Registros ligados que estão na lixeira
        SET @EtapaAtual = 'Registros ligados';
        IF @Recusa = N''
        BEGIN
            INSERT INTO @Fks (COLUNA, TABELA_REF)
            SELECT pc.name, OBJECT_SCHEMA_NAME(fk.referenced_object_id) + N'.' + OBJECT_NAME(fk.referenced_object_id)
            FROM sys.foreign_keys fk
            INNER JOIN sys.foreign_key_columns fkc ON fkc.constraint_object_id = fk.object_id
            INNER JOIN sys.columns pc ON pc.object_id = fkc.parent_object_id AND pc.column_id = fkc.parent_column_id
            WHERE fk.parent_object_id = @ObjId
              AND (SELECT COUNT(*) FROM sys.foreign_key_columns x WHERE x.constraint_object_id = fk.object_id) = 1;

            SELECT @i = 1, @Total = COUNT(*) FROM @Fks;
            WHILE @i <= @Total AND @Recusa = N''
            BEGIN
                SELECT @Campo = f.COLUNA, @TabRef = f.TABELA_REF FROM @Fks f WHERE f.ORDEM = @i;
                SET @Ref = NULL;
                SET @Sql = N'SELECT @Ref = TRY_CONVERT(BIGINT, t.' + QUOTENAME(@Campo) + N') FROM ' + @Nome + N' t WHERE t.' + QUOTENAME(@Pk) + N' = @Id;';
                EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @Ref BIGINT OUTPUT', @Id = @IdRegistro, @Ref = @Ref OUTPUT;
                IF @Ref IS NOT NULL AND SIS.fn_SIS_Na_Lixeira(@TabRef, @Ref) = 1
                    SET @Recusa = LEFT(N'Este registro está ligado a outro que também está na lixeira ('
                                + ISNULL((SELECT TOP 1 l.DESCRICAO FROM SIS.Lixeira l WHERE l.TABELA = @TabRef AND l.ID_REGISTRO = @Ref AND l.SITUACAO = 'LIXEIRA'), N'')
                                + N'). Recupere aquele antes.', 400);
                SET @i = @i + 1;
            END;
        END;

        IF @Recusa = N''
        BEGIN
            EXEC SIS.SIS_Tabela_Trava_Conferir @Tabela = @Tabela, @IdRegistro = @IdRegistro, @Operacao = 'RECUPERAR', @Mensagem = @Recusa OUTPUT;
            SET @Recusa = ISNULL(@Recusa, N'');
        END;

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(@Tabela AS NVARCHAR(256)) AS TABELA, @IdRegistro AS ID_REGISTRO;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        SET @TemAlteracao = CASE WHEN COL_LENGTH(@Tabela, N'DT_ALTERACAO') IS NOT NULL AND COL_LENGTH(@Tabela, N'USUARIO_ALTERACAO') IS NOT NULL THEN 1 ELSE 0 END;
        SET @Sql = N'UPDATE t SET t.ATIVO = @Ativo, t.DT_EXCLUSAO = NULL, t.USUARIO_EXCLUSAO = NULL'
                 + CASE WHEN @TemAlteracao = 1 THEN N', t.DT_ALTERACAO = SYSDATETIME(), t.USUARIO_ALTERACAO = @Usuario' ELSE N'' END
                 + N' FROM ' + @Nome + N' t WHERE t.' + QUOTENAME(@Pk) + N' = @Id AND t.DT_EXCLUSAO IS NOT NULL; SET @n = @@ROWCOUNT;';

        IF @TranCountEntrada = 0 BEGIN TRANSACTION;
            EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @Ativo BIT, @Usuario NVARCHAR(100), @n INT OUTPUT',
                 @Id = @IdRegistro, @Ativo = @AtivoAntes, @Usuario = @Usuario, @n = @Linhas OUTPUT;

            UPDATE l
               SET l.SITUACAO = 'RECUPERADO', l.DT_SITUACAO = SYSDATETIME(), l.USUARIO_SITUACAO = ISNULL(@Usuario, N''),
                   l.MOTIVO_SITUACAO = @Motivo, l.DT_ALTERACAO = SYSDATETIME(), l.USUARIO_ALTERACAO = ISNULL(@Usuario, N'')
            FROM SIS.Lixeira l
            WHERE l.ID_LIXEIRA = @IdLixeira AND l.SITUACAO = 'LIXEIRA';
        IF @TranCountEntrada = 0 COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(CASE WHEN @AtivoAntes = 1 THEN N'Registro recuperado: voltou ativo.' ELSE N'Registro recuperado: voltou desativado, como estava antes de ir para a lixeira.' END AS NVARCHAR(400)) AS MENSAGEM,
               CAST(@Tabela AS NVARCHAR(256)) AS TABELA, @IdRegistro AS ID_REGISTRO;
    END TRY
    BEGIN CATCH
        IF @TranCountEntrada = 0 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível recuperar o registro. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(@Tabela AS NVARCHAR(256)) AS TABELA, @IdRegistro AS ID_REGISTRO;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Manter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Manter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Botão "Manter mais N dias" da tela Sistema › Lixeira (P20):
                adia a data em que o registro será apagado de vez, sem
                recuperar. Conta os dias a partir da data marcada (ou de hoje,
                se ela já passou) e libera um novo aviso por e-mail.
                Permissão: ALTERAR em SIS_LIXEIRA e VER na tela do registro.
                Devolve 1 linha: SUCESSO, MENSAGEM, DT_APAGAR.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Lixeira_Manter @IdUsuario = 2, @IdLixeira = 1, @Dias = 30;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Manter]
    @IdUsuario  INT,
    @IdLixeira  BIGINT,
    @Dias       INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Lixeira_Manter]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa NVARCHAR(400) = N'', @Item VARCHAR(40), @Situacao VARCHAR(12), @DtApagar DATE, @Usuario NVARCHAR(100);

    BEGIN TRY
        SELECT @Item = l.ITEM_CODIGO, @Situacao = l.SITUACAO FROM SIS.Lixeira l WHERE l.ID_LIXEIRA = @IdLixeira;

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_LIXEIRA', 'ALTERAR') = 0
            SET @Recusa = N'Você não tem permissão para mudar o prazo da lixeira.';
        ELSE IF @Situacao IS NULL
            SET @Recusa = N'Registro da lixeira não encontrado.';
        ELSE IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'VER') = 0
            SET @Recusa = N'Você não tem permissão para ver a tela deste registro.';
        ELSE IF @Situacao <> 'LIXEIRA'
            SET @Recusa = N'O registro não está mais na lixeira.';
        ELSE IF ISNULL(@Dias, 0) NOT BETWEEN 1 AND 3650
            SET @Recusa = N'Informe de 1 a 3650 dias.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS DATE) AS DT_APAGAR;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        UPDATE l
           SET @DtApagar = l.DT_APAGAR = DATEADD(DAY, @Dias, CASE WHEN l.DT_APAGAR < CAST(SYSDATETIME() AS DATE) THEN CAST(SYSDATETIME() AS DATE) ELSE l.DT_APAGAR END),
               l.DT_AVISO = NULL, l.DT_ALTERACAO = SYSDATETIME(), l.USUARIO_ALTERACAO = @Usuario
        FROM SIS.Lixeira l
        WHERE l.ID_LIXEIRA = @IdLixeira AND l.SITUACAO = 'LIXEIRA';

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(N'Prazo adiado: o registro fica na lixeira até ' + ISNULL(SIS.fn_SIS_Formatar_Data(@DtApagar), N'') + N'.' AS NVARCHAR(400)) AS MENSAGEM,
               @DtApagar AS DT_APAGAR;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível mudar o prazo. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS DATE) AS DT_APAGAR;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Esvaziar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Esvaziar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Botão "Esvaziar agora" da tela Sistema › Lixeira (P20): apaga
                de vez os registros escolhidos (@Ids = lista de ID_LIXEIRA
                separados por vírgula), sem esperar o prazo. Cada registro é
                independente: se um não puder ser apagado (passou a ser usado,
                trava), os outros seguem. A cópia completa fica na auditoria.
                Permissão: ESVAZIAR em SIS_LIXEIRA e VER na tela de cada
                registro (os de telas que o usuário não vê são ignorados).
                Devolve 1 linha: SUCESSO, MENSAGEM, QTD_APAGADOS, QTD_RECUSADOS.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Lixeira_Esvaziar @IdUsuario = 2, @Ids = N'1,2';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Esvaziar]
    @IdUsuario  INT,
    @Ids        NVARCHAR(MAX),
    @Motivo     NVARCHAR(400) = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    -- Sem XACT_ABORT: laço isolado, um registro ruim não derruba os outros (PADRAO_SQL regras 2 e 13).

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Lixeira_Esvaziar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @TranCountEntrada INT = @@TRANCOUNT;
    DECLARE @Lista TABLE (ORDEM INT IDENTITY(1,1), ID_LIXEIRA BIGINT);
    DECLARE @i INT = 1, @Total INT, @Id BIGINT, @Msg NVARCHAR(400), @PrimeiraRecusa NVARCHAR(400) = N'';
    DECLARE @Apagados INT = 0, @Recusados INT = 0, @Usuario NVARCHAR(100);

    IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_LIXEIRA', 'ESVAZIAR') = 0
    BEGIN
        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Você não tem permissão para esvaziar a lixeira.' AS NVARCHAR(400)) AS MENSAGEM, 0 AS QTD_APAGADOS, 0 AS QTD_RECUSADOS;
        RETURN;
    END;

    INSERT INTO @Lista (ID_LIXEIRA)
    SELECT DISTINCT l.ID_LIXEIRA
    FROM STRING_SPLIT(ISNULL(@Ids, N''), N',') s
    INNER JOIN SIS.Lixeira l ON l.ID_LIXEIRA = TRY_CONVERT(BIGINT, LTRIM(RTRIM(s.value)))
    WHERE l.SITUACAO = 'LIXEIRA'
      AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, l.ITEM_CODIGO, 'VER') = 1;

    SELECT @Total = COUNT(*) FROM @Lista;
    IF @Total = 0
    BEGIN
        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Escolha os registros da lixeira que serão apagados de vez.' AS NVARCHAR(400)) AS MENSAGEM, 0 AS QTD_APAGADOS, 0 AS QTD_RECUSADOS;
        RETURN;
    END;

    SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
    SET @Motivo = ISNULL(NULLIF(LTRIM(RTRIM(@Motivo)), N''), N'Esvaziar agora');
    SET @EtapaAtual = 'Apagando';

    WHILE @i <= @Total
    BEGIN
        SELECT @Id = l.ID_LIXEIRA FROM @Lista l WHERE l.ORDEM = @i;
        SET @Msg = N'';
        BEGIN TRY
            IF @TranCountEntrada = 0 BEGIN TRANSACTION;
                EXEC SIS.SIS_Lixeira_Apagar @IdLixeira = @Id, @Usuario = @Usuario, @Motivo = @Motivo, @Mensagem = @Msg OUTPUT;
            IF @TranCountEntrada = 0 COMMIT TRANSACTION;

            IF ISNULL(@Msg, N'') = N'' SET @Apagados = @Apagados + 1;
            ELSE
            BEGIN
                SET @Recusados = @Recusados + 1;
                IF @PrimeiraRecusa = N'' SET @PrimeiraRecusa = @Msg;
            END;
        END TRY
        BEGIN CATCH
            IF @TranCountEntrada = 0 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
            IF XACT_STATE() <> -1
                INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
                VALUES (@NomeProc, @EtapaAtual + N' ' + CAST(@Id AS NVARCHAR(20)), ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
            SET @Recusados = @Recusados + 1;
            IF @PrimeiraRecusa = N'' SET @PrimeiraRecusa = N'Um registro não pôde ser apagado (erro registrado para análise).';
            IF XACT_STATE() = -1 BREAK;
        END CATCH;
        SET @i = @i + 1;
    END;

    SELECT CAST(CASE WHEN @Apagados > 0 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
           CAST(LEFT(CAST(@Apagados AS NVARCHAR(10)) + N' registro(s) apagado(s) de vez.'
                + CASE WHEN @Recusados > 0 THEN N' ' + CAST(@Recusados AS NVARCHAR(10)) + N' não apagado(s): ' + @PrimeiraRecusa ELSE N'' END, 400) AS NVARCHAR(400)) AS MENSAGEM,
           @Apagados AS QTD_APAGADOS, @Recusados AS QTD_RECUSADOS;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Lista da tela Sistema › Lixeira (P20), uma tela só para todos
                os módulos: filtros por módulo, tela, período da exclusão,
                quem excluiu, texto e situação (padrão LIXEIRA; '' = todas,
                para ver o histórico de recuperados e apagados). Só traz os
                registros das telas que o usuário pode ver. APAGA_LOGO = 1
                quando o registro será apagado dentro do prazo do aviso
                (LIXEIRA_AVISO_DIAS, "apaga amanhã").
                Permissão: VER em SIS_LIXEIRA.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Lixeira_Listar @IdUsuario = 2;
    -- EXEC SIS.SIS_Lixeira_Listar @IdUsuario = 2, @Modulo = 'CAD', @Situacao = '';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Listar]
    @IdUsuario  INT,
    @Modulo     VARCHAR(10)   = NULL,
    @Item       VARCHAR(40)   = NULL,
    @DtInicio   DATE          = NULL,
    @DtFim      DATE          = NULL,
    @Usuario    NVARCHAR(100) = NULL,
    @Texto      NVARCHAR(100) = NULL,
    @Situacao   VARCHAR(12)   = 'LIXEIRA'
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Lixeira_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Hoje DATE = CAST(SYSDATETIME() AS DATE);
    DECLARE @Aviso INT;

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_LIXEIRA', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver a lixeira.', 1;

        SET @Modulo   = NULLIF(LTRIM(RTRIM(ISNULL(@Modulo, ''))), '');
        SET @Item     = NULLIF(LTRIM(RTRIM(ISNULL(@Item, ''))), '');
        SET @Usuario  = NULLIF(LTRIM(RTRIM(ISNULL(@Usuario, N''))), N'');
        SET @Texto    = NULLIF(LTRIM(RTRIM(ISNULL(@Texto, N''))), N'');
        SET @Situacao = NULLIF(LTRIM(RTRIM(ISNULL(@Situacao, ''))), '');
        SET @Aviso    = SIS.fn_SIS_Parametro_Inteiro('LIXEIRA_AVISO_DIAS');

        SET @EtapaAtual = 'Consulta';
        SELECT l.ID_LIXEIRA,
               m.CODIGO AS MODULO_CODIGO,
               m.NOME   AS MODULO_NOME,
               l.ITEM_CODIGO,
               i.NOME   AS TELA_NOME,
               CAST(l.TABELA AS NVARCHAR(256)) AS TABELA,
               l.ID_REGISTRO,
               l.DESCRICAO,
               l.MOTIVO,
               l.DT_EXCLUSAO,
               l.USUARIO_EXCLUSAO,
               l.DT_APAGAR,
               CAST(CASE WHEN l.SITUACAO = 'LIXEIRA' THEN DATEDIFF(DAY, @Hoje, l.DT_APAGAR) ELSE 0 END AS INT) AS DIAS_RESTANTES,
               CAST(CASE WHEN l.SITUACAO = 'LIXEIRA' AND @Aviso > 0 AND l.DT_APAGAR <= DATEADD(DAY, @Aviso, @Hoje) THEN 1 ELSE 0 END AS BIT) AS APAGA_LOGO,
               l.SITUACAO,
               l.DT_SITUACAO,
               l.USUARIO_SITUACAO,
               l.MOTIVO_SITUACAO,
               l.DT_AVISO
        FROM SIS.Lixeira l WITH (NOLOCK)
        INNER JOIN SIS.Item   i WITH (NOLOCK) ON i.CODIGO    = l.ITEM_CODIGO
        INNER JOIN SIS.Modulo m WITH (NOLOCK) ON m.ID_MODULO = i.ID_MODULO
        WHERE (@Situacao IS NULL OR l.SITUACAO = @Situacao)
          AND (@Modulo   IS NULL OR m.CODIGO = @Modulo)
          AND (@Item     IS NULL OR l.ITEM_CODIGO = @Item)
          AND (@DtInicio IS NULL OR l.DT_EXCLUSAO >= @DtInicio)
          AND (@DtFim    IS NULL OR l.DT_EXCLUSAO <  DATEADD(DAY, 1, @DtFim))
          AND (@Usuario  IS NULL OR l.USUARIO_EXCLUSAO = @Usuario)
          AND (@Texto    IS NULL OR l.DESCRICAO LIKE N'%' + @Texto + N'%' OR l.MOTIVO LIKE N'%' + @Texto + N'%')
          AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, l.ITEM_CODIGO, 'VER') = 1
        ORDER BY m.ORDEM_MENU, i.ORDEM, l.DT_EXCLUSAO DESC, l.ID_LIXEIRA DESC;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível carregar a lixeira. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Prazo_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Prazo_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Prazos da lixeira por tela (P20), para a tela Sistema ›
                Lixeira: tela, módulo, prazo próprio (vazio = vale o geral),
                prazo que vale e quantos registros estão na lixeira. Só as
                telas que o usuário pode ver.
                Permissão: VER em SIS_LIXEIRA.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Lixeira_Prazo_Listar @IdUsuario = 2;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Prazo_Listar]
    @IdUsuario  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Lixeira_Prazo_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_LIXEIRA', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver a lixeira.', 1;

        SET @EtapaAtual = 'Consulta';
        SELECT CAST(c.TABELA AS NVARCHAR(256)) AS TABELA,
               x.ITEM_CODIGO,
               i.NOME AS TELA_NOME,
               m.CODIGO AS MODULO_CODIGO,
               m.NOME AS MODULO_NOME,
               c.DIAS_GUARDA,
               SIS.fn_SIS_Lixeira_Dias(c.TABELA) AS DIAS_VALE,
               SIS.fn_SIS_Parametro_Inteiro('LIXEIRA_DIAS_GUARDA') AS DIAS_GERAL,
               (SELECT COUNT(*) FROM SIS.Lixeira l WITH (NOLOCK) WHERE l.TABELA = c.TABELA AND l.SITUACAO = 'LIXEIRA') AS QTD_NA_LIXEIRA
        FROM SIS.Tabela_Config c WITH (NOLOCK)
        CROSS APPLY (SELECT SIS.fn_SIS_Item_Da_Tabela(c.TABELA) AS ITEM_CODIGO) x
        INNER JOIN SIS.Item   i WITH (NOLOCK) ON i.CODIGO = x.ITEM_CODIGO
        INNER JOIN SIS.Modulo m WITH (NOLOCK) ON m.ID_MODULO = i.ID_MODULO
        WHERE c.ATIVO = 1
          AND c.PERMITE_LIXEIRA = 1
          AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, x.ITEM_CODIGO, 'VER') = 1
        ORDER BY m.ORDEM_MENU, i.ORDEM, c.TABELA;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível carregar os prazos da lixeira. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Prazo_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Prazo_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Prazo próprio da lixeira para uma tela (P20). @Dias vazio
                (NULL) = volta a valer o prazo geral (LIXEIRA_DIAS_GUARDA).
                Vale para o que for excluído daqui em diante; o que já está na
                lixeira mantém a data marcada (use "Manter mais N dias").
                Permissão: ALTERAR em SIS_LIXEIRA e VER na tela.
                Devolve 1 linha: SUCESSO, MENSAGEM.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Lixeira_Prazo_Gravar @IdUsuario = 2, @Tabela = N'CAD.Pessoa', @Dias = 120;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Prazo_Gravar]
    @IdUsuario  INT,
    @Tabela     NVARCHAR(256),
    @Dias       INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Lixeira_Prazo_Gravar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa NVARCHAR(400) = N'', @Usuario NVARCHAR(100);

    BEGIN TRY
        SET @Tabela = LTRIM(RTRIM(ISNULL(@Tabela, N'')));

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_LIXEIRA', 'ALTERAR') = 0
            SET @Recusa = N'Você não tem permissão para mudar o prazo da lixeira.';
        ELSE IF NOT EXISTS (SELECT 1 FROM SIS.Tabela_Config c WHERE c.TABELA = @Tabela AND c.ATIVO = 1 AND c.PERMITE_LIXEIRA = 1)
            SET @Recusa = N'Esta tela não usa a lixeira.';
        ELSE IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, SIS.fn_SIS_Item_Da_Tabela(@Tabela), 'VER') = 0
            SET @Recusa = N'Você não tem permissão para ver esta tela.';
        ELSE IF @Dias IS NOT NULL AND @Dias NOT BETWEEN 1 AND 3650
            SET @Recusa = N'Informe de 1 a 3650 dias, ou deixe em branco para usar o prazo geral.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        UPDATE c
           SET c.DIAS_GUARDA = @Dias, c.DT_ALTERACAO = SYSDATETIME(), c.USUARIO_ALTERACAO = @Usuario
        FROM SIS.Tabela_Config c
        WHERE c.TABELA = @Tabela
          AND ISNULL(c.DIAS_GUARDA, -1) <> ISNULL(@Dias, -1);

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(CASE WHEN @Dias IS NULL THEN N'Prazo próprio retirado: vale o prazo geral (' + CAST(SIS.fn_SIS_Lixeira_Dias(@Tabela) AS NVARCHAR(10)) + N' dias).'
                         ELSE N'Prazo gravado: ' + CAST(@Dias AS NVARCHAR(10)) + N' dias, para o que for excluído daqui em diante.' END AS NVARCHAR(400)) AS MENSAGEM;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar o prazo. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Lixeira_Processar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Lixeira_Processar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Rotina diária da lixeira (P20; rotina LIXEIRA_LIMPEZA):
                  1) limpeza (liga/desliga LIXEIRA_LIMPEZA_ATIVA): apaga de vez
                     o que passou do prazo (DT_APAGAR até hoje). O que passou a
                     ser usado não é apagado: o motivo fica na linha da lixeira
                     e sai no aviso;
                  2) aviso: um e-mail para o grupo do parâmetro
                     LIXEIRA_AVISO_GRUPO com o que será apagado nos próximos
                     LIXEIRA_AVISO_DIAS dia(s) e ainda não foi avisado. Sem
                     nada para avisar, não sai e-mail. Em teste (@bRunLocal),
                     o aviso vai para o EMAIL_TESTE e não marca "avisado".
                Blocos independentes (regra 13): no fim, se algum falhou,
                relança um erro agregado (a rotina fica com resultado ERRO).
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Lixeira_Processar;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Lixeira_Processar]
    @bRunLocal  BIT = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    -- Sem XACT_ABORT: laço isolado na limpeza (regras 2 e 13).
    SET @bRunLocal = ISNULL(@bRunLocal, CASE WHEN DB_NAME() LIKE '%[_]LOCAL' THEN 1 ELSE 0 END);

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Lixeira_Processar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Limpeza';
    DECLARE @Hoje DATE = CAST(SYSDATETIME() AS DATE);
    DECLARE @Vencidos TABLE (ORDEM INT IDENTITY(1,1), ID_LIXEIRA BIGINT);
    DECLARE @Aviso TABLE (ID_LIXEIRA BIGINT PRIMARY KEY);
    DECLARE @i INT = 1, @Total INT, @Id BIGINT, @Msg NVARCHAR(400), @Falhas INT = 0;
    DECLARE @Dias INT, @Grupo VARCHAR(30), @Para NVARCHAR(MAX), @Linhas NVARCHAR(MAX), @Corpo NVARCHAR(MAX), @Assunto NVARCHAR(400), @Chave NVARCHAR(200), @IdEmail BIGINT;
    DECLARE @Qtd INT;

    -- 1) Limpeza do que venceu
    BEGIN TRY
        IF SIS.fn_SIS_Parametro_SN('LIXEIRA_LIMPEZA_ATIVA') = 1
        BEGIN
            INSERT INTO @Vencidos (ID_LIXEIRA)
            SELECT l.ID_LIXEIRA FROM SIS.Lixeira l WHERE l.SITUACAO = 'LIXEIRA' AND l.DT_APAGAR <= @Hoje ORDER BY l.ID_LIXEIRA;
            SELECT @Total = COUNT(*) FROM @Vencidos;

            WHILE @i <= @Total
            BEGIN
                SELECT @Id = v.ID_LIXEIRA FROM @Vencidos v WHERE v.ORDEM = @i;
                SET @Msg = N'';
                BEGIN TRY
                    BEGIN TRANSACTION;
                        EXEC SIS.SIS_Lixeira_Apagar @IdLixeira = @Id, @Usuario = N'rotina', @Motivo = N'Prazo da lixeira vencido', @Mensagem = @Msg OUTPUT;
                        IF ISNULL(@Msg, N'') <> N''
                            UPDATE l SET l.MOTIVO_SITUACAO = @Msg, l.DT_ALTERACAO = SYSDATETIME(), l.USUARIO_ALTERACAO = N'rotina'
                            FROM SIS.Lixeira l WHERE l.ID_LIXEIRA = @Id AND l.SITUACAO = 'LIXEIRA' AND l.MOTIVO_SITUACAO <> @Msg;
                    COMMIT TRANSACTION;
                END TRY
                BEGIN CATCH
                    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
                    INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
                    VALUES (@NomeProc, N'Limpeza ' + CAST(@Id AS NVARCHAR(20)), ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
                    SET @Falhas = @Falhas + 1;
                END CATCH;
                SET @i = @i + 1;
            END;
        END;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
        VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        SET @Falhas = @Falhas + 1;
    END CATCH;

    -- 2) Aviso do que vai ser apagado
    BEGIN TRY
        SET @EtapaAtual = 'Aviso';
        SET @Dias  = SIS.fn_SIS_Parametro_Inteiro('LIXEIRA_AVISO_DIAS');
        SET @Grupo = CONVERT(VARCHAR(30), LTRIM(RTRIM(ISNULL(SIS.fn_SIS_Parametro('LIXEIRA_AVISO_GRUPO'), N''))));

        IF @Dias > 0
        BEGIN
            INSERT INTO @Aviso (ID_LIXEIRA)
            SELECT l.ID_LIXEIRA
            FROM SIS.Lixeira l
            WHERE l.SITUACAO = 'LIXEIRA'
              AND l.DT_AVISO IS NULL
              AND l.DT_APAGAR <= DATEADD(DAY, @Dias, @Hoje);
            SELECT @Qtd = COUNT(*) FROM @Aviso;

            SET @Para = CASE WHEN @Grupo = '' THEN N'' ELSE SIS.fn_SIS_Emails_Do_Grupo(@Grupo) END;
            IF @Qtd > 0 AND @Para = N''
                INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
                VALUES (@NomeProc, @EtapaAtual, 0, N'Aviso da lixeira não enviado: o grupo de e-mail do parâmetro LIXEIRA_AVISO_GRUPO está vazio ou sem destinatário.', 0, SYSDATETIME());

            IF @Qtd > 0 AND @Para <> N''
            BEGIN
                SELECT @Linhas = STRING_AGG(CONVERT(NVARCHAR(MAX),
                           N'<tr style="background:' + CASE WHEN x.N % 2 = 0 THEN N'#f5f5f5' ELSE N'#ffffff' END + N'">'
                         + N'<td style="padding:6px;border-bottom:1px solid #eeeeee">' + SIS.fn_SIS_Texto_HTML(ISNULL(x.MODULO, N'') + N' › ' + ISNULL(x.TELA, N'')) + N'</td>'
                         + N'<td style="padding:6px;border-bottom:1px solid #eeeeee">' + SIS.fn_SIS_Texto_HTML(ISNULL(x.DESCRICAO, N''))
                         + CASE WHEN ISNULL(x.MOTIVO_SITUACAO, N'') <> N'' THEN N'<br><span style="color:#E65100">' + SIS.fn_SIS_Texto_HTML(x.MOTIVO_SITUACAO) + N'</span>' ELSE N'' END + N'</td>'
                         + N'<td style="padding:6px;border-bottom:1px solid #eeeeee">' + SIS.fn_SIS_Texto_HTML(ISNULL(x.USUARIO_EXCLUSAO, N'')) + N'<br>' + ISNULL(SIS.fn_SIS_Formatar_Data_Hora(x.DT_EXCLUSAO), N'') + N'</td>'
                         + N'<td style="padding:6px;border-bottom:1px solid #eeeeee;text-align:center">' + ISNULL(SIS.fn_SIS_Formatar_Data(x.DT_APAGAR), N'') + N'</td></tr>'), N'')
                       WITHIN GROUP (ORDER BY x.N)
                FROM (SELECT ROW_NUMBER() OVER (ORDER BY l.DT_APAGAR, m.ORDEM_MENU, i.ORDEM, l.ID_LIXEIRA) AS N,
                             m.NOME AS MODULO, i.NOME AS TELA, l.DESCRICAO, l.MOTIVO_SITUACAO, l.USUARIO_EXCLUSAO, l.DT_EXCLUSAO, l.DT_APAGAR
                      FROM @Aviso a
                      INNER JOIN SIS.Lixeira l ON l.ID_LIXEIRA = a.ID_LIXEIRA
                      LEFT  JOIN SIS.Item   i ON i.CODIGO = l.ITEM_CODIGO
                      LEFT  JOIN SIS.Modulo m ON m.ID_MODULO = i.ID_MODULO) x;

                SET @Corpo = SIS.fn_SIS_Email_HTML(N'Lixeira: registros que serão apagados de vez', 'INFO',
                    N'<p>Os registros abaixo estão na lixeira e serão <b>apagados de vez</b> na data indicada. '
                    + N'Para manter algum, abra <b>Sistema › Lixeira</b> e use <b>Recuperar</b> ou <b>Manter mais N dias</b>.</p>'
                    + N'<table style="width:100%;border-collapse:collapse;font-size:13px">'
                    + N'<tr style="background:#eeeeee"><th style="padding:6px;text-align:left">Módulo › Tela</th><th style="padding:6px;text-align:left">Registro</th>'
                    + N'<th style="padding:6px;text-align:left">Excluído por / em</th><th style="padding:6px">Apaga em</th></tr>'
                    + ISNULL(@Linhas, N'') + N'</table>',
                    @NomeProc, @Grupo, 0);

                SET @Assunto = LEFT(ISNULL(SIS.fn_SIS_Parametro('SISTEMA_NOME'), N'SisCMJ') + N' - Lixeira: ' + CAST(@Qtd AS NVARCHAR(10))
                             + N' registro(s) serão apagados de vez', 400);
                SET @Chave = N'LIXEIRA_AVISO_' + CONVERT(NVARCHAR(8), @Hoje, 112) + N'_' + CAST((SELECT MAX(a.ID_LIXEIRA) FROM @Aviso a) AS NVARCHAR(20))
                           + CASE WHEN @bRunLocal = 1 THEN N'_' + CONVERT(NVARCHAR(30), SYSDATETIME(), 126) ELSE N'' END;

                EXEC SIS.SIS_Email_Enfileirar @Para = @Para, @Assunto = @Assunto, @CorpoHTML = @Corpo, @Tipo = 'LIXEIRA_AVISO',
                     @Origem = @NomeProc, @ChaveOrigem = @Chave, @Grupo = @Grupo, @IdEmail = @IdEmail OUTPUT;

                IF @bRunLocal = 0 AND @IdEmail IS NOT NULL
                    UPDATE l SET l.DT_AVISO = SYSDATETIME()
                    FROM SIS.Lixeira l
                    INNER JOIN @Aviso a ON a.ID_LIXEIRA = l.ID_LIXEIRA
                    WHERE l.DT_AVISO IS NULL;
            END;
        END;
    END TRY
    BEGIN CATCH
        INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
        VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        SET @Falhas = @Falhas + 1;
    END CATCH;

    IF @Falhas > 0
        THROW 50002, N'Rotina da lixeira terminou com falha (ver o log de erros).', 1;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Historico_Desfazer_Montar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Historico_Desfazer_Montar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Motor do desfazer pelo histórico (P20). Monta, sem gravar
                nada, o plano do que vai mudar, na tabela #Desfazer_Plano
                criada por quem chama (SIS_Historico_Desfazer_Previa e
                SIS_Historico_Desfazer). Modos:
                  REGISTRO  voltar o registro (e as filhas que vão junto) para
                            como estava logo depois da operação @IdAuditoria,
                            ou na data/hora @DataHora;
                  OPERACAO  desfazer a operação (transação) da linha
                            @IdAuditoria;
                  LOTE      desfazer tudo o que o lote @IdLote fez.
                Para cada campo alterado: o valor novo é o "antes" da primeira
                mudança do conjunto; só muda se hoje o campo estiver igual ao
                "depois" da última (senão CONFLITO: alguém mexeu depois).
                Inclusão no conjunto: conforme SIS.Tabela_Config.
                DESFAZER_INCLUSAO (LIXEIRA, DESATIVAR, APAGAR ou RECUSAR).
                Exclusão definitiva no conjunto: conforme DESFAZER_EXCLUSAO
                (REINSERIR, só tabelas de ligação como permissões, ou RECUSAR).
                No modo REGISTRO entram também as filhas que vão junto,
                inclusive as já apagadas (achadas pela foto da auditoria).
                BLOQUEADO: tabela sem desfazer, registro apagado de vez ou na
                lixeira, mês fechado, trava própria. IGNORADO: campo sigiloso,
                bloqueado na configuração, de controle ou a marca da lixeira.
                Comparação de texto em binário, igual à trigger de auditoria.
                Uso interno (DENY para a API).
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Historico_Desfazer_Montar]
    @Modo         VARCHAR(10),
    @Tabela       NVARCHAR(256) = NULL,
    @IdRegistro   BIGINT        = NULL,
    @IdAuditoria  BIGINT        = NULL,
    @DataHora     DATETIME2(0)  = NULL,
    @IdLote       BIGINT        = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Limite BIGINT, @Transacao BIGINT, @Sql NVARCHAR(MAX), @Lista NVARCHAR(MAX);
    DECLARE @i INT, @Total INT, @T NVARCHAR(256), @ObjId INT, @Pk NVARCHAR(128), @Nome NVARCHAR(300), @DescSql NVARCHAR(1000);
    DECLARE @Id BIGINT, @Msg NVARCHAR(400), @ColData NVARCHAR(128), @DataNova DATE;

    DROP TABLE IF EXISTS #Reg;
    DROP TABLE IF EXISTS #Lin;
    DROP TABLE IF EXISTS #Campo;
    DROP TABLE IF EXISTS #Atual;
    DROP TABLE IF EXISTS #Rec;
    DROP TABLE IF EXISTS #Tab;

    CREATE TABLE #Reg  (TABELA NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL, ID_REGISTRO BIGINT NOT NULL, PRIMARY KEY (TABELA, ID_REGISTRO));
    CREATE TABLE #Lin  (ID_AUDITORIA BIGINT NOT NULL PRIMARY KEY, TABELA NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL, ID_REGISTRO BIGINT NOT NULL, OPERACAO CHAR(1) NOT NULL,
                        CAMPO NVARCHAR(128) COLLATE DATABASE_DEFAULT NOT NULL, VALOR_ANTES NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL, VALOR_DEPOIS NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL);
    CREATE TABLE #Campo (TABELA NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL, ID_REGISTRO BIGINT NOT NULL, CAMPO NVARCHAR(128) COLLATE DATABASE_DEFAULT NOT NULL,
                         PRIMEIRA BIGINT NOT NULL, ULTIMA BIGINT NOT NULL, VALOR_NOVO NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL, VALOR_ESPERADO NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL,
                         PRIMARY KEY (TABELA, ID_REGISTRO, CAMPO));
    CREATE TABLE #Atual (TABELA NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL, ID_REGISTRO BIGINT NOT NULL, CAMPO NVARCHAR(128) COLLATE DATABASE_DEFAULT NOT NULL, VALOR NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL,
                         PRIMARY KEY (TABELA, ID_REGISTRO, CAMPO));
    CREATE TABLE #Rec  (TABELA NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL, ID_REGISTRO BIGINT NOT NULL, TEM_I BIT NOT NULL, TEM_E BIT NOT NULL,
                        EXISTE BIT NOT NULL DEFAULT (0), DESCRICAO NVARCHAR(400) COLLATE DATABASE_DEFAULT NULL, BLOQUEIO NVARCHAR(400) COLLATE DATABASE_DEFAULT NULL,
                        ACAO VARCHAR(10) COLLATE DATABASE_DEFAULT NULL, AVISO NVARCHAR(400) COLLATE DATABASE_DEFAULT NULL, FOTO NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL,
                        PRIMARY KEY (TABELA, ID_REGISTRO));
    CREATE TABLE #Tab  (ORDEM INT IDENTITY(1,1) NOT NULL, TABELA NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL);

    -- 1) Linhas da auditoria que entram no conjunto
    IF @Modo = 'REGISTRO'
    BEGIN
        IF @IdAuditoria IS NOT NULL
        BEGIN
            SELECT @Transacao = a.TRANSACAO, @Limite = a.ID_AUDITORIA FROM SIS.Auditoria a WHERE a.ID_AUDITORIA = @IdAuditoria;
            IF @Transacao IS NOT NULL
                SELECT @Limite = MAX(a.ID_AUDITORIA) FROM SIS.Auditoria a WHERE a.TRANSACAO = @Transacao;
        END;
        IF @Limite IS NULL AND @DataHora IS NOT NULL
            SELECT @Limite = ISNULL(MAX(a.ID_AUDITORIA), 0) FROM SIS.Auditoria a WHERE a.DT_OPERACAO <= @DataHora;
        IF @Limite IS NULL GOTO Fim;

        INSERT INTO #Reg (TABELA, ID_REGISTRO) VALUES (@Tabela, @IdRegistro);

        -- filhas que vão junto: as que existem hoje e as incluídas/apagadas depois do ponto (pela foto da auditoria)
        SET @Sql = N'';
        SELECT @Sql = @Sql
                    + N'INSERT INTO #Reg (TABELA, ID_REGISTRO) SELECT DISTINCT N''' + REPLACE(f.TABELA, N'''', N'''''') + N''', CAST(f.'
                    + QUOTENAME(SIS.fn_SIS_Tabela_PK(f.TABELA)) + N' AS BIGINT) FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(OBJECT_ID(f.TABELA, N'U'))) + N'.'
                    + QUOTENAME(OBJECT_NAME(OBJECT_ID(f.TABELA, N'U'))) + N' f WHERE f.' + QUOTENAME(f.COLUNA) + N' = @Id'
                    + N' AND NOT EXISTS (SELECT 1 FROM #Reg r WHERE r.TABELA = N''' + REPLACE(f.TABELA, N'''', N'''''') + N''' AND r.ID_REGISTRO = f.'
                    + QUOTENAME(SIS.fn_SIS_Tabela_PK(f.TABELA)) + N');' + NCHAR(13) + NCHAR(10)
                    + N'INSERT INTO #Reg (TABELA, ID_REGISTRO) SELECT DISTINCT a.TABELA, a.ID_REGISTRO FROM SIS.Auditoria a'
                    + N' WHERE a.TABELA = N''' + REPLACE(f.TABELA, N'''', N'''''') + N''' AND a.OPERACAO IN (''I'', ''E'') AND a.ID_AUDITORIA > @Limite'
                    + N' AND JSON_VALUE(COALESCE(a.VALOR_DEPOIS, a.VALOR_ANTES), N''$.' + REPLACE(f.COLUNA, N'''', N'''''') + N''') = CAST(@Id AS NVARCHAR(30))'
                    + N' AND NOT EXISTS (SELECT 1 FROM #Reg r WHERE r.TABELA = a.TABELA AND r.ID_REGISTRO = a.ID_REGISTRO);' + NCHAR(13) + NCHAR(10)
        FROM (SELECT LEFT(x.v, LEN(x.v) - CHARINDEX(N'.', REVERSE(x.v))) AS TABELA, RIGHT(x.v, CHARINDEX(N'.', REVERSE(x.v)) - 1) AS COLUNA
              FROM SIS.Tabela_Config c
              CROSS APPLY (SELECT LTRIM(RTRIM(s.value)) AS v FROM STRING_SPLIT(c.TABELAS_FILHAS, N',') s) x
              WHERE c.TABELA = @Tabela AND x.v LIKE N'%_._%._%') f
        WHERE OBJECT_ID(f.TABELA, N'U') IS NOT NULL AND COL_LENGTH(f.TABELA, f.COLUNA) IS NOT NULL AND SIS.fn_SIS_Tabela_PK(f.TABELA) <> N'';
        IF @Sql <> N'' EXEC sys.sp_executesql @Sql, N'@Id BIGINT, @Limite BIGINT', @Id = @IdRegistro, @Limite = @Limite;

        INSERT INTO #Lin (ID_AUDITORIA, TABELA, ID_REGISTRO, OPERACAO, CAMPO, VALOR_ANTES, VALOR_DEPOIS)
        SELECT a.ID_AUDITORIA, a.TABELA, a.ID_REGISTRO, a.OPERACAO, a.CAMPO, a.VALOR_ANTES, a.VALOR_DEPOIS
        FROM SIS.Auditoria a
        INNER JOIN #Reg r ON r.TABELA = a.TABELA AND r.ID_REGISTRO = a.ID_REGISTRO
        WHERE a.ID_AUDITORIA > @Limite;
    END;

    IF @Modo = 'OPERACAO'
    BEGIN
        SELECT @Transacao = a.TRANSACAO FROM SIS.Auditoria a WHERE a.ID_AUDITORIA = @IdAuditoria;

        INSERT INTO #Lin (ID_AUDITORIA, TABELA, ID_REGISTRO, OPERACAO, CAMPO, VALOR_ANTES, VALOR_DEPOIS)
        SELECT a.ID_AUDITORIA, a.TABELA, a.ID_REGISTRO, a.OPERACAO, a.CAMPO, a.VALOR_ANTES, a.VALOR_DEPOIS
        FROM SIS.Auditoria a
        WHERE (@Transacao IS NOT NULL AND a.TRANSACAO = @Transacao)
           OR (@Transacao IS NULL AND a.ID_AUDITORIA = @IdAuditoria);
    END;

    IF @Modo = 'LOTE'
        INSERT INTO #Lin (ID_AUDITORIA, TABELA, ID_REGISTRO, OPERACAO, CAMPO, VALOR_ANTES, VALOR_DEPOIS)
        SELECT a.ID_AUDITORIA, a.TABELA, a.ID_REGISTRO, a.OPERACAO, a.CAMPO, a.VALOR_ANTES, a.VALOR_DEPOIS
        FROM SIS.Auditoria a
        WHERE a.ID_LOTE = @IdLote;

    IF NOT EXISTS (SELECT 1 FROM #Lin) GOTO Fim;

    -- 2) Registros e campos
    INSERT INTO #Rec (TABELA, ID_REGISTRO, TEM_I, TEM_E)
    SELECT l.TABELA, l.ID_REGISTRO,
           CAST(MAX(CASE WHEN l.OPERACAO = 'I' THEN 1 ELSE 0 END) AS BIT),
           CAST(MAX(CASE WHEN l.OPERACAO = 'E' THEN 1 ELSE 0 END) AS BIT)
    FROM #Lin l
    GROUP BY l.TABELA, l.ID_REGISTRO;

    INSERT INTO #Campo (TABELA, ID_REGISTRO, CAMPO, PRIMEIRA, ULTIMA)
    SELECT l.TABELA, l.ID_REGISTRO, l.CAMPO, MIN(l.ID_AUDITORIA), MAX(l.ID_AUDITORIA)
    FROM #Lin l
    WHERE l.OPERACAO = 'A' AND l.CAMPO <> N''
    GROUP BY l.TABELA, l.ID_REGISTRO, l.CAMPO;

    UPDATE c SET c.VALOR_NOVO = p.VALOR_ANTES, c.VALOR_ESPERADO = u.VALOR_DEPOIS
    FROM #Campo c
    INNER JOIN #Lin p ON p.ID_AUDITORIA = c.PRIMEIRA
    INNER JOIN #Lin u ON u.ID_AUDITORIA = c.ULTIMA;

    -- inclusão a desativar: o campo ATIVO entra para leitura do valor de hoje
    INSERT INTO #Campo (TABELA, ID_REGISTRO, CAMPO, PRIMEIRA, ULTIMA, VALOR_NOVO, VALOR_ESPERADO)
    SELECT r.TABELA, r.ID_REGISTRO, N'ATIVO', 0, 0, N'0', NULL
    FROM #Rec r
    INNER JOIN SIS.Tabela_Config cf ON cf.TABELA = r.TABELA AND cf.ATIVO = 1 AND cf.DESFAZER_INCLUSAO = 'DESATIVAR'
    WHERE r.TEM_I = 1 AND COL_LENGTH(r.TABELA, N'ATIVO') IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM #Campo c WHERE c.TABELA = r.TABELA AND c.ID_REGISTRO = r.ID_REGISTRO AND c.CAMPO = N'ATIVO');

    -- inclusão a desativar: o valor novo do ATIVO é sempre 0 (mesmo que o ATIVO tenha mudado depois)
    UPDATE c SET c.VALOR_NOVO = N'0'
    FROM #Campo c
    INNER JOIN #Rec r ON r.TABELA = c.TABELA AND r.ID_REGISTRO = c.ID_REGISTRO
    INNER JOIN SIS.Tabela_Config cf ON cf.TABELA = r.TABELA AND cf.ATIVO = 1 AND cf.DESFAZER_INCLUSAO = 'DESATIVAR'
    WHERE r.TEM_I = 1 AND c.CAMPO = N'ATIVO';

    -- 3) Valores de hoje, existência e descrição (uma consulta por tabela)
    INSERT INTO #Tab (TABELA) SELECT DISTINCT r.TABELA FROM #Rec r WHERE OBJECT_ID(r.TABELA, N'U') IS NOT NULL AND SIS.fn_SIS_Tabela_PK(r.TABELA) <> N'';
    SELECT @i = 1, @Total = COUNT(*) FROM #Tab;
    WHILE @i <= @Total
    BEGIN
        SELECT @T = t.TABELA FROM #Tab t WHERE t.ORDEM = @i;
        SET @ObjId = OBJECT_ID(@T, N'U');
        SET @Pk = SIS.fn_SIS_Tabela_PK(@T);
        SET @Nome = QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId));
        SET @DescSql = NULL;
        SELECT @DescSql = NULLIF(LTRIM(RTRIM(cf.DESCRICAO_SQL)), N'') FROM SIS.Tabela_Config cf WHERE cf.TABELA = @T;

        SET @Sql = N'UPDATE r SET r.EXISTE = 1, r.DESCRICAO = LEFT(CONVERT(NVARCHAR(MAX), '
                 + ISNULL(@DescSql, N'CAST(t.' + QUOTENAME(@Pk) + N' AS NVARCHAR(30))') + N'), 400)'
                 + N' FROM #Rec r INNER JOIN ' + @Nome + N' t ON t.' + QUOTENAME(@Pk) + N' = r.ID_REGISTRO WHERE r.TABELA = @T;';
        EXEC sys.sp_executesql @Sql, N'@T NVARCHAR(256)', @T = @T;

        SET @Lista = NULL;
        SELECT @Lista = STRING_AGG(CONVERT(NVARCHAR(MAX),
                   N'(N''' + REPLACE(x.CAMPO, N'''', N'''''') + N''', '
                 + CASE WHEN ty.name IN ('date', 'datetime', 'datetime2', 'smalldatetime', 'datetimeoffset', 'time') THEN N'CONVERT(NVARCHAR(MAX), t.' + QUOTENAME(x.CAMPO) + N', 121)'
                        WHEN ty.name IN ('varbinary', 'binary', 'image', 'timestamp') THEN N'CASE WHEN t.' + QUOTENAME(x.CAMPO) + N' IS NULL THEN NULL ELSE N''***'' END'
                        ELSE N'CONVERT(NVARCHAR(MAX), t.' + QUOTENAME(x.CAMPO) + N')' END + N')'), N', ')
        FROM (SELECT DISTINCT c.CAMPO FROM #Campo c WHERE c.TABELA = @T) x
        INNER JOIN sys.columns col ON col.object_id = @ObjId AND col.name = x.CAMPO
        INNER JOIN sys.types ty ON ty.system_type_id = col.system_type_id AND ty.user_type_id = col.system_type_id
        WHERE ty.name NOT IN ('text', 'ntext', 'geography', 'geometry');

        IF @Lista IS NOT NULL
        BEGIN
            SET @Sql = N'INSERT INTO #Atual (TABELA, ID_REGISTRO, CAMPO, VALOR) SELECT @T, c.ID_REGISTRO, c.CAMPO, v.VALOR'
                     + N' FROM #Campo c INNER JOIN ' + @Nome + N' t ON t.' + QUOTENAME(@Pk) + N' = c.ID_REGISTRO'
                     + N' CROSS APPLY (VALUES ' + @Lista + N') v (CAMPO, VALOR)'
                     + N' WHERE c.TABELA = @T AND v.CAMPO = c.CAMPO;';
            EXEC sys.sp_executesql @Sql, N'@T NVARCHAR(256)', @T = @T;
        END;
        SET @i = @i + 1;
    END;

    -- 4) Decisão por registro: ACAO = CAMPOS, LIXEIRA, DESATIVAR, APAGAR, REINSERIR ou NADA; BLOQUEIO = o que impede
    UPDATE r SET r.FOTO = (SELECT TOP 1 l.VALOR_ANTES FROM #Lin l WHERE l.TABELA = r.TABELA AND l.ID_REGISTRO = r.ID_REGISTRO AND l.OPERACAO = 'E' ORDER BY l.ID_AUDITORIA)
    FROM #Rec r WHERE r.TEM_E = 1;

    UPDATE r SET
           r.BLOQUEIO = CASE
             WHEN cf.TABELA IS NULL OR cf.PERMITE_DESFAZER = 0 THEN N'Este tipo de registro não pode ser desfeito pelo histórico.'
             WHEN r.TEM_I = 1 AND r.TEM_E = 1 THEN NULL
             WHEN r.TEM_E = 1 AND r.EXISTE = 0 AND cf.DESFAZER_EXCLUSAO = 'REINSERIR' THEN NULL
             WHEN r.TEM_E = 1 AND r.EXISTE = 0 THEN N'O registro foi apagado de vez: não dá para desfazer.'
             WHEN r.EXISTE = 0 AND r.TEM_I = 1 AND cf.DESFAZER_INCLUSAO = 'APAGAR' THEN NULL
             WHEN r.EXISTE = 0 THEN N'O registro foi apagado de vez depois: não dá para desfazer.'
             WHEN SIS.fn_SIS_Na_Lixeira(r.TABELA, r.ID_REGISTRO) = 1 THEN N'O registro está na lixeira: recupere-o antes (Sistema › Lixeira).'
             WHEN r.TEM_I = 1 AND cf.DESFAZER_INCLUSAO = 'RECUSAR' THEN N'O registro foi incluído nesta operação e este tipo de inclusão não é desfeito.'
             WHEN r.TEM_I = 1 AND cf.DESFAZER_INCLUSAO = 'LIXEIRA' AND cf.PERMITE_LIXEIRA = 0 THEN N'O registro foi incluído nesta operação e não pode ir para a lixeira.'
             WHEN r.TEM_I = 1 AND cf.DESFAZER_INCLUSAO = 'DESATIVAR' AND COL_LENGTH(r.TABELA, N'ATIVO') IS NULL THEN N'O registro foi incluído nesta operação e não pode ser desativado.'
             END,
           r.ACAO = CASE
             WHEN r.TEM_I = 1 AND r.TEM_E = 1 THEN 'NADA'
             WHEN r.TEM_E = 1 AND r.EXISTE = 0 THEN 'REINSERIR'
             WHEN r.EXISTE = 0 THEN 'NADA'
             WHEN r.TEM_I = 1 THEN cf.DESFAZER_INCLUSAO
             ELSE 'CAMPOS' END,
           r.AVISO = CASE
             WHEN r.TEM_I = 1 AND r.TEM_E = 1 THEN N'Incluído e apagado dentro do que será desfeito: nada a fazer.'
             WHEN r.TEM_E = 1 AND r.EXISTE = 0 THEN N'Apagado nesta operação: volta como estava (com código novo).'
             WHEN r.EXISTE = 0 THEN N'Incluído nesta operação e já não existe: nada a fazer.'
             WHEN r.TEM_I = 1 AND cf.DESFAZER_INCLUSAO = 'LIXEIRA' THEN N'Incluído nesta operação: vai para a lixeira (pode ser recuperado).'
             WHEN r.TEM_I = 1 AND cf.DESFAZER_INCLUSAO = 'APAGAR' THEN N'Incluído nesta operação: será retirado.'
             END
    FROM #Rec r
    LEFT JOIN SIS.Tabela_Config cf ON cf.TABELA = r.TABELA AND cf.ATIVO = 1;

    UPDATE #Rec SET BLOQUEIO = N'O registro apagado tinha campo sigiloso e não pode voltar.'
    WHERE BLOQUEIO IS NULL AND ACAO = 'REINSERIR' AND FOTO LIKE N'%"***"%';

    -- 5) Plano: registros inteiros (lixeira, apagar, reinserir, nada)
    INSERT INTO #Desfazer_Plano (TABELA, ID_REGISTRO, DESCRICAO, CAMPO, VALOR_ATUAL, VALOR_NOVO, ACAO, SITUACAO, MENSAGEM, ULTIMA_AUDITORIA)
    SELECT r.TABELA, r.ID_REGISTRO, r.DESCRICAO, N'', NULL, CASE WHEN r.ACAO = 'REINSERIR' THEN r.FOTO END,
           r.ACAO, 'OK', r.AVISO,
           (SELECT MAX(l.ID_AUDITORIA) FROM #Lin l WHERE l.TABELA = r.TABELA AND l.ID_REGISTRO = r.ID_REGISTRO)
    FROM #Rec r
    WHERE r.BLOQUEIO IS NULL AND r.ACAO IN ('LIXEIRA', 'APAGAR', 'REINSERIR', 'NADA');

    -- 6) Plano: campos (registros a alterar e inclusões a desativar)
    INSERT INTO #Desfazer_Plano (TABELA, ID_REGISTRO, DESCRICAO, CAMPO, VALOR_ATUAL, VALOR_NOVO, ACAO, SITUACAO, MENSAGEM, ULTIMA_AUDITORIA)
    SELECT c.TABELA, c.ID_REGISTRO, r.DESCRICAO, c.CAMPO, a.VALOR, c.VALOR_NOVO,
           CASE WHEN x.IGNORAR = 1 OR x.JA_ESTA = 1 THEN 'NADA'
                WHEN x.IGUAL_ESPERADO = 1 OR r.ACAO = 'DESATIVAR' THEN 'ALTERAR' ELSE 'NADA' END,
           CASE WHEN x.IGNORAR = 1 THEN 'IGNORADO'
                WHEN x.JA_ESTA = 1 OR x.IGUAL_ESPERADO = 1 OR r.ACAO = 'DESATIVAR' THEN 'OK' ELSE 'CONFLITO' END,
           CAST(CASE WHEN a.CAMPO IS NULL THEN N'O campo não existe mais.'
                     WHEN x.IGNORAR = 1 THEN N'Campo que não é desfeito (sigiloso, calculado, de controle ou marca da lixeira).'
                     WHEN x.JA_ESTA = 1 THEN N'Já está assim.'
                     WHEN r.ACAO = 'DESATIVAR' THEN N'Incluído nesta operação: vai ser desativado.'
                     WHEN x.IGUAL_ESPERADO = 1 THEN N''
                     ELSE LEFT(N'Mudou depois desta operação: hoje está "' + ISNULL(a.VALOR, N'(vazio)') + N'".', 400) END AS NVARCHAR(400)),
           NULLIF(c.ULTIMA, 0)
    FROM #Campo c
    INNER JOIN #Rec r ON r.TABELA = c.TABELA AND r.ID_REGISTRO = c.ID_REGISTRO
    LEFT  JOIN SIS.Tabela_Config cf ON cf.TABELA = c.TABELA
    LEFT  JOIN #Atual a ON a.TABELA = c.TABELA AND a.ID_REGISTRO = c.ID_REGISTRO AND a.CAMPO = c.CAMPO
    CROSS APPLY (SELECT
           CAST(CASE WHEN a.CAMPO IS NULL
                       OR c.CAMPO IN (N'DT_CRIACAO', N'USUARIO_CRIACAO', N'DT_ALTERACAO', N'USUARIO_ALTERACAO', N'DT_EXCLUSAO', N'USUARIO_EXCLUSAO')
                       OR c.CAMPO = SIS.fn_SIS_Tabela_PK(c.TABELA)
                       OR c.VALOR_NOVO = N'***' OR c.VALOR_ESPERADO = N'***' OR a.VALOR = N'***'
                       OR EXISTS (SELECT 1 FROM STRING_SPLIT(ISNULL(cf.CAMPOS_BLOQUEADOS, N''), N',') s WHERE LTRIM(RTRIM(s.value)) = c.CAMPO)
                     THEN 1 ELSE 0 END AS BIT) AS IGNORAR,
           CAST(CASE WHEN (a.VALOR IS NULL AND c.VALOR_NOVO IS NULL)
                       OR (a.VALOR COLLATE Latin1_General_BIN2 = c.VALOR_NOVO COLLATE Latin1_General_BIN2) THEN 1 ELSE 0 END AS BIT) AS JA_ESTA,
           CAST(CASE WHEN (a.VALOR IS NULL AND c.VALOR_ESPERADO IS NULL)
                       OR (a.VALOR COLLATE Latin1_General_BIN2 = c.VALOR_ESPERADO COLLATE Latin1_General_BIN2) THEN 1 ELSE 0 END AS BIT) AS IGUAL_ESPERADO
        ) x
    WHERE r.BLOQUEIO IS NULL
      AND (r.ACAO = 'CAMPOS' OR (r.ACAO = 'DESATIVAR' AND c.CAMPO = N'ATIVO'));

    -- 7) Travas (mês fechado e trava própria) dos registros que vão mudar e ainda existem
    DROP TABLE IF EXISTS #Trava;
    SELECT ROW_NUMBER() OVER (ORDER BY p.TABELA, p.ID_REGISTRO) AS ORDEM, p.TABELA, p.ID_REGISTRO
    INTO #Trava
    FROM #Desfazer_Plano p
    WHERE p.ACAO IN ('ALTERAR', 'LIXEIRA', 'APAGAR')
    GROUP BY p.TABELA, p.ID_REGISTRO;

    SELECT @i = 1, @Total = COUNT(*) FROM #Trava;
    WHILE @i <= @Total
    BEGIN
        SELECT @T = t.TABELA, @Id = t.ID_REGISTRO FROM #Trava t WHERE t.ORDEM = @i;
        SET @ColData = NULL;
        SELECT @ColData = NULLIF(cf.COLUNA_DATA_MES, N'') FROM SIS.Tabela_Config cf WHERE cf.TABELA = @T;
        SET @DataNova = (SELECT TOP 1 TRY_CONVERT(DATE, p.VALOR_NOVO, 121) FROM #Desfazer_Plano p
                         WHERE p.TABELA = @T AND p.ID_REGISTRO = @Id AND p.CAMPO = @ColData AND p.ACAO = 'ALTERAR' ORDER BY p.ORDEM);
        SET @Msg = N'';
        EXEC SIS.SIS_Tabela_Trava_Conferir @Tabela = @T, @IdRegistro = @Id, @Operacao = 'DESFAZER', @DataNova = @DataNova, @Mensagem = @Msg OUTPUT;
        IF ISNULL(@Msg, N'') <> N''
            UPDATE #Rec SET BLOQUEIO = @Msg WHERE TABELA = @T AND ID_REGISTRO = @Id;
        SET @i = @i + 1;
    END;
    DROP TABLE IF EXISTS #Trava;

    -- 8) Registros bloqueados: uma linha cada, sem os campos
    DELETE p FROM #Desfazer_Plano p INNER JOIN #Rec r ON r.TABELA = p.TABELA AND r.ID_REGISTRO = p.ID_REGISTRO WHERE r.BLOQUEIO IS NOT NULL;

    INSERT INTO #Desfazer_Plano (TABELA, ID_REGISTRO, DESCRICAO, CAMPO, VALOR_ATUAL, VALOR_NOVO, ACAO, SITUACAO, MENSAGEM, ULTIMA_AUDITORIA)
    SELECT r.TABELA, r.ID_REGISTRO, r.DESCRICAO, N'', NULL, NULL, 'NADA', 'BLOQUEADO', r.BLOQUEIO,
           (SELECT MAX(l.ID_AUDITORIA) FROM #Lin l WHERE l.TABELA = r.TABELA AND l.ID_REGISTRO = r.ID_REGISTRO)
    FROM #Rec r
    WHERE r.BLOQUEIO IS NOT NULL;

Fim:
    DROP TABLE IF EXISTS #Reg;
    DROP TABLE IF EXISTS #Lin;
    DROP TABLE IF EXISTS #Campo;
    DROP TABLE IF EXISTS #Atual;
    DROP TABLE IF EXISTS #Rec;
    DROP TABLE IF EXISTS #Tab;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Historico_Desfazer_Previa.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Historico_Desfazer_Previa]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Prévia do desfazer pelo histórico (P20), sem gravar nada: o
                que vai mudar, campo a campo (como está agora e como vai
                ficar), o que vai para a lixeira e o que impede (CONFLITO,
                BLOQUEADO). Usada pela aba Histórico das fichas e pela tela de
                Auditoria antes de confirmar. Modos e regras: ver
                SIS_Historico_Desfazer_Montar.
                Permissão: DESFAZER na tela (@Item); no modo REGISTRO a tela
                precisa mostrar a tabela; no modo LOTE, a tela é
                SIS_AUDITORIA.
                Devolve as linhas do plano, com TELA_NOME e as colunas
                PODE_DESFAZER (1 = tudo certo) e RESUMO iguais em todas.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Historico_Desfazer_Previa @IdUsuario = 2, @Item = 'CAD_PESSOA', @Modo = 'REGISTRO', @Tabela = N'CAD.Pessoa', @IdRegistro = 1, @IdAuditoria = 10;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Historico_Desfazer_Previa]
    @IdUsuario    INT,
    @Item         VARCHAR(40),
    @Modo         VARCHAR(10),
    @Tabela       NVARCHAR(256) = NULL,
    @IdRegistro   BIGINT        = NULL,
    @IdAuditoria  BIGINT        = NULL,
    @DataHora     DATETIME2(0)  = NULL,
    @IdLote       BIGINT        = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Historico_Desfazer_Previa]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Pode BIT, @Resumo NVARCHAR(400), @Muda INT, @Impede INT;

    DROP TABLE IF EXISTS #Desfazer_Plano;

    BEGIN TRY
        SET @Modo   = UPPER(LTRIM(RTRIM(ISNULL(@Modo, ''))));
        SET @Tabela = LTRIM(RTRIM(ISNULL(@Tabela, N'')));

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'DESFAZER') = 0
            THROW 50001, N'Você não tem permissão para desfazer nesta tela.', 1;
        IF @Modo NOT IN ('REGISTRO', 'OPERACAO', 'LOTE')
            THROW 50001, N'Modo de desfazer inválido.', 1;
        IF @Modo = 'REGISTRO' AND (SIS.fn_SIS_Item_Tem_Tabela(@Item, @Tabela) = 0 OR @IdRegistro IS NULL OR (@IdAuditoria IS NULL AND @DataHora IS NULL))
            THROW 50001, N'Escolha o registro e o ponto do histórico para onde voltar.', 1;
        IF @Modo = 'OPERACAO' AND @IdAuditoria IS NULL
            THROW 50001, N'Escolha a operação a desfazer.', 1;
        IF @Modo = 'LOTE' AND (@Item <> 'SIS_AUDITORIA' OR @IdLote IS NULL)
            THROW 50001, N'Escolha o lote a desfazer (tela de Auditoria).', 1;

        SET @EtapaAtual = 'Montagem';
        CREATE TABLE #Desfazer_Plano
        (
            ORDEM             INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
            TABELA            NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL,
            ID_REGISTRO       BIGINT        NOT NULL,
            DESCRICAO         NVARCHAR(400) COLLATE DATABASE_DEFAULT NULL,
            CAMPO             NVARCHAR(128) COLLATE DATABASE_DEFAULT NOT NULL,
            VALOR_ATUAL       NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL,
            VALOR_NOVO        NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL,
            ACAO              VARCHAR(10)   COLLATE DATABASE_DEFAULT NOT NULL,
            SITUACAO          VARCHAR(10)   COLLATE DATABASE_DEFAULT NOT NULL,
            MENSAGEM          NVARCHAR(400) COLLATE DATABASE_DEFAULT NULL,
            ULTIMA_AUDITORIA  BIGINT        NULL
        );

        EXEC SIS.SIS_Historico_Desfazer_Montar @Modo = @Modo, @Tabela = @Tabela, @IdRegistro = @IdRegistro,
             @IdAuditoria = @IdAuditoria, @DataHora = @DataHora, @IdLote = @IdLote;

        SELECT @Muda = COUNT(*) FROM #Desfazer_Plano WHERE ACAO IN ('ALTERAR', 'LIXEIRA', 'APAGAR', 'REINSERIR');
        SELECT @Impede = COUNT(*) FROM #Desfazer_Plano WHERE SITUACAO IN ('CONFLITO', 'BLOQUEADO');
        SET @Pode = CASE WHEN @Muda > 0 AND @Impede = 0 THEN 1 ELSE 0 END;
        SET @Resumo = CASE WHEN @Impede > 0 THEN CAST(@Impede AS NVARCHAR(10)) + N' ponto(s) impedem desfazer: veja as linhas em vermelho.'
                           WHEN @Muda = 0 THEN N'Nada a desfazer: já está tudo como estava.'
                           ELSE CAST(@Muda AS NVARCHAR(10)) + N' mudança(s) a fazer. Confira e informe o motivo.' END;

        SELECT p.ORDEM,
               p.TABELA,
               ISNULL(i.NOME, p.TABELA) AS TELA_NOME,
               p.ID_REGISTRO,
               ISNULL(p.DESCRICAO, N'') AS DESCRICAO,
               p.CAMPO,
               ISNULL(CAST(p.VALOR_ATUAL AS NVARCHAR(4000)), N'') AS VALOR_ATUAL,
               ISNULL(CAST(p.VALOR_NOVO  AS NVARCHAR(4000)), N'') AS VALOR_NOVO,
               p.ACAO,
               p.SITUACAO,
               ISNULL(p.MENSAGEM, N'') AS MENSAGEM,
               p.ULTIMA_AUDITORIA,
               @Pode AS PODE_DESFAZER,
               @Resumo AS RESUMO
        FROM #Desfazer_Plano p
        LEFT JOIN SIS.Item i ON i.CODIGO = SIS.fn_SIS_Item_Da_Tabela(p.TABELA)
        ORDER BY CASE p.SITUACAO WHEN 'BLOQUEADO' THEN 0 WHEN 'CONFLITO' THEN 1 ELSE 2 END, p.TABELA, p.ID_REGISTRO, p.ORDEM;

        DROP TABLE IF EXISTS #Desfazer_Plano;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> -1 DROP TABLE IF EXISTS #Desfazer_Plano;
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível montar a prévia. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Historico_Desfazer.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Historico_Desfazer]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 22/11/2026
  Descrição   : Desfaz pelo histórico (P20), depois da prévia
                (SIS_Historico_Desfazer_Previa): voltar um registro a um ponto
                do histórico (REGISTRO), desfazer uma operação (OPERACAO) ou
                um lote inteiro (LOTE, tela de Auditoria).
                Tudo-ou-nada: se houver qualquer CONFLITO ou BLOQUEADO, não
                faz nada. Grava como alteração nova (a auditoria registra
                tudo, com a origem "desfazer"), as inclusões desfeitas vão para
                a lixeira, são desativadas ou retiradas (tabelas de ligação),
                as exclusões de tabelas de ligação voltam com a foto da
                auditoria (código novo), e o pedido fica em SIS.Desfazer
                com o motivo (obrigatório).
                Permissão: DESFAZER na tela (@Item) e, para cada tipo de
                registro que vai mudar, DESFAZER numa tela que o mostra.
                Devolve 1 linha: SUCESSO, MENSAGEM, ID_DESFAZER, QTD_REGISTROS,
                QTD_CAMPOS, QTD_LIXEIRA.
  Changelog:
    v1.0 (22/11/2026) - Criação (etapa 04b).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Historico_Desfazer @IdUsuario = 2, @Item = 'CAD_PESSOA', @Modo = 'OPERACAO', @IdAuditoria = 10, @Motivo = N'alterado por engano';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Historico_Desfazer]
    @IdUsuario    INT,
    @Item         VARCHAR(40),
    @Modo         VARCHAR(10),
    @Tabela       NVARCHAR(256) = NULL,
    @IdRegistro   BIGINT        = NULL,
    @IdAuditoria  BIGINT        = NULL,
    @DataHora     DATETIME2(0)  = NULL,
    @IdLote       BIGINT        = NULL,
    @Motivo       NVARCHAR(400) = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Historico_Desfazer]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @TranCountEntrada INT = @@TRANCOUNT;
    DECLARE @Recusa NVARCHAR(400) = N'', @Usuario NVARCHAR(100), @OrigemAntes NVARCHAR(256), @OrigemNova NVARCHAR(256);
    DECLARE @Muda INT, @Impede INT, @QtdReg INT, @QtdCampos INT, @QtdLixeira INT, @IdDesfazer BIGINT, @Transacao BIGINT;
    DECLARE @Alt TABLE (ORDEM INT IDENTITY(1,1), TABELA NVARCHAR(256), CAMPO NVARCHAR(128), QTD INT);
    DECLARE @Lix TABLE (ORDEM INT IDENTITY(1,1), TABELA NVARCHAR(256), ID_REGISTRO BIGINT);
    DECLARE @Apg TABLE (ORDEM INT IDENTITY(1,1), TABELA NVARCHAR(256), QTD INT);
    DECLARE @Rei TABLE (ORDEM INT IDENTITY(1,1), TABELA NVARCHAR(256), FOTO NVARCHAR(MAX));
    DECLARE @Foto NVARCHAR(MAX), @Cols NVARCHAR(MAX), @With NVARCHAR(MAX);
    DECLARE @i INT, @Total INT, @T NVARCHAR(256), @C NVARCHAR(128), @Qtd INT, @Feitos INT, @Id BIGINT;
    DECLARE @ObjId INT, @Pk NVARCHAR(128), @Nome NVARCHAR(300), @Tipo NVARCHAR(128), @EData BIT, @Expr NVARCHAR(400), @Sql NVARCHAR(MAX), @IdLixeira BIGINT, @Msg NVARCHAR(400);
    DECLARE @TelaSemPermissao NVARCHAR(256);

    DROP TABLE IF EXISTS #Desfazer_Plano;

    BEGIN TRY
        SET @Modo   = UPPER(LTRIM(RTRIM(ISNULL(@Modo, ''))));
        SET @Tabela = LTRIM(RTRIM(ISNULL(@Tabela, N'')));
        SET @Motivo = LTRIM(RTRIM(ISNULL(@Motivo, N'')));

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'DESFAZER') = 0
            SET @Recusa = N'Você não tem permissão para desfazer nesta tela.';
        ELSE IF @Modo NOT IN ('REGISTRO', 'OPERACAO', 'LOTE')
            SET @Recusa = N'Modo de desfazer inválido.';
        ELSE IF @Modo = 'REGISTRO' AND (SIS.fn_SIS_Item_Tem_Tabela(@Item, @Tabela) = 0 OR @IdRegistro IS NULL OR (@IdAuditoria IS NULL AND @DataHora IS NULL))
            SET @Recusa = N'Escolha o registro e o ponto do histórico para onde voltar.';
        ELSE IF @Modo = 'OPERACAO' AND @IdAuditoria IS NULL
            SET @Recusa = N'Escolha a operação a desfazer.';
        ELSE IF @Modo = 'LOTE' AND (@Item <> 'SIS_AUDITORIA' OR @IdLote IS NULL)
            SET @Recusa = N'Escolha o lote a desfazer (tela de Auditoria).';
        ELSE IF LEN(@Motivo) < 3
            SET @Recusa = N'Informe o motivo do desfazer.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID_DESFAZER, 0 AS QTD_REGISTROS, 0 AS QTD_CAMPOS, 0 AS QTD_LIXEIRA;
            RETURN;
        END;

        SET @EtapaAtual = 'Montagem';
        CREATE TABLE #Desfazer_Plano
        (
            ORDEM             INT IDENTITY(1,1) NOT NULL PRIMARY KEY,
            TABELA            NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL,
            ID_REGISTRO       BIGINT        NOT NULL,
            DESCRICAO         NVARCHAR(400) COLLATE DATABASE_DEFAULT NULL,
            CAMPO             NVARCHAR(128) COLLATE DATABASE_DEFAULT NOT NULL,
            VALOR_ATUAL       NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL,
            VALOR_NOVO        NVARCHAR(MAX) COLLATE DATABASE_DEFAULT NULL,
            ACAO              VARCHAR(10)   COLLATE DATABASE_DEFAULT NOT NULL,
            SITUACAO          VARCHAR(10)   COLLATE DATABASE_DEFAULT NOT NULL,
            MENSAGEM          NVARCHAR(400) COLLATE DATABASE_DEFAULT NULL,
            ULTIMA_AUDITORIA  BIGINT        NULL
        );

        EXEC SIS.SIS_Historico_Desfazer_Montar @Modo = @Modo, @Tabela = @Tabela, @IdRegistro = @IdRegistro,
             @IdAuditoria = @IdAuditoria, @DataHora = @DataHora, @IdLote = @IdLote;

        SELECT @Muda = COUNT(*) FROM #Desfazer_Plano WHERE ACAO IN ('ALTERAR', 'LIXEIRA', 'APAGAR', 'REINSERIR');
        SELECT @Impede = COUNT(*) FROM #Desfazer_Plano WHERE SITUACAO IN ('CONFLITO', 'BLOQUEADO');

        IF @Impede > 0
            SET @Recusa = LEFT(N'Nada foi desfeito: ' + CAST(@Impede AS NVARCHAR(10)) + N' ponto(s) impedem. '
                        + ISNULL((SELECT TOP 1 p.MENSAGEM FROM #Desfazer_Plano p WHERE p.SITUACAO IN ('CONFLITO', 'BLOQUEADO')
                                  ORDER BY CASE p.SITUACAO WHEN 'BLOQUEADO' THEN 0 ELSE 1 END, p.ORDEM), N''), 400);
        ELSE IF @Muda = 0
            SET @Recusa = N'Nada a desfazer: já está tudo como estava.';

        -- Permissão para cada tipo de registro que vai mudar
        IF @Recusa = N''
        BEGIN
            SELECT TOP 1 @TelaSemPermissao = p.TABELA
            FROM (SELECT DISTINCT TABELA FROM #Desfazer_Plano WHERE ACAO IN ('ALTERAR', 'LIXEIRA', 'APAGAR', 'REINSERIR')) p
            WHERE NOT EXISTS (SELECT 1 FROM SIS.Item it
                              CROSS APPLY STRING_SPLIT(it.TABELAS_DA_TELA, ',') s
                              WHERE LTRIM(RTRIM(s.value)) = p.TABELA AND it.TIPO = 'TELA'
                                AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, it.CODIGO, 'DESFAZER') = 1)
            ORDER BY p.TABELA;
            IF @TelaSemPermissao IS NOT NULL
                SET @Recusa = LEFT(N'Você não tem permissão para desfazer em ' + ISNULL((SELECT i.NOME FROM SIS.Item i WHERE i.CODIGO = SIS.fn_SIS_Item_Da_Tabela(@TelaSemPermissao)), @TelaSemPermissao) + N'.', 400);
        END;

        IF @Recusa <> N''
        BEGIN
            DROP TABLE IF EXISTS #Desfazer_Plano;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID_DESFAZER, 0 AS QTD_REGISTROS, 0 AS QTD_CAMPOS, 0 AS QTD_LIXEIRA;
            RETURN;
        END;

        INSERT INTO @Alt (TABELA, CAMPO, QTD)
        SELECT p.TABELA, p.CAMPO, COUNT(*) FROM #Desfazer_Plano p WHERE p.ACAO = 'ALTERAR' GROUP BY p.TABELA, p.CAMPO ORDER BY p.TABELA, p.CAMPO;
        INSERT INTO @Lix (TABELA, ID_REGISTRO)
        SELECT p.TABELA, p.ID_REGISTRO FROM #Desfazer_Plano p WHERE p.ACAO = 'LIXEIRA' ORDER BY p.ORDEM DESC;
        INSERT INTO @Apg (TABELA, QTD)
        SELECT p.TABELA, COUNT(*) FROM #Desfazer_Plano p WHERE p.ACAO = 'APAGAR' GROUP BY p.TABELA ORDER BY p.TABELA;
        INSERT INTO @Rei (TABELA, FOTO)
        SELECT p.TABELA, p.VALOR_NOVO FROM #Desfazer_Plano p WHERE p.ACAO = 'REINSERIR' ORDER BY p.ORDEM;

        SELECT @QtdReg = COUNT(*) FROM (SELECT DISTINCT TABELA, ID_REGISTRO FROM #Desfazer_Plano WHERE ACAO IN ('ALTERAR', 'LIXEIRA', 'APAGAR', 'REINSERIR')) x;
        SELECT @QtdCampos = COUNT(*) FROM #Desfazer_Plano WHERE ACAO = 'ALTERAR';
        SELECT @QtdLixeira = COUNT(*) FROM @Lix;

        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        SET @OrigemAntes = ISNULL(CONVERT(NVARCHAR(256), SESSION_CONTEXT(N'ORIGEM')), N'');
        SET @OrigemNova = LEFT(CASE WHEN @OrigemAntes = N'' THEN N'' ELSE @OrigemAntes + N' › ' END + N'desfazer', 256);

        SET @EtapaAtual = 'Gravação';
        IF @TranCountEntrada = 0 BEGIN TRANSACTION;

            EXEC sys.sp_set_session_context @key = N'ORIGEM', @value = @OrigemNova;
            SET @Transacao = CURRENT_TRANSACTION_ID();

            -- Inclusões de tabelas de ligação: retiradas
            SELECT @i = 1, @Total = COUNT(*) FROM @Apg;
            WHILE @i <= @Total
            BEGIN
                SELECT @T = a.TABELA, @Qtd = a.QTD FROM @Apg a WHERE a.ORDEM = @i;
                SET @ObjId = OBJECT_ID(@T, N'U');
                SET @Pk = SIS.fn_SIS_Tabela_PK(@T);
                SET @Sql = N'DELETE t FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId)) + N' t'
                         + N' INNER JOIN #Desfazer_Plano p ON p.ID_REGISTRO = t.' + QUOTENAME(@Pk) + N' WHERE p.TABELA = @T AND p.ACAO = ''APAGAR''; SET @n = @@ROWCOUNT;';
                SET @Feitos = 0;
                EXEC sys.sp_executesql @Sql, N'@T NVARCHAR(256), @n INT OUTPUT', @T = @T, @n = @Feitos OUTPUT;
                IF ISNULL(@Feitos, 0) <> @Qtd
                    THROW 50003, N'Nada foi desfeito: alguém mudou estes registros enquanto a prévia estava aberta. Abra a prévia de novo.', 1;
                SET @i = @i + 1;
            END;

            -- Campos: um UPDATE por tabela e campo, só onde o valor de hoje ainda é o da prévia
            SELECT @i = 1, @Total = COUNT(*) FROM @Alt;
            WHILE @i <= @Total
            BEGIN
                SELECT @T = a.TABELA, @C = a.CAMPO, @Qtd = a.QTD FROM @Alt a WHERE a.ORDEM = @i;
                SET @ObjId = OBJECT_ID(@T, N'U');
                SET @Pk = SIS.fn_SIS_Tabela_PK(@T);
                SET @Nome = QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId));
                SET @Tipo = SIS.fn_SIS_Coluna_Tipo(@T, @C);
                SET @EData = CASE WHEN @Tipo LIKE N'DATE%' OR @Tipo LIKE N'TIME%' OR @Tipo LIKE N'SMALLDATETIME%' THEN 1 ELSE 0 END;
                SET @Expr = CASE WHEN @EData = 1 THEN N'CONVERT(NVARCHAR(MAX), t.' + QUOTENAME(@C) + N', 121)' ELSE N'CONVERT(NVARCHAR(MAX), t.' + QUOTENAME(@C) + N')' END;

                SET @Sql = N'UPDATE t SET t.' + QUOTENAME(@C) + N' = CONVERT(' + @Tipo + N', p.VALOR_NOVO' + CASE WHEN @EData = 1 THEN N', 121' ELSE N'' END + N')'
                         + CASE WHEN COL_LENGTH(@T, N'DT_ALTERACAO') IS NOT NULL AND COL_LENGTH(@T, N'USUARIO_ALTERACAO') IS NOT NULL AND @C NOT IN (N'DT_ALTERACAO', N'USUARIO_ALTERACAO')
                                THEN N', t.DT_ALTERACAO = SYSDATETIME(), t.USUARIO_ALTERACAO = @Usuario' ELSE N'' END
                         + N' FROM ' + @Nome + N' t INNER JOIN #Desfazer_Plano p ON p.ID_REGISTRO = t.' + QUOTENAME(@Pk)
                         + N' WHERE p.TABELA = @T AND p.CAMPO = @C AND p.ACAO = ''ALTERAR'''
                         + N' AND ((' + @Expr + N' IS NULL AND p.VALOR_ATUAL IS NULL) OR (' + @Expr + N' COLLATE Latin1_General_BIN2 = p.VALOR_ATUAL COLLATE Latin1_General_BIN2));'
                         + N' SET @n = @@ROWCOUNT;';
                SET @Feitos = 0;
                EXEC sys.sp_executesql @Sql, N'@T NVARCHAR(256), @C NVARCHAR(128), @Usuario NVARCHAR(100), @n INT OUTPUT', @T = @T, @C = @C, @Usuario = @Usuario, @n = @Feitos OUTPUT;
                IF ISNULL(@Feitos, 0) <> @Qtd
                    THROW 50003, N'Nada foi desfeito: alguém mudou estes registros enquanto a prévia estava aberta. Abra a prévia de novo.', 1;
                SET @i = @i + 1;
            END;

            -- Exclusões de tabelas de ligação: voltam com a foto da auditoria (código novo)
            SELECT @i = 1, @Total = COUNT(*) FROM @Rei;
            WHILE @i <= @Total
            BEGIN
                SELECT @T = r.TABELA, @Foto = r.FOTO FROM @Rei r WHERE r.ORDEM = @i;
                SET @ObjId = OBJECT_ID(@T, N'U');
                SELECT @Cols = STRING_AGG(CONVERT(NVARCHAR(MAX), QUOTENAME(c.name)), N', ') WITHIN GROUP (ORDER BY c.column_id),
                       @With = STRING_AGG(CONVERT(NVARCHAR(MAX), QUOTENAME(c.name) + N' ' + SIS.fn_SIS_Coluna_Tipo(@T, c.name) + N' ''$.' + REPLACE(c.name, N'''', N'''''') + N''''), N', ')
                                 WITHIN GROUP (ORDER BY c.column_id)
                FROM sys.columns c
                INNER JOIN sys.types ty ON ty.system_type_id = c.system_type_id AND ty.user_type_id = c.system_type_id
                WHERE c.object_id = @ObjId AND c.is_identity = 0 AND c.is_computed = 0
                  AND c.name NOT IN (N'DT_CRIACAO', N'USUARIO_CRIACAO', N'DT_ALTERACAO', N'USUARIO_ALTERACAO')
                  AND ty.name NOT IN ('varbinary', 'binary', 'image', 'timestamp', 'text', 'ntext', 'geography', 'geometry');
                SET @Sql = N'INSERT INTO ' + QUOTENAME(OBJECT_SCHEMA_NAME(@ObjId)) + N'.' + QUOTENAME(OBJECT_NAME(@ObjId)) + N' (' + @Cols + N')'
                         + N' SELECT ' + @Cols + N' FROM OPENJSON(@Foto) WITH (' + @With + N');';
                BEGIN TRY
                    EXEC sys.sp_executesql @Sql, N'@Foto NVARCHAR(MAX)', @Foto = @Foto;
                END TRY
                BEGIN CATCH
                    IF ERROR_NUMBER() IN (2601, 2627)
                        THROW 50003, N'Nada foi desfeito: um registro apagado não pode voltar porque já existe outro igual.', 1;
                    THROW;
                END CATCH;
                SET @i = @i + 1;
            END;

            -- Inclusões desfeitas: para a lixeira (das filhas para o principal)
            SELECT @i = 1, @Total = COUNT(*) FROM @Lix;
            WHILE @i <= @Total
            BEGIN
                SELECT @T = l.TABELA, @Id = l.ID_REGISTRO FROM @Lix l WHERE l.ORDEM = @i;
                SET @Msg = N'';
                EXEC SIS.SIS_Lixeira_Marcar @IdUsuario = @IdUsuario, @Tabela = @T, @IdRegistro = @Id, @Item = NULL,
                     @Motivo = @Motivo, @IdLixeira = @IdLixeira OUTPUT, @Mensagem = @Msg OUTPUT;
                IF ISNULL(@Msg, N'') <> N''
                BEGIN
                    SET @Msg = LEFT(N'Nada foi desfeito: um registro incluído não pôde ir para a lixeira. ' + @Msg, 400);
                    THROW 50003, @Msg, 1;
                END;
                SET @i = @i + 1;
            END;

            INSERT INTO SIS.Desfazer (TIPO, ITEM_CODIGO, TABELA, ID_REGISTRO, ID_AUDITORIA, DT_ALVO, TRANSACAO_ALVO, ID_LOTE_ALVO, MOTIVO,
                                      QTD_REGISTROS, QTD_CAMPOS, QTD_LIXEIRA, TRANSACAO, ID_USUARIO, USUARIO)
            VALUES (@Modo, ISNULL(@Item, ''), @Tabela, @IdRegistro, @IdAuditoria, @DataHora,
                    CASE WHEN @Modo = 'OPERACAO' THEN (SELECT a.TRANSACAO FROM SIS.Auditoria a WHERE a.ID_AUDITORIA = @IdAuditoria) END,
                    @IdLote, @Motivo, ISNULL(@QtdReg, 0), ISNULL(@QtdCampos, 0), ISNULL(@QtdLixeira, 0), @Transacao, @IdUsuario, ISNULL(@Usuario, N''));
            SET @IdDesfazer = SCOPE_IDENTITY();

            EXEC sys.sp_set_session_context @key = N'ORIGEM', @value = @OrigemAntes;
        IF @TranCountEntrada = 0 COMMIT TRANSACTION;

        DROP TABLE IF EXISTS #Desfazer_Plano;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(N'Desfeito: ' + CAST(ISNULL(@QtdCampos, 0) AS NVARCHAR(10)) + N' campo(s) em ' + CAST(ISNULL(@QtdReg, 0) AS NVARCHAR(10)) + N' registro(s)'
                    + CASE WHEN @QtdLixeira > 0 THEN N'; ' + CAST(@QtdLixeira AS NVARCHAR(10)) + N' registro(s) incluído(s) foram para a lixeira' ELSE N'' END
                    + CASE WHEN (SELECT ISNULL(SUM(a.QTD), 0) FROM @Apg a) > 0 THEN N'; ' + CAST((SELECT SUM(a.QTD) FROM @Apg a) AS NVARCHAR(10)) + N' retirado(s)' ELSE N'' END
                    + CASE WHEN (SELECT COUNT(*) FROM @Rei) > 0 THEN N'; ' + CAST((SELECT COUNT(*) FROM @Rei) AS NVARCHAR(10)) + N' devolvido(s)' ELSE N'' END
                    + N'. Tudo ficou no histórico.' AS NVARCHAR(400)) AS MENSAGEM,
               @IdDesfazer AS ID_DESFAZER, ISNULL(@QtdReg, 0) AS QTD_REGISTROS, ISNULL(@QtdCampos, 0) AS QTD_CAMPOS, ISNULL(@QtdLixeira, 0) AS QTD_LIXEIRA;
    END TRY
    BEGIN CATCH
        IF @TranCountEntrada = 0 AND @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF XACT_STATE() <> -1
        BEGIN
            EXEC sys.sp_set_session_context @key = N'ORIGEM', @value = @OrigemAntes;
            DROP TABLE IF EXISTS #Desfazer_Plano;
            IF ERROR_NUMBER() <> 50003
                INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
                VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        END;

        SELECT CAST(0 AS BIT) AS SUCESSO,
               CAST(CASE WHEN ERROR_NUMBER() = 50003 THEN ERROR_MESSAGE() ELSE N'Não foi possível desfazer. Nada foi alterado; o erro foi registrado para análise.' END AS NVARCHAR(400)) AS MENSAGEM,
               CAST(NULL AS BIGINT) AS ID_DESFAZER, 0 AS QTD_REGISTROS, 0 AS QTD_CAMPOS, 0 AS QTD_LIXEIRA;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Historico_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Historico_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 23/11/2026
  Descrição   : Aba Histórico padrão de todas as fichas (P20, etapa 04b2): o
                histórico do registro e das filhas que "vão junto"
                (SIS.Tabela_Config.TABELAS_FILHAS), inclusive as já apagadas
                (achadas pela foto da auditoria), mais recente primeiro.
                TRANSACAO agrupa o que foi gravado junto (uma operação).
                PRINCIPAL = 1 nas linhas do próprio registro.
                DESCRICAO: nas permissões (tabelas com ID_ITEM_ACAO), o nome
                da tela e da ação; nas outras, vazia.
                Permissão: VER na tela (@Item), que precisa mostrar @Tabela.
                Padrão "Listar": THROW 50001 com mensagem amigável.
  Changelog:
    v1.0 (23/11/2026) - Criação (etapa 04b2).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Historico_Listar @IdUsuario = 2, @Item = 'CAD_PESSOA', @Tabela = N'CAD.Pessoa', @IdRegistro = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Historico_Listar]
    @IdUsuario   INT,
    @Item        VARCHAR(40),
    @Tabela      NVARCHAR(256),
    @IdRegistro  BIGINT,
    @MaxLinhas   INT = NULL
WITH EXECUTE AS OWNER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Historico_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Sql NVARCHAR(MAX) = N'';

    DROP TABLE IF EXISTS #Reg;

    BEGIN TRY
        SET @Tabela    = LTRIM(RTRIM(ISNULL(@Tabela, N'')));
        SET @MaxLinhas = ISNULL(@MaxLinhas, 1000);
        IF @MaxLinhas < 1 OR @MaxLinhas > 10000 SET @MaxLinhas = 1000;

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver esta tela.', 1;
        IF SIS.fn_SIS_Item_Tem_Tabela(@Item, @Tabela) = 0
            THROW 50001, N'Esta tela não mostra histórico desse tipo de registro.', 1;
        IF @IdRegistro IS NULL
            THROW 50001, N'Escolha o registro.', 1;

        SET @EtapaAtual = 'Registros';
        CREATE TABLE #Reg (TABELA NVARCHAR(256) COLLATE DATABASE_DEFAULT NOT NULL, ID_REGISTRO BIGINT NOT NULL, PRIMARY KEY (TABELA, ID_REGISTRO));
        INSERT INTO #Reg (TABELA, ID_REGISTRO) VALUES (@Tabela, @IdRegistro);

        -- filhas que vão junto: as que existem hoje e as que já existiram (foto da auditoria)
        SELECT @Sql = @Sql
                    + N'INSERT INTO #Reg (TABELA, ID_REGISTRO) SELECT DISTINCT N''' + REPLACE(f.TABELA, N'''', N'''''') + N''', CAST(f.'
                    + QUOTENAME(SIS.fn_SIS_Tabela_PK(f.TABELA)) + N' AS BIGINT) FROM ' + QUOTENAME(OBJECT_SCHEMA_NAME(OBJECT_ID(f.TABELA, N'U'))) + N'.'
                    + QUOTENAME(OBJECT_NAME(OBJECT_ID(f.TABELA, N'U'))) + N' f WITH (NOLOCK) WHERE f.' + QUOTENAME(f.COLUNA) + N' = @Id'
                    + N' AND NOT EXISTS (SELECT 1 FROM #Reg r WHERE r.TABELA = N''' + REPLACE(f.TABELA, N'''', N'''''') + N''' AND r.ID_REGISTRO = f.'
                    + QUOTENAME(SIS.fn_SIS_Tabela_PK(f.TABELA)) + N');' + NCHAR(13) + NCHAR(10)
                    + N'INSERT INTO #Reg (TABELA, ID_REGISTRO) SELECT DISTINCT a.TABELA, a.ID_REGISTRO FROM SIS.Auditoria a WITH (NOLOCK)'
                    + N' WHERE a.TABELA = N''' + REPLACE(f.TABELA, N'''', N'''''') + N''' AND a.OPERACAO IN (''I'', ''E'')'
                    + N' AND JSON_VALUE(COALESCE(a.VALOR_DEPOIS, a.VALOR_ANTES), N''$.' + REPLACE(f.COLUNA, N'''', N'''''') + N''') = CAST(@Id AS NVARCHAR(30))'
                    + N' AND NOT EXISTS (SELECT 1 FROM #Reg r WHERE r.TABELA = a.TABELA AND r.ID_REGISTRO = a.ID_REGISTRO);' + NCHAR(13) + NCHAR(10)
        FROM (SELECT LEFT(x.v, LEN(x.v) - CHARINDEX(N'.', REVERSE(x.v))) AS TABELA, RIGHT(x.v, CHARINDEX(N'.', REVERSE(x.v)) - 1) AS COLUNA
              FROM SIS.Tabela_Config c WITH (NOLOCK)
              CROSS APPLY (SELECT LTRIM(RTRIM(s.value)) AS v FROM STRING_SPLIT(c.TABELAS_FILHAS, N',') s) x
              WHERE c.TABELA = @Tabela AND c.ATIVO = 1 AND x.v LIKE N'%_._%._%') f
        WHERE OBJECT_ID(f.TABELA, N'U') IS NOT NULL AND COL_LENGTH(f.TABELA, f.COLUNA) IS NOT NULL AND SIS.fn_SIS_Tabela_PK(f.TABELA) <> N'';
        IF @Sql <> N'' EXEC sys.sp_executesql @Sql, N'@Id BIGINT', @Id = @IdRegistro;

        SET @EtapaAtual = 'Consulta';
        SELECT TOP (@MaxLinhas)
               a.ID_AUDITORIA,
               a.DT_OPERACAO,
               CAST(a.TABELA AS NVARCHAR(256)) AS TABELA,
               a.ID_REGISTRO,
               CAST(CASE WHEN a.TABELA = @Tabela AND a.ID_REGISTRO = @IdRegistro THEN 1 ELSE 0 END AS BIT) AS PRINCIPAL,
               a.OPERACAO,
               CAST(CASE a.OPERACAO WHEN 'I' THEN N'Inclusão' WHEN 'A' THEN N'Alteração' ELSE N'Exclusão' END AS NVARCHAR(20)) AS OPERACAO_NOME,
               a.CAMPO,
               ISNULL(CAST(a.VALOR_ANTES  AS NVARCHAR(4000)), N'') AS VALOR_ANTES,
               ISNULL(CAST(a.VALOR_DEPOIS AS NVARCHAR(4000)), N'') AS VALOR_DEPOIS,
               a.USUARIO,
               a.ESTACAO,
               a.ORIGEM,
               a.ID_LOTE,
               a.TRANSACAO,
               CAST(ISNULL(it.NOME + N' › ' + ac.NOME, N'') AS NVARCHAR(200)) AS DESCRICAO
        FROM SIS.Auditoria a WITH (NOLOCK)
        INNER JOIN #Reg r ON r.TABELA = a.TABELA AND r.ID_REGISTRO = a.ID_REGISTRO
        OUTER APPLY (SELECT TRY_CONVERT(INT, CASE WHEN ISNULL(a.CAMPO, N'') = N'' THEN JSON_VALUE(COALESCE(a.VALOR_DEPOIS, a.VALOR_ANTES), N'$.ID_ITEM_ACAO') END) AS ID_ITEM_ACAO) j
        LEFT JOIN SIS.Item_Acao ia WITH (NOLOCK) ON ia.ID_ITEM_ACAO = j.ID_ITEM_ACAO
        LEFT JOIN SIS.Item      it WITH (NOLOCK) ON it.ID_ITEM = ia.ID_ITEM
        LEFT JOIN SIS.Acao      ac WITH (NOLOCK) ON ac.ID_ACAO = ia.ID_ACAO
        ORDER BY a.ID_AUDITORIA DESC;

        DROP TABLE IF EXISTS #Reg;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> -1 DROP TABLE IF EXISTS #Reg;
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível carregar o histórico. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Versao_Nota_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Versao_Nota_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 23/11/2026
  Descrição   : Notas das versões já instaladas (aba "Notas das versões" da
                tela Sistema › Versões, pedido P22), da mais nova para a mais
                antiga. Qualquer usuário ativo vê (decisão do Celso,
                23/11/2026); os itens marcados para o administrador geral
                (PUBLICO = GERAL) só aparecem para o nível 2. Filtros: versão,
                tipo (NOVO, MELHORIA, CORRECAO) e parte do texto.
  Changelog:
    v1.0 (23/11/2026) - Criação (etapa 04c, P22).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Versao_Nota_Listar @IdUsuario = 2, @Busca = N'lixeira';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Versao_Nota_Listar]
    @IdUsuario  INT,
    @Versao     VARCHAR(20)    = '',
    @Tipo       VARCHAR(10)    = '',
    @Busca      NVARCHAR(100)  = N''
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Versao_Nota_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Usuário';
    DECLARE @Geral BIT, @Atual INT;

    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM SIS.Usuario u WITH (NOLOCK) WHERE u.ID_USUARIO = @IdUsuario AND u.ATIVO = 1)
            THROW 50001, N'Usuário não identificado. Entre no sistema de novo.', 1;

        SET @Geral  = CASE WHEN SIS.fn_SIS_Usuario_Nivel_Admin(@IdUsuario) = 2 THEN 1 ELSE 0 END;
        SET @Atual  = SIS.fn_SIS_Versao_Numero(SIS.fn_SIS_Versao_Banco());
        SET @Versao = LTRIM(RTRIM(ISNULL(@Versao, '')));
        SET @Tipo   = UPPER(LTRIM(RTRIM(ISNULL(@Tipo, ''))));
        SET @Busca  = LTRIM(RTRIM(ISNULL(@Busca, N'')));

        SET @EtapaAtual = 'Consulta';
        SELECT n.VERSAO,
               n.VERSAO_NUMERO,
               CAST(ISNULL(CONVERT(VARCHAR(10), n.DT_VERSAO, 103), '') AS VARCHAR(10)) AS DT_VERSAO,
               n.ORDEM,
               n.TIPO,
               CAST(CASE n.TIPO WHEN 'NOVO' THEN N'Novo' WHEN 'MELHORIA' THEN N'Melhoria' ELSE N'Correção' END AS NVARCHAR(20)) AS TIPO_NOME,
               n.PUBLICO,
               n.TEXTO,
               n.TEXTO_HTML,
               CAST(CASE WHEN n.VERSAO_NUMERO = @Atual THEN 1 ELSE 0 END AS BIT) AS ATUAL
        FROM SIS.Versao_Nota n WITH (NOLOCK)
        WHERE n.VERSAO_NUMERO <= @Atual
          AND (n.PUBLICO = 'TODOS' OR @Geral = 1)
          AND (@Versao = '' OR n.VERSAO = @Versao)
          AND (@Tipo = '' OR n.TIPO = @Tipo)
          AND (@Busca = N'' OR n.TEXTO LIKE N'%' + @Busca + N'%')
        ORDER BY n.VERSAO_NUMERO DESC, n.ORDEM;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível carregar as notas das versões. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Versao_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Versao_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 23/11/2026
  Descrição   : Histórico das versões do sistema (aba "Histórico de
                atualizações" da tela Sistema › Versões, pedido P22), do mais
                novo para o mais antigo. Junta:
                  - ATUALIZACAO: cada atualizar.cmd (SIS.Atualizacao), com
                    versões de/para do programa e do banco, tempo fora do ar,
                    resultado e mensagem;
                  - INSTALACAO: o MASTER rodado à mão (SIS.Versao_Banco com
                    ORIGEM = MASTER que não é de uma atualização);
                  - PACOTE: pacote de desenvolvimento (só no banco _LOCAL).
                De SIS.Versao_Banco entram só as mudanças de versão (rodar o
                MASTER de novo na mesma versão não aparece).
                Permissão: VER em SIS_VERSOES (só o administrador, decisão do
                Celso de 23/11/2026; as notas são para todos).
  Changelog:
    v1.0 (23/11/2026) - Criação (etapa 04c, P22).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Versao_Listar @IdUsuario = 2;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Versao_Listar]
    @IdUsuario  INT,
    @DtInicio   DATE = NULL,
    @DtFim      DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Versao_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_VERSOES', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver o histórico de atualizações.', 1;

        SET @EtapaAtual = 'Consulta';
        SELECT x.ORIGEM,
               CAST(CASE x.ORIGEM WHEN 'ATUALIZACAO' THEN N'Atualização' WHEN 'INSTALACAO' THEN N'Instalação' ELSE N'Pacote (desenvolvimento)' END AS NVARCHAR(30)) AS ORIGEM_NOME,
               x.ID_ATUALIZACAO,
               x.DT_INICIO,
               x.DT_FIM,
               x.VERSAO_BANCO_DE,
               x.VERSAO_BANCO_PARA,
               x.VERSAO_PROGRAMA_DE,
               x.VERSAO_PROGRAMA_PARA,
               x.SEGUNDOS_FORA,
               x.SITUACAO,
               CAST(CASE x.SITUACAO WHEN 'CONCLUIDA' THEN N'Concluída' WHEN 'DESFEITA' THEN N'Desfeita (voltou sozinha)' ELSE N'Erro' END AS NVARCHAR(30)) AS SITUACAO_NOME,
               x.MENSAGEM,
               x.USUARIO,
               x.ESTACAO,
               x.PACOTE,
               CAST(CASE WHEN EXISTS (SELECT 1 FROM SIS.Versao_Nota n WITH (NOLOCK) WHERE n.VERSAO = x.VERSAO_BANCO_PARA) THEN 1 ELSE 0 END AS BIT) AS TEM_NOTA
        FROM (
                SELECT CAST('ATUALIZACAO' AS VARCHAR(12)) AS ORIGEM, CAST(a.ID_ATUALIZACAO AS INT) AS ID_ATUALIZACAO,
                       a.DT_INICIO, a.DT_FIM, a.VERSAO_BANCO_DE, a.VERSAO_BANCO_PARA, a.VERSAO_PROGRAMA_DE, a.VERSAO_PROGRAMA_PARA,
                       a.SEGUNDOS_FORA, a.SITUACAO, CAST(a.MENSAGEM AS NVARCHAR(2000)) AS MENSAGEM,
                       CAST(a.USUARIO AS NVARCHAR(128)) AS USUARIO, CAST(a.ESTACAO AS NVARCHAR(128)) AS ESTACAO, CAST(a.PACOTE AS NVARCHAR(260)) AS PACOTE
                FROM SIS.Atualizacao a WITH (NOLOCK)
                UNION ALL
                SELECT CAST(CASE v.ORIGEM WHEN 'MASTER' THEN 'INSTALACAO' ELSE 'PACOTE' END AS VARCHAR(12)), CAST(0 AS INT),
                       v.DT_INSTALACAO, v.DT_INSTALACAO, CAST(ISNULL(ant.VERSAO, '') AS VARCHAR(20)), v.VERSAO, CAST('' AS VARCHAR(20)), CAST('' AS VARCHAR(20)),
                       CAST(0 AS INT), CAST('CONCLUIDA' AS VARCHAR(10)), CAST(N'' AS NVARCHAR(2000)),
                       CAST(v.USUARIO AS NVARCHAR(128)), CAST(v.ESTACAO AS NVARCHAR(128)), CAST(N'' AS NVARCHAR(260))
                FROM SIS.Versao_Banco v WITH (NOLOCK)
                OUTER APPLY (SELECT TOP (1) p.VERSAO FROM SIS.Versao_Banco p WITH (NOLOCK)
                             WHERE p.ID_VERSAO_BANCO < v.ID_VERSAO_BANCO ORDER BY p.ID_VERSAO_BANCO DESC) ant
                WHERE ISNULL(ant.VERSAO, '') <> v.VERSAO
                  AND NOT EXISTS (SELECT 1 FROM SIS.Atualizacao a WITH (NOLOCK)
                                  WHERE a.VERSAO_BANCO_PARA = v.VERSAO
                                    AND v.DT_INSTALACAO BETWEEN DATEADD(MINUTE, -1, a.DT_INICIO) AND DATEADD(MINUTE, 1, a.DT_FIM))
             ) x
        WHERE (@DtInicio IS NULL OR x.DT_INICIO >= CAST(@DtInicio AS DATETIME2(0)))
          AND (@DtFim    IS NULL OR x.DT_INICIO <  DATEADD(DAY, 1, CAST(@DtFim AS DATETIME2(0))))
        ORDER BY x.DT_INICIO DESC, x.ID_ATUALIZACAO DESC;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível carregar o histórico de atualizações. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Novidades_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Novidades_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 23/11/2026
  Descrição   : Aviso "O que há de novo" (pedido P22): as notas das versões
                instaladas depois da última que o usuário já viu
                (SIS.Usuario_Novidade), no máximo NOVIDADES_VERSOES_MAX versões
                (as mais novas; VERSOES_OMITIDAS diz quantas ficaram de fora,
                para a tela oferecer "ver todas as versões").
                Nenhuma linha = nada a mostrar (aviso desligado pelo parâmetro
                NOVIDADES_AVISO_ATIVO, usuário já viu tudo, ou usuário sem
                registro: nasce com a versão atual vista).
                Não marca como visto: quem marca é SIS_Novidades_Marcar_Vista
                (botão "Entendi" da janela).
  Changelog:
    v1.0 (23/11/2026) - Criação (etapa 04c, P22).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Novidades_Obter @IdUsuario = 2;
    -- sql/testes/SIS/04c_Homologacao_Versoes.sql
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Novidades_Obter]
    @IdUsuario  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Novidades_Obter]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Usuário';
    DECLARE @VersaoAtual VARCHAR(20), @Atual INT, @Vista INT = 0, @Max INT, @Mostrar BIT = 1, @Geral BIT, @Omitidas INT = 0;
    DECLARE @Versoes TABLE (VERSAO_NUMERO INT NOT NULL PRIMARY KEY, POSICAO INT NOT NULL);

    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM SIS.Usuario u WITH (NOLOCK) WHERE u.ID_USUARIO = @IdUsuario AND u.ATIVO = 1)
            THROW 50001, N'Usuário não identificado. Entre no sistema de novo.', 1;

        SET @VersaoAtual = SIS.fn_SIS_Versao_Banco();
        SET @Atual       = SIS.fn_SIS_Versao_Numero(@VersaoAtual);
        SET @Geral       = CASE WHEN SIS.fn_SIS_Usuario_Nivel_Admin(@IdUsuario) = 2 THEN 1 ELSE 0 END;
        SET @Max         = ISNULL(SIS.fn_SIS_Parametro_Inteiro('NOVIDADES_VERSOES_MAX'), 3);
        IF @Max < 1 SET @Max = 1;
        IF SIS.fn_SIS_Parametro_SN('NOVIDADES_AVISO_ATIVO') = 0 SET @Mostrar = 0;

        SET @EtapaAtual = 'Última versão vista';
        IF @Mostrar = 1
        BEGIN
            BEGIN TRANSACTION;
            INSERT INTO SIS.Usuario_Novidade (ID_USUARIO, VERSAO_VISTA)
            SELECT @IdUsuario, ISNULL(@VersaoAtual, '')
            WHERE NOT EXISTS (SELECT 1 FROM SIS.Usuario_Novidade n WITH (UPDLOCK, HOLDLOCK) WHERE n.ID_USUARIO = @IdUsuario);
            IF @@ROWCOUNT > 0 SET @Mostrar = 0;
            COMMIT TRANSACTION;

            SELECT @Vista = SIS.fn_SIS_Versao_Numero(n.VERSAO_VISTA)
            FROM SIS.Usuario_Novidade n WITH (NOLOCK)
            WHERE n.ID_USUARIO = @IdUsuario;
        END;

        SET @EtapaAtual = 'Versões novas';
        INSERT INTO @Versoes (VERSAO_NUMERO, POSICAO)
        SELECT v.VERSAO_NUMERO, ROW_NUMBER() OVER (ORDER BY v.VERSAO_NUMERO DESC)
        FROM (SELECT DISTINCT n.VERSAO_NUMERO
              FROM SIS.Versao_Nota n WITH (NOLOCK)
              WHERE @Mostrar = 1
                AND n.VERSAO_NUMERO > ISNULL(@Vista, 0)
                AND n.VERSAO_NUMERO <= @Atual
                AND (n.PUBLICO = 'TODOS' OR @Geral = 1)) v;

        SELECT @Omitidas = COUNT(*) FROM @Versoes WHERE POSICAO > @Max;

        SET @EtapaAtual = 'Consulta';
        SELECT n.VERSAO,
               n.VERSAO_NUMERO,
               CAST(ISNULL(CONVERT(VARCHAR(10), n.DT_VERSAO, 103), '') AS VARCHAR(10)) AS DT_VERSAO,
               n.ORDEM,
               n.TIPO,
               CAST(CASE n.TIPO WHEN 'NOVO' THEN N'Novo' WHEN 'MELHORIA' THEN N'Melhoria' ELSE N'Correção' END AS NVARCHAR(20)) AS TIPO_NOME,
               n.PUBLICO,
               n.TEXTO,
               n.TEXTO_HTML,
               CAST(ISNULL(@VersaoAtual, '') AS VARCHAR(20)) AS VERSAO_ATUAL,
               CAST(@Omitidas AS INT) AS VERSOES_OMITIDAS
        FROM SIS.Versao_Nota n WITH (NOLOCK)
        INNER JOIN @Versoes v ON v.VERSAO_NUMERO = n.VERSAO_NUMERO AND v.POSICAO <= @Max
        WHERE (n.PUBLICO = 'TODOS' OR @Geral = 1)
        ORDER BY n.VERSAO_NUMERO DESC, n.ORDEM;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF ERROR_NUMBER() = 50001 THROW;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        THROW 50001, N'Não foi possível carregar as novidades da versão. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Novidades_Marcar_Vista.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Novidades_Marcar_Vista]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 23/11/2026
  Descrição   : Botão "Entendi" do aviso "O que há de novo" (pedido P22):
                grava que o usuário já viu as novidades até a versão instalada
                agora (SIS.Usuario_Novidade). O aviso só volta na próxima
                atualização.
                Devolve 1 linha: SUCESSO, MENSAGEM, VERSAO_VISTA.
  Changelog:
    v1.0 (23/11/2026) - Criação (etapa 04c, P22).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Novidades_Marcar_Vista @IdUsuario = 2;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Novidades_Marcar_Vista]
    @IdUsuario  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[SIS].[SIS_Novidades_Marcar_Vista]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Usuário';
    DECLARE @VersaoAtual VARCHAR(20)   = ISNULL(SIS.fn_SIS_Versao_Banco(), '');

    BEGIN TRY
        IF NOT EXISTS (SELECT 1 FROM SIS.Usuario u WITH (NOLOCK) WHERE u.ID_USUARIO = @IdUsuario AND u.ATIVO = 1)
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Usuário não identificado. Entre no sistema de novo.' AS NVARCHAR(400)) AS MENSAGEM,
                   CAST('' AS VARCHAR(20)) AS VERSAO_VISTA;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;
        UPDATE n
           SET n.VERSAO_VISTA = @VersaoAtual,
               n.DT_VISTA     = SYSDATETIME()
        FROM SIS.Usuario_Novidade n WITH (UPDLOCK, HOLDLOCK)
        WHERE n.ID_USUARIO = @IdUsuario;

        IF @@ROWCOUNT = 0
            INSERT INTO SIS.Usuario_Novidade (ID_USUARIO, VERSAO_VISTA) VALUES (@IdUsuario, @VersaoAtual);
        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Novidades marcadas como vistas.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(@VersaoAtual AS VARCHAR(20)) AS VERSAO_VISTA;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());
        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível marcar as novidades como vistas. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST('' AS VARCHAR(20)) AS VERSAO_VISTA;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/CAD/CAD.CAD_Parceiro_Tipo_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [CAD].[CAD_Parceiro_Tipo_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Lista os tipos de parceiro (tela Tipos de parceiro e filtros
                das telas de Parceiros), com a quantidade de parceiros ativos
                de cada tipo. Não mostra o que está na lixeira.
                Permissão: VER em CAD_PARCEIRO_TIPO ou em CAD_PESSOA (a ficha do
                parceiro precisa da lista para marcar os tipos).

  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04d).

  Homologação (LOCAL):
    -- EXEC CAD.CAD_Parceiro_Tipo_Listar @IdUsuario = 2;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [CAD].[CAD_Parceiro_Tipo_Listar]
    @IdUsuario      INT,
    @Busca          NVARCHAR(60) = NULL,
    @SomenteAtivos  BIT          = 0
AS
BEGIN
    SET NOCOUNT ON;

    IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_PARCEIRO_TIPO', 'VER') = 0
       AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_PESSOA', 'VER') = 0
    BEGIN
        SELECT TOP (0) CAST(NULL AS INT) AS ID_PARCEIRO_TIPO;
        RETURN;
    END;

    SET @Busca = NULLIF(LTRIM(RTRIM(ISNULL(@Busca, N''))), N'');

    SELECT t.ID_PARCEIRO_TIPO, t.CODIGO, t.DESCRICAO, t.SISTEMA, t.ORDEM, t.ATIVO,
           ISNULL(q.QTD, 0) AS QTD_PARCEIROS
    FROM CAD.Parceiro_Tipo t
    OUTER APPLY (SELECT COUNT(*) AS QTD
                 FROM CAD.Pessoa_Tipo x
                 INNER JOIN CAD.Pessoa p ON p.ID_PESSOA = x.ID_PESSOA AND p.ATIVO = 1
                 WHERE x.ID_PARCEIRO_TIPO = t.ID_PARCEIRO_TIPO AND x.ATIVO = 1) q
    WHERE t.DT_EXCLUSAO IS NULL
      AND (@SomenteAtivos = 0 OR t.ATIVO = 1)
      AND (@Busca IS NULL OR t.DESCRICAO LIKE N'%' + @Busca + N'%' OR t.CODIGO LIKE @Busca + '%')
    ORDER BY t.ORDEM, t.DESCRICAO;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/CAD/CAD.CAD_Parceiro_Tipo_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [CAD].[CAD_Parceiro_Tipo_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Inclui (@IdParceiroTipo NULL) ou altera um tipo de parceiro.
                Código: letras, números e "_" (maiúsculas), único. Tipos do
                sistema (SISTEMA = 1): só a descrição e a ordem mudam (código e
                situação não). Desativar um tipo em uso: avisa quantos
                parceiros têm o tipo (eles continuam com ele).
                Permissão: INCLUIR ou ALTERAR em CAD_PARCEIRO_TIPO (desativar
                ou reativar: DESATIVAR). Devolve SUCESSO, MENSAGEM, ID.

  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04d).

  Homologação (LOCAL):
    -- EXEC CAD.CAD_Parceiro_Tipo_Gravar @IdUsuario = 2, @Codigo = 'EMPREITEIRO', @Descricao = N'Empreiteiro';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [CAD].[CAD_Parceiro_Tipo_Gravar]
    @IdUsuario        INT,
    @IdParceiroTipo   INT           = NULL,
    @Codigo           VARCHAR(20),
    @Descricao        NVARCHAR(60),
    @Ordem            INT           = NULL,
    @Ativo            BIT           = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[CAD].[CAD_Parceiro_Tipo_Gravar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Usuario    NVARCHAR(100) = SIS.fn_SIS_Usuario_Login(@IdUsuario);
    DECLARE @Sistema    BIT           = 0;
    DECLARE @CodigoAtual VARCHAR(20);
    DECLARE @AtivoAtual BIT;
    DECLARE @EmUso      INT           = 0;

    BEGIN TRY
        SET @Codigo    = UPPER(LTRIM(RTRIM(ISNULL(@Codigo, ''))));
        SET @Descricao = LTRIM(RTRIM(ISNULL(@Descricao, N'')));
        SET @Ativo     = ISNULL(@Ativo, 1);

        SELECT @Sistema = t.SISTEMA, @CodigoAtual = t.CODIGO, @AtivoAtual = t.ATIVO
        FROM CAD.Parceiro_Tipo t WHERE t.ID_PARCEIRO_TIPO = @IdParceiroTipo;

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_PARCEIRO_TIPO', CASE WHEN @IdParceiroTipo IS NULL THEN 'INCLUIR' ELSE 'ALTERAR' END) = 0
            SET @Recusa = N'Você não tem permissão para gravar tipos de parceiro.';
        IF @Recusa = N'' AND @IdParceiroTipo IS NOT NULL AND @CodigoAtual IS NULL
            SET @Recusa = N'Tipo de parceiro não encontrado.';
        IF @Recusa = N'' AND @IdParceiroTipo IS NOT NULL AND SIS.fn_SIS_Na_Lixeira(N'CAD.Parceiro_Tipo', @IdParceiroTipo) = 1
            SET @Recusa = N'O registro está na lixeira: recupere-o antes de alterar (Sistema › Lixeira).';
        IF @Recusa = N'' AND @Sistema = 1 AND @Codigo <> @CodigoAtual
            SET @Recusa = N'O código de um tipo do sistema não pode ser mudado (só a descrição e a ordem).';
        IF @Recusa = N'' AND @Sistema = 1 AND @Ativo = 0
            SET @Recusa = N'Um tipo do sistema não pode ser desativado.';
        IF @Recusa = N'' AND (@Codigo = '' OR @Codigo LIKE '%[^A-Z0-9_]%' COLLATE Latin1_General_BIN2)
            SET @Recusa = N'Código inválido: use letras sem acento, números e "_" (ex.: EMPREITEIRO).';
        IF @Recusa = N'' AND @Descricao = N''
            SET @Recusa = N'Informe a descrição.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM CAD.Parceiro_Tipo t WHERE t.CODIGO = @Codigo AND t.ID_PARCEIRO_TIPO <> ISNULL(@IdParceiroTipo, 0))
            SET @Recusa = N'Já existe um tipo de parceiro com este código (confira também a lixeira).';
        IF @Recusa = N'' AND @IdParceiroTipo IS NOT NULL AND @Ativo <> @AtivoAtual
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_PARCEIRO_TIPO', 'DESATIVAR') = 0
            SET @Recusa = N'Você não tem permissão para desativar ou reativar tipos de parceiro.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdParceiroTipo AS ID;
            RETURN;
        END;

        IF @IdParceiroTipo IS NOT NULL AND @Ativo = 0 AND @AtivoAtual = 1
            SELECT @EmUso = COUNT(*) FROM CAD.Pessoa_Tipo x WHERE x.ID_PARCEIRO_TIPO = @IdParceiroTipo AND x.ATIVO = 1;

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        IF @IdParceiroTipo IS NULL
        BEGIN
            INSERT INTO CAD.Parceiro_Tipo (CODIGO, DESCRICAO, SISTEMA, ORDEM, ATIVO, USUARIO_CRIACAO)
            VALUES (@Codigo, @Descricao, 0, ISNULL(@Ordem, 100), @Ativo, @Usuario);
            SET @IdParceiroTipo = SCOPE_IDENTITY();
        END
        ELSE
            UPDATE CAD.Parceiro_Tipo
               SET CODIGO = @Codigo, DESCRICAO = @Descricao, ORDEM = ISNULL(@Ordem, ORDEM), ATIVO = @Ativo,
                   DT_ALTERACAO = SYSDATETIME(), USUARIO_ALTERACAO = @Usuario
             WHERE ID_PARCEIRO_TIPO = @IdParceiroTipo;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(N'Tipo de parceiro gravado.'
                    + CASE WHEN @EmUso > 0 THEN N' Atenção: ' + CONVERT(NVARCHAR(10), @EmUso)
                                + N' parceiro(s) continuam com este tipo; ele só não aparece mais para novas marcações.' ELSE N'' END
                    AS NVARCHAR(400)) AS MENSAGEM,
               @IdParceiroTipo AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar o tipo de parceiro. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, @IdParceiroTipo AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Anexo_Tipo_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Anexo_Tipo_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Tipos de anexo ativos para a janela "Anexar" das telas, com as
                extensões aceitas e o tamanho máximo (ANEXO_TAMANHO_MAX_MB), para
                a tela avisar antes de enviar. A conferência que vale continua
                no SIS_Anexo_Gravar.
                Permissão: VER na tela (@Item).
                Padrão "Listar": THROW 50001 com mensagem amigável.

  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04d2, passo 5: aba Anexos).

  Homologação (LOCAL): ver sql/testes/CAD/04d2_Homologacao_Anexos.sql.
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Anexo_Tipo_Listar]
    @IdUsuario  INT,
    @Item       VARCHAR(40)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Anexo_Tipo_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver estes anexos.', 1;

        SET @EtapaAtual = 'Consulta';

        SELECT t.CODIGO,
               t.NOME,
               t.EXTENSOES,
               SIS.fn_SIS_Parametro_Inteiro('ANEXO_TAMANHO_MAX_MB') AS TAMANHO_MAX_MB
        FROM SIS.Anexo_Tipo t WITH (NOLOCK)
        WHERE t.ATIVO = 1
        ORDER BY t.NOME;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar os tipos de anexo. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/CAD/CAD.CAD_Centro_Custo_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [CAD].[CAD_Centro_Custo_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Ficha de um centro de custo (tela CAD_CENTRO_CUSTO): todos os
                campos, empresa, conta padrão (a própria ou, se vazia, a da
                empresa), data de encerramento, quantos lançamentos usam o centro
                (QTD_LANCAMENTOS: com lançamento, a empresa não muda) e NA_LIXEIRA.
                Permissão: VER em CAD_CENTRO_CUSTO. Padrão "Listar": THROW 50001.

  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04e).

  Homologação (LOCAL):
    -- EXEC CAD.CAD_Centro_Custo_Obter @IdUsuario = 2, @IdCentroCusto = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [CAD].[CAD_Centro_Custo_Obter]
    @IdUsuario      INT,
    @IdCentroCusto  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[CAD].[CAD_Centro_Custo_Obter]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_CENTRO_CUSTO', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver os centros de custo.', 1;
        IF NOT EXISTS (SELECT 1 FROM CAD.Centro_Custo cc WITH (NOLOCK) WHERE cc.ID_CENTRO_CUSTO = @IdCentroCusto)
            THROW 50001, N'Centro de custo não encontrado.', 1;

        SET @EtapaAtual = 'Consulta';
        SELECT cc.ID_CENTRO_CUSTO, cc.CODIGO, cc.DESCRICAO, cc.TIPO, cc.CONTABIL,
               cc.ID_EMPRESA, e.RAZAO_SOCIAL AS EMPRESA_RAZAO_SOCIAL, e.NOME_FANTASIA AS EMPRESA_NOME_FANTASIA,
               cc.ID_CONTA_BANCARIA_PADRAO, ISNULL(c.DESCRICAO, N'') AS CONTA_PADRAO_DESCRICAO,
               ISNULL(ce.DESCRICAO, N'') AS CONTA_PADRAO_EMPRESA_DESCRICAO,
               cc.DT_ENCERRAMENTO,
               CAST(CASE WHEN cc.DT_ENCERRAMENTO <= CONVERT(DATE, SYSDATETIME()) THEN 1 ELSE 0 END AS BIT) AS ENCERRADO,
               (SELECT COUNT(*) FROM FIN.Lancamento l WITH (NOLOCK) WHERE l.ID_CENTRO_CUSTO = cc.ID_CENTRO_CUSTO) AS QTD_LANCAMENTOS,
               cc.ATIVO, CAST(CASE WHEN cc.DT_EXCLUSAO IS NULL THEN 0 ELSE 1 END AS BIT) AS NA_LIXEIRA,
               cc.CODIGO_ACCESS, cc.DT_CRIACAO, cc.USUARIO_CRIACAO, cc.DT_ALTERACAO, ISNULL(cc.USUARIO_ALTERACAO, N'') AS USUARIO_ALTERACAO
        FROM CAD.Centro_Custo cc WITH (NOLOCK)
        INNER JOIN CAD.Empresa e WITH (NOLOCK) ON e.ID_EMPRESA = cc.ID_EMPRESA
        LEFT  JOIN BANCO.Conta c  WITH (NOLOCK) ON c.ID_CONTA  = cc.ID_CONTA_BANCARIA_PADRAO
        LEFT  JOIN BANCO.Conta ce WITH (NOLOCK) ON ce.ID_CONTA = e.ID_CONTA_BANCARIA_PADRAO
        WHERE cc.ID_CENTRO_CUSTO = @IdCentroCusto;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar o centro de custo. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/CAD/CAD.CAD_Seletor_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [CAD].[CAD_Seletor_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Fonte única das escolhas com busca (componente js/seletor.js) de
                conta do plano (@Tipo = 'PLANO'), centro de custo ('CENTRO') e
                conta bancária ('CONTA'). Só registros ativos e fora da lixeira;
                a busca olha código/número e descrição (sem acento, qualquer parte)
                e, no plano, também o grupo e o subgrupo. @IdEmpresa filtra centros
                e contas; @IdAtual sempre volta (mesmo inativo), para a ficha mostrar
                o valor já gravado. No máximo SELETOR_LIMITE linhas.
                Permissão: VER em qualquer tela que usa essas escolhas (cadastros
                de parceiro, empresa, centro, plano, conta; o FIN entra na 04f).
                Padrão "Listar": THROW 50001.

  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04e, seletor com busca aprovado pelo Celso).
    v1.1 (25/11/2026) - Etapa 04f: escolhas PESSOA (parceiro; @Filtro =
                        código do tipo, ex.: FORNECEDOR, que aparece primeiro,
                        sem esconder os demais) e HISTORICO (histórico padrão
                        do financeiro); quem vê Contas a pagar ou a receber
                        também usa as escolhas.

  Homologação (LOCAL):
    -- EXEC CAD.CAD_Seletor_Listar @IdUsuario = 2, @Tipo = 'PLANO', @Busca = N'cimento';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [CAD].[CAD_Seletor_Listar]
    @IdUsuario  INT,
    @Tipo       VARCHAR(10),
    @Busca      NVARCHAR(100) = NULL,
    @IdEmpresa  INT           = NULL,
    @IdAtual    INT           = NULL,
    @Filtro     VARCHAR(20)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[CAD].[CAD_Seletor_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Limite     INT;
    DECLARE @Termo      NVARCHAR(102);

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_PESSOA', 'VER') = 0
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_EMPRESA', 'VER') = 0
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_CENTRO_CUSTO', 'VER') = 0
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_PLANO_CONTA', 'VER') = 0
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_CONTA', 'VER') = 0
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PAGAR', 'VER') = 0
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_RECEBER', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver estas escolhas.', 1;
        SET @Tipo = UPPER(LTRIM(RTRIM(ISNULL(@Tipo, ''))));
        IF @Tipo NOT IN ('PLANO', 'CENTRO', 'CONTA', 'PESSOA', 'HISTORICO')
            THROW 50001, N'Escolha inválida.', 1;

        SET @Limite = ISNULL(SIS.fn_SIS_Parametro_Inteiro('SELETOR_LIMITE'), 50);
        IF @Limite NOT BETWEEN 10 AND 500 SET @Limite = 50;
        SET @Busca = LTRIM(RTRIM(ISNULL(@Busca, N'')));
        SET @Termo = N'%' + REPLACE(REPLACE(REPLACE(@Busca, N'[', N'[[]'), N'%', N'[%]'), N'_', N'[_]') + N'%';

        SET @EtapaAtual = 'Consulta';
        IF @Tipo = 'PLANO'
            SELECT TOP (@Limite) v.ID, v.CODIGO, v.DESCRICAO, v.COMPLEMENTO, v.ATIVO
            FROM (SELECT v.ID_PLANO_CONTA AS ID, v.CODIGO, v.DESCRICAO, v.GRUPO_DESCRICAO + N' › ' + v.SUBGRUPO_DESCRICAO AS COMPLEMENTO,
                         v.ATIVO_EFETIVO AS ATIVO, v.ORDEM_ARVORE
                  FROM CAD.vw_CAD_Plano_Conta v WITH (NOLOCK)
                  INNER JOIN CAD.Plano_Conta pc WITH (NOLOCK) ON pc.ID_PLANO_CONTA = v.ID_PLANO_CONTA
                  WHERE pc.DT_EXCLUSAO IS NULL
                    AND (v.ID_PLANO_CONTA = @IdAtual
                         OR (v.ATIVO_EFETIVO = 1
                             AND (@Busca = N'' OR v.DESCRICAO COLLATE Latin1_General_CI_AI LIKE @Termo
                                  OR v.SUBGRUPO_DESCRICAO COLLATE Latin1_General_CI_AI LIKE @Termo OR v.GRUPO_DESCRICAO COLLATE Latin1_General_CI_AI LIKE @Termo
                                  OR v.CODIGO LIKE @Busca + '%')))
                 ) v
            ORDER BY CASE WHEN v.ID = @IdAtual THEN 0 ELSE 1 END, v.ORDEM_ARVORE;
        ELSE IF @Tipo = 'CENTRO'
            SELECT TOP (@Limite) cc.ID_CENTRO_CUSTO AS ID, cc.CODIGO, cc.DESCRICAO,
                   ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL)
                     + CASE WHEN cc.DT_ENCERRAMENTO <= CONVERT(DATE, SYSDATETIME()) THEN N' · encerrado em ' + CONVERT(NVARCHAR(10), cc.DT_ENCERRAMENTO, 103) ELSE N'' END AS COMPLEMENTO,
                   cc.ATIVO
            FROM CAD.Centro_Custo cc WITH (NOLOCK)
            INNER JOIN CAD.Empresa e WITH (NOLOCK) ON e.ID_EMPRESA = cc.ID_EMPRESA
            WHERE cc.DT_EXCLUSAO IS NULL
              AND (cc.ID_CENTRO_CUSTO = @IdAtual
                   OR (cc.ATIVO = 1 AND (@IdEmpresa IS NULL OR cc.ID_EMPRESA = @IdEmpresa)
                       AND (@Busca = N'' OR cc.DESCRICAO COLLATE Latin1_General_CI_AI LIKE @Termo OR cc.CODIGO LIKE @Busca + '%')))
            ORDER BY CASE WHEN cc.ID_CENTRO_CUSTO = @IdAtual THEN 0 ELSE 1 END, cc.CODIGO;
        ELSE IF @Tipo = 'PESSOA'
            SELECT TOP (@Limite) p.ID_PESSOA AS ID,
                   CAST(CASE WHEN p.CPF_CNPJ = '' THEN '' ELSE SIS.fn_SIS_Mascarar_CPF_CNPJ(p.CPF_CNPJ, 0) END AS VARCHAR(20)) AS CODIGO,
                   p.NOME AS DESCRICAO,
                   ISNULL(STUFF((SELECT N', ' + t.DESCRICAO FROM CAD.Pessoa_Tipo x WITH (NOLOCK)
                                 INNER JOIN CAD.Parceiro_Tipo t WITH (NOLOCK) ON t.ID_PARCEIRO_TIPO = x.ID_PARCEIRO_TIPO
                                 WHERE x.ID_PESSOA = p.ID_PESSOA AND x.ATIVO = 1 ORDER BY t.ORDEM FOR XML PATH(''), TYPE).value('.', 'NVARCHAR(400)'), 1, 2, N''), N'')
                     + CASE WHEN p.NOME_FANTASIA <> N'' AND p.NOME_FANTASIA <> p.NOME THEN N' · ' + p.NOME_FANTASIA ELSE N'' END AS COMPLEMENTO,
                   p.ATIVO
            FROM CAD.Pessoa p WITH (NOLOCK)
            WHERE p.DT_EXCLUSAO IS NULL
              AND (p.ID_PESSOA = @IdAtual
                   OR (p.ATIVO = 1
                       AND (@Busca = N'' OR p.NOME COLLATE Latin1_General_CI_AI LIKE @Termo OR p.NOME_FANTASIA COLLATE Latin1_General_CI_AI LIKE @Termo
                            OR (LEN(CAD.fn_CAD_Somente_Digitos(@Busca)) >= 3 AND p.CPF_CNPJ LIKE CAD.fn_CAD_Somente_Digitos(@Busca) + '%'))))
            ORDER BY CASE WHEN p.ID_PESSOA = @IdAtual THEN 0 ELSE 1 END,
                     CASE WHEN ISNULL(@Filtro, '') <> '' AND EXISTS (SELECT 1 FROM CAD.Pessoa_Tipo x WITH (NOLOCK)
                                                                    INNER JOIN CAD.Parceiro_Tipo t WITH (NOLOCK) ON t.ID_PARCEIRO_TIPO = x.ID_PARCEIRO_TIPO
                                                                    WHERE x.ID_PESSOA = p.ID_PESSOA AND x.ATIVO = 1 AND t.CODIGO = @Filtro) THEN 0 ELSE 1 END,
                     p.NOME;
        ELSE IF @Tipo = 'HISTORICO'
            SELECT TOP (@Limite) h.ID_HISTORICO_PADRAO AS ID, CAST(h.ID_HISTORICO_PADRAO AS VARCHAR(20)) AS CODIGO, h.DESCRICAO,
                   CAST(N'' AS NVARCHAR(200)) AS COMPLEMENTO, h.ATIVO
            FROM FIN.Historico_Padrao h WITH (NOLOCK)
            WHERE h.ID_HISTORICO_PADRAO = @IdAtual
               OR (h.ATIVO = 1 AND (@Busca = N'' OR h.DESCRICAO COLLATE Latin1_General_CI_AI LIKE @Termo))
            ORDER BY CASE WHEN h.ID_HISTORICO_PADRAO = @IdAtual THEN 0 ELSE 1 END, h.DESCRICAO;
        ELSE
            SELECT TOP (@Limite) c.ID_CONTA AS ID, CAST(c.ID_CONTA AS VARCHAR(20)) AS CODIGO, c.DESCRICAO,
                   ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL)
                     + CASE WHEN c.NUMERO <> '' THEN N' · ag. ' + c.AGENCIA + N' c/c ' + c.NUMERO + CASE WHEN c.NUMERO_DV <> '' THEN N'-' + c.NUMERO_DV ELSE N'' END ELSE N'' END AS COMPLEMENTO,
                   c.ATIVO
            FROM BANCO.Conta c WITH (NOLOCK)
            INNER JOIN CAD.Empresa e WITH (NOLOCK) ON e.ID_EMPRESA = c.ID_EMPRESA
            WHERE c.DT_EXCLUSAO IS NULL
              AND (c.ID_CONTA = @IdAtual
                   OR (c.ATIVO = 1 AND (@IdEmpresa IS NULL OR c.ID_EMPRESA = @IdEmpresa)
                       AND (@Busca = N'' OR c.DESCRICAO COLLATE Latin1_General_CI_AI LIKE @Termo OR c.NUMERO LIKE @Busca + '%')))
            ORDER BY CASE WHEN c.ID_CONTA = @IdAtual THEN 0 ELSE 1 END, e.RAZAO_SOCIAL, c.ORDEM, c.DESCRICAO;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar a lista. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/CAD/CAD.CAD_Empresa_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [CAD].[CAD_Empresa_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Ficha de uma empresa (tela CAD_EMPRESA): todos os campos, o
                rodapé dos e-mails (P11), a pasta do OFX (PODE_PASTA_OFX = 1 só
                para administrador), a conta padrão, quantas contas e centros de
                custo ativos ela tem e NA_LIXEIRA (ficha só para consulta).
                Permissão: VER em CAD_EMPRESA. Padrão "Listar": THROW 50001.

  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04e).

  Homologação (LOCAL):
    -- EXEC CAD.CAD_Empresa_Obter @IdUsuario = 2, @IdEmpresa = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [CAD].[CAD_Empresa_Obter]
    @IdUsuario  INT,
    @IdEmpresa  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[CAD].[CAD_Empresa_Obter]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'CAD_EMPRESA', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver as empresas.', 1;
        IF NOT EXISTS (SELECT 1 FROM CAD.Empresa e WITH (NOLOCK) WHERE e.ID_EMPRESA = @IdEmpresa)
            THROW 50001, N'Empresa não encontrada.', 1;

        SET @EtapaAtual = 'Consulta';
        SELECT e.ID_EMPRESA, e.RAZAO_SOCIAL, e.NOME_FANTASIA, e.CNPJ,
               SIS.fn_SIS_Mascarar_CPF_CNPJ(e.CNPJ, 0) AS CNPJ_FORMATADO,
               e.CNPJ_COMPRAS, SIS.fn_SIS_Mascarar_CPF_CNPJ(e.CNPJ_COMPRAS, 0) AS CNPJ_COMPRAS_FORMATADO,
               e.TIPO, e.INSCRICAO_ESTADUAL, e.INSCRICAO_MUNICIPAL, e.REGIME_TRIBUTARIO,
               e.CEP, e.LOGRADOURO, e.NUMERO, e.COMPLEMENTO, e.BAIRRO, e.CIDADE, e.UF, e.EMAIL, e.TELEFONE,
               e.RODAPE_EMAIL,
               CASE WHEN SIS.fn_SIS_Usuario_Nivel_Admin(@IdUsuario) >= 1 THEN e.PASTA_OFX ELSE N'' END AS PASTA_OFX,
               CAST(CASE WHEN SIS.fn_SIS_Usuario_Nivel_Admin(@IdUsuario) >= 1 THEN 1 ELSE 0 END AS BIT) AS PODE_PASTA_OFX,
               e.ID_CONTA_BANCARIA_PADRAO, ISNULL(c.DESCRICAO, N'') AS CONTA_PADRAO_DESCRICAO,
               (SELECT COUNT(*) FROM BANCO.Conta x WITH (NOLOCK) WHERE x.ID_EMPRESA = e.ID_EMPRESA AND x.ATIVO = 1 AND x.DT_EXCLUSAO IS NULL) AS QTD_CONTAS,
               (SELECT COUNT(*) FROM CAD.Centro_Custo x WITH (NOLOCK) WHERE x.ID_EMPRESA = e.ID_EMPRESA AND x.ATIVO = 1 AND x.DT_EXCLUSAO IS NULL) AS QTD_CENTROS,
               e.ATIVO, CAST(CASE WHEN e.DT_EXCLUSAO IS NULL THEN 0 ELSE 1 END AS BIT) AS NA_LIXEIRA,
               e.CODIGO_ACCESS, e.DT_CRIACAO, e.USUARIO_CRIACAO, e.DT_ALTERACAO, ISNULL(e.USUARIO_ALTERACAO, N'') AS USUARIO_ALTERACAO
        FROM CAD.Empresa e WITH (NOLOCK)
        LEFT JOIN BANCO.Conta c WITH (NOLOCK) ON c.ID_CONTA = e.ID_CONTA_BANCARIA_PADRAO
        WHERE e.ID_EMPRESA = @IdEmpresa;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar a empresa. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/BANCO/BANCO.BANCO_Conta_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [BANCO].[BANCO_Conta_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Ficha de uma conta bancária, caixa ou conta de permuta (tela
                BANCO_CONTA): todos os campos, empresa e banco, se é a conta
                padrão da empresa, TEM_MOVIMENTO (já há movimento ou baixa: a
                tela trava empresa, tipo e saldo inicial) e NA_LIXEIRA.
                Permissão: VER em BANCO_CONTA. Padrão "Listar": THROW 50001.

  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04e).

  Homologação (LOCAL):
    -- EXEC BANCO.BANCO_Conta_Obter @IdUsuario = 2, @IdConta = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [BANCO].[BANCO_Conta_Obter]
    @IdUsuario  INT,
    @IdConta    INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[BANCO].[BANCO_Conta_Obter]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_CONTA', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver as contas bancárias.', 1;
        IF NOT EXISTS (SELECT 1 FROM BANCO.Conta c WITH (NOLOCK) WHERE c.ID_CONTA = @IdConta)
            THROW 50001, N'Conta não encontrada.', 1;

        SET @EtapaAtual = 'Consulta';
        SELECT c.ID_CONTA, c.ID_EMPRESA, e.RAZAO_SOCIAL AS EMPRESA_RAZAO_SOCIAL, e.NOME_FANTASIA AS EMPRESA_NOME_FANTASIA,
               c.DESCRICAO, c.TIPO, c.ID_BANCO, ISNULL(b.CODIGO, '') AS BANCO_CODIGO, ISNULL(b.NOME, N'') AS BANCO_NOME,
               c.AGENCIA, c.AGENCIA_DV, c.NUMERO, c.NUMERO_DV, c.LIMITE_CREDITO, c.SALDO_INICIAL, c.DT_SALDO_INICIAL,
               c.CONCILIA, c.MOSTRA_SALDO, c.CONTA_CONTABIL_REF, c.ORDEM,
               CAST(CASE WHEN e.ID_CONTA_BANCARIA_PADRAO = c.ID_CONTA THEN 1 ELSE 0 END AS BIT) AS PADRAO_DA_EMPRESA,
               CAST(CASE WHEN EXISTS (SELECT 1 FROM BANCO.Movimento m WITH (NOLOCK) WHERE m.ID_CONTA = c.ID_CONTA)
                           OR EXISTS (SELECT 1 FROM FIN.Baixa x WITH (NOLOCK) WHERE x.ID_CONTA = c.ID_CONTA)
                         THEN 1 ELSE 0 END AS BIT) AS TEM_MOVIMENTO,
               c.ATIVO, CAST(CASE WHEN c.DT_EXCLUSAO IS NULL THEN 0 ELSE 1 END AS BIT) AS NA_LIXEIRA,
               c.CODIGO_ACCESS, c.DT_CRIACAO, c.USUARIO_CRIACAO, c.DT_ALTERACAO, ISNULL(c.USUARIO_ALTERACAO, N'') AS USUARIO_ALTERACAO
        FROM BANCO.Conta c WITH (NOLOCK)
        INNER JOIN CAD.Empresa e WITH (NOLOCK) ON e.ID_EMPRESA = c.ID_EMPRESA
        LEFT  JOIN BANCO.Banco b WITH (NOLOCK) ON b.ID_BANCO = c.ID_BANCO
        WHERE c.ID_CONTA = @IdConta;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar a conta. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Trava_Conferir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Trava_Conferir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Trava própria de FIN.Lancamento e FIN.Parcela para a lixeira e
                o desfazer (SIS.Tabela_Config.PROC_VALIDAR, P20). Chamada por
                SIS_Tabela_Trava_Conferir. @Mensagem vazia = pode.
                  - mês fechado da empresa na competência, com conta contábil
                    (pedido 10: só conta marcada como contábil);
                  - LIXEIRA: só lançamento de origem manual, sem baixa (as
                    baixas também barram pela SIS_Lixeira_Referencias);
                  - DESFAZER: recusa se o lançamento (ou a parcela) tem baixa:
                    o que tem pagamento é acertado pela ficha.
                  - origem de outra rotina (venda, compra...): recusa;
                  - LIXEIRA com o usuário da API no contexto: confere EXCLUIR
                    na tela do tipo do lançamento (a pagar ou a receber), já
                    que as duas telas usam as mesmas tabelas.
                Uso interno (DENY para a API).
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Trava_Conferir]
    @Tabela      NVARCHAR(256),
    @IdRegistro  BIGINT,
    @Operacao    VARCHAR(20),
    @Mensagem    NVARCHAR(400) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @IdLancamento BIGINT;
    DECLARE @Origem       VARCHAR(15);
    DECLARE @Tipo         CHAR(1);
    DECLARE @IdUsuario    INT = TRY_CONVERT(INT, SESSION_CONTEXT(N'ID_USUARIO'));

    SET @Mensagem = N'';

    IF @Tabela = N'FIN.Parcela'
        SELECT @IdLancamento = p.ID_LANCAMENTO FROM FIN.Parcela p WHERE p.ID_PARCELA = @IdRegistro;
    ELSE
        SET @IdLancamento = @IdRegistro;

    SELECT @Origem = l.ORIGEM, @Tipo = l.TIPO FROM FIN.Lancamento l WHERE l.ID_LANCAMENTO = @IdLancamento;
    IF @Origem IS NULL RETURN;

    IF EXISTS (SELECT 1 FROM FIN.Lancamento l
               INNER JOIN FIN.Mes_Fechado m  ON m.ID_EMPRESA = l.ID_EMPRESA AND m.MES = l.DT_COMPETENCIA AND m.FECHADO = 1
               INNER JOIN CAD.Plano_Conta pc ON pc.ID_PLANO_CONTA = l.ID_PLANO_CONTA AND pc.CONTABIL = 1
               WHERE l.ID_LANCAMENTO = @IdLancamento)
    BEGIN
        SET @Mensagem = N'O mês do lançamento está fechado (conta contábil).';
        RETURN;
    END;

    IF @Origem NOT IN ('MANUAL', 'MIGRACAO')
    BEGIN
        SET @Mensagem = N'Lançamento gerado por outra rotina (' + CONVERT(NVARCHAR(15), @Origem) + N'): use a tela de origem.';
        RETURN;
    END;

    IF @Operacao = 'LIXEIRA' AND @IdUsuario IS NOT NULL
       AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'EXCLUIR') = 0
    BEGIN
        SET @Mensagem = N'Você não tem permissão para excluir lançamentos a ' + CASE @Tipo WHEN 'P' THEN N'pagar.' ELSE N'receber.' END;
        RETURN;
    END;

    IF @Operacao = 'LIXEIRA' AND @Origem <> 'MANUAL'
    BEGIN
        SET @Mensagem = N'Só lançamento incluído pela tela vai para a lixeira; os que vieram do Access podem ser cancelados.';
        RETURN;
    END;

    IF @Operacao IN ('LIXEIRA', 'DESFAZER')
       AND EXISTS (SELECT 1 FROM FIN.Baixa b INNER JOIN FIN.Parcela p ON p.ID_PARCELA = b.ID_PARCELA
                   WHERE p.ID_LANCAMENTO = @IdLancamento AND (@Tabela <> N'FIN.Parcela' OR p.ID_PARCELA = @IdRegistro))
    BEGIN
        SET @Mensagem = N'O lançamento tem pagamento ou recebimento: acerte pela ficha (as baixas não são desfeitas por aqui).';
        RETURN;
    END;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Inclui (@IdLancamento NULL) ou altera um lançamento a pagar (P)
                ou a receber (R) com as suas parcelas (telas Contas a pagar e
                Contas a receber, etapa 04f). Tudo-ou-nada.
                @Parcelas: JSON [{"id":null|ID_PARCELA,"vencimento":"aaaa-mm-dd",
                "valor":100.00,"idContaPrevista":null}]; a numeração é refeita
                pela ordem de vencimento. Parcela existente fora da lista é
                retirada (só sem nenhuma baixa, nem estornada). Empresa vem do centro de custo.
                Proteções contra erro de digitação (P17), conferidas aqui e na
                prévia (@SomenteConferir = 1, usada por FIN_Lancamento_Conferir):
                  BLOQUEIO  não grava (fixos: parceiro/centro/conta inativos,
                            mês fechado de conta contábil, trava de datas sem a
                            permissão LANCAR_RETROATIVO; e as regras FIN_REGRA_*
                            com BLOQUEIO, CENTRO_ENCERRADO_BLOQUEIA = S);
                  MOTIVO    trava de datas para quem tem LANCAR_RETROATIVO:
                            grava só com @MotivoRetroativo;
                  AVISO     grava só se o código vier em @AvisosConfirmados
                            (lista separada por vírgula).
                Avisos confirmados e motivos ficam em SIS.Aviso_Confirmado.
                Em alteração, cada regra só olha o que mudou. Com baixa, ficam
                travados o parceiro, o valor total e as parcelas com baixa.
                Duplicidade de documento: só documento com número (no Access o
                campo também guardava textos como "Pis, Cofins e CSLL").
                @MarcarTipoParceiro = 1: marca o tipo Fornecedor (P) ou Cliente
                (R) no parceiro (resposta ao aviso TIPO_PARCEIRO).
                Permissão: INCLUIR ou ALTERAR em FIN_PAGAR / FIN_RECEBER.
                Devolve 1 linha: SUCESSO, MENSAGEM, ID, PENDENTE (há avisos a
                confirmar ou motivo a informar) e AVISOS (JSON: codigo, nivel,
                mensagem, idReferencia, campo).
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f).
    v1.1 (26/11/2026) - Etapa 04f2b: integração em branco vale COMPLETA (a API
                        manda texto vazio quando a ficha não informa).

    v1.2 (27/11/2026) - Etapa 04g4: só a baixa viva (não estornada) trava
                        parceiro, valor total e parcela (fn_FIN_Parcela_Baixa_Viva);
                        parcela só com baixa estornada muda, mas não sai.
  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Gravar @IdUsuario = 2, @Tipo = 'P', @IdCentroCusto = 1, @IdPessoa = 1, @IdPlanoConta = 1,
    --      @DtEmissao = '2026-11-25', @ValorTotal = 100, @Parcelas = N'[{"vencimento":"2026-12-10","valor":100}]', @SomenteConferir = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Gravar]
    @IdUsuario           INT,
    @IdLancamento        BIGINT          = NULL,
    @Tipo                CHAR(1)         = NULL,
    @IdCentroCusto       INT             = NULL,
    @IdPessoa            INT             = NULL,
    @IdPlanoConta        INT             = NULL,
    @IdHistoricoPadrao   INT             = NULL,
    @Documento           NVARCHAR(40)    = NULL,
    @DtEmissao           DATE            = NULL,
    @DtCompetencia       DATE            = NULL,
    @Historico           NVARCHAR(200)   = NULL,
    @Observacao          NVARCHAR(2000)  = NULL,
    @ValorTotal          DECIMAL(18,2)   = NULL,
    @Previsao            BIT             = 0,
    @Integracao          VARCHAR(12)     = NULL,
    @Parcelas            NVARCHAR(MAX)   = NULL,
    @AvisosConfirmados   NVARCHAR(1000)  = NULL,
    @MotivoRetroativo    NVARCHAR(400)   = NULL,
    @MarcarTipoParceiro  BIT             = 0,
    @SomenteConferir     BIT             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Gravar]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Validação';
    DECLARE @Recusa       NVARCHAR(400) = N'';
    DECLARE @Usuario      NVARCHAR(100);
    DECLARE @Item         VARCHAR(40);
    DECLARE @Hoje         DATE = CONVERT(DATE, SYSDATETIME());
    DECLARE @Novo         BIT;
    DECLARE @Avisos       NVARCHAR(MAX) = N'[]';
    DECLARE @Pendente     BIT = 0;
    DECLARE @Nivel        VARCHAR(12);
    DECLARE @N            INT;
    DECLARE @Meses        INT;
    DECLARE @V            DECIMAL(18,6);
    DECLARE @Soma         DECIMAL(18,2);
    DECLARE @IdEmpresa    INT;
    DECLARE @TemBaixa     BIT = 0;
    DECLARE @PodeRetro    BIT = 0;
    DECLARE @IdTipoMarcar INT;
    DECLARE @IdTipoNA     INT;

    -- valores atuais (alteração)
    DECLARE @aTipo CHAR(1), @aCentro INT, @aPessoa INT, @aPlano INT, @aDocumento NVARCHAR(40), @aEmissao DATE,
            @aCompetencia DATE, @aValor DECIMAL(18,2), @aOrigem VARCHAR(15), @aSituacao VARCHAR(10), @aEmpresa INT;
    DECLARE @MudouPessoa BIT = 1, @MudouPlano BIT = 1, @MudouCentro BIT = 1, @MudouEmissao BIT = 1,
            @MudouCompetencia BIT = 1, @MudouValor BIT = 1, @MudouDocumento BIT = 1;

    DROP TABLE IF EXISTS #P;
    DROP TABLE IF EXISTS #Regra;
    CREATE TABLE #P (CHAVE INT NOT NULL, ID_PARCELA BIGINT NULL, DT_VENCIMENTO DATE NULL, VALOR DECIMAL(18,2) NULL,
                     ID_CONTA_PREVISTA INT NULL, NUMERO SMALLINT NULL, MUDOU BIT NOT NULL DEFAULT (1));
    CREATE TABLE #Regra (ORDEM INT IDENTITY(1,1), CODIGO VARCHAR(40) NOT NULL, NIVEL VARCHAR(12) NOT NULL,
                         MENSAGEM NVARCHAR(400) NOT NULL, ID_REFERENCIA BIGINT NULL, CAMPO VARCHAR(40) NOT NULL DEFAULT (''));

    BEGIN TRY
        SET @Novo               = CASE WHEN @IdLancamento IS NULL THEN 1 ELSE 0 END;
        SET @Documento          = LTRIM(RTRIM(ISNULL(@Documento, N'')));
        SET @Historico          = LTRIM(RTRIM(ISNULL(@Historico, N'')));
        SET @Observacao         = LTRIM(RTRIM(ISNULL(@Observacao, N'')));
        SET @Integracao         = UPPER(LTRIM(RTRIM(ISNULL(NULLIF(LTRIM(RTRIM(@Integracao)), ''), 'COMPLETA'))));
        SET @Previsao           = ISNULL(@Previsao, 0);
        SET @MotivoRetroativo   = LTRIM(RTRIM(ISNULL(@MotivoRetroativo, N'')));
        SET @AvisosConfirmados  = UPPER(ISNULL(@AvisosConfirmados, N''));
        SET @MarcarTipoParceiro = ISNULL(@MarcarTipoParceiro, 0);
        SET @SomenteConferir    = ISNULL(@SomenteConferir, 0);

        ---------------------------------------------------------------------
        -- 1) Situação atual (alteração) e permissão
        ---------------------------------------------------------------------
        IF @Novo = 0
        BEGIN
            SELECT @aTipo = l.TIPO, @aCentro = l.ID_CENTRO_CUSTO, @aPessoa = l.ID_PESSOA, @aPlano = l.ID_PLANO_CONTA,
                   @aDocumento = l.DOCUMENTO, @aEmissao = l.DT_EMISSAO, @aCompetencia = l.DT_COMPETENCIA, @aValor = l.VALOR_TOTAL,
                   @aOrigem = l.ORIGEM, @aSituacao = l.SITUACAO, @aEmpresa = l.ID_EMPRESA
            FROM FIN.Lancamento l
            WHERE l.ID_LANCAMENTO = @IdLancamento;

            IF @aTipo IS NULL
                SET @Recusa = N'Lançamento não encontrado.';
            ELSE
                SET @Tipo = @aTipo;

            -- só baixa viva (não estornada) trava o lançamento (04g4)
            IF EXISTS (SELECT 1 FROM FIN.Parcela p WHERE p.ID_LANCAMENTO = @IdLancamento AND EXISTS (SELECT 1 FROM FIN.fn_FIN_Parcela_Baixa_Viva(p.ID_PARCELA)))
                SET @TemBaixa = 1;
        END;

        SET @Tipo = UPPER(ISNULL(@Tipo, ''));
        SET @Item = CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' WHEN 'R' THEN 'FIN_RECEBER' ELSE '' END;

        IF @Recusa = N'' AND @Item = ''
            SET @Recusa = N'Informe se o lançamento é a pagar ou a receber.';
        IF @Recusa = N'' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, CASE WHEN @Novo = 1 THEN 'INCLUIR' ELSE 'ALTERAR' END) = 0
            SET @Recusa = N'Você não tem permissão para ' + CASE WHEN @Novo = 1 THEN N'incluir' ELSE N'alterar' END
                        + N' contas a ' + CASE @Tipo WHEN 'P' THEN N'pagar.' ELSE N'receber.' END;
        IF @Recusa = N'' AND @Novo = 0 AND SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', @IdLancamento) = 1
            SET @Recusa = N'O lançamento está na lixeira: recupere-o antes de alterar (Sistema › Lixeira).';
        IF @Recusa = N'' AND @Novo = 0 AND @aSituacao = 'CANCELADO'
            SET @Recusa = N'O lançamento está cancelado e não pode ser alterado.';
        IF @Recusa = N'' AND @Novo = 0 AND @aOrigem NOT IN ('MANUAL', 'MIGRACAO')
            SET @Recusa = N'Este lançamento foi gerado por outra rotina (' + CONVERT(NVARCHAR(15), @aOrigem) + N'): altere pela tela de origem.';

        ---------------------------------------------------------------------
        -- 2) Campos do documento
        ---------------------------------------------------------------------
        IF @Recusa = N'' AND @IdCentroCusto IS NULL AND (@Novo = 1 OR @aCentro IS NOT NULL)
            SET @Recusa = N'Escolha o centro de custo (obra ou setor).';
        IF @Recusa = N'' AND @IdPessoa IS NULL AND (@Novo = 1 OR @aPessoa IS NOT NULL)
            SET @Recusa = N'Escolha o parceiro (' + CASE @Tipo WHEN 'P' THEN N'fornecedor' ELSE N'cliente' END + N').';
        IF @Recusa = N'' AND @IdPlanoConta IS NULL AND (@Novo = 1 OR @aPlano IS NOT NULL)
            SET @Recusa = N'Escolha a conta do plano de contas.';
        IF @Recusa = N'' AND @DtEmissao IS NULL
            SET @Recusa = N'Informe a data de emissão do documento.';
        IF @Recusa = N'' AND @DtEmissao NOT BETWEEN '1990-01-01' AND '2099-12-31'
            SET @Recusa = N'Data de emissão inválida: confira o ano.';
        IF @Recusa = N'' AND ISNULL(@ValorTotal, 0) <= 0
            SET @Recusa = N'Informe o valor total (maior que zero).';
        IF @Recusa = N'' AND @Integracao NOT IN ('COMPLETA', 'SO_CONTABIL', 'NENHUMA')
            SET @Recusa = N'Integração inválida.';
        IF @Recusa = N'' AND @IdHistoricoPadrao IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM FIN.Historico_Padrao h WHERE h.ID_HISTORICO_PADRAO = @IdHistoricoPadrao AND h.ATIVO = 1)
            SET @Recusa = N'O histórico padrão escolhido não existe ou está desativado.';
        IF @Recusa = N'' AND @IdCentroCusto IS NOT NULL AND NOT EXISTS (SELECT 1 FROM CAD.Centro_Custo c WHERE c.ID_CENTRO_CUSTO = @IdCentroCusto)
            SET @Recusa = N'Centro de custo não encontrado.';
        IF @Recusa = N'' AND @IdPessoa IS NOT NULL AND NOT EXISTS (SELECT 1 FROM CAD.Pessoa p WHERE p.ID_PESSOA = @IdPessoa)
            SET @Recusa = N'Parceiro não encontrado.';
        IF @Recusa = N'' AND @IdPlanoConta IS NOT NULL AND NOT EXISTS (SELECT 1 FROM CAD.Plano_Conta c WHERE c.ID_PLANO_CONTA = @IdPlanoConta)
            SET @Recusa = N'Conta do plano não encontrada.';

        IF @DtEmissao IS NOT NULL
            SET @DtCompetencia = DATEFROMPARTS(YEAR(ISNULL(@DtCompetencia, @DtEmissao)), MONTH(ISNULL(@DtCompetencia, @DtEmissao)), 1);
        SELECT @IdEmpresa = c.ID_EMPRESA FROM CAD.Centro_Custo c WHERE c.ID_CENTRO_CUSTO = @IdCentroCusto;
        SET @IdEmpresa = ISNULL(@IdEmpresa, @aEmpresa);
        IF @Recusa = N'' AND @IdEmpresa IS NULL
            SET @Recusa = N'Escolha o centro de custo (a empresa vem dele).';

        IF @Novo = 0
        BEGIN
            SET @MudouPessoa      = CASE WHEN ISNULL(@IdPessoa, 0)      = ISNULL(@aPessoa, 0)  THEN 0 ELSE 1 END;
            SET @MudouPlano       = CASE WHEN ISNULL(@IdPlanoConta, 0)  = ISNULL(@aPlano, 0)   THEN 0 ELSE 1 END;
            SET @MudouCentro      = CASE WHEN ISNULL(@IdCentroCusto, 0) = ISNULL(@aCentro, 0)  THEN 0 ELSE 1 END;
            SET @MudouEmissao     = CASE WHEN @DtEmissao = @aEmissao         THEN 0 ELSE 1 END;
            SET @MudouCompetencia = CASE WHEN @DtCompetencia = @aCompetencia THEN 0 ELSE 1 END;
            SET @MudouValor       = CASE WHEN @ValorTotal = @aValor          THEN 0 ELSE 1 END;
            SET @MudouDocumento   = CASE WHEN @Documento = ISNULL(@aDocumento, N'') COLLATE Latin1_General_CI_AI THEN 0 ELSE 1 END;
        END;

        IF @Recusa = N'' AND @TemBaixa = 1 AND @MudouPessoa = 1
            SET @Recusa = N'O lançamento já tem pagamento ou recebimento: o parceiro não pode mudar.';
        IF @Recusa = N'' AND @TemBaixa = 1 AND @MudouValor = 1
            SET @Recusa = N'O lançamento já tem pagamento ou recebimento: o valor total não pode mudar (ajuste só as parcelas em aberto).';

        ---------------------------------------------------------------------
        -- 3) Parcelas
        ---------------------------------------------------------------------
        SET @EtapaAtual = 'Parcelas';
        IF @Recusa = N'' AND (ISNULL(@Parcelas, N'') = N'' OR ISJSON(@Parcelas) = 0)
            SET @Recusa = N'Informe ao menos uma parcela (use "Gerar parcelas").';

        IF @Recusa = N''
        BEGIN
            INSERT INTO #P (CHAVE, ID_PARCELA, DT_VENCIMENTO, VALOR, ID_CONTA_PREVISTA)
            SELECT CONVERT(INT, k.[key]), j.id, TRY_CONVERT(DATE, j.vencimento, 23), j.valor, j.idContaPrevista
            FROM OPENJSON(@Parcelas) k
            CROSS APPLY OPENJSON(k.value) WITH (id BIGINT '$.id', vencimento VARCHAR(10) '$.vencimento',
                                                valor DECIMAL(18,2) '$.valor', idContaPrevista INT '$.idContaPrevista') j
            WHERE k.[type] = 5;

            SET @N    = (SELECT COUNT(*) FROM #P);
            SET @Soma = (SELECT ISNULL(SUM(x.VALOR), 0) FROM #P x);

            IF @N = 0
                SET @Recusa = N'Informe ao menos uma parcela (use "Gerar parcelas").';
            ELSE IF @N > 480
                SET @Recusa = N'No máximo 480 parcelas por lançamento.';
            ELSE IF EXISTS (SELECT 1 FROM #P WHERE DT_VENCIMENTO IS NULL OR DT_VENCIMENTO NOT BETWEEN '1990-01-01' AND '2099-12-31')
                SET @Recusa = N'Parcela ' + (SELECT TOP 1 CONVERT(NVARCHAR(5), CHAVE + 1) FROM #P
                                              WHERE DT_VENCIMENTO IS NULL OR DT_VENCIMENTO NOT BETWEEN '1990-01-01' AND '2099-12-31' ORDER BY CHAVE)
                            + N': informe um vencimento válido.';
            ELSE IF EXISTS (SELECT 1 FROM #P WHERE ISNULL(VALOR, 0) <= 0)
                SET @Recusa = N'Parcela ' + (SELECT TOP 1 CONVERT(NVARCHAR(5), CHAVE + 1) FROM #P WHERE ISNULL(VALOR, 0) <= 0 ORDER BY CHAVE)
                            + N': informe um valor maior que zero.';
            ELSE IF @Soma <> @ValorTotal
                SET @Recusa = N'A soma das parcelas (' + SIS.fn_SIS_Formatar_Moeda(@Soma)
                            + N') é diferente do valor total (' + SIS.fn_SIS_Formatar_Moeda(@ValorTotal) + N').';
            ELSE IF EXISTS (SELECT 1 FROM #P x WHERE x.ID_PARCELA IS NOT NULL
                              AND NOT EXISTS (SELECT 1 FROM FIN.Parcela p WHERE p.ID_PARCELA = x.ID_PARCELA AND p.ID_LANCAMENTO = ISNULL(@IdLancamento, 0)))
                SET @Recusa = N'Parcela de outro lançamento na lista: abra a ficha de novo.';
            ELSE IF EXISTS (SELECT x.ID_PARCELA FROM #P x WHERE x.ID_PARCELA IS NOT NULL GROUP BY x.ID_PARCELA HAVING COUNT(*) > 1)
                SET @Recusa = N'Parcela repetida na lista: abra a ficha de novo.';
            ELSE IF EXISTS (SELECT 1 FROM #P x WHERE x.ID_CONTA_PREVISTA IS NOT NULL
                              AND NOT EXISTS (SELECT 1 FROM BANCO.Conta c WHERE c.ID_CONTA = x.ID_CONTA_PREVISTA AND c.DT_EXCLUSAO IS NULL
                                                AND (c.ATIVO = 1 OR EXISTS (SELECT 1 FROM FIN.Parcela p WHERE p.ID_PARCELA = x.ID_PARCELA AND p.ID_CONTA_PREVISTA = c.ID_CONTA))))
                SET @Recusa = N'A conta bancária prevista de uma parcela não existe ou está desativada.';
        END;

        IF @Recusa = N'' AND @Novo = 0
        BEGIN
            UPDATE x
               SET x.MUDOU = CASE WHEN p.DT_VENCIMENTO = x.DT_VENCIMENTO AND p.VALOR = x.VALOR THEN 0 ELSE 1 END
            FROM #P x
            INNER JOIN FIN.Parcela p ON p.ID_PARCELA = x.ID_PARCELA;

            -- parcelas com baixa viva: não mudam e não saem
            IF EXISTS (SELECT 1 FROM FIN.Parcela p
                       WHERE p.ID_LANCAMENTO = @IdLancamento
                         AND EXISTS (SELECT 1 FROM FIN.fn_FIN_Parcela_Baixa_Viva(p.ID_PARCELA))
                         AND NOT EXISTS (SELECT 1 FROM #P x WHERE x.ID_PARCELA = p.ID_PARCELA AND x.MUDOU = 0))
                SET @Recusa = N'Parcela com pagamento ou recebimento não pode mudar de vencimento ou valor, nem ser retirada.';
            -- parcela só com baixa estornada: pode mudar, mas não sai (guarda o histórico)
            ELSE IF EXISTS (SELECT 1 FROM FIN.Parcela p
                            WHERE p.ID_LANCAMENTO = @IdLancamento
                              AND EXISTS (SELECT 1 FROM FIN.Baixa b WHERE b.ID_PARCELA = p.ID_PARCELA)
                              AND NOT EXISTS (SELECT 1 FROM #P x WHERE x.ID_PARCELA = p.ID_PARCELA))
                SET @Recusa = N'Parcela com baixa estornada não pode ser retirada (guarda o histórico); mude o vencimento ou o valor dela.';
        END;

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdLancamento AS ID,
                   CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #P;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        WITH n AS (SELECT x.NUMERO, ROW_NUMBER() OVER (ORDER BY x.DT_VENCIMENTO, x.CHAVE) AS NOVO FROM #P x)
        UPDATE n SET n.NUMERO = n.NOVO;

        ---------------------------------------------------------------------
        -- 4) Regras (P17)
        ---------------------------------------------------------------------
        SET @EtapaAtual = 'Regras';
        SET @PodeRetro = SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'LANCAR_RETROATIVO');

        -- cadastros inativos (bloqueio fixo)
        IF @MudouPessoa = 1 AND @IdPessoa IS NOT NULL
           AND EXISTS (SELECT 1 FROM CAD.Pessoa p WHERE p.ID_PESSOA = @IdPessoa AND (p.ATIVO = 0 OR p.DT_EXCLUSAO IS NOT NULL))
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO) VALUES ('PARCEIRO_INATIVO', 'BLOQUEIO', N'O parceiro escolhido está desativado ou na lixeira.', 'idPessoa');
        IF @MudouCentro = 1 AND @IdCentroCusto IS NOT NULL
           AND EXISTS (SELECT 1 FROM CAD.Centro_Custo c WHERE c.ID_CENTRO_CUSTO = @IdCentroCusto AND (c.ATIVO = 0 OR c.DT_EXCLUSAO IS NOT NULL))
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO) VALUES ('CENTRO_INATIVO', 'BLOQUEIO', N'O centro de custo escolhido está desativado ou na lixeira.', 'idCentroCusto');
        IF @MudouPlano = 1 AND @IdPlanoConta IS NOT NULL
           AND EXISTS (SELECT 1 FROM CAD.vw_CAD_Plano_Conta v INNER JOIN CAD.Plano_Conta c ON c.ID_PLANO_CONTA = v.ID_PLANO_CONTA
                       WHERE v.ID_PLANO_CONTA = @IdPlanoConta AND (v.ATIVO_EFETIVO = 0 OR c.DT_EXCLUSAO IS NOT NULL))
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO) VALUES ('CONTA_INATIVA', 'BLOQUEIO', N'A conta do plano escolhida está desativada ou na lixeira.', 'idPlanoConta');

        -- centro de custo encerrado
        IF (@MudouCentro = 1 OR @MudouEmissao = 1)
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            SELECT 'CENTRO_ENCERRADO', CASE WHEN ISNULL(SIS.fn_SIS_Parametro_SN('CENTRO_ENCERRADO_BLOQUEIA'), 1) = 1 THEN 'BLOQUEIO' ELSE 'AVISO' END,
                   N'O centro de custo ' + CONVERT(NVARCHAR(20), c.CODIGO) + N' foi encerrado em ' + CONVERT(NVARCHAR(10), c.DT_ENCERRAMENTO, 103) + N'.', 'idCentroCusto'
            FROM CAD.Centro_Custo c
            WHERE c.ID_CENTRO_CUSTO = @IdCentroCusto AND c.DT_ENCERRAMENTO <= @DtEmissao;

        -- mês fechado (só conta contábil; olha o mês novo e, na alteração, o atual)
        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
        SELECT TOP 1 'MES_FECHADO', 'BLOQUEIO',
               N'O mês ' + RIGHT('0' + CONVERT(NVARCHAR(2), MONTH(m.MES)), 2) + N'/' + CONVERT(NVARCHAR(4), YEAR(m.MES))
               + N' está fechado para a empresa ' + ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL) + N' (conta contábil).', 'dtCompetencia'
        FROM (SELECT @IdEmpresa AS EMP, @DtCompetencia AS MES, @IdPlanoConta AS PLANO
              UNION ALL SELECT @aEmpresa, @aCompetencia, @aPlano WHERE @Novo = 0) x
        INNER JOIN FIN.Mes_Fechado m  ON m.ID_EMPRESA = x.EMP AND m.MES = x.MES AND m.FECHADO = 1
        INNER JOIN CAD.Plano_Conta pc ON pc.ID_PLANO_CONTA = x.PLANO AND pc.CONTABIL = 1
        INNER JOIN CAD.Empresa e      ON e.ID_EMPRESA = x.EMP
        ORDER BY m.MES;

        -- trava de datas (bloqueio, ou motivo para quem tem LANCAR_RETROATIVO)
        IF @MudouEmissao = 1 AND FIN.fn_FIN_Data_Recusa('EMISSAO', @DtEmissao) <> N''
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('DATA_EMISSAO', CASE WHEN @PodeRetro = 1 THEN 'MOTIVO' ELSE 'BLOQUEIO' END, FIN.fn_FIN_Data_Recusa('EMISSAO', @DtEmissao), 'dtEmissao');

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
        SELECT TOP 1 'DATA_VENCIMENTO', CASE WHEN @PodeRetro = 1 THEN 'MOTIVO' ELSE 'BLOQUEIO' END,
               N'Parcela ' + CONVERT(NVARCHAR(5), x.NUMERO) + N': ' + FIN.fn_FIN_Data_Recusa('VENCIMENTO', x.DT_VENCIMENTO), 'parcelas'
        FROM #P x
        WHERE x.MUDOU = 1 AND FIN.fn_FIN_Data_Recusa('VENCIMENTO', x.DT_VENCIMENTO) <> N''
        ORDER BY x.NUMERO;

        -- data a confirmar (dentro do permitido, mas distante de hoje)
        SET @N = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_DATA_AVISO_DIAS'), 3);
        IF @MudouEmissao = 1 AND ABS(DATEDIFF(DAY, @Hoje, @DtEmissao)) > @N AND NOT EXISTS (SELECT 1 FROM #Regra WHERE CODIGO = 'DATA_EMISSAO')
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('DATA_CONFIRMAR', 'AVISO', N'Confirma a data de emissão ' + CONVERT(NVARCHAR(10), @DtEmissao, 103) + N'?', 'dtEmissao');
        IF NOT EXISTS (SELECT 1 FROM #Regra WHERE CODIGO IN ('DATA_VENCIMENTO', 'DATA_CONFIRMAR'))
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            SELECT TOP 1 'DATA_CONFIRMAR', 'AVISO',
                   N'Confirma o vencimento ' + CONVERT(NVARCHAR(10), x.DT_VENCIMENTO, 103) + N' (parcela ' + CONVERT(NVARCHAR(5), x.NUMERO) + N', já passado)?', 'parcelas'
            FROM #P x
            WHERE x.MUDOU = 1 AND x.DT_VENCIMENTO < DATEADD(DAY, -@N, @Hoje)
            ORDER BY x.NUMERO;

        -- vencimento antes da emissão
        SET @Nivel = FIN.fn_FIN_Regra_Nivel('FIN_REGRA_VENC_ANTES_EMISSAO');
        IF @Nivel <> 'NAO'
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            SELECT TOP 1 'VENC_ANTES_EMISSAO', @Nivel,
                   N'A parcela ' + CONVERT(NVARCHAR(5), x.NUMERO) + N' vence em ' + CONVERT(NVARCHAR(10), x.DT_VENCIMENTO, 103)
                   + N', antes da emissão (' + CONVERT(NVARCHAR(10), @DtEmissao, 103) + N').', 'parcelas'
            FROM #P x
            WHERE (x.MUDOU = 1 OR @MudouEmissao = 1) AND x.DT_VENCIMENTO < @DtEmissao
            ORDER BY x.NUMERO;

        -- competência distante da emissão
        SET @Nivel = FIN.fn_FIN_Regra_Nivel('FIN_REGRA_COMPETENCIA_DISTANTE');
        SET @N = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_COMPETENCIA_MESES'), 3);
        SET @Meses = ABS(DATEDIFF(MONTH, @DtEmissao, @DtCompetencia));
        IF @Nivel <> 'NAO' AND (@MudouEmissao = 1 OR @MudouCompetencia = 1) AND @Meses > @N
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('COMPETENCIA_DISTANTE', @Nivel,
                    N'A competência ' + RIGHT('0' + CONVERT(NVARCHAR(2), MONTH(@DtCompetencia)), 2) + N'/' + CONVERT(NVARCHAR(4), YEAR(@DtCompetencia))
                    + N' está a ' + CONVERT(NVARCHAR(5), @Meses) + N' meses da emissão.', 'dtCompetencia');

        -- mesmo parceiro e mesmo documento (só documento com número)
        SET @Nivel = FIN.fn_FIN_Regra_Nivel('FIN_REGRA_DUPLIC_DOCUMENTO');
        IF @Nivel <> 'NAO' AND @IdPessoa IS NOT NULL AND @Documento LIKE N'%[0-9]%' AND (@MudouDocumento = 1 OR @MudouPessoa = 1)
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
            SELECT TOP 1 'DUPLIC_DOCUMENTO', @Nivel,
                   N'O documento ' + l.DOCUMENTO + N' deste parceiro já foi lançado (nº ' + CONVERT(NVARCHAR(20), l.ID_LANCAMENTO)
                   + N', emissão ' + CONVERT(NVARCHAR(10), l.DT_EMISSAO, 103) + N', ' + SIS.fn_SIS_Formatar_Moeda(l.VALOR_TOTAL) + N').',
                   l.ID_LANCAMENTO, 'documento'
            FROM FIN.Lancamento l WITH (NOLOCK)
            WHERE l.ID_PESSOA = @IdPessoa AND l.TIPO = @Tipo AND l.DOCUMENTO = @Documento
              AND l.SITUACAO = 'ATIVO' AND l.DT_EXCLUSAO IS NULL AND l.ID_LANCAMENTO <> ISNULL(@IdLancamento, 0)
            ORDER BY l.DT_EMISSAO DESC, l.ID_LANCAMENTO DESC;

        -- possível duplicidade: mesmo parceiro, mesmo valor de parcela, vencimento próximo
        SET @Nivel = FIN.fn_FIN_Regra_Nivel('FIN_REGRA_DUPLIC_VALOR');
        SET @N = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_DUPLIC_VALOR_DIAS'), 5);
        IF @Nivel <> 'NAO' AND @IdPessoa IS NOT NULL
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
            SELECT TOP 1 'DUPLIC_VALOR', @Nivel,
                   N'Possível duplicidade: o lançamento nº ' + CONVERT(NVARCHAR(20), l.ID_LANCAMENTO) + N' deste parceiro tem parcela de '
                   + SIS.fn_SIS_Formatar_Moeda(p.VALOR) + N' com vencimento em ' + CONVERT(NVARCHAR(10), p.DT_VENCIMENTO, 103) + N'.',
                   l.ID_LANCAMENTO, 'parcelas'
            FROM #P x
            INNER JOIN FIN.Parcela p    WITH (NOLOCK) ON p.VALOR = x.VALOR AND p.SITUACAO <> 'CANCELADA'
                                                     AND p.DT_VENCIMENTO BETWEEN DATEADD(DAY, -@N, x.DT_VENCIMENTO) AND DATEADD(DAY, @N, x.DT_VENCIMENTO)
            INNER JOIN FIN.Lancamento l WITH (NOLOCK) ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
            WHERE (x.MUDOU = 1 OR @MudouPessoa = 1)
              AND l.ID_PESSOA = @IdPessoa AND l.TIPO = @Tipo AND l.SITUACAO = 'ATIVO' AND l.DT_EXCLUSAO IS NULL
              AND l.ID_LANCAMENTO <> ISNULL(@IdLancamento, 0)
              AND NOT EXISTS (SELECT 1 FROM #Regra r WHERE r.CODIGO = 'DUPLIC_DOCUMENTO' AND r.ID_REFERENCIA = l.ID_LANCAMENTO)
            ORDER BY ABS(DATEDIFF(DAY, x.DT_VENCIMENTO, p.DT_VENCIMENTO)), l.ID_LANCAMENTO DESC;

        -- valor fora do padrão (média do mesmo parceiro e conta do plano)
        SET @Nivel = FIN.fn_FIN_Regra_Nivel('FIN_REGRA_VALOR_FORA_PADRAO');
        IF @Nivel <> 'NAO' AND @IdPessoa IS NOT NULL AND @IdPlanoConta IS NOT NULL AND (@MudouValor = 1 OR @MudouPessoa = 1 OR @MudouPlano = 1)
        BEGIN
            SET @V     = ISNULL(SIS.fn_SIS_Parametro_Decimal('FIN_VALOR_FORA_PADRAO_VEZES'), 3);
            SET @N     = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_VALOR_FORA_PADRAO_MIN_HIST'), 3);
            SET @Meses = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_VALOR_FORA_PADRAO_MESES'), 12);
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            SELECT 'VALOR_FORA_PADRAO', @Nivel,
                   N'O valor ' + SIS.fn_SIS_Formatar_Moeda(@ValorTotal) + N' é ' + CONVERT(NVARCHAR(20), CAST(ROUND(@ValorTotal / NULLIF(h.MEDIA, 0), 1) AS DECIMAL(18,1)))
                   + N' vezes a média (' + SIS.fn_SIS_Formatar_Moeda(CAST(h.MEDIA AS DECIMAL(18,2))) + N') dos últimos ' + CONVERT(NVARCHAR(10), h.QTD)
                   + N' lançamentos deste parceiro nesta conta.', 'valorTotal'
            FROM (SELECT COUNT(*) AS QTD, AVG(l.VALOR_TOTAL) AS MEDIA
                  FROM FIN.Lancamento l WITH (NOLOCK)
                  WHERE l.ID_PESSOA = @IdPessoa AND l.ID_PLANO_CONTA = @IdPlanoConta AND l.TIPO = @Tipo
                    AND l.SITUACAO = 'ATIVO' AND l.DT_EXCLUSAO IS NULL AND l.ID_LANCAMENTO <> ISNULL(@IdLancamento, 0)
                    AND l.DT_EMISSAO >= DATEADD(MONTH, -@Meses, @DtEmissao)
                    AND l.DT_EMISSAO <= @DtEmissao) h
            WHERE h.QTD >= @N AND h.MEDIA > 0 AND @ValorTotal > h.MEDIA * @V;
        END;

        -- parceiro sem o tipo Fornecedor / Cliente
        SET @Nivel = FIN.fn_FIN_Regra_Nivel('FIN_REGRA_TIPO_PARCEIRO');
        IF @Nivel <> 'NAO' AND @MudouPessoa = 1 AND @MarcarTipoParceiro = 0
           AND EXISTS (SELECT 1 FROM CAD.Pessoa p WHERE p.ID_PESSOA = @IdPessoa AND ((@Tipo = 'P' AND p.FORNECEDOR = 0) OR (@Tipo = 'R' AND p.CLIENTE = 0)))
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('TIPO_PARCEIRO', @Nivel, N'O parceiro não está marcado como ' + CASE @Tipo WHEN 'P' THEN N'Fornecedor' ELSE N'Cliente' END + N'.', 'idPessoa');

        -- conta de receita no a pagar, ou de despesa no a receber
        SET @Nivel = FIN.fn_FIN_Regra_Nivel('FIN_REGRA_TIPO_CONTA');
        IF @Nivel <> 'NAO' AND @MudouPlano = 1
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            SELECT 'TIPO_CONTA', @Nivel,
                   N'A conta ' + CONVERT(NVARCHAR(12), v.CODIGO) + N' - ' + v.DESCRICAO + N' é de ' + CASE v.TIPO WHEN 'RECEITA' THEN N'receita' ELSE N'despesa' END
                   + N' e o lançamento é a ' + CASE @Tipo WHEN 'P' THEN N'pagar.' ELSE N'receber.' END, 'idPlanoConta'
            FROM CAD.vw_CAD_Plano_Conta v
            WHERE v.ID_PLANO_CONTA = @IdPlanoConta AND ((@Tipo = 'P' AND v.TIPO = 'RECEITA') OR (@Tipo = 'R' AND v.TIPO = 'DESPESA'));

        ---------------------------------------------------------------------
        -- 5) Resultado das regras
        ---------------------------------------------------------------------
        SET @Avisos = ISNULL((SELECT r.CODIGO AS codigo, r.NIVEL AS nivel, r.MENSAGEM AS mensagem, r.ID_REFERENCIA AS idReferencia, r.CAMPO AS campo
                              FROM #Regra r
                              ORDER BY CASE r.NIVEL WHEN 'BLOQUEIO' THEN 0 WHEN 'MOTIVO' THEN 1 ELSE 2 END, r.ORDEM
                              FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]');

        IF EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'BLOQUEIO')
        BEGIN
            SELECT TOP 1 @Recusa = r.MENSAGEM FROM #Regra r WHERE r.NIVEL = 'BLOQUEIO' ORDER BY r.ORDEM;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdLancamento AS ID,
                   CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #P;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        IF (EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') AND LEN(@MotivoRetroativo) < 5)
           OR EXISTS (SELECT 1 FROM #Regra r WHERE r.NIVEL = 'AVISO'
                        AND NOT EXISTS (SELECT 1 FROM STRING_SPLIT(@AvisosConfirmados, N',') s WHERE LTRIM(RTRIM(s.value)) = r.CODIGO))
            SET @Pendente = 1;

        IF @SomenteConferir = 1 OR @Pendente = 1
        BEGIN
            SELECT CAST(CASE WHEN @SomenteConferir = 1 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
                   CAST(CASE WHEN @Pendente = 0 THEN N'Nada a confirmar.'
                             WHEN EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') AND LEN(@MotivoRetroativo) < 5
                                  THEN N'Data fora da trava de datas: informe o motivo para gravar.'
                             ELSE N'Confira os avisos antes de gravar.' END AS NVARCHAR(400)) AS MENSAGEM,
                   @IdLancamento AS ID, @Pendente AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #P;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        ---------------------------------------------------------------------
        -- 6) Gravação
        ---------------------------------------------------------------------
        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        SET @N = (SELECT COUNT(*) FROM #P);
        SELECT @IdTipoMarcar = t.ID_PARCEIRO_TIPO FROM CAD.Parceiro_Tipo t WHERE t.CODIGO = CASE @Tipo WHEN 'P' THEN 'FORNECEDOR' ELSE 'CLIENTE' END;
        SELECT @IdTipoNA = t.ID_PARCEIRO_TIPO FROM CAD.Parceiro_Tipo t WHERE t.CODIGO = 'NA';

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        -- duplicidade de documento conferida de novo com trava (regra 22)
        IF FIN.fn_FIN_Regra_Nivel('FIN_REGRA_DUPLIC_DOCUMENTO') = 'BLOQUEIO' AND @IdPessoa IS NOT NULL AND @Documento LIKE N'%[0-9]%'
           AND (@MudouDocumento = 1 OR @MudouPessoa = 1)
           AND EXISTS (SELECT 1 FROM FIN.Lancamento l WITH (UPDLOCK, HOLDLOCK)
                       WHERE l.ID_PESSOA = @IdPessoa AND l.TIPO = @Tipo AND l.DOCUMENTO = @Documento
                         AND l.SITUACAO = 'ATIVO' AND l.DT_EXCLUSAO IS NULL AND l.ID_LANCAMENTO <> ISNULL(@IdLancamento, 0))
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Este documento deste parceiro acabou de ser lançado por outra pessoa.' AS NVARCHAR(400)) AS MENSAGEM,
                   @IdLancamento AS ID, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #P;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        IF @Novo = 1
        BEGIN
            INSERT INTO FIN.Lancamento (TIPO, ID_EMPRESA, ID_CENTRO_CUSTO, ID_PESSOA, ID_PLANO_CONTA, ID_HISTORICO_PADRAO, DOCUMENTO,
                                        DT_EMISSAO, DT_COMPETENCIA, HISTORICO, OBSERVACAO, VALOR_TOTAL, ORIGEM, SITUACAO, PREVISAO,
                                        INTEGRACAO, USUARIO_CRIACAO)
            VALUES (@Tipo, @IdEmpresa, @IdCentroCusto, @IdPessoa, @IdPlanoConta, @IdHistoricoPadrao, ISNULL(@Documento, N''),
                    @DtEmissao, @DtCompetencia, ISNULL(@Historico, N''), ISNULL(@Observacao, N''), ISNULL(@ValorTotal, 0), 'MANUAL', 'ATIVO',
                    ISNULL(@Previsao, 0), ISNULL(@Integracao, 'COMPLETA'), ISNULL(@Usuario, N'sistema'));
            SET @IdLancamento = SCOPE_IDENTITY();
        END
        ELSE
            UPDATE l
               SET l.ID_EMPRESA = @IdEmpresa, l.ID_CENTRO_CUSTO = @IdCentroCusto, l.ID_PESSOA = @IdPessoa, l.ID_PLANO_CONTA = @IdPlanoConta,
                   l.ID_HISTORICO_PADRAO = @IdHistoricoPadrao, l.DOCUMENTO = ISNULL(@Documento, N''), l.DT_EMISSAO = @DtEmissao,
                   l.DT_COMPETENCIA = @DtCompetencia, l.HISTORICO = ISNULL(@Historico, N''), l.OBSERVACAO = ISNULL(@Observacao, N''),
                   l.VALOR_TOTAL = ISNULL(@ValorTotal, 0), l.PREVISAO = ISNULL(@Previsao, 0), l.INTEGRACAO = ISNULL(@Integracao, 'COMPLETA'),
                   l.DT_ALTERACAO = SYSDATETIME(), l.USUARIO_ALTERACAO = @Usuario
            FROM FIN.Lancamento l
            WHERE l.ID_LANCAMENTO = @IdLancamento;

        -- parcelas: retira as que saíram (sem baixa), acerta as que ficaram, inclui as novas
        DELETE p
        FROM FIN.Parcela p
        WHERE p.ID_LANCAMENTO = @IdLancamento
          AND NOT EXISTS (SELECT 1 FROM #P x WHERE x.ID_PARCELA = p.ID_PARCELA)
          AND NOT EXISTS (SELECT 1 FROM FIN.Baixa b WHERE b.ID_PARCELA = p.ID_PARCELA);

        UPDATE p
           SET p.NUMERO = x.NUMERO, p.QTD_PARCELAS = @N, p.DT_VENCIMENTO = x.DT_VENCIMENTO, p.VALOR = x.VALOR,
               p.ID_CONTA_PREVISTA = x.ID_CONTA_PREVISTA,
               p.SITUACAO = CASE WHEN p.SITUACAO = 'CANCELADA' THEN p.SITUACAO
                                 WHEN p.VALOR_BAIXADO = 0 THEN 'ABERTA'
                                 WHEN p.VALOR_BAIXADO >= x.VALOR THEN 'PAGA' ELSE 'PARCIAL' END,
               p.DT_ALTERACAO = SYSDATETIME(), p.USUARIO_ALTERACAO = @Usuario
        FROM FIN.Parcela p
        INNER JOIN #P x ON x.ID_PARCELA = p.ID_PARCELA
        WHERE p.NUMERO <> x.NUMERO OR p.QTD_PARCELAS <> @N OR p.DT_VENCIMENTO <> x.DT_VENCIMENTO OR p.VALOR <> x.VALOR
           OR ISNULL(p.ID_CONTA_PREVISTA, 0) <> ISNULL(x.ID_CONTA_PREVISTA, 0);

        INSERT INTO FIN.Parcela (ID_LANCAMENTO, NUMERO, QTD_PARCELAS, DT_VENCIMENTO, VALOR, SITUACAO, ID_CONTA_PREVISTA, USUARIO_CRIACAO)
        SELECT @IdLancamento, ISNULL(x.NUMERO, 1), @N, x.DT_VENCIMENTO, ISNULL(x.VALOR, 0), 'ABERTA', x.ID_CONTA_PREVISTA, ISNULL(@Usuario, N'sistema')
        FROM #P x
        WHERE x.ID_PARCELA IS NULL;

        -- marcar o tipo Fornecedor / Cliente no parceiro (resposta ao aviso)
        IF @MarcarTipoParceiro = 1 AND @IdPessoa IS NOT NULL AND @IdTipoMarcar IS NOT NULL
           AND EXISTS (SELECT 1 FROM CAD.Pessoa p WHERE p.ID_PESSOA = @IdPessoa AND ((@Tipo = 'P' AND p.FORNECEDOR = 0) OR (@Tipo = 'R' AND p.CLIENTE = 0)))
        BEGIN
            UPDATE pt SET pt.ATIVO = 1, pt.DT_ALTERACAO = SYSDATETIME(), pt.USUARIO_ALTERACAO = @Usuario
            FROM CAD.Pessoa_Tipo pt
            WHERE pt.ID_PESSOA = @IdPessoa AND pt.ID_PARCEIRO_TIPO = @IdTipoMarcar AND pt.ATIVO = 0;

            INSERT INTO CAD.Pessoa_Tipo (ID_PESSOA, ID_PARCEIRO_TIPO, ATIVO, USUARIO_CRIACAO)
            SELECT @IdPessoa, @IdTipoMarcar, 1, ISNULL(@Usuario, N'sistema')
            WHERE NOT EXISTS (SELECT 1 FROM CAD.Pessoa_Tipo pt WHERE pt.ID_PESSOA = @IdPessoa AND pt.ID_PARCEIRO_TIPO = @IdTipoMarcar);

            UPDATE pt SET pt.ATIVO = 0, pt.DT_ALTERACAO = SYSDATETIME(), pt.USUARIO_ALTERACAO = @Usuario
            FROM CAD.Pessoa_Tipo pt
            WHERE pt.ID_PESSOA = @IdPessoa AND pt.ID_PARCEIRO_TIPO = @IdTipoNA AND pt.ATIVO = 1;

            UPDATE p
               SET p.FORNECEDOR = CASE WHEN @Tipo = 'P' THEN 1 ELSE p.FORNECEDOR END,
                   p.CLIENTE    = CASE WHEN @Tipo = 'R' THEN 1 ELSE p.CLIENTE END,
                   p.DT_ALTERACAO = SYSDATETIME(), p.USUARIO_ALTERACAO = @Usuario
            FROM CAD.Pessoa p
            WHERE p.ID_PESSOA = @IdPessoa;

            INSERT INTO SIS.Aviso_Confirmado (TABELA, ID_REGISTRO, CODIGO_REGRA, NIVEL, MENSAGEM, MOTIVO, ID_USUARIO, USUARIO_CRIACAO)
            VALUES (N'FIN.Lancamento', @IdLancamento, 'TIPO_PARCEIRO', 'AVISO',
                    N'Tipo ' + CASE @Tipo WHEN 'P' THEN N'Fornecedor' ELSE N'Cliente' END + N' marcado no parceiro.', N'', @IdUsuario, ISNULL(@Usuario, N'sistema'));
        END;

        -- avisos confirmados e motivo da trava de datas
        INSERT INTO SIS.Aviso_Confirmado (TABELA, ID_REGISTRO, CODIGO_REGRA, NIVEL, MENSAGEM, MOTIVO, ID_REFERENCIA, ID_USUARIO, USUARIO_CRIACAO)
        SELECT N'FIN.Lancamento', @IdLancamento, r.CODIGO, r.NIVEL, r.MENSAGEM,
               CASE WHEN r.NIVEL = 'MOTIVO' THEN ISNULL(@MotivoRetroativo, N'') ELSE N'' END, r.ID_REFERENCIA, @IdUsuario, ISNULL(@Usuario, N'sistema')
        FROM #Regra r
        WHERE r.NIVEL IN ('AVISO', 'MOTIVO');

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Lançamento gravado.' AS NVARCHAR(400)) AS MENSAGEM, @IdLancamento AS ID,
               CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;

        DROP TABLE IF EXISTS #P;
        DROP TABLE IF EXISTS #Regra;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        DROP TABLE IF EXISTS #P;
        DROP TABLE IF EXISTS #Regra;

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar o lançamento. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               @IdLancamento AS ID, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Conferir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Conferir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Prévia, só leitura, das proteções contra erro de digitação
                (P17) de um lançamento antes de gravar: a tela mostra os
                bloqueios, os avisos a confirmar e o pedido de motivo (trava de
                datas). Usa a mesma conferência da gravação
                (FIN_Lancamento_Gravar com @SomenteConferir = 1), para as
                regras nunca ficarem diferentes. Não grava nada.
                Devolve 1 linha: SUCESSO (0 = há bloqueio ou dado inválido),
                MENSAGEM, ID, PENDENTE (há aviso ou motivo) e AVISOS (JSON).
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Conferir]
    @IdUsuario           INT,
    @IdLancamento        BIGINT          = NULL,
    @Tipo                CHAR(1)         = NULL,
    @IdCentroCusto       INT             = NULL,
    @IdPessoa            INT             = NULL,
    @IdPlanoConta        INT             = NULL,
    @IdHistoricoPadrao   INT             = NULL,
    @Documento           NVARCHAR(40)    = NULL,
    @DtEmissao           DATE            = NULL,
    @DtCompetencia       DATE            = NULL,
    @Historico           NVARCHAR(200)   = NULL,
    @Observacao          NVARCHAR(2000)  = NULL,
    @ValorTotal          DECIMAL(18,2)   = NULL,
    @Previsao            BIT             = 0,
    @Integracao          VARCHAR(12)     = NULL,
    @Parcelas            NVARCHAR(MAX)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    EXEC FIN.FIN_Lancamento_Gravar
         @IdUsuario = @IdUsuario, @IdLancamento = @IdLancamento, @Tipo = @Tipo, @IdCentroCusto = @IdCentroCusto,
         @IdPessoa = @IdPessoa, @IdPlanoConta = @IdPlanoConta, @IdHistoricoPadrao = @IdHistoricoPadrao,
         @Documento = @Documento, @DtEmissao = @DtEmissao, @DtCompetencia = @DtCompetencia, @Historico = @Historico,
         @Observacao = @Observacao, @ValorTotal = @ValorTotal, @Previsao = @Previsao, @Integracao = @Integracao,
         @Parcelas = @Parcelas, @SomenteConferir = 1;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Lista das telas Contas a pagar (@Tipo P) e Contas a receber
                (@Tipo R) e da aba Movimentação do Parceiro (@Tipo NULL com
                @IdPessoa: os dois tipos que o usuário pode ver).
                @Visao PARCELA (padrão): uma linha por vencimento.
                @Visao LANCAMENTO: uma linha por lançamento (vencimento = o
                primeiro das parcelas filtradas; valores = todas as parcelas).
                @Situacao: EM_ABERTO (aberta + parcial), ABERTA, PARCIAL, PAGA,
                CANCELADA, VENCIDA (em aberto e vencida), HOJE (em aberto
                vencendo hoje), A_VENCER (em aberto, de amanhã até
                FIN_LISTA_DIAS_A_VENCER dias) ou vazio (todas; sem as
                canceladas quando FIN_LISTA_OCULTA_CANCELADAS = S).
                @CampoData escolhe a data do período (@VencDe/@VencAte):
                VENCIMENTO (padrão), EMISSAO ou COMPETENCIA (mês).
                Filtros opcionais por período, empresa, centro,
                parceiro, conta do plano, lote, documento, texto e valor.
                Paginação (@Pagina, @PorPagina; padrão FIN_LISTA_POR_PAGINA:
                a página é escolhida antes de buscar os detalhes) e
                totais do filtro inteiro em cada linha (TOTAL_*). Não lista o
                que está na lixeira. Permissão: VER em FIN_PAGAR / FIN_RECEBER.
                Padrão "Listar": THROW 50001.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f).
    v1.1 (25/11/2026) - Etapa 04f2a: situações HOJE e A_VENCER, período por
                        emissão ou competência (@CampoData) e canceladas fora
                        de "todas" pelo parâmetro FIN_LISTA_OCULTA_CANCELADAS.
    v1.2 (26/11/2026) - Etapa 04f2c (P27): filtro de pendências (@Pendencia
                        COM, AUTOMATICA, MANUAL, MINHAS, ATRASADA ou BLOQUEIA;
                        @PendenciaCodigo = tipo manual ou regra automática) e
                        colunas QTD_PENDENCIAS, PENDENCIAS (texto), PENDENCIA_
                        BLOQUEIA e PENDENCIA_ATRASADA, calculadas só para as
                        linhas da página (FIN.fn_FIN_Lancamento_Pendencias).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Listar @IdUsuario = 2, @Tipo = 'R', @Situacao = 'EM_ABERTO';
    -- EXEC FIN.FIN_Lancamento_Listar @IdUsuario = 2, @Tipo = 'P', @Visao = 'LANCAMENTO', @Texto = N'cimento';
    -- EXEC FIN.FIN_Lancamento_Listar @IdUsuario = 2, @Tipo = 'R', @Situacao = 'A_VENCER', @CampoData = 'EMISSAO', @VencDe = '2026-01-01';
    -- EXEC FIN.FIN_Lancamento_Listar @IdUsuario = 2, @Tipo = 'P', @Pendencia = 'COM', @Visao = 'LANCAMENTO';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Listar]
    @IdUsuario      INT,
    @Tipo           CHAR(1)        = NULL,
    @Visao          VARCHAR(12)    = 'PARCELA',
    @Situacao       VARCHAR(12)    = NULL,
    @VencDe         DATE           = NULL,
    @VencAte        DATE           = NULL,
    @CampoData      VARCHAR(12)    = 'VENCIMENTO',
    @IdEmpresa      INT            = NULL,
    @IdCentroCusto  INT            = NULL,
    @IdPessoa       INT            = NULL,
    @IdPlanoConta   INT            = NULL,
    @IdLote         BIGINT         = NULL,
    @IdLancamento   BIGINT         = NULL,
    @Documento      NVARCHAR(40)   = NULL,
    @Texto          NVARCHAR(100)  = NULL,
    @ValorDe        DECIMAL(18,2)  = NULL,
    @ValorAte       DECIMAL(18,2)  = NULL,
    @Ordem          VARCHAR(12)    = 'VENCIMENTO',
    @Pagina         INT            = 1,
    @PorPagina      INT            = NULL,
    @Pendencia      VARCHAR(12)    = NULL,
    @PendenciaCodigo VARCHAR(20)   = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @VeP        BIT;
    DECLARE @VeR        BIT;
    DECLARE @Hoje       DATE = CONVERT(DATE, SYSDATETIME());
    DECLARE @Termo      NVARCHAR(102);
    DECLARE @Digitos    VARCHAR(100);
    DECLARE @Linhas     INT = 0;
    DECLARE @TotValor   DECIMAL(18,2) = 0;
    DECLARE @TotBaixado DECIMAL(18,2) = 0;
    DECLARE @TotSaldo   DECIMAL(18,2) = 0;
    DECLARE @DiasAVencer INT;
    DECLARE @OcultaCanc  BIT;

    DROP TABLE IF EXISTS #F;
    DROP TABLE IF EXISTS #G;
    DROP TABLE IF EXISTS #T;
    DROP TABLE IF EXISTS #Pg;
    DROP TABLE IF EXISTS #PendL;

    BEGIN TRY
        SET @Tipo = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@Tipo, '')))), '');
        SET @VeP  = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PAGAR', 'VER');
        SET @VeR  = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_RECEBER', 'VER');
        IF (@Tipo = 'P' AND @VeP = 0) OR (@Tipo = 'R' AND @VeR = 0) OR (@Tipo IS NULL AND @VeP = 0 AND @VeR = 0)
            THROW 50001, N'Você não tem permissão para ver estes lançamentos.', 1;
        IF @Tipo IS NOT NULL AND @Tipo NOT IN ('P', 'R')
            THROW 50001, N'Tipo inválido.', 1;

        SET @Visao     = CASE WHEN UPPER(ISNULL(@Visao, '')) = 'LANCAMENTO' THEN 'LANCAMENTO' ELSE 'PARCELA' END;
        SET @Situacao  = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@Situacao, '')))), '');
        SET @Ordem     = UPPER(ISNULL(@Ordem, 'VENCIMENTO'));
        SET @CampoData = CASE UPPER(ISNULL(@CampoData, '')) WHEN 'EMISSAO' THEN 'EMISSAO' WHEN 'COMPETENCIA' THEN 'COMPETENCIA' ELSE 'VENCIMENTO' END;
        SET @DiasAVencer = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_LISTA_DIAS_A_VENCER'), 7);
        IF @DiasAVencer NOT BETWEEN 1 AND 365 SET @DiasAVencer = 7;
        SET @OcultaCanc  = ISNULL(SIS.fn_SIS_Parametro_SN('FIN_LISTA_OCULTA_CANCELADAS'), 1);
        SET @Pagina    = CASE WHEN ISNULL(@Pagina, 1) < 1 THEN 1 ELSE @Pagina END;
        SET @PorPagina = ISNULL(@PorPagina, ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_LISTA_POR_PAGINA'), 100));
        IF @PorPagina NOT BETWEEN 10 AND 1000 SET @PorPagina = 100;
        SET @Documento = NULLIF(LTRIM(RTRIM(ISNULL(@Documento, N''))), N'');
        SET @Texto     = NULLIF(LTRIM(RTRIM(ISNULL(@Texto, N''))), N'');
        SET @Termo     = N'%' + REPLACE(REPLACE(REPLACE(ISNULL(@Texto, N''), N'[', N'[[]'), N'%', N'[%]'), N'_', N'[_]') + N'%';
        SET @Digitos   = NULLIF(CONVERT(VARCHAR(100), CAD.fn_CAD_Somente_Digitos(ISNULL(@Texto, N''))), '');
        SET @Pendencia       = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@Pendencia, '')))), '');
        SET @PendenciaCodigo = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@PendenciaCodigo, '')))), '');
        IF @PendenciaCodigo IS NOT NULL AND @Pendencia IS NULL SET @Pendencia = 'COM';

        SET @EtapaAtual = 'Filtro';
        SELECT p.ID_PARCELA, p.ID_LANCAMENTO, p.NUMERO, p.DT_VENCIMENTO, p.VALOR, p.VALOR_BAIXADO, p.SALDO, l.DT_EMISSAO,
               ISNULL(pe.NOME, N'') AS PESSOA_NOME
        INTO #F
        FROM FIN.Parcela p WITH (NOLOCK)
        INNER JOIN FIN.Lancamento l WITH (NOLOCK) ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
        LEFT  JOIN CAD.Pessoa pe    WITH (NOLOCK) ON pe.ID_PESSOA = l.ID_PESSOA
        WHERE l.DT_EXCLUSAO IS NULL
          AND ((l.TIPO = 'P' AND @VeP = 1) OR (l.TIPO = 'R' AND @VeR = 1))
          AND (@Tipo IS NULL OR l.TIPO = @Tipo)
          AND ((@Situacao IS NULL AND (@OcultaCanc = 0 OR p.SITUACAO <> 'CANCELADA'))
               OR (@Situacao = 'EM_ABERTO' AND p.SITUACAO IN ('ABERTA', 'PARCIAL'))
               OR (@Situacao = 'VENCIDA'   AND p.SITUACAO IN ('ABERTA', 'PARCIAL') AND p.DT_VENCIMENTO < @Hoje)
               OR (@Situacao = 'HOJE'      AND p.SITUACAO IN ('ABERTA', 'PARCIAL') AND p.DT_VENCIMENTO = @Hoje)
               OR (@Situacao = 'A_VENCER'  AND p.SITUACAO IN ('ABERTA', 'PARCIAL') AND p.DT_VENCIMENTO > @Hoje AND p.DT_VENCIMENTO <= DATEADD(DAY, @DiasAVencer, @Hoje))
               OR p.SITUACAO = @Situacao)
          AND (@VencDe IS NULL
               OR (@CampoData = 'VENCIMENTO'  AND p.DT_VENCIMENTO >= @VencDe)
               OR (@CampoData = 'EMISSAO'     AND l.DT_EMISSAO >= @VencDe)
               OR (@CampoData = 'COMPETENCIA' AND l.DT_COMPETENCIA >= DATEFROMPARTS(YEAR(@VencDe), MONTH(@VencDe), 1)))
          AND (@VencAte IS NULL
               OR (@CampoData = 'VENCIMENTO'  AND p.DT_VENCIMENTO <= @VencAte)
               OR (@CampoData = 'EMISSAO'     AND l.DT_EMISSAO <= @VencAte)
               OR (@CampoData = 'COMPETENCIA' AND l.DT_COMPETENCIA <= @VencAte))
          AND (@IdEmpresa     IS NULL OR l.ID_EMPRESA = @IdEmpresa)
          AND (@IdCentroCusto IS NULL OR l.ID_CENTRO_CUSTO = @IdCentroCusto)
          AND (@IdPessoa      IS NULL OR l.ID_PESSOA = @IdPessoa)
          AND (@IdPlanoConta  IS NULL OR l.ID_PLANO_CONTA = @IdPlanoConta)
          AND (@IdLote        IS NULL OR l.ID_LOTE = @IdLote OR p.ID_LOTE = @IdLote)
          AND (@IdLancamento  IS NULL OR l.ID_LANCAMENTO = @IdLancamento)
          AND (@Documento     IS NULL OR l.DOCUMENTO LIKE @Documento + N'%')
          AND (@ValorDe       IS NULL OR p.VALOR >= @ValorDe)
          AND (@ValorAte      IS NULL OR p.VALOR <= @ValorAte)
          AND (@Texto IS NULL
               OR l.HISTORICO  COLLATE Latin1_General_CI_AI LIKE @Termo
               OR l.DOCUMENTO  COLLATE Latin1_General_CI_AI LIKE @Termo
               OR l.OBSERVACAO COLLATE Latin1_General_CI_AI LIKE @Termo
               OR pe.NOME      COLLATE Latin1_General_CI_AI LIKE @Termo
               OR pe.NOME_FANTASIA COLLATE Latin1_General_CI_AI LIKE @Termo
               OR (@Digitos IS NOT NULL AND LEN(@Digitos) >= 5 AND pe.CPF_CNPJ LIKE @Digitos + '%')
               OR CONVERT(NVARCHAR(20), l.ID_LANCAMENTO) = @Texto)
        OPTION (RECOMPILE);

        -- P27: filtro de pendências (calcula só para os lançamentos que já passaram pelo filtro)
        IF @Pendencia IS NOT NULL
        BEGIN
            SET @EtapaAtual = 'Pendências';
            SELECT DISTINCT l.ID_LANCAMENTO
            INTO #PendL
            FROM (SELECT DISTINCT ID_LANCAMENTO FROM #F) l
            CROSS APPLY FIN.fn_FIN_Lancamento_Pendencias(l.ID_LANCAMENTO) pd
            WHERE (@Pendencia = 'COM'
                   OR (@Pendencia = 'AUTOMATICA' AND pd.ORIGEM = 'AUTOMATICA')
                   OR (@Pendencia = 'MANUAL'     AND pd.ORIGEM = 'MANUAL')
                   OR (@Pendencia = 'MINHAS'     AND pd.ORIGEM = 'MANUAL' AND pd.ID_USUARIO_RESPONSAVEL = @IdUsuario)
                   OR (@Pendencia = 'ATRASADA'   AND pd.ATRASADA = 1)
                   OR (@Pendencia = 'BLOQUEIA'   AND pd.BLOQUEIA_BAIXA = 1))
              AND (@PendenciaCodigo IS NULL OR pd.CODIGO = @PendenciaCodigo)
              -- só os candidatos: em aberto (automáticas) ou com pendência manual aberta
              AND (EXISTS (SELECT 1 FROM FIN.Parcela p2 WITH (NOLOCK) WHERE p2.ID_LANCAMENTO = l.ID_LANCAMENTO AND p2.SITUACAO IN ('ABERTA', 'PARCIAL'))
                   OR EXISTS (SELECT 1 FROM FIN.Lancamento_Pendencia x WITH (NOLOCK) WHERE x.ID_LANCAMENTO = l.ID_LANCAMENTO AND x.SITUACAO = 'ABERTA' AND x.ATIVO = 1));

            DELETE f FROM #F f WHERE NOT EXISTS (SELECT 1 FROM #PendL x WHERE x.ID_LANCAMENTO = f.ID_LANCAMENTO);
        END;

        -- linhas da página primeiro (só com o que já está em #F); detalhes depois, só para elas
        SET @EtapaAtual = 'Página';
        CREATE TABLE #Pg (ORDEM INT NOT NULL, ID_LANCAMENTO BIGINT NOT NULL, ID_PARCELA BIGINT NULL, DT_VENCIMENTO DATE NULL,
                          QTD INT NULL, VALOR DECIMAL(18,2) NULL, BAIXADO DECIMAL(18,2) NULL, SALDO DECIMAL(18,2) NULL,
                          EM_ABERTO INT NULL, CANCELADAS INT NULL, PRIMEIRA_VENCIDA DATE NULL);

        IF @Visao = 'PARCELA'
        BEGIN
            SELECT @Linhas = COUNT(*), @TotValor = ISNULL(SUM(f.VALOR), 0), @TotBaixado = ISNULL(SUM(f.VALOR_BAIXADO), 0), @TotSaldo = ISNULL(SUM(f.SALDO), 0) FROM #F f;

            INSERT INTO #Pg (ORDEM, ID_LANCAMENTO, ID_PARCELA, DT_VENCIMENTO)
            SELECT ROW_NUMBER() OVER (ORDER BY (SELECT 1)), x.ID_LANCAMENTO, x.ID_PARCELA, x.DT_VENCIMENTO
            FROM (SELECT f.ID_LANCAMENTO, f.ID_PARCELA, f.DT_VENCIMENTO, f.VALOR, f.PESSOA_NOME, f.DT_EMISSAO, f.NUMERO
                  FROM #F f
                  ORDER BY CASE WHEN @Ordem = 'VALOR'    THEN f.VALOR END DESC,
                           CASE WHEN @Ordem = 'PARCEIRO' THEN f.PESSOA_NOME END,
                           CASE WHEN @Ordem = 'EMISSAO'  THEN f.DT_EMISSAO END DESC,
                           f.DT_VENCIMENTO, f.ID_LANCAMENTO, f.NUMERO
                  OFFSET (@Pagina - 1) * @PorPagina ROWS FETCH NEXT @PorPagina ROWS ONLY) x;
        END
        ELSE
        BEGIN
            SELECT g.ID_LANCAMENTO, MIN(g.DT_VENCIMENTO) AS DT_VENCIMENTO, MAX(g.PESSOA_NOME) AS PESSOA_NOME, MAX(g.DT_EMISSAO) AS DT_EMISSAO
            INTO #G
            FROM #F g
            GROUP BY g.ID_LANCAMENTO;

            SELECT p.ID_LANCAMENTO, COUNT(*) AS QTD, SUM(p.VALOR) AS VALOR, SUM(p.VALOR_BAIXADO) AS BAIXADO, SUM(p.SALDO) AS SALDO,
                   SUM(CASE WHEN p.SITUACAO IN ('ABERTA', 'PARCIAL') THEN 1 ELSE 0 END) AS EM_ABERTO,
                   SUM(CASE WHEN p.SITUACAO = 'CANCELADA' THEN 1 ELSE 0 END) AS CANCELADAS,
                   MIN(CASE WHEN p.SITUACAO IN ('ABERTA', 'PARCIAL') AND p.DT_VENCIMENTO < @Hoje THEN p.DT_VENCIMENTO END) AS PRIMEIRA_VENCIDA
            INTO #T
            FROM FIN.Parcela p WITH (NOLOCK)
            INNER JOIN #G g ON g.ID_LANCAMENTO = p.ID_LANCAMENTO
            GROUP BY p.ID_LANCAMENTO;

            SELECT @Linhas = COUNT(*), @TotValor = ISNULL(SUM(t.VALOR), 0), @TotBaixado = ISNULL(SUM(t.BAIXADO), 0), @TotSaldo = ISNULL(SUM(t.SALDO), 0) FROM #T t;

            INSERT INTO #Pg (ORDEM, ID_LANCAMENTO, DT_VENCIMENTO, QTD, VALOR, BAIXADO, SALDO, EM_ABERTO, CANCELADAS, PRIMEIRA_VENCIDA)
            SELECT ROW_NUMBER() OVER (ORDER BY (SELECT 1)), x.ID_LANCAMENTO, x.DT_VENCIMENTO, x.QTD, x.VALOR, x.BAIXADO, x.SALDO, x.EM_ABERTO, x.CANCELADAS, x.PRIMEIRA_VENCIDA
            FROM (SELECT g.ID_LANCAMENTO, g.DT_VENCIMENTO, t.QTD, t.VALOR, t.BAIXADO, t.SALDO, t.EM_ABERTO, t.CANCELADAS, t.PRIMEIRA_VENCIDA
                  FROM #G g
                  INNER JOIN #T t ON t.ID_LANCAMENTO = g.ID_LANCAMENTO
                  ORDER BY CASE WHEN @Ordem = 'VALOR'    THEN t.VALOR END DESC,
                           CASE WHEN @Ordem = 'PARCEIRO' THEN g.PESSOA_NOME END,
                           CASE WHEN @Ordem = 'EMISSAO'  THEN g.DT_EMISSAO END DESC,
                           g.DT_VENCIMENTO, g.ID_LANCAMENTO
                  OFFSET (@Pagina - 1) * @PorPagina ROWS FETCH NEXT @PorPagina ROWS ONLY) x;
        END;

        SET @EtapaAtual = 'Consulta';
        SELECT l.ID_LANCAMENTO, pg.ID_PARCELA, l.TIPO,
               CAST(p.NUMERO AS SMALLINT) AS NUMERO,
               CAST(ISNULL(p.QTD_PARCELAS, pg.QTD) AS SMALLINT) AS QTD_PARCELAS,
               pg.DT_VENCIMENTO,
               CAST(ISNULL(p.VALOR, pg.VALOR) AS DECIMAL(18,2)) AS VALOR,
               CAST(ISNULL(p.VALOR_BAIXADO, pg.BAIXADO) AS DECIMAL(18,2)) AS VALOR_BAIXADO,
               CAST(ISNULL(p.SALDO, pg.SALDO) AS DECIMAL(18,2)) AS SALDO,
               CAST(CASE WHEN p.ID_PARCELA IS NOT NULL THEN p.SITUACAO
                         WHEN pg.CANCELADAS = pg.QTD THEN 'CANCELADA'
                         WHEN pg.EM_ABERTO = 0 THEN 'PAGA'
                         WHEN pg.BAIXADO > 0 THEN 'PARCIAL'
                         ELSE 'ABERTA' END AS VARCHAR(10)) AS SITUACAO,
               CAST(CASE WHEN p.ID_PARCELA IS NOT NULL AND p.SITUACAO IN ('ABERTA', 'PARCIAL') AND p.DT_VENCIMENTO < @Hoje THEN 1
                         WHEN p.ID_PARCELA IS NULL AND pg.PRIMEIRA_VENCIDA IS NOT NULL THEN 1 ELSE 0 END AS BIT) AS VENCIDA,
               CASE WHEN p.ID_PARCELA IS NOT NULL AND p.SITUACAO IN ('ABERTA', 'PARCIAL') AND p.DT_VENCIMENTO < @Hoje THEN DATEDIFF(DAY, p.DT_VENCIMENTO, @Hoje)
                    WHEN p.ID_PARCELA IS NULL AND pg.PRIMEIRA_VENCIDA IS NOT NULL THEN DATEDIFF(DAY, pg.PRIMEIRA_VENCIDA, @Hoje) ELSE 0 END AS DIAS_ATRASO,
               l.DT_EMISSAO, l.DT_COMPETENCIA, l.DOCUMENTO, l.HISTORICO,
               l.ID_PESSOA, ISNULL(pe.NOME, N'') AS PESSOA_NOME,
               l.ID_EMPRESA, ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL) AS EMPRESA_NOME,
               l.ID_CENTRO_CUSTO, ISNULL(CONVERT(NVARCHAR(20), cc.CODIGO), N'') AS CENTRO_CODIGO, ISNULL(cc.DESCRICAO, N'') AS CENTRO_DESCRICAO,
               l.ID_PLANO_CONTA, ISNULL(CONVERT(NVARCHAR(12), v.CODIGO), N'') AS PLANO_CODIGO, ISNULL(v.DESCRICAO, N'') AS PLANO_DESCRICAO,
               ISNULL(p.ID_LOTE, l.ID_LOTE) AS ID_LOTE, l.ORIGEM, l.PREVISAO, l.SITUACAO AS LANCAMENTO_SITUACAO,
               @Linhas AS TOTAL_LINHAS, @TotValor AS TOTAL_VALOR, @TotBaixado AS TOTAL_BAIXADO, @TotSaldo AS TOTAL_SALDO,
               ISNULL(pd.QTD, 0) AS QTD_PENDENCIAS, CAST(ISNULL(pd.TEXTO, N'') AS NVARCHAR(1000)) AS PENDENCIAS,
               CAST(ISNULL(pd.BLOQUEIA, 0) AS BIT) AS PENDENCIA_BLOQUEIA, CAST(ISNULL(pd.ATRASADA, 0) AS BIT) AS PENDENCIA_ATRASADA
        FROM #Pg pg
        INNER JOIN FIN.Lancamento l         WITH (NOLOCK) ON l.ID_LANCAMENTO = pg.ID_LANCAMENTO
        INNER JOIN CAD.Empresa e            WITH (NOLOCK) ON e.ID_EMPRESA = l.ID_EMPRESA
        LEFT  JOIN FIN.Parcela p            WITH (NOLOCK) ON p.ID_PARCELA = pg.ID_PARCELA
        LEFT  JOIN CAD.Pessoa pe            WITH (NOLOCK) ON pe.ID_PESSOA = l.ID_PESSOA
        LEFT  JOIN CAD.Centro_Custo cc      WITH (NOLOCK) ON cc.ID_CENTRO_CUSTO = l.ID_CENTRO_CUSTO
        LEFT  JOIN CAD.vw_CAD_Plano_Conta v ON v.ID_PLANO_CONTA = l.ID_PLANO_CONTA
        OUTER APPLY (SELECT COUNT(*) AS QTD,
                            STRING_AGG(CONVERT(NVARCHAR(MAX), f.DESCRICAO), N'; ') AS TEXTO,
                            MAX(CAST(f.BLOQUEIA_BAIXA AS INT)) AS BLOQUEIA, MAX(CAST(f.ATRASADA AS INT)) AS ATRASADA
                     FROM FIN.fn_FIN_Lancamento_Pendencias(l.ID_LANCAMENTO) f) pd
        ORDER BY pg.ORDEM;

        DROP TABLE IF EXISTS #F;
        DROP TABLE IF EXISTS #G;
        DROP TABLE IF EXISTS #T;
        DROP TABLE IF EXISTS #Pg;
        DROP TABLE IF EXISTS #PendL;
    END TRY
    BEGIN CATCH
        DROP TABLE IF EXISTS #F;
        DROP TABLE IF EXISTS #G;
        DROP TABLE IF EXISTS #T;
        DROP TABLE IF EXISTS #Pg;
        DROP TABLE IF EXISTS #PendL;
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar os lançamentos. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Ficha do lançamento (Contas a pagar / a receber): dados do
                documento com os nomes do que foi escolhido, as parcelas
                (PARCELAS, JSON, com QTD_BAIXAS e TRAVADA), as baixas (BAIXAS,
                JSON, só consulta até a etapa 04g) e os avisos já confirmados
                (AVISOS_CONFIRMADOS, JSON). Situação para a tela: TEM_BAIXA,
                NA_LIXEIRA, MES_FECHADO, PODE_ALTERAR (permissão + situação +
                origem), PODE_CANCELAR e PODE_EXCLUIR.
                Permissão: VER em FIN_PAGAR / FIN_RECEBER (conforme o tipo).
                Padrão "Listar": THROW 50001.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f).
    v1.1 (26/11/2026) - Etapa 04f2c (P27): PENDENCIAS (JSON, as abertas,
                        automáticas e manuais), QTD_PENDENCIAS, PODE_PENDENCIA,
                        BLOQUEIA_BAIXA e MOTIVO_BLOQUEIO (FIN.fn_FIN_Pendencia_Bloqueia).

    v1.2 (27/11/2026) - Etapa 04g4: TEM_BAIXA e "travada" contam só a baixa
                        viva (fn_FIN_Parcela_Baixa_Viva); TEM_HISTORICO_BAIXA e
                        "fixa" (parcela que não sai) contam qualquer baixa;
                        excluir continua proibido com qualquer baixa.
  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Obter @IdUsuario = 2, @IdLancamento = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Obter]
    @IdUsuario     INT,
    @IdLancamento  BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Obter]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Tipo       CHAR(1);
    DECLARE @Item       VARCHAR(40);
    DECLARE @TemBaixa   BIT = 0;
    DECLARE @TemHistBaixa BIT = 0;
    DECLARE @NaLixeira  BIT = 0;
    DECLARE @MesFechado BIT = 0;
    DECLARE @Editavel   BIT = 0;

    BEGIN TRY
        SELECT @Tipo = l.TIPO FROM FIN.Lancamento l WITH (NOLOCK) WHERE l.ID_LANCAMENTO = @IdLancamento;
        IF @Tipo IS NULL
            THROW 50001, N'Lançamento não encontrado.', 1;

        SET @Item = CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END;
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver este lançamento.', 1;

        SET @EtapaAtual = 'Situação';
        IF EXISTS (SELECT 1 FROM FIN.Parcela p WITH (NOLOCK) WHERE p.ID_LANCAMENTO = @IdLancamento AND EXISTS (SELECT 1 FROM FIN.fn_FIN_Parcela_Baixa_Viva(p.ID_PARCELA)))
            SET @TemBaixa = 1;
        IF EXISTS (SELECT 1 FROM FIN.Baixa b WITH (NOLOCK) INNER JOIN FIN.Parcela p WITH (NOLOCK) ON p.ID_PARCELA = b.ID_PARCELA
                   WHERE p.ID_LANCAMENTO = @IdLancamento)
            SET @TemHistBaixa = 1;
        SET @NaLixeira = SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', @IdLancamento);
        IF EXISTS (SELECT 1 FROM FIN.Lancamento l WITH (NOLOCK)
                   INNER JOIN FIN.Mes_Fechado m  WITH (NOLOCK) ON m.ID_EMPRESA = l.ID_EMPRESA AND m.MES = l.DT_COMPETENCIA AND m.FECHADO = 1
                   INNER JOIN CAD.Plano_Conta pc WITH (NOLOCK) ON pc.ID_PLANO_CONTA = l.ID_PLANO_CONTA AND pc.CONTABIL = 1
                   WHERE l.ID_LANCAMENTO = @IdLancamento)
            SET @MesFechado = 1;
        SELECT @Editavel = CASE WHEN l.SITUACAO = 'ATIVO' AND l.ORIGEM IN ('MANUAL', 'MIGRACAO') AND @NaLixeira = 0 AND @MesFechado = 0 THEN 1 ELSE 0 END
        FROM FIN.Lancamento l WITH (NOLOCK) WHERE l.ID_LANCAMENTO = @IdLancamento;

        SET @EtapaAtual = 'Consulta';
        SELECT l.ID_LANCAMENTO, l.TIPO, l.ID_EMPRESA, ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL) AS EMPRESA_NOME,
               l.ID_CENTRO_CUSTO, ISNULL(CONVERT(NVARCHAR(20), cc.CODIGO), N'') AS CENTRO_CODIGO, ISNULL(cc.DESCRICAO, N'') AS CENTRO_DESCRICAO,
               l.ID_PESSOA, ISNULL(pe.NOME, N'') AS PESSOA_NOME, ISNULL(pe.CPF_CNPJ, '') AS PESSOA_CPF_CNPJ,
               l.ID_PLANO_CONTA, ISNULL(CONVERT(NVARCHAR(12), v.CODIGO), N'') AS PLANO_CODIGO, ISNULL(v.DESCRICAO, N'') AS PLANO_DESCRICAO,
               ISNULL(CONVERT(VARCHAR(15), v.TIPO), '') AS PLANO_TIPO,
               l.ID_HISTORICO_PADRAO, ISNULL(h.DESCRICAO, N'') AS HISTORICO_PADRAO_DESCRICAO,
               l.DOCUMENTO, l.DT_EMISSAO, l.DT_COMPETENCIA, l.HISTORICO, l.OBSERVACAO, l.VALOR_TOTAL,
               l.ORIGEM, l.ID_ORIGEM, l.ID_LOTE, l.SITUACAO, l.PREVISAO, l.INTEGRACAO,
               l.DT_CANCELAMENTO, ISNULL(l.USUARIO_CANCELAMENTO, N'') AS USUARIO_CANCELAMENTO, l.MOTIVO_CANCELAMENTO,
               l.CODIGO_ACCESS, l.DT_CRIACAO, l.USUARIO_CRIACAO, l.DT_ALTERACAO, ISNULL(l.USUARIO_ALTERACAO, N'') AS USUARIO_ALTERACAO,
               @TemBaixa AS TEM_BAIXA, @NaLixeira AS NA_LIXEIRA, @MesFechado AS MES_FECHADO,
               CAST(CASE WHEN @Editavel = 1 AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'ALTERAR') = 1 THEN 1 ELSE 0 END AS BIT) AS PODE_ALTERAR,
               CAST(CASE WHEN @Editavel = 1 AND @TemBaixa = 0 AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'CANCELAR') = 1 THEN 1 ELSE 0 END AS BIT) AS PODE_CANCELAR,
               CAST(CASE WHEN @Editavel = 1 AND @TemHistBaixa = 0 AND l.ORIGEM = 'MANUAL' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'EXCLUIR') = 1 THEN 1 ELSE 0 END AS BIT) AS PODE_EXCLUIR,
               ISNULL((SELECT p.ID_PARCELA AS id, p.NUMERO AS numero, p.QTD_PARCELAS AS qtdParcelas, p.DT_VENCIMENTO AS vencimento,
                              p.VALOR AS valor, p.VALOR_BAIXADO AS valorBaixado, p.SALDO AS saldo, p.SITUACAO AS situacao,
                              p.ID_CONTA_PREVISTA AS idContaPrevista, ISNULL(c.DESCRICAO, N'') AS contaPrevista, p.ID_LOTE AS idLote,
                              (SELECT COUNT(*) FROM FIN.Baixa b WITH (NOLOCK) WHERE b.ID_PARCELA = p.ID_PARCELA) AS qtdBaixas,
                              CAST(CASE WHEN EXISTS (SELECT 1 FROM FIN.fn_FIN_Parcela_Baixa_Viva(p.ID_PARCELA)) THEN 1 ELSE 0 END AS BIT) AS travada,
                              CAST(CASE WHEN EXISTS (SELECT 1 FROM FIN.Baixa b WITH (NOLOCK) WHERE b.ID_PARCELA = p.ID_PARCELA) THEN 1 ELSE 0 END AS BIT) AS fixa
                       FROM FIN.Parcela p WITH (NOLOCK)
                       LEFT JOIN BANCO.Conta c WITH (NOLOCK) ON c.ID_CONTA = p.ID_CONTA_PREVISTA
                       WHERE p.ID_LANCAMENTO = l.ID_LANCAMENTO
                       ORDER BY p.NUMERO
                       FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]') AS PARCELAS,
               ISNULL((SELECT b.ID_BAIXA AS id, p.NUMERO AS parcela, b.DT_PAGAMENTO AS data, b.ID_CONTA AS idConta, c.DESCRICAO AS conta,
                              b.FORMA AS forma, b.VALOR_PRINCIPAL AS principal, b.JUROS AS juros, b.MULTA AS multa, b.CORRECAO AS correcao,
                              b.DESCONTO AS desconto, b.ABATIMENTO AS abatimento, b.TARIFA AS tarifa, b.RETENCAO AS retencao,
                              b.VALOR_LIQUIDO AS liquido, b.COMPENSADO AS compensado, b.DT_COMPENSACAO AS dataCompensacao,
                              b.ID_BAIXA_ESTORNADA AS idBaixaEstornada,
                              CAST(CASE WHEN EXISTS (SELECT 1 FROM FIN.Baixa x WITH (NOLOCK) WHERE x.ID_BAIXA_ESTORNADA = b.ID_BAIXA) THEN 1 ELSE 0 END AS BIT) AS estornada,
                              b.OBSERVACAO AS observacao, b.USUARIO_CRIACAO AS usuario
                       FROM FIN.Baixa b WITH (NOLOCK)
                       INNER JOIN FIN.Parcela p WITH (NOLOCK) ON p.ID_PARCELA = b.ID_PARCELA
                       INNER JOIN BANCO.Conta c WITH (NOLOCK) ON c.ID_CONTA = b.ID_CONTA
                       WHERE p.ID_LANCAMENTO = l.ID_LANCAMENTO
                       ORDER BY b.DT_PAGAMENTO, b.ID_BAIXA
                       FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]') AS BAIXAS,
               ISNULL((SELECT a.CODIGO_REGRA AS codigo, a.NIVEL AS nivel, a.MENSAGEM AS mensagem, a.MOTIVO AS motivo,
                              a.ID_REFERENCIA AS idReferencia, a.USUARIO_CRIACAO AS usuario, a.DT_CRIACAO AS data
                       FROM SIS.Aviso_Confirmado a WITH (NOLOCK)
                       WHERE a.TABELA = N'FIN.Lancamento' AND a.ID_REGISTRO = l.ID_LANCAMENTO
                       ORDER BY a.DT_CRIACAO DESC, a.ID_AVISO_CONFIRMADO DESC
                       FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]') AS AVISOS_CONFIRMADOS,
               ISNULL((SELECT pd.ID_LANCAMENTO_PENDENCIA AS id, pd.ORIGEM AS origem, pd.CODIGO AS codigo, pd.DESCRICAO AS descricao,
                              pd.ORIENTACAO AS orientacao, pd.BLOQUEIA_BAIXA AS bloqueiaBaixa, pd.ATRASADA AS atrasada,
                              pd.ID_PARCELA AS idParcela, pd.ID_USUARIO_RESPONSAVEL AS idResponsavel, pd.DT_PREVISAO AS previsao
                       FROM FIN.fn_FIN_Lancamento_Pendencias(l.ID_LANCAMENTO) pd
                       ORDER BY CASE pd.ORIGEM WHEN 'MANUAL' THEN 0 ELSE 1 END, pd.DT_PREVISAO, pd.CODIGO
                       FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]') AS PENDENCIAS,
               (SELECT COUNT(*) FROM FIN.fn_FIN_Lancamento_Pendencias(l.ID_LANCAMENTO) pc) AS QTD_PENDENCIAS,
               CAST(CASE WHEN @NaLixeira = 0 AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'PENDENCIA') = 1 THEN 1 ELSE 0 END AS BIT) AS PODE_PENDENCIA,
               bq.BLOQUEIA AS BLOQUEIA_BAIXA, bq.MOTIVO AS MOTIVO_BLOQUEIO, @TemHistBaixa AS TEM_HISTORICO_BAIXA
        FROM FIN.Lancamento l WITH (NOLOCK)
        INNER JOIN CAD.Empresa e            WITH (NOLOCK) ON e.ID_EMPRESA = l.ID_EMPRESA
        LEFT  JOIN CAD.Centro_Custo cc      WITH (NOLOCK) ON cc.ID_CENTRO_CUSTO = l.ID_CENTRO_CUSTO
        LEFT  JOIN CAD.Pessoa pe            WITH (NOLOCK) ON pe.ID_PESSOA = l.ID_PESSOA
        LEFT  JOIN CAD.vw_CAD_Plano_Conta v ON v.ID_PLANO_CONTA = l.ID_PLANO_CONTA
        LEFT  JOIN FIN.Historico_Padrao h   WITH (NOLOCK) ON h.ID_HISTORICO_PADRAO = l.ID_HISTORICO_PADRAO
        CROSS APPLY FIN.fn_FIN_Pendencia_Bloqueia(l.ID_LANCAMENTO, NULL) bq
        WHERE l.ID_LANCAMENTO = @IdLancamento;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar o lançamento. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Cancelar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Cancelar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Cancela um lançamento (botão Cancelar da ficha): o lançamento
                fica CANCELADO, com data, usuário e motivo, e as parcelas em
                aberto ficam CANCELADA. Continua na lista (filtro Canceladas) e
                no histórico; volta pelo desfazer da aba Histórico. Só sem
                baixa, fora de mês fechado (conta contábil) e de origem manual
                ou migração. Motivo obrigatório. Tudo-ou-nada.
                Permissão: CANCELAR em FIN_PAGAR / FIN_RECEBER.
                Devolve SUCESSO, MENSAGEM, ID.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f).

    v1.1 (27/11/2026) - Etapa 04g4: só a baixa viva (não estornada) impede o
                        cancelamento (fn_FIN_Parcela_Baixa_Viva).
  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Cancelar @IdUsuario = 2, @IdLancamento = 1, @Motivo = N'Lançado em dobro';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Cancelar]
    @IdUsuario     INT,
    @IdLancamento  BIGINT,
    @Motivo        NVARCHAR(400)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Cancelar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Usuario    NVARCHAR(100);
    DECLARE @Tipo       CHAR(1);
    DECLARE @Situacao   VARCHAR(10);
    DECLARE @Origem     VARCHAR(15);
    DECLARE @Linhas     INT;

    BEGIN TRY
        SET @Motivo = LTRIM(RTRIM(ISNULL(@Motivo, N'')));

        SELECT @Tipo = l.TIPO, @Situacao = l.SITUACAO, @Origem = l.ORIGEM
        FROM FIN.Lancamento l WHERE l.ID_LANCAMENTO = @IdLancamento;

        IF @Tipo IS NULL
            SET @Recusa = N'Lançamento não encontrado.';
        IF @Recusa = N'' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'CANCELAR') = 0
            SET @Recusa = N'Você não tem permissão para cancelar lançamentos.';
        IF @Recusa = N'' AND SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', @IdLancamento) = 1
            SET @Recusa = N'O lançamento está na lixeira.';
        IF @Recusa = N'' AND @Situacao = 'CANCELADO'
            SET @Recusa = N'O lançamento já está cancelado.';
        IF @Recusa = N'' AND @Origem NOT IN ('MANUAL', 'MIGRACAO')
            SET @Recusa = N'Este lançamento foi gerado por outra rotina (' + CONVERT(NVARCHAR(15), @Origem) + N'): cancele pela tela de origem.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM FIN.Parcela p WHERE p.ID_LANCAMENTO = @IdLancamento AND EXISTS (SELECT 1 FROM FIN.fn_FIN_Parcela_Baixa_Viva(p.ID_PARCELA)))
            SET @Recusa = N'O lançamento tem pagamento ou recebimento: estorne as baixas antes de cancelar.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM FIN.Lancamento l
                                     INNER JOIN FIN.Mes_Fechado m  ON m.ID_EMPRESA = l.ID_EMPRESA AND m.MES = l.DT_COMPETENCIA AND m.FECHADO = 1
                                     INNER JOIN CAD.Plano_Conta pc ON pc.ID_PLANO_CONTA = l.ID_PLANO_CONTA AND pc.CONTABIL = 1
                                     WHERE l.ID_LANCAMENTO = @IdLancamento)
            SET @Recusa = N'O mês do lançamento está fechado (conta contábil).';
        IF @Recusa = N'' AND LEN(@Motivo) < 5
            SET @Recusa = N'Informe o motivo do cancelamento.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdLancamento AS ID;
            RETURN;
        END;

        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        UPDATE l
           SET l.SITUACAO = 'CANCELADO', l.DT_CANCELAMENTO = SYSDATETIME(), l.USUARIO_CANCELAMENTO = @Usuario,
               l.MOTIVO_CANCELAMENTO = @Motivo, l.DT_ALTERACAO = SYSDATETIME(), l.USUARIO_ALTERACAO = @Usuario
        FROM FIN.Lancamento l
        WHERE l.ID_LANCAMENTO = @IdLancamento AND l.SITUACAO = 'ATIVO';
        SET @Linhas = @@ROWCOUNT;

        UPDATE p
           SET p.SITUACAO = 'CANCELADA', p.DT_ALTERACAO = SYSDATETIME(), p.USUARIO_ALTERACAO = @Usuario
        FROM FIN.Parcela p
        WHERE p.ID_LANCAMENTO = @IdLancamento AND p.SITUACAO = 'ABERTA';

        COMMIT TRANSACTION;

        SELECT CAST(CASE WHEN @Linhas = 1 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
               CAST(CASE WHEN @Linhas = 1 THEN N'Lançamento cancelado.' ELSE N'O lançamento foi alterado por outra pessoa. Abra a ficha de novo.' END AS NVARCHAR(400)) AS MENSAGEM,
               @IdLancamento AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível cancelar o lançamento. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, @IdLancamento AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Padroes_Obter.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Padroes_Obter]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Sugestão de conta do plano e centro de custo ao escolher o
                parceiro na ficha do lançamento (P17): primeiro a conta/centro
                padrão do cadastro do parceiro (04e); sem padrão, os do último
                lançamento ativo do mesmo tipo deste parceiro. Só sugere o que
                está ativo. Informa também se o parceiro tem o tipo esperado
                (Fornecedor no a pagar, Cliente no a receber).
                ORIGEM_PLANO / ORIGEM_CENTRO: PARCEIRO, ULTIMO ou vazio.
                Permissão: INCLUIR ou ALTERAR em FIN_PAGAR / FIN_RECEBER.
                Padrão "Listar": THROW 50001.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Padroes_Obter @IdUsuario = 2, @IdPessoa = 1, @Tipo = 'P';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Padroes_Obter]
    @IdUsuario  INT,
    @IdPessoa   INT,
    @Tipo       CHAR(1)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Padroes_Obter]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Permissão';
    DECLARE @Item         VARCHAR(40);
    DECLARE @Plano        INT;
    DECLARE @Centro       INT;
    DECLARE @OrigemPlano  VARCHAR(10) = '';
    DECLARE @OrigemCentro VARCHAR(10) = '';

    BEGIN TRY
        SET @Tipo = UPPER(ISNULL(@Tipo, ''));
        SET @Item = CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' WHEN 'R' THEN 'FIN_RECEBER' ELSE '' END;
        IF @Item = ''
            THROW 50001, N'Tipo inválido.', 1;
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'INCLUIR') = 0 AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'ALTERAR') = 0
            THROW 50001, N'Você não tem permissão para lançar.', 1;
        IF NOT EXISTS (SELECT 1 FROM CAD.Pessoa p WITH (NOLOCK) WHERE p.ID_PESSOA = @IdPessoa)
            THROW 50001, N'Parceiro não encontrado.', 1;

        SET @EtapaAtual = 'Padrão do parceiro';
        SELECT @Plano  = CASE WHEN v.ATIVO_EFETIVO = 1 AND pc.DT_EXCLUSAO IS NULL THEN p.ID_PLANO_CONTA_PADRAO END,
               @Centro = CASE WHEN cc.ATIVO = 1 AND cc.DT_EXCLUSAO IS NULL THEN p.ID_CENTRO_CUSTO_PADRAO END
        FROM CAD.Pessoa p WITH (NOLOCK)
        LEFT JOIN CAD.vw_CAD_Plano_Conta v  ON v.ID_PLANO_CONTA = p.ID_PLANO_CONTA_PADRAO
        LEFT JOIN CAD.Plano_Conta pc        WITH (NOLOCK) ON pc.ID_PLANO_CONTA = p.ID_PLANO_CONTA_PADRAO
        LEFT JOIN CAD.Centro_Custo cc       WITH (NOLOCK) ON cc.ID_CENTRO_CUSTO = p.ID_CENTRO_CUSTO_PADRAO
        WHERE p.ID_PESSOA = @IdPessoa;

        IF @Plano  IS NOT NULL SET @OrigemPlano  = 'PARCEIRO';
        IF @Centro IS NOT NULL SET @OrigemCentro = 'PARCEIRO';

        SET @EtapaAtual = 'Último lançamento';
        IF @Plano IS NULL
        BEGIN
            SELECT TOP 1 @Plano = l.ID_PLANO_CONTA
            FROM FIN.Lancamento l WITH (NOLOCK)
            INNER JOIN CAD.vw_CAD_Plano_Conta v ON v.ID_PLANO_CONTA = l.ID_PLANO_CONTA AND v.ATIVO_EFETIVO = 1
            INNER JOIN CAD.Plano_Conta pc WITH (NOLOCK) ON pc.ID_PLANO_CONTA = l.ID_PLANO_CONTA AND pc.DT_EXCLUSAO IS NULL
            WHERE l.ID_PESSOA = @IdPessoa AND l.TIPO = @Tipo AND l.SITUACAO = 'ATIVO' AND l.DT_EXCLUSAO IS NULL
            ORDER BY l.DT_EMISSAO DESC, l.ID_LANCAMENTO DESC;
            IF @Plano IS NOT NULL SET @OrigemPlano = 'ULTIMO';
        END;

        IF @Centro IS NULL
        BEGIN
            SELECT TOP 1 @Centro = l.ID_CENTRO_CUSTO
            FROM FIN.Lancamento l WITH (NOLOCK)
            INNER JOIN CAD.Centro_Custo cc WITH (NOLOCK) ON cc.ID_CENTRO_CUSTO = l.ID_CENTRO_CUSTO AND cc.ATIVO = 1 AND cc.DT_EXCLUSAO IS NULL
                                                         AND (cc.DT_ENCERRAMENTO IS NULL OR cc.DT_ENCERRAMENTO > CONVERT(DATE, SYSDATETIME()))
            WHERE l.ID_PESSOA = @IdPessoa AND l.TIPO = @Tipo AND l.SITUACAO = 'ATIVO' AND l.DT_EXCLUSAO IS NULL
            ORDER BY l.DT_EMISSAO DESC, l.ID_LANCAMENTO DESC;
            IF @Centro IS NOT NULL SET @OrigemCentro = 'ULTIMO';
        END;

        SET @EtapaAtual = 'Consulta';
        SELECT @Plano AS ID_PLANO_CONTA, ISNULL(CONVERT(NVARCHAR(12), v.CODIGO), N'') AS PLANO_CODIGO, ISNULL(v.DESCRICAO, N'') AS PLANO_DESCRICAO,
               @OrigemPlano AS ORIGEM_PLANO,
               @Centro AS ID_CENTRO_CUSTO, ISNULL(CONVERT(NVARCHAR(20), cc.CODIGO), N'') AS CENTRO_CODIGO, ISNULL(cc.DESCRICAO, N'') AS CENTRO_DESCRICAO,
               @OrigemCentro AS ORIGEM_CENTRO,
               CAST(CASE WHEN (@Tipo = 'P' AND p.FORNECEDOR = 1) OR (@Tipo = 'R' AND p.CLIENTE = 1) THEN 1 ELSE 0 END AS BIT) AS TIPO_OK,
               p.ATIVO AS PARCEIRO_ATIVO
        FROM CAD.Pessoa p WITH (NOLOCK)
        LEFT JOIN CAD.vw_CAD_Plano_Conta v ON v.ID_PLANO_CONTA = @Plano
        LEFT JOIN CAD.Centro_Custo cc      WITH (NOLOCK) ON cc.ID_CENTRO_CUSTO = @Centro
        WHERE p.ID_PESSOA = @IdPessoa;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar as sugestões. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Resumo.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Resumo]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Contadores do topo das telas Contas a pagar (@Tipo P) e Contas
                a receber (@Tipo R): quantidade e saldo das parcelas em aberto
                vencidas, vencendo hoje, a vencer (de amanhã até
                FIN_LISTA_DIAS_A_VENCER dias) e o total em aberto. Respeita os
                filtros de empresa, centro, parceiro e conta do plano (não os
                de situação e período: cada contador é uma situação). Devolve
                também os parâmetros que a tela usa ao abrir (situação e visão
                iniciais, linhas por página, dias a vencer). Não conta o que
                está na lixeira. Permissão: VER em FIN_PAGAR / FIN_RECEBER.
                Padrão "Listar": THROW 50001.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f2a).
    v1.1 (26/11/2026) - Etapa 04f2c (P27): QTD_COM_PENDENCIA (lançamentos com
                        alguma pendência aberta, automática ou manual) e
                        QTD_MINHAS_PENDENCIAS (manuais com o usuário como
                        responsável), com os mesmos filtros.

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Resumo @IdUsuario = 2, @Tipo = 'R';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Resumo]
    @IdUsuario      INT,
    @Tipo           CHAR(1),
    @IdEmpresa      INT = NULL,
    @IdCentroCusto  INT = NULL,
    @IdPessoa       INT = NULL,
    @IdPlanoConta   INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Resumo]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Permissão';
    DECLARE @Hoje        DATE = CONVERT(DATE, SYSDATETIME());
    DECLARE @DiasAVencer INT;
    DECLARE @Limite      DATE;
    DECLARE @PorPagina   INT;
    DECLARE @SitInicial  NVARCHAR(20);
    DECLARE @VisInicial  NVARCHAR(20);
    DECLARE @QtdPend     INT = 0;
    DECLARE @QtdMinhas   INT = 0;

    BEGIN TRY
        SET @Tipo = UPPER(LTRIM(RTRIM(ISNULL(@Tipo, ''))));
        IF @Tipo NOT IN ('P', 'R')
            THROW 50001, N'Tipo inválido.', 1;
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver estes lançamentos.', 1;

        SET @EtapaAtual  = 'Parâmetros';
        SET @DiasAVencer = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_LISTA_DIAS_A_VENCER'), 7);
        IF @DiasAVencer NOT BETWEEN 1 AND 365 SET @DiasAVencer = 7;
        SET @Limite      = DATEADD(DAY, @DiasAVencer, @Hoje);
        SET @PorPagina   = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_LISTA_POR_PAGINA'), 100);
        IF @PorPagina NOT BETWEEN 10 AND 1000 SET @PorPagina = 100;
        SET @SitInicial  = UPPER(ISNULL(SIS.fn_SIS_Parametro('FIN_LISTA_SITUACAO_INICIAL'), N'EM_ABERTO'));
        IF @SitInicial NOT IN (N'EM_ABERTO', N'VENCIDA', N'HOJE', N'A_VENCER', N'TODAS') SET @SitInicial = N'EM_ABERTO';
        SET @VisInicial  = UPPER(ISNULL(SIS.fn_SIS_Parametro('FIN_LISTA_VISAO_INICIAL'), N'PARCELA'));
        IF @VisInicial NOT IN (N'PARCELA', N'LANCAMENTO') SET @VisInicial = N'PARCELA';

        SET @EtapaAtual = 'Pendências';
        SELECT @QtdPend   = COUNT(DISTINCT l.ID_LANCAMENTO),
               @QtdMinhas = COUNT(DISTINCT CASE WHEN pd.ORIGEM = 'MANUAL' AND pd.ID_USUARIO_RESPONSAVEL = @IdUsuario THEN l.ID_LANCAMENTO END)
        FROM FIN.Lancamento l WITH (NOLOCK)
        CROSS APPLY FIN.fn_FIN_Lancamento_Pendencias(l.ID_LANCAMENTO) pd
        WHERE l.DT_EXCLUSAO IS NULL
          AND l.TIPO = @Tipo
          AND l.SITUACAO = 'ATIVO'
          AND (EXISTS (SELECT 1 FROM FIN.Parcela p2 WITH (NOLOCK) WHERE p2.ID_LANCAMENTO = l.ID_LANCAMENTO AND p2.SITUACAO IN ('ABERTA', 'PARCIAL'))
               OR EXISTS (SELECT 1 FROM FIN.Lancamento_Pendencia x WITH (NOLOCK) WHERE x.ID_LANCAMENTO = l.ID_LANCAMENTO AND x.SITUACAO = 'ABERTA' AND x.ATIVO = 1))
          AND (@IdEmpresa     IS NULL OR l.ID_EMPRESA = @IdEmpresa)
          AND (@IdCentroCusto IS NULL OR l.ID_CENTRO_CUSTO = @IdCentroCusto)
          AND (@IdPessoa      IS NULL OR l.ID_PESSOA = @IdPessoa)
          AND (@IdPlanoConta  IS NULL OR l.ID_PLANO_CONTA = @IdPlanoConta)
        OPTION (RECOMPILE);

        SET @EtapaAtual = 'Consulta';
        SELECT CAST(ISNULL(SUM(CASE WHEN p.DT_VENCIMENTO < @Hoje THEN 1 ELSE 0 END), 0) AS INT)                                        AS QTD_VENCIDAS,
               CAST(ISNULL(SUM(CASE WHEN p.DT_VENCIMENTO < @Hoje THEN p.SALDO ELSE 0 END), 0) AS DECIMAL(18,2))                        AS VALOR_VENCIDAS,
               CAST(ISNULL(SUM(CASE WHEN p.DT_VENCIMENTO = @Hoje THEN 1 ELSE 0 END), 0) AS INT)                                        AS QTD_HOJE,
               CAST(ISNULL(SUM(CASE WHEN p.DT_VENCIMENTO = @Hoje THEN p.SALDO ELSE 0 END), 0) AS DECIMAL(18,2))                        AS VALOR_HOJE,
               CAST(ISNULL(SUM(CASE WHEN p.DT_VENCIMENTO > @Hoje AND p.DT_VENCIMENTO <= @Limite THEN 1 ELSE 0 END), 0) AS INT)         AS QTD_A_VENCER,
               CAST(ISNULL(SUM(CASE WHEN p.DT_VENCIMENTO > @Hoje AND p.DT_VENCIMENTO <= @Limite THEN p.SALDO ELSE 0 END), 0) AS DECIMAL(18,2)) AS VALOR_A_VENCER,
               CAST(COUNT(*) AS INT)                                                                                                   AS QTD_EM_ABERTO,
               CAST(ISNULL(SUM(p.SALDO), 0) AS DECIMAL(18,2))                                                                          AS VALOR_EM_ABERTO,
               @DiasAVencer                                                                                                            AS DIAS_A_VENCER,
               @PorPagina                                                                                                              AS POR_PAGINA,
               CAST(@SitInicial AS VARCHAR(12))                                                                                        AS SITUACAO_INICIAL,
               CAST(@VisInicial AS VARCHAR(12))                                                                                        AS VISAO_INICIAL,
               ISNULL(@QtdPend, 0)                                                                                                     AS QTD_COM_PENDENCIA,
               ISNULL(@QtdMinhas, 0)                                                                                                   AS QTD_MINHAS_PENDENCIAS
        FROM FIN.Parcela p WITH (NOLOCK)
        INNER JOIN FIN.Lancamento l WITH (NOLOCK) ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
        WHERE l.DT_EXCLUSAO IS NULL
          AND l.TIPO = @Tipo
          AND p.SITUACAO IN ('ABERTA', 'PARCIAL')
          AND (@IdEmpresa     IS NULL OR l.ID_EMPRESA = @IdEmpresa)
          AND (@IdCentroCusto IS NULL OR l.ID_CENTRO_CUSTO = @IdCentroCusto)
          AND (@IdPessoa      IS NULL OR l.ID_PESSOA = @IdPessoa)
          AND (@IdPlanoConta  IS NULL OR l.ID_PLANO_CONTA = @IdPlanoConta)
        OPTION (RECOMPILE);
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar o resumo dos lançamentos. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Filtro_Salvo_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Filtro_Salvo_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Filtros salvos do próprio usuário numa tela (@Item = código da
                tela em SIS.Item, ex.: FIN_RECEBER), o padrão primeiro e depois
                por nome. Permissão: VER na tela. Padrão "Listar": THROW 50001.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f2a).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Filtro_Salvo_Listar @IdUsuario = 2, @Item = 'FIN_RECEBER';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Filtro_Salvo_Listar]
    @IdUsuario  INT,
    @Item       VARCHAR(40)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Filtro_Salvo_Listar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';

    BEGIN TRY
        SET @Item = UPPER(LTRIM(RTRIM(ISNULL(@Item, ''))));
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver esta tela.', 1;

        SET @EtapaAtual = 'Consulta';
        SELECT f.ID_FILTRO_SALVO, f.NOME, f.FILTRO, f.PADRAO
        FROM SIS.Filtro_Salvo f
        WHERE f.ID_USUARIO = @IdUsuario
          AND f.ITEM = @Item
        ORDER BY f.PADRAO DESC, f.NOME;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar os filtros salvos. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Filtro_Salvo_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Filtro_Salvo_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Salva um filtro da lista para o próprio usuário. Nome que já
                existe na mesma tela é substituído (salvar de novo atualiza).
                @Padrao = 1 marca como o filtro com que a lista abre e tira a
                marca dos outros da mesma tela. Limite de filtros por usuário
                e tela no parâmetro FILTRO_SALVO_MAX. Permissão: VER na tela.
                Devolve 1 linha: SUCESSO, MENSAGEM, ID_FILTRO_SALVO.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f2a).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Filtro_Salvo_Gravar @IdUsuario = 2, @Item = 'FIN_RECEBER', @Nome = N'Vencidos', @Filtro = N'{"situacao":"VENCIDA"}', @Padrao = 0;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Filtro_Salvo_Gravar]
    @IdUsuario  INT,
    @Item       VARCHAR(40),
    @Nome       NVARCHAR(60),
    @Filtro     NVARCHAR(MAX),
    @Padrao     BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Filtro_Salvo_Gravar]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Id         INT;
    DECLARE @Max        INT;
    DECLARE @Usuario    NVARCHAR(100);

    BEGIN TRY
        SET @Item   = UPPER(LTRIM(RTRIM(ISNULL(@Item, ''))));
        SET @Nome   = LTRIM(RTRIM(ISNULL(@Nome, N'')));
        SET @Filtro = LTRIM(RTRIM(ISNULL(@Filtro, N'')));
        SET @Padrao = ISNULL(@Padrao, 0);

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'VER') = 0
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Você não tem permissão para ver esta tela.' AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS INT) AS ID_FILTRO_SALVO;
            RETURN;
        END;
        IF @Nome = N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Informe um nome para o filtro.' AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS INT) AS ID_FILTRO_SALVO;
            RETURN;
        END;
        IF LEN(@Filtro) > 2000 OR ISJSON(@Filtro) = 0
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Filtro inválido.' AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS INT) AS ID_FILTRO_SALVO;
            RETURN;
        END;

        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        SET @Max     = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FILTRO_SALVO_MAX'), 20);

        SET @EtapaAtual = 'Limite';
        SELECT @Id = f.ID_FILTRO_SALVO
        FROM SIS.Filtro_Salvo f
        WHERE f.ID_USUARIO = @IdUsuario AND f.ITEM = @Item AND f.NOME = @Nome;

        IF @Id IS NULL AND (SELECT COUNT(*) FROM SIS.Filtro_Salvo f WHERE f.ID_USUARIO = @IdUsuario AND f.ITEM = @Item) >= @Max
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO,
                   CAST(N'Você já tem ' + CONVERT(NVARCHAR(10), @Max) + N' filtros salvos nesta tela. Apague um antes de salvar outro.' AS NVARCHAR(400)) AS MENSAGEM,
                   CAST(NULL AS INT) AS ID_FILTRO_SALVO;
            RETURN;
        END;

        -- preferência do próprio usuário (só ele grava): sem disputa entre sessões
        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

            IF @Padrao = 1
                UPDATE f
                   SET f.PADRAO = 0, f.DT_ALTERACAO = SYSDATETIME(), f.USUARIO_ALTERACAO = @Usuario
                FROM SIS.Filtro_Salvo f
                WHERE f.ID_USUARIO = @IdUsuario AND f.ITEM = @Item AND f.PADRAO = 1
                  AND (@Id IS NULL OR f.ID_FILTRO_SALVO <> @Id);

            IF @Id IS NULL
            BEGIN
                INSERT INTO SIS.Filtro_Salvo (ID_USUARIO, ITEM, NOME, FILTRO, PADRAO, USUARIO_CRIACAO)
                VALUES (@IdUsuario, @Item, @Nome, @Filtro, @Padrao, @Usuario);
                SET @Id = SCOPE_IDENTITY();
            END
            ELSE
                UPDATE f
                   SET f.FILTRO = @Filtro, f.PADRAO = @Padrao, f.DT_ALTERACAO = SYSDATETIME(), f.USUARIO_ALTERACAO = @Usuario
                FROM SIS.Filtro_Salvo f
                WHERE f.ID_FILTRO_SALVO = @Id;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Filtro salvo.' AS NVARCHAR(400)) AS MENSAGEM, @Id AS ID_FILTRO_SALVO;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO,
               CAST(N'Não foi possível salvar o filtro. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(NULL AS INT) AS ID_FILTRO_SALVO;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Filtro_Salvo_Excluir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Filtro_Salvo_Excluir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Apaga um filtro salvo do próprio usuário (filtro de outro
                usuário não é encontrado). Preferência de uso: apaga de vez,
                sem lixeira. Devolve 1 linha: SUCESSO, MENSAGEM, ID_FILTRO_SALVO.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f2a).

  Homologação (LOCAL):
    -- EXEC SIS.SIS_Filtro_Salvo_Excluir @IdUsuario = 2, @IdFiltroSalvo = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Filtro_Salvo_Excluir]
    @IdUsuario      INT,
    @IdFiltroSalvo  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Filtro_Salvo_Excluir]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Exclusão';

    BEGIN TRY
        DELETE f
        FROM SIS.Filtro_Salvo f
        WHERE f.ID_FILTRO_SALVO = @IdFiltroSalvo
          AND f.ID_USUARIO = @IdUsuario;

        IF @@ROWCOUNT = 0
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Filtro não encontrado.' AS NVARCHAR(400)) AS MENSAGEM, @IdFiltroSalvo AS ID_FILTRO_SALVO;
            RETURN;
        END;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Filtro apagado.' AS NVARCHAR(400)) AS MENSAGEM, @IdFiltroSalvo AS ID_FILTRO_SALVO;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO,
               CAST(N'Não foi possível apagar o filtro. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               @IdFiltroSalvo AS ID_FILTRO_SALVO;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Pendencia_Tipo_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Pendencia_Tipo_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : P27 - tipos de pendência (tela Financeiro › Tipos de
                pendência e escolha do tipo na ficha do lançamento).
                @Tipo P/R: só os tipos que valem para contas a pagar ou a
                receber (APLICA_A = @Tipo ou A). Não lista o que está na
                lixeira. QTD_ABERTAS: pendências abertas do tipo.
                Permissão: VER em FIN_PENDENCIA_TIPO, FIN_PAGAR ou FIN_RECEBER.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2c).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Pendencia_Tipo_Listar @IdUsuario = 2;
    -- EXEC FIN.FIN_Pendencia_Tipo_Listar @IdUsuario = 2, @Tipo = 'R', @SomenteAtivos = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Pendencia_Tipo_Listar]
    @IdUsuario      INT,
    @Busca          NVARCHAR(60) = NULL,
    @SomenteAtivos  BIT          = 0,
    @Tipo           CHAR(1)      = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PENDENCIA_TIPO', 'VER') = 0
       AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PAGAR', 'VER') = 0
       AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_RECEBER', 'VER') = 0
    BEGIN
        SELECT TOP (0) CAST(NULL AS INT) AS ID_PENDENCIA_TIPO;
        RETURN;
    END;

    SET @Busca = NULLIF(LTRIM(RTRIM(ISNULL(@Busca, N''))), N'');
    SET @Tipo  = NULLIF(UPPER(ISNULL(@Tipo, '')), '');

    SELECT t.ID_PENDENCIA_TIPO, t.CODIGO, t.DESCRICAO, t.ORIENTACAO, t.APLICA_A, t.BLOQUEIA_BAIXA, t.SISTEMA, t.ORDEM, t.ATIVO,
           ISNULL(q.QTD, 0) AS QTD_ABERTAS
    FROM FIN.Pendencia_Tipo t WITH (NOLOCK)
    OUTER APPLY (SELECT COUNT(*) AS QTD
                 FROM FIN.Lancamento_Pendencia lp WITH (NOLOCK)
                 WHERE lp.ID_PENDENCIA_TIPO = t.ID_PENDENCIA_TIPO AND lp.SITUACAO = 'ABERTA' AND lp.ATIVO = 1) q
    WHERE t.DT_EXCLUSAO IS NULL
      AND (@SomenteAtivos = 0 OR t.ATIVO = 1)
      AND (@Tipo IS NULL OR t.APLICA_A IN ('A', @Tipo))
      AND (@Busca IS NULL OR t.DESCRICAO LIKE N'%' + @Busca + N'%' OR t.CODIGO LIKE @Busca + '%')
    ORDER BY t.ORDEM, t.DESCRICAO;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Pendencia_Tipo_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Pendencia_Tipo_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : P27 - inclui ou altera um tipo de pendência (@IdPendenciaTipo
                NULL = novo). Tipo do sistema (MIGRACAO): código não muda e
                não pode ser desativado; descrição, orientação, onde vale e o
                bloqueio da baixa podem. Desativar: o tipo some da escolha,
                as pendências já lançadas continuam valendo.
                Permissão: INCLUIR / ALTERAR em FIN_PENDENCIA_TIPO e DESATIVAR
                para mudar o ativo. Excluir = lixeira (SIS_Lixeira_Excluir).
                Devolve SUCESSO, MENSAGEM, ID.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2c).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Pendencia_Tipo_Gravar @IdUsuario = 2, @Codigo = 'TESTE', @Descricao = N'Teste', @AplicaA = 'A', @BloqueiaBaixa = 0;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Pendencia_Tipo_Gravar]
    @IdUsuario        INT,
    @IdPendenciaTipo  INT            = NULL,
    @Codigo           VARCHAR(20),
    @Descricao        NVARCHAR(60),
    @Orientacao       NVARCHAR(400)  = NULL,
    @AplicaA          CHAR(1)        = 'A',
    @BloqueiaBaixa    BIT            = 0,
    @Ordem            INT            = NULL,
    @Ativo            BIT            = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[FIN].[FIN_Pendencia_Tipo_Gravar]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Validação';
    DECLARE @Recusa      NVARCHAR(400) = N'';
    DECLARE @Usuario     NVARCHAR(100) = SIS.fn_SIS_Usuario_Login(@IdUsuario);
    DECLARE @Sistema     BIT           = 0;
    DECLARE @CodigoAtual VARCHAR(20);
    DECLARE @AtivoAtual  BIT;
    DECLARE @Abertas     INT           = 0;

    BEGIN TRY
        SET @Codigo        = UPPER(LTRIM(RTRIM(ISNULL(@Codigo, ''))));
        SET @Descricao     = LTRIM(RTRIM(ISNULL(@Descricao, N'')));
        SET @Orientacao    = LTRIM(RTRIM(ISNULL(@Orientacao, N'')));
        SET @AplicaA       = UPPER(ISNULL(@AplicaA, 'A'));
        SET @BloqueiaBaixa = ISNULL(@BloqueiaBaixa, 0);
        SET @Ativo         = ISNULL(@Ativo, 1);

        SELECT @Sistema = t.SISTEMA, @CodigoAtual = t.CODIGO, @AtivoAtual = t.ATIVO
        FROM FIN.Pendencia_Tipo t WHERE t.ID_PENDENCIA_TIPO = @IdPendenciaTipo;

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PENDENCIA_TIPO', CASE WHEN @IdPendenciaTipo IS NULL THEN 'INCLUIR' ELSE 'ALTERAR' END) = 0
            SET @Recusa = N'Você não tem permissão para gravar tipos de pendência.';
        IF @Recusa = N'' AND @IdPendenciaTipo IS NOT NULL AND @CodigoAtual IS NULL
            SET @Recusa = N'Tipo de pendência não encontrado.';
        IF @Recusa = N'' AND @IdPendenciaTipo IS NOT NULL AND SIS.fn_SIS_Na_Lixeira(N'FIN.Pendencia_Tipo', @IdPendenciaTipo) = 1
            SET @Recusa = N'O registro está na lixeira: recupere-o antes de alterar (Sistema › Lixeira).';
        IF @Recusa = N'' AND @Sistema = 1 AND @Codigo <> @CodigoAtual
            SET @Recusa = N'O código de um tipo do sistema não pode ser mudado.';
        IF @Recusa = N'' AND @Sistema = 1 AND @Ativo = 0
            SET @Recusa = N'Um tipo do sistema não pode ser desativado.';
        IF @Recusa = N'' AND (@Codigo = '' OR @Codigo LIKE '%[^A-Z0-9_]%' COLLATE Latin1_General_BIN2)
            SET @Recusa = N'Código inválido: use letras sem acento, números e "_" (ex.: AGUARDA_MEDICAO).';
        IF @Recusa = N'' AND @Descricao = N''
            SET @Recusa = N'Informe a descrição.';
        IF @Recusa = N'' AND @AplicaA NOT IN ('P', 'R', 'A')
            SET @Recusa = N'Escolha onde o tipo vale: contas a pagar, a receber ou ambos.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM FIN.Pendencia_Tipo t WHERE t.CODIGO = @Codigo AND t.ID_PENDENCIA_TIPO <> ISNULL(@IdPendenciaTipo, 0))
            SET @Recusa = N'Já existe um tipo de pendência com este código (confira também a lixeira).';
        IF @Recusa = N'' AND @IdPendenciaTipo IS NOT NULL AND @Ativo <> @AtivoAtual
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PENDENCIA_TIPO', 'DESATIVAR') = 0
            SET @Recusa = N'Você não tem permissão para desativar ou reativar tipos de pendência.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdPendenciaTipo AS ID;
            RETURN;
        END;

        IF @IdPendenciaTipo IS NOT NULL AND @Ativo = 0 AND @AtivoAtual = 1
            SELECT @Abertas = COUNT(*) FROM FIN.Lancamento_Pendencia x
            WHERE x.ID_PENDENCIA_TIPO = @IdPendenciaTipo AND x.SITUACAO = 'ABERTA' AND x.ATIVO = 1;

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        IF @IdPendenciaTipo IS NULL
        BEGIN
            INSERT INTO FIN.Pendencia_Tipo (CODIGO, DESCRICAO, ORIENTACAO, APLICA_A, BLOQUEIA_BAIXA, SISTEMA, ORDEM, ATIVO, USUARIO_CRIACAO)
            VALUES (@Codigo, @Descricao, @Orientacao, @AplicaA, @BloqueiaBaixa, 0, ISNULL(@Ordem, 100), @Ativo, ISNULL(@Usuario, N''));
            SET @IdPendenciaTipo = SCOPE_IDENTITY();
        END
        ELSE
            UPDATE FIN.Pendencia_Tipo
               SET CODIGO = @Codigo, DESCRICAO = @Descricao, ORIENTACAO = @Orientacao, APLICA_A = @AplicaA,
                   BLOQUEIA_BAIXA = @BloqueiaBaixa, ORDEM = ISNULL(@Ordem, ORDEM), ATIVO = @Ativo,
                   DT_ALTERACAO = SYSDATETIME(), USUARIO_ALTERACAO = @Usuario
             WHERE ID_PENDENCIA_TIPO = @IdPendenciaTipo;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(N'Tipo de pendência gravado.'
                    + CASE WHEN @Abertas > 0 THEN N' Atenção: ' + CONVERT(NVARCHAR(10), @Abertas)
                                + N' pendência(s) abertas continuam com este tipo; ele só não aparece mais para novas pendências.' ELSE N'' END
                    AS NVARCHAR(400)) AS MENSAGEM,
               @IdPendenciaTipo AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar o tipo de pendência. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, @IdPendenciaTipo AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Pendencia_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Pendencia_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : P27 - quadro de pendências da ficha do lançamento: as
                automáticas (calculadas na hora, FIN.fn_FIN_Lancamento_Pendencias)
                e as manuais ativas (abertas e, com @IncluirResolvidas = 1,
                também as resolvidas). Ordem: manuais abertas (por
                previsão), automáticas e, por último, as resolvidas.
                PODE_ALTERAR = 1 na manual aberta quando o usuário tem a ação
                PENDENCIA; PODE_REABRIR na resolvida.
                Permissão: VER em FIN_PAGAR / FIN_RECEBER (conforme o tipo).
                Padrão "Listar": THROW 50001.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2c).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Pendencia_Listar @IdUsuario = 2, @IdLancamento = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Pendencia_Listar]
    @IdUsuario          INT,
    @IdLancamento       BIGINT,
    @IncluirResolvidas  BIT = 1
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Tipo  CHAR(1);
    DECLARE @Item  VARCHAR(40);
    DECLARE @Pode  BIT;

    SELECT @Tipo = l.TIPO FROM FIN.Lancamento l WITH (NOLOCK) WHERE l.ID_LANCAMENTO = @IdLancamento;
    SET @Item = CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END;

    IF @Tipo IS NULL OR SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'VER') = 0
        THROW 50001, N'Você não tem permissão para ver este lançamento.', 1;

    SET @Pode = CASE WHEN SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'PENDENCIA') = 1
                      AND SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', @IdLancamento) = 0 THEN 1 ELSE 0 END;

    SELECT x.ID_LANCAMENTO_PENDENCIA, x.ORIGEM, x.CODIGO, x.DESCRICAO, x.ORIENTACAO, x.SITUACAO, x.BLOQUEIA_BAIXA, x.ATRASADA,
           x.ID_PENDENCIA_TIPO, x.ID_PARCELA, x.PARCELA, x.OBSERVACAO, x.ID_USUARIO_RESPONSAVEL, x.RESPONSAVEL, x.DT_PREVISAO,
           x.DT_RESOLUCAO, x.USUARIO_RESOLUCAO, x.RESOLUCAO, x.DT_CRIACAO, x.USUARIO_CRIACAO,
           CAST(CASE WHEN x.ORIGEM = 'MANUAL' AND x.SITUACAO = 'ABERTA' THEN @Pode ELSE 0 END AS BIT) AS PODE_ALTERAR,
           CAST(CASE WHEN x.ORIGEM = 'MANUAL' AND x.SITUACAO = 'RESOLVIDA' THEN @Pode ELSE 0 END AS BIT) AS PODE_REABRIR
    FROM (
        SELECT CAST(NULL AS BIGINT) AS ID_LANCAMENTO_PENDENCIA, f.ORIGEM, f.CODIGO, f.DESCRICAO, f.ORIENTACAO,
               CAST('ABERTA' AS VARCHAR(10)) AS SITUACAO, f.BLOQUEIA_BAIXA, f.ATRASADA, f.ID_PENDENCIA_TIPO,
               f.ID_PARCELA, ISNULL(CONVERT(NVARCHAR(5), p.NUMERO) + N'/' + CONVERT(NVARCHAR(5), p.QTD_PARCELAS), N'') AS PARCELA,
               CAST(N'' AS NVARCHAR(1000)) AS OBSERVACAO, CAST(NULL AS INT) AS ID_USUARIO_RESPONSAVEL, CAST(N'' AS NVARCHAR(100)) AS RESPONSAVEL,
               CAST(NULL AS DATE) AS DT_PREVISAO, CAST(NULL AS DATETIME2(0)) AS DT_RESOLUCAO, CAST(N'' AS NVARCHAR(100)) AS USUARIO_RESOLUCAO,
               CAST(N'' AS NVARCHAR(1000)) AS RESOLUCAO, CAST(NULL AS DATETIME2(0)) AS DT_CRIACAO, CAST(N'' AS NVARCHAR(100)) AS USUARIO_CRIACAO,
               1 AS ORDEM_GRUPO
        FROM FIN.fn_FIN_Lancamento_Pendencias(@IdLancamento) f
        LEFT JOIN FIN.Parcela p WITH (NOLOCK) ON p.ID_PARCELA = f.ID_PARCELA
        WHERE f.ORIGEM = 'AUTOMATICA'

        UNION ALL
        SELECT lp.ID_LANCAMENTO_PENDENCIA, CAST('MANUAL' AS VARCHAR(10)), t.CODIGO, t.DESCRICAO, t.ORIENTACAO,
               lp.SITUACAO, t.BLOQUEIA_BAIXA,
               CAST(CASE WHEN lp.SITUACAO = 'ABERTA' AND lp.DT_PREVISAO < CAST(SYSDATETIME() AS DATE) THEN 1 ELSE 0 END AS BIT),
               lp.ID_PENDENCIA_TIPO, lp.ID_PARCELA,
               ISNULL(CONVERT(NVARCHAR(5), p.NUMERO) + N'/' + CONVERT(NVARCHAR(5), p.QTD_PARCELAS), N''),
               lp.OBSERVACAO, lp.ID_USUARIO_RESPONSAVEL, ISNULL(u.NOME, N''), lp.DT_PREVISAO,
               lp.DT_RESOLUCAO, ISNULL(lp.USUARIO_RESOLUCAO, N''), lp.RESOLUCAO, lp.DT_CRIACAO, lp.USUARIO_CRIACAO,
               CASE WHEN lp.SITUACAO = 'ABERTA' THEN 0 ELSE 2 END
        FROM FIN.Lancamento_Pendencia lp WITH (NOLOCK)
        INNER JOIN FIN.Pendencia_Tipo t WITH (NOLOCK) ON t.ID_PENDENCIA_TIPO = lp.ID_PENDENCIA_TIPO
        LEFT JOIN FIN.Parcela p WITH (NOLOCK) ON p.ID_PARCELA = lp.ID_PARCELA
        LEFT JOIN SIS.Usuario u WITH (NOLOCK) ON u.ID_USUARIO = lp.ID_USUARIO_RESPONSAVEL
        WHERE lp.ID_LANCAMENTO = @IdLancamento
          AND lp.ATIVO = 1
          AND (lp.SITUACAO = 'ABERTA' OR ISNULL(@IncluirResolvidas, 1) = 1)
    ) x
    ORDER BY x.ORDEM_GRUPO, CASE WHEN x.DT_PREVISAO IS NULL THEN 1 ELSE 0 END, x.DT_PREVISAO, x.DT_RESOLUCAO DESC, x.CODIGO;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Pendencia_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Pendencia_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : P27 - inclui (@IdLancamentoPendencia NULL) ou altera uma
                pendência manual do lançamento: tipo, parcela (opcional),
                observação, responsável e previsão. @Ativo = 0: desativa a
                pendência lançada por engano (não conta mais em lugar
                nenhum; o histórico guarda).
                Regras: lançamento ativo e fora da lixeira; tipo ativo e que
                vale para o tipo do lançamento (a pagar / a receber); parcela
                do próprio lançamento; responsável = usuário ativo; uma só
                pendência aberta do mesmo tipo por lançamento e parcela;
                pendência resolvida não é alterada (reabrir antes).
                Permissão: PENDENCIA em FIN_PAGAR / FIN_RECEBER.
                Devolve SUCESSO, MENSAGEM, ID.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2c).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Pendencia_Gravar @IdUsuario = 2, @IdLancamento = 1, @IdPendenciaTipo = 1, @Observacao = N'NF 123';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Pendencia_Gravar]
    @IdUsuario              INT,
    @IdLancamentoPendencia  BIGINT          = NULL,
    @IdLancamento           BIGINT,
    @IdParcela              BIGINT          = NULL,
    @IdPendenciaTipo        INT,
    @Observacao             NVARCHAR(1000)  = NULL,
    @IdUsuarioResponsavel   INT             = NULL,
    @DtPrevisao             DATE            = NULL,
    @Ativo                  BIT             = 1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc      NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Pendencia_Gravar]';
    DECLARE @EtapaAtual    VARCHAR(100)  = 'Validação';
    DECLARE @Recusa        NVARCHAR(400) = N'';
    DECLARE @Usuario       NVARCHAR(100) = SIS.fn_SIS_Usuario_Login(@IdUsuario);
    DECLARE @TipoLanc      CHAR(1);
    DECLARE @SituacaoLanc  VARCHAR(10);
    DECLARE @AplicaA       CHAR(1);
    DECLARE @TipoAtivo     BIT;
    DECLARE @TipoAtual     INT;
    DECLARE @LancAtual     BIGINT;
    DECLARE @SituacaoAtual VARCHAR(10);
    DECLARE @AtivoAtual    BIT;
    DECLARE @Linhas        INT;

    BEGIN TRY
        SET @Observacao = LTRIM(RTRIM(ISNULL(@Observacao, N'')));
        SET @Ativo      = ISNULL(@Ativo, 1);
        IF @IdUsuarioResponsavel = 0 SET @IdUsuarioResponsavel = NULL;
        IF @IdParcela = 0 SET @IdParcela = NULL;

        IF @IdLancamentoPendencia IS NOT NULL
            SELECT @LancAtual = lp.ID_LANCAMENTO, @SituacaoAtual = lp.SITUACAO, @AtivoAtual = lp.ATIVO, @TipoAtual = lp.ID_PENDENCIA_TIPO
            FROM FIN.Lancamento_Pendencia lp WHERE lp.ID_LANCAMENTO_PENDENCIA = @IdLancamentoPendencia;

        IF @IdLancamentoPendencia IS NOT NULL AND @IdLancamento IS NULL
            SET @IdLancamento = @LancAtual;

        SELECT @TipoLanc = l.TIPO, @SituacaoLanc = l.SITUACAO FROM FIN.Lancamento l WHERE l.ID_LANCAMENTO = @IdLancamento;
        SELECT @AplicaA = t.APLICA_A, @TipoAtivo = CASE WHEN t.ATIVO = 1 AND t.DT_EXCLUSAO IS NULL THEN 1 ELSE 0 END
        FROM FIN.Pendencia_Tipo t WHERE t.ID_PENDENCIA_TIPO = @IdPendenciaTipo;

        IF @TipoLanc IS NULL
            SET @Recusa = N'Lançamento não encontrado.';
        IF @Recusa = N'' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE @TipoLanc WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'PENDENCIA') = 0
            SET @Recusa = N'Você não tem permissão para lançar ou alterar pendências.';
        IF @Recusa = N'' AND @IdLancamentoPendencia IS NOT NULL AND (@LancAtual IS NULL OR @LancAtual <> @IdLancamento)
            SET @Recusa = N'Pendência não encontrada neste lançamento.';
        IF @Recusa = N'' AND SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', @IdLancamento) = 1
            SET @Recusa = N'O lançamento está na lixeira.';
        IF @Recusa = N'' AND @IdLancamentoPendencia IS NULL AND @SituacaoLanc = 'CANCELADO'
            SET @Recusa = N'O lançamento está cancelado.';
        IF @Recusa = N'' AND @IdLancamentoPendencia IS NOT NULL AND @AtivoAtual = 0
            SET @Recusa = N'Esta pendência foi desativada.';
        IF @Recusa = N'' AND @IdLancamentoPendencia IS NOT NULL AND @SituacaoAtual = 'RESOLVIDA'
            SET @Recusa = N'A pendência já está resolvida: reabra-a antes de alterar.';

        IF @Recusa = N'' AND @Ativo = 1
        BEGIN
            IF @AplicaA IS NULL
                SET @Recusa = N'Escolha o tipo da pendência.';
            IF @Recusa = N'' AND @TipoAtivo = 0 AND ISNULL(@TipoAtual, 0) <> @IdPendenciaTipo
                SET @Recusa = N'Este tipo de pendência está desativado.';
            IF @Recusa = N'' AND @AplicaA NOT IN ('A', @TipoLanc)
                SET @Recusa = CASE @TipoLanc WHEN 'P' THEN N'Este tipo de pendência vale só para contas a receber.'
                                             ELSE N'Este tipo de pendência vale só para contas a pagar.' END;
            IF @Recusa = N'' AND @IdParcela IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM FIN.Parcela p WHERE p.ID_PARCELA = @IdParcela AND p.ID_LANCAMENTO = @IdLancamento)
                SET @Recusa = N'A parcela escolhida não é deste lançamento.';
            IF @Recusa = N'' AND @IdUsuarioResponsavel IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM SIS.Usuario u WHERE u.ID_USUARIO = @IdUsuarioResponsavel AND u.ATIVO = 1)
                SET @Recusa = N'O responsável escolhido não é um usuário ativo.';
            IF @Recusa = N'' AND EXISTS (SELECT 1 FROM FIN.Lancamento_Pendencia x
                                         WHERE x.ID_LANCAMENTO = @IdLancamento AND x.ID_PENDENCIA_TIPO = @IdPendenciaTipo
                                           AND ISNULL(x.ID_PARCELA, 0) = ISNULL(@IdParcela, 0)
                                           AND x.SITUACAO = 'ABERTA' AND x.ATIVO = 1
                                           AND x.ID_LANCAMENTO_PENDENCIA <> ISNULL(@IdLancamentoPendencia, 0))
                SET @Recusa = N'Já existe uma pendência aberta deste tipo neste lançamento' + CASE WHEN @IdParcela IS NULL THEN N'.' ELSE N' e parcela.' END;
        END;

        IF @Recusa = N'' AND @Ativo = 0 AND @IdLancamentoPendencia IS NULL
            SET @Recusa = N'Pendência não encontrada.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdLancamentoPendencia AS ID;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        IF @IdLancamentoPendencia IS NULL
        BEGIN
            INSERT INTO FIN.Lancamento_Pendencia (ID_LANCAMENTO, ID_PARCELA, ID_PENDENCIA_TIPO, OBSERVACAO, ID_USUARIO_RESPONSAVEL, DT_PREVISAO,
                                                  SITUACAO, ORIGEM, ATIVO, USUARIO_CRIACAO)
            VALUES (@IdLancamento, @IdParcela, @IdPendenciaTipo, @Observacao, @IdUsuarioResponsavel, @DtPrevisao,
                    'ABERTA', 'MANUAL', 1, ISNULL(@Usuario, N''));
            SET @IdLancamentoPendencia = SCOPE_IDENTITY();
            SET @Linhas = 1;
        END
        ELSE IF @Ativo = 0
        BEGIN
            UPDATE FIN.Lancamento_Pendencia
               SET ATIVO = 0, DT_ALTERACAO = SYSDATETIME(), USUARIO_ALTERACAO = @Usuario
             WHERE ID_LANCAMENTO_PENDENCIA = @IdLancamentoPendencia AND ATIVO = 1 AND SITUACAO = 'ABERTA';
            SET @Linhas = @@ROWCOUNT;
        END
        ELSE
        BEGIN
            UPDATE FIN.Lancamento_Pendencia
               SET ID_PARCELA = @IdParcela, ID_PENDENCIA_TIPO = @IdPendenciaTipo, OBSERVACAO = @Observacao,
                   ID_USUARIO_RESPONSAVEL = @IdUsuarioResponsavel, DT_PREVISAO = @DtPrevisao,
                   DT_ALTERACAO = SYSDATETIME(), USUARIO_ALTERACAO = @Usuario
             WHERE ID_LANCAMENTO_PENDENCIA = @IdLancamentoPendencia AND ATIVO = 1 AND SITUACAO = 'ABERTA';
            SET @Linhas = @@ROWCOUNT;
        END;

        COMMIT TRANSACTION;

        SELECT CAST(CASE WHEN @Linhas = 1 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
               CAST(CASE WHEN @Linhas <> 1 THEN N'A pendência foi alterada por outra pessoa. Abra a ficha de novo.'
                         WHEN @Ativo = 0 THEN N'Pendência desativada.'
                         ELSE N'Pendência gravada.' END AS NVARCHAR(400)) AS MENSAGEM,
               @IdLancamentoPendencia AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar a pendência. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, @IdLancamentoPendencia AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Pendencia_Resolver.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Pendencia_Resolver]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : P27 - resolve uma pendência manual aberta, com a nota da
                resolução (obrigatória), quem e quando. Para voltar atrás:
                FIN_Lancamento_Pendencia_Reabrir.
                Permissão: PENDENCIA em FIN_PAGAR / FIN_RECEBER.
                Devolve SUCESSO, MENSAGEM, ID.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2c).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Pendencia_Resolver @IdUsuario = 2, @IdLancamentoPendencia = 1, @Resolucao = N'NF anexada';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Pendencia_Resolver]
    @IdUsuario              INT,
    @IdLancamentoPendencia  BIGINT,
    @Resolucao              NVARCHAR(1000)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Pendencia_Resolver]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Validação';
    DECLARE @Recusa     NVARCHAR(400) = N'';
    DECLARE @Usuario    NVARCHAR(100) = SIS.fn_SIS_Usuario_Login(@IdUsuario);
    DECLARE @TipoLanc   CHAR(1);
    DECLARE @IdLanc     BIGINT;
    DECLARE @Situacao   VARCHAR(10);
    DECLARE @Ativo      BIT;
    DECLARE @Linhas     INT;

    BEGIN TRY
        SET @Resolucao = LTRIM(RTRIM(ISNULL(@Resolucao, N'')));

        SELECT @IdLanc = lp.ID_LANCAMENTO, @Situacao = lp.SITUACAO, @Ativo = lp.ATIVO, @TipoLanc = l.TIPO
        FROM FIN.Lancamento_Pendencia lp
        INNER JOIN FIN.Lancamento l ON l.ID_LANCAMENTO = lp.ID_LANCAMENTO
        WHERE lp.ID_LANCAMENTO_PENDENCIA = @IdLancamentoPendencia;

        IF @IdLanc IS NULL OR @Ativo = 0
            SET @Recusa = N'Pendência não encontrada.';
        IF @Recusa = N'' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE @TipoLanc WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'PENDENCIA') = 0
            SET @Recusa = N'Você não tem permissão para resolver pendências.';
        IF @Recusa = N'' AND SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', @IdLanc) = 1
            SET @Recusa = N'O lançamento está na lixeira.';
        IF @Recusa = N'' AND @Situacao = 'RESOLVIDA'
            SET @Recusa = N'A pendência já está resolvida.';
        IF @Recusa = N'' AND LEN(@Resolucao) < 3
            SET @Recusa = N'Informe como a pendência foi resolvida.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdLancamentoPendencia AS ID;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        UPDATE FIN.Lancamento_Pendencia
           SET SITUACAO = 'RESOLVIDA', DT_RESOLUCAO = SYSDATETIME(), USUARIO_RESOLUCAO = @Usuario, RESOLUCAO = @Resolucao,
               DT_ALTERACAO = SYSDATETIME(), USUARIO_ALTERACAO = @Usuario
         WHERE ID_LANCAMENTO_PENDENCIA = @IdLancamentoPendencia AND SITUACAO = 'ABERTA' AND ATIVO = 1;
        SET @Linhas = @@ROWCOUNT;

        COMMIT TRANSACTION;

        SELECT CAST(CASE WHEN @Linhas = 1 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
               CAST(CASE WHEN @Linhas = 1 THEN N'Pendência resolvida.' ELSE N'A pendência foi alterada por outra pessoa. Abra a ficha de novo.' END AS NVARCHAR(400)) AS MENSAGEM,
               @IdLancamentoPendencia AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível resolver a pendência. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, @IdLancamentoPendencia AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Lancamento_Pendencia_Reabrir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Lancamento_Pendencia_Reabrir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : P27 - reabre uma pendência manual resolvida (volta a ABERTA e
                limpa a resolução; o histórico do lançamento guarda quem
                resolveu, quando e a nota). Lançamento cancelado ou na
                lixeira não reabre.
                Permissão: PENDENCIA em FIN_PAGAR / FIN_RECEBER.
                Devolve SUCESSO, MENSAGEM, ID.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2c).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Lancamento_Pendencia_Reabrir @IdUsuario = 2, @IdLancamentoPendencia = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Lancamento_Pendencia_Reabrir]
    @IdUsuario              INT,
    @IdLancamentoPendencia  BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[FIN].[FIN_Lancamento_Pendencia_Reabrir]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Validação';
    DECLARE @Recusa       NVARCHAR(400) = N'';
    DECLARE @Usuario      NVARCHAR(100) = SIS.fn_SIS_Usuario_Login(@IdUsuario);
    DECLARE @TipoLanc     CHAR(1);
    DECLARE @SituacaoLanc VARCHAR(10);
    DECLARE @IdLanc       BIGINT;
    DECLARE @IdTipo       INT;
    DECLARE @IdParcela    BIGINT;
    DECLARE @Situacao     VARCHAR(10);
    DECLARE @Ativo        BIT;
    DECLARE @Linhas       INT;

    BEGIN TRY
        SELECT @IdLanc = lp.ID_LANCAMENTO, @Situacao = lp.SITUACAO, @Ativo = lp.ATIVO, @IdTipo = lp.ID_PENDENCIA_TIPO,
               @IdParcela = lp.ID_PARCELA, @TipoLanc = l.TIPO, @SituacaoLanc = l.SITUACAO
        FROM FIN.Lancamento_Pendencia lp
        INNER JOIN FIN.Lancamento l ON l.ID_LANCAMENTO = lp.ID_LANCAMENTO
        WHERE lp.ID_LANCAMENTO_PENDENCIA = @IdLancamentoPendencia;

        IF @IdLanc IS NULL OR @Ativo = 0
            SET @Recusa = N'Pendência não encontrada.';
        IF @Recusa = N'' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE @TipoLanc WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'PENDENCIA') = 0
            SET @Recusa = N'Você não tem permissão para reabrir pendências.';
        IF @Recusa = N'' AND SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', @IdLanc) = 1
            SET @Recusa = N'O lançamento está na lixeira.';
        IF @Recusa = N'' AND @SituacaoLanc = 'CANCELADO'
            SET @Recusa = N'O lançamento está cancelado.';
        IF @Recusa = N'' AND @Situacao = 'ABERTA'
            SET @Recusa = N'A pendência já está aberta.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM FIN.Lancamento_Pendencia x
                                     WHERE x.ID_LANCAMENTO = @IdLanc AND x.ID_PENDENCIA_TIPO = @IdTipo
                                       AND ISNULL(x.ID_PARCELA, 0) = ISNULL(@IdParcela, 0)
                                       AND x.SITUACAO = 'ABERTA' AND x.ATIVO = 1)
            SET @Recusa = N'Já existe outra pendência aberta deste tipo neste lançamento.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdLancamentoPendencia AS ID;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        UPDATE FIN.Lancamento_Pendencia
           SET SITUACAO = 'ABERTA', DT_RESOLUCAO = NULL, USUARIO_RESOLUCAO = NULL, RESOLUCAO = N'',
               DT_ALTERACAO = SYSDATETIME(), USUARIO_ALTERACAO = @Usuario
         WHERE ID_LANCAMENTO_PENDENCIA = @IdLancamentoPendencia AND SITUACAO = 'RESOLVIDA' AND ATIVO = 1;
        SET @Linhas = @@ROWCOUNT;

        COMMIT TRANSACTION;

        SELECT CAST(CASE WHEN @Linhas = 1 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
               CAST(CASE WHEN @Linhas = 1 THEN N'Pendência reaberta.' ELSE N'A pendência foi alterada por outra pessoa. Abra a ficha de novo.' END AS NVARCHAR(400)) AS MENSAGEM,
               @IdLancamentoPendencia AS ID;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível reabrir a pendência. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM, @IdLancamentoPendencia AS ID;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Pendencia_Responsavel_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Pendencia_Responsavel_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : P27 - usuários que podem ser responsáveis por uma pendência
                (escolha na ficha do lançamento): ativos e não internos (o
                usuário de teste e o de consulta do Claude ficam de fora).
                Só ID, nome e login: nada de e-mail, perfil ou senha.
                Permissão: VER em FIN_PAGAR ou FIN_RECEBER.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2c).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Pendencia_Responsavel_Listar @IdUsuario = 2;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Pendencia_Responsavel_Listar]
    @IdUsuario  INT
AS
BEGIN
    SET NOCOUNT ON;

    IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PAGAR', 'VER') = 0
       AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_RECEBER', 'VER') = 0
    BEGIN
        SELECT TOP (0) CAST(NULL AS INT) AS ID_USUARIO, CAST(N'' AS NVARCHAR(100)) AS NOME, CAST('' AS VARCHAR(40)) AS LOGIN;
        RETURN;
    END;

    SELECT u.ID_USUARIO, u.NOME, u.LOGIN
    FROM SIS.Usuario u WITH (NOLOCK)
    WHERE u.ATIVO = 1
      AND u.INTERNO = 0
    ORDER BY u.NOME;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/SIS/SIS.SIS_Parametro_Conferir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [SIS].[SIS_Parametro_Conferir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : Prévia da tela de parâmetros, antes de gravar (etapa 04f2d):
                  PEDE_MOTIVO  1 = a troca afrouxa uma proteção
                               (SIS.fn_SIS_Parametro_Afrouxa): a tela pede o
                               motivo, que o SIS_Parametro_Gravar exige;
                  QTD_ATUAL /  só nos parâmetros de pendência (FIN_PEND_*):
                  QTD_NOVA     quantos lançamentos em aberto têm hoje a
                               pendência da regra e quantos passam a ter com
                               o valor novo (sugestão (a));
                  EFEITO       a frase pronta para a tela (vazio = nada a
                               mostrar).
                Não grava nada. O valor é conferido de leve (data dd/mm/aaaa
                ou aaaa-mm-dd, decimal com vírgula ou ponto); a conferência de
                verdade é do SIS_Parametro_Gravar.
                Permissão: a mesma da lista (VER em SIS_PARAMETRO, ou VER em
                SIS_PARAMETRO_USO para administrador nível 1 ou 2 nos de uso).
                Padrão "Listar": THROW 50001.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2d).
  Homologação (LOCAL):
    -- EXEC SIS.SIS_Parametro_Conferir @IdUsuario = 2, @Chave = 'FIN_PEND_PAGAR_SEM_ANEXO_VALOR', @Valor = N'500';
    -- EXEC SIS.SIS_Parametro_Conferir @IdUsuario = 2, @Chave = 'FIN_REGRA_DUPLIC_DOCUMENTO', @Valor = N'NAO';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [SIS].[SIS_Parametro_Conferir]
    @IdUsuario INT,
    @Chave     VARCHAR(60),
    @Valor     NVARCHAR(4000)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[SIS].[SIS_Parametro_Conferir]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Tipo       VARCHAR(10);
    DECLARE @Atual      NVARCHAR(4000);
    DECLARE @Nivel      TINYINT;
    DECLARE @Novo       NVARCHAR(4000);
    DECLARE @Codigo     VARCHAR(20);
    DECLARE @QtdAtual   INT;
    DECLARE @QtdNova    INT;
    DECLARE @Efeito     NVARCHAR(400) = N'';
    DECLARE @VeTodos    BIT;

    BEGIN TRY
        SET @VeTodos = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_PARAMETRO', 'VER');
        IF @VeTodos = 0
           AND (SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'SIS_PARAMETRO_USO', 'VER') = 0 OR SIS.fn_SIS_Usuario_Nivel_Admin(@IdUsuario) < 1)
            THROW 50001, N'Você não tem permissão para ver os parâmetros.', 1;

        SET @Chave = UPPER(LTRIM(RTRIM(ISNULL(@Chave, ''))));
        SELECT @Tipo = TIPO, @Atual = VALOR, @Nivel = NIVEL_MINIMO FROM SIS.Parametro WHERE CHAVE = @Chave;
        IF @Tipo IS NULL
            THROW 50001, N'Parâmetro não encontrado.', 1;
        IF @VeTodos = 0 AND @Nivel <> 1
            THROW 50001, N'Este parâmetro só pode ser visto pelo administrador geral.', 1;

        SET @EtapaAtual = 'Valor';
        SET @Novo = LTRIM(RTRIM(ISNULL(@Valor, N'')));
        IF @Tipo IN ('SN', 'TEXTO') SET @Novo = UPPER(@Novo);
        IF @Tipo = 'DECIMAL' SET @Novo = REPLACE(@Novo, N',', N'.');
        IF @Tipo = 'DATA' SET @Novo = ISNULL(CONVERT(NVARCHAR(10), ISNULL(TRY_CONVERT(DATE, @Novo, 103), TRY_CONVERT(DATE, @Novo, 23)), 23), @Novo);

        SET @Codigo = CASE @Chave
                          WHEN 'FIN_PEND_SEM_CENTRO'            THEN 'SEM_CENTRO'
                          WHEN 'FIN_PEND_SEM_PLANO'             THEN 'SEM_PLANO'
                          WHEN 'FIN_PEND_SEM_DOCUMENTO'         THEN 'SEM_DOCUMENTO'
                          WHEN 'FIN_PEND_PAGAR_SEM_ANEXO_VALOR' THEN 'SEM_ANEXO'
                          WHEN 'FIN_PEND_RECEBER_NAO_APTO'      THEN 'NAO_APTO'
                          WHEN 'FIN_PEND_VENCIDA_DIAS'          THEN 'VENCIDA'
                          WHEN 'FIN_PEND_A_PARTIR_DE'           THEN '*'
                      END;

        IF @Codigo IS NOT NULL AND @Novo <> ISNULL(@Atual, N'')
        BEGIN
            SET @EtapaAtual = 'Efeito';
            SELECT l.ID_LANCAMENTO
            INTO #abertos
            FROM FIN.Lancamento l WITH (NOLOCK)
            WHERE l.SITUACAO = 'ATIVO'
              AND l.DT_EXCLUSAO IS NULL
              AND EXISTS (SELECT 1 FROM FIN.Parcela p WITH (NOLOCK) WHERE p.ID_LANCAMENTO = l.ID_LANCAMENTO AND p.SITUACAO IN ('ABERTA', 'PARCIAL'));

            SELECT @QtdAtual = COUNT(*)
            FROM #abertos a
            WHERE EXISTS (SELECT 1 FROM FIN.fn_FIN_Lancamento_Pendencias_Simular(a.ID_LANCAMENTO, NULL, NULL) f
                          WHERE f.ORIGEM = 'AUTOMATICA' AND (@Codigo = '*' OR f.CODIGO = @Codigo))
            OPTION (RECOMPILE);

            SELECT @QtdNova = COUNT(*)
            FROM #abertos a
            WHERE EXISTS (SELECT 1 FROM FIN.fn_FIN_Lancamento_Pendencias_Simular(a.ID_LANCAMENTO, @Chave, @Novo) f
                          WHERE f.ORIGEM = 'AUTOMATICA' AND (@Codigo = '*' OR f.CODIGO = @Codigo))
            OPTION (RECOMPILE);

            SET @QtdAtual = ISNULL(@QtdAtual, 0);
            SET @QtdNova  = ISNULL(@QtdNova, 0);
            SET @Efeito = CASE
                              WHEN @QtdNova = @QtdAtual THEN N'Nenhuma mudança: continuam ' + CONVERT(NVARCHAR(10), @QtdNova) + N' lançamentos em aberto com '
                                   + CASE WHEN @Codigo = '*' THEN N'pendência automática.' ELSE N'esta pendência.' END
                              ELSE N'Com o valor novo, ' + CONVERT(NVARCHAR(10), @QtdNova) + N' lançamentos em aberto passam a ter '
                                   + CASE WHEN @Codigo = '*' THEN N'pendência automática' ELSE N'esta pendência' END
                                   + N' (hoje são ' + CONVERT(NVARCHAR(10), @QtdAtual) + N'; '
                                   + CASE WHEN @QtdNova > @QtdAtual THEN N'+' ELSE N'' END + CONVERT(NVARCHAR(10), @QtdNova - @QtdAtual) + N').'
                          END;
        END;

        SELECT SIS.fn_SIS_Parametro_Afrouxa(@Chave, @Atual, @Novo) AS PEDE_MOTIVO,
               @QtdAtual                                            AS QTD_ATUAL,
               @QtdNova                                             AS QTD_NOVA,
               CAST(@Efeito AS NVARCHAR(400))                       AS EFEITO;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível conferir o parâmetro. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Parceiro_Movimento_Resumo.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Parceiro_Movimento_Resumo]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : Resumo do topo da aba Movimentação da ficha do Parceiro.
                Uma linha por tipo (P = a pagar, R = a receber) que o usuário
                pode ver (VER em FIN_PAGAR / FIN_RECEBER):
                  QTD/VALOR_EM_ABERTO   parcelas abertas ou parciais (saldo)
                  QTD/VALOR_VENCIDAS    das em aberto, vencidas antes de hoje
                  QTD/VALOR_PAGO_12M    baixas dos últimos 12 meses (valor
                                        líquido; estorno entra negativo e
                                        anula a original)
                  MEDIA_MENSAL_12M      VALOR_PAGO_12M / 12 (sugestão (b) da
                                        04f2d: ajuda a perceber valor fora do
                                        padrão)
                  DT_ULTIMO_PAGAMENTO   data da baixa mais recente
                Não conta o que está na lixeira nem lançamento cancelado.
                Sem permissão em nenhum dos dois tipos: THROW 50001.
                Padrão "Listar": THROW 50001 com mensagem amigável em erro.

  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04f2d).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Parceiro_Movimento_Resumo @IdUsuario = 2, @IdPessoa = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Parceiro_Movimento_Resumo]
    @IdUsuario INT,
    @IdPessoa  INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc   NVARCHAR(128) = N'[FIN].[FIN_Parceiro_Movimento_Resumo]';
    DECLARE @EtapaAtual VARCHAR(100)  = 'Permissão';
    DECLARE @Hoje       DATE = CONVERT(DATE, SYSDATETIME());
    DECLARE @Desde      DATE;
    DECLARE @VeP        BIT;
    DECLARE @VeR        BIT;

    BEGIN TRY
        SET @VeP = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PAGAR', 'VER');
        SET @VeR = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_RECEBER', 'VER');
        IF @VeP = 0 AND @VeR = 0
            THROW 50001, N'Você não tem permissão para ver a movimentação financeira.', 1;
        IF NOT EXISTS (SELECT 1 FROM CAD.Pessoa WITH (NOLOCK) WHERE ID_PESSOA = @IdPessoa)
            THROW 50001, N'Parceiro não encontrado.', 1;

        SET @EtapaAtual = 'Consulta';
        SET @Desde = DATEADD(DAY, 1, DATEADD(MONTH, -12, @Hoje));

        ;WITH Tipos AS (
            SELECT t.TIPO
            FROM (VALUES ('P'), ('R')) t (TIPO)
            WHERE (t.TIPO = 'P' AND @VeP = 1) OR (t.TIPO = 'R' AND @VeR = 1)
        ),
        Aberto AS (
            SELECT l.TIPO,
                   COUNT(*)                                                     AS QTD_EM_ABERTO,
                   SUM(p.SALDO)                                                 AS VALOR_EM_ABERTO,
                   SUM(CASE WHEN p.DT_VENCIMENTO < @Hoje THEN 1 ELSE 0 END)     AS QTD_VENCIDAS,
                   SUM(CASE WHEN p.DT_VENCIMENTO < @Hoje THEN p.SALDO ELSE 0 END) AS VALOR_VENCIDAS
            FROM FIN.Parcela p WITH (NOLOCK)
            INNER JOIN FIN.Lancamento l WITH (NOLOCK) ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
            WHERE l.ID_PESSOA = @IdPessoa
              AND l.DT_EXCLUSAO IS NULL
              AND l.SITUACAO = 'ATIVO'
              AND p.SITUACAO IN ('ABERTA', 'PARCIAL')
            GROUP BY l.TIPO
        ),
        Pago AS (
            SELECT l.TIPO,
                   SUM(CASE WHEN b.ID_BAIXA_ESTORNADA IS NULL THEN 1 ELSE -1 END) AS QTD_PAGO_12M,
                   SUM(b.VALOR_LIQUIDO)                                           AS VALOR_PAGO_12M
            FROM FIN.Baixa b WITH (NOLOCK)
            INNER JOIN FIN.Parcela p WITH (NOLOCK) ON p.ID_PARCELA = b.ID_PARCELA
            INNER JOIN FIN.Lancamento l WITH (NOLOCK) ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
            WHERE l.ID_PESSOA = @IdPessoa
              AND l.DT_EXCLUSAO IS NULL
              AND b.DT_PAGAMENTO BETWEEN @Desde AND @Hoje
            GROUP BY l.TIPO
        ),
        Ultimo AS (
            SELECT l.TIPO, MAX(b.DT_PAGAMENTO) AS DT_ULTIMO_PAGAMENTO
            FROM FIN.Baixa b WITH (NOLOCK)
            INNER JOIN FIN.Parcela p WITH (NOLOCK) ON p.ID_PARCELA = b.ID_PARCELA
            INNER JOIN FIN.Lancamento l WITH (NOLOCK) ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
            WHERE l.ID_PESSOA = @IdPessoa
              AND l.DT_EXCLUSAO IS NULL
              AND b.ID_BAIXA_ESTORNADA IS NULL
            GROUP BY l.TIPO
        )
        SELECT t.TIPO,
               CAST(ISNULL(a.QTD_EM_ABERTO, 0) AS INT)              AS QTD_EM_ABERTO,
               CAST(ISNULL(a.VALOR_EM_ABERTO, 0) AS DECIMAL(18,2))  AS VALOR_EM_ABERTO,
               CAST(ISNULL(a.QTD_VENCIDAS, 0) AS INT)               AS QTD_VENCIDAS,
               CAST(ISNULL(a.VALOR_VENCIDAS, 0) AS DECIMAL(18,2))   AS VALOR_VENCIDAS,
               CAST(ISNULL(g.QTD_PAGO_12M, 0) AS INT)               AS QTD_PAGO_12M,
               CAST(ISNULL(g.VALOR_PAGO_12M, 0) AS DECIMAL(18,2))   AS VALOR_PAGO_12M,
               CAST(ROUND(ISNULL(g.VALOR_PAGO_12M, 0) / 12.0, 2) AS DECIMAL(18,2)) AS MEDIA_MENSAL_12M,
               u.DT_ULTIMO_PAGAMENTO,
               @Desde                                               AS DT_DESDE
        FROM Tipos t
        LEFT JOIN Aberto a ON a.TIPO = t.TIPO
        LEFT JOIN Pago   g ON g.TIPO = t.TIPO
        LEFT JOIN Ultimo u ON u.TIPO = t.TIPO
        ORDER BY t.TIPO
        OPTION (RECOMPILE);
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível carregar o resumo da movimentação. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Baixa_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Baixa_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : Baixa (pagamento ou recebimento) de uma ou várias parcelas, total
                ou parcial (etapa 04g, desenho aprovado em 26/11/2026). Todas as
                parcelas do mesmo tipo (pagar ou receber). Tudo-ou-nada.
                @Itens: JSON [{"idParcela":1,"principal":100.00,"juros":0,
                "multa":0,"correcao":0,"desconto":0,"abatimento":0,
                "retencao":0,"tarifa":0}]. principal = quanto da parcela fica
                quitado (abate o saldo; o abatimento faz parte dele, sem
                dinheiro). Gera um lote (origem BAIXA), UM BANCO.Movimento pelo
                total líquido (entra no receber, sai no pagar; sem movimento
                quando o líquido é zero, ex.: só abatimento) e um movimento
                TARIFA pela soma das tarifas. Cheque nasce não compensado (a
                compensação entra com a conciliação).
                Regras (mesmo contrato do FIN_Lancamento_Gravar: BLOQUEIO,
                MOTIVO, AVISO; @SomenteConferir = 1 é a prévia):
                  BLOQUEIO  parcela inexistente/repetida/cancelada/sem saldo,
                            lançamento cancelado/na lixeira/de previsão, tipos
                            misturados, valor acima do saldo ou negativo,
                            conta inativa, forma inválida, mês fechado (conta
                            contábil, mês do pagamento), caixa fechado
                            (BANCO.fn_BANCO_Caixa_Recusa); trava de datas,
                            pendência que bloqueia e desconto acima do limite
                            para quem não tem a permissão;
                  MOTIVO    trava de datas com LANCAR_RETROATIVO, pendência
                            que bloqueia com LIBERAR_PENDENCIA (justificativa)
                            e desconto acima do limite com DESCONTO_LIMITE:
                            grava só com @Motivo;
                  AVISO     encargo diferente do calculado (ENCARGO_AJUSTADO),
                            conta de outra empresa (CONTA_OUTRA_EMPRESA),
                            pagamento antes da emissão (PAGTO_ANTES_EMISSAO):
                            grava só com o código em @AvisosConfirmados.
                Avisos e motivos ficam em SIS.Aviso_Confirmado (TABELA
                FIN.Baixa).
                Permissão: BAIXAR em FIN_PAGAR / FIN_RECEBER.
                Devolve 1 linha: SUCESSO, MENSAGEM, ID (1ª baixa), ID_MOVIMENTO,
                ID_LOTE, PENDENTE, AVISOS (JSON: codigo, nivel, mensagem,
                idReferencia = ID_PARCELA, campo).
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04g).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Baixa_Gravar @IdUsuario = 2, @DtPagamento = '2026-11-26', @IdConta = 1, @Forma = 'PIX',
    --      @Itens = N'[{"idParcela":1,"principal":100}]', @SomenteConferir = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Baixa_Gravar]
    @IdUsuario          INT,
    @DtPagamento        DATE            = NULL,
    @IdConta            INT             = NULL,
    @Forma              VARCHAR(12)     = NULL,
    @Itens              NVARCHAR(MAX)   = NULL,
    @Documento          NVARCHAR(40)    = NULL,
    @Observacao         NVARCHAR(400)   = NULL,
    @AvisosConfirmados  NVARCHAR(1000)  = NULL,
    @Motivo             NVARCHAR(400)   = NULL,
    @SomenteConferir    BIT             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[FIN].[FIN_Baixa_Gravar]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Validação';
    DECLARE @Recusa      NVARCHAR(400) = N'';
    DECLARE @Usuario     NVARCHAR(100);
    DECLARE @Tipo        CHAR(1);
    DECLARE @Item        VARCHAR(40);
    DECLARE @Avisos      NVARCHAR(MAX) = N'[]';
    DECLARE @Pendente    BIT = 0;
    DECLARE @IdEmpresaConta INT;
    DECLARE @ContaAtiva  BIT;
    DECLARE @Liquido     DECIMAL(18,2);
    DECLARE @Tarifa      DECIMAL(18,2);
    DECLARE @IdLote      BIGINT;
    DECLARE @IdMovimento BIGINT;
    DECLARE @IdPrimeira  BIGINT;
    DECLARE @N           INT;
    DECLARE @Historico   NVARCHAR(200);

    CREATE TABLE #I (ORDEM INT NOT NULL, ID_PARCELA BIGINT NULL, PRINCIPAL DECIMAL(18,2) NULL, JUROS DECIMAL(18,2) NULL, MULTA DECIMAL(18,2) NULL,
                     CORRECAO DECIMAL(18,2) NULL, DESCONTO DECIMAL(18,2) NULL, ABATIMENTO DECIMAL(18,2) NULL, RETENCAO DECIMAL(18,2) NULL,
                     TARIFA DECIMAL(18,2) NULL, ID_LANCAMENTO BIGINT NULL, TIPO CHAR(1) NULL, ID_EMPRESA INT NULL, ID_PLANO_CONTA INT NULL,
                     NUMERO SMALLINT NULL, QTD SMALLINT NULL, SALDO DECIMAL(18,2) NULL, SITUACAO VARCHAR(10) NULL, SITUACAO_LANC VARCHAR(10) NULL,
                     PREVISAO BIT NULL, DT_EMISSAO DATE NULL, PESSOA NVARCHAR(150) NULL, DOCUMENTO NVARCHAR(40) NULL,
                     SUG_JUROS DECIMAL(18,2) NULL, SUG_MULTA DECIMAL(18,2) NULL, CALCULA BIT NULL, DESC_LIMITE DECIMAL(18,2) NULL,
                     ID_BAIXA BIGINT NULL);
    CREATE TABLE #Regra (ORDEM INT IDENTITY(1,1), CODIGO VARCHAR(40) NOT NULL, NIVEL VARCHAR(12) NOT NULL,
                         MENSAGEM NVARCHAR(400) NOT NULL, ID_REFERENCIA BIGINT NULL, CAMPO VARCHAR(40) NOT NULL DEFAULT (''));

    BEGIN TRY
        SET @Forma             = UPPER(LTRIM(RTRIM(ISNULL(@Forma, ''))));
        SET @Documento         = LTRIM(RTRIM(ISNULL(@Documento, N'')));
        SET @Observacao        = LTRIM(RTRIM(ISNULL(@Observacao, N'')));
        SET @Motivo            = LTRIM(RTRIM(ISNULL(@Motivo, N'')));
        SET @AvisosConfirmados = ISNULL(@AvisosConfirmados, N'');

        ---------------------------------------------------------------------
        -- 1) Itens
        ---------------------------------------------------------------------
        IF ISJSON(ISNULL(@Itens, N'')) = 1
            INSERT INTO #I (ORDEM, ID_PARCELA, PRINCIPAL, JUROS, MULTA, CORRECAO, DESCONTO, ABATIMENTO, RETENCAO, TARIFA)
            SELECT CONVERT(INT, j.[key]) + 1, x.idParcela, x.principal, ISNULL(x.juros, 0), ISNULL(x.multa, 0), ISNULL(x.correcao, 0),
                   ISNULL(x.desconto, 0), ISNULL(x.abatimento, 0), ISNULL(x.retencao, 0), ISNULL(x.tarifa, 0)
            FROM OPENJSON(@Itens) j
            CROSS APPLY OPENJSON(j.[value]) WITH (idParcela BIGINT '$.idParcela', principal DECIMAL(18,2) '$.principal', juros DECIMAL(18,2) '$.juros',
                                                  multa DECIMAL(18,2) '$.multa', correcao DECIMAL(18,2) '$.correcao', desconto DECIMAL(18,2) '$.desconto',
                                                  abatimento DECIMAL(18,2) '$.abatimento', retencao DECIMAL(18,2) '$.retencao', tarifa DECIMAL(18,2) '$.tarifa') x;

        UPDATE i
           SET i.ID_LANCAMENTO = l.ID_LANCAMENTO, i.TIPO = l.TIPO, i.ID_EMPRESA = l.ID_EMPRESA, i.ID_PLANO_CONTA = l.ID_PLANO_CONTA,
               i.NUMERO = p.NUMERO, i.QTD = p.QTD_PARCELAS, i.SALDO = p.SALDO, i.SITUACAO = p.SITUACAO, i.SITUACAO_LANC = l.SITUACAO,
               i.PREVISAO = l.PREVISAO, i.DT_EMISSAO = l.DT_EMISSAO, i.DOCUMENTO = l.DOCUMENTO,
               i.PESSOA = ISNULL(NULLIF(pe.NOME_FANTASIA, N''), pe.NOME)
        FROM #I i
        INNER JOIN FIN.Parcela p    ON p.ID_PARCELA = i.ID_PARCELA
        INNER JOIN FIN.Lancamento l ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
        LEFT  JOIN CAD.Pessoa pe    ON pe.ID_PESSOA = l.ID_PESSOA;

        SELECT TOP 1 @Tipo = i.TIPO FROM #I i WHERE i.TIPO IS NOT NULL ORDER BY i.ORDEM;
        SET @Item = CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END;

        IF NOT EXISTS (SELECT 1 FROM #I)
            SET @Recusa = N'Escolha pelo menos uma parcela para baixar.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #I WHERE ID_LANCAMENTO IS NULL)
            SET @Recusa = N'Parcela não encontrada.';
        IF @Recusa = N'' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'BAIXAR') = 0
            SET @Recusa = CASE @Tipo WHEN 'P' THEN N'Você não tem permissão para baixar contas a pagar.' ELSE N'Você não tem permissão para baixar contas a receber.' END;
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #I WHERE TIPO <> @Tipo)
            SET @Recusa = N'Baixe as contas a pagar e as contas a receber separadamente.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #I GROUP BY ID_PARCELA HAVING COUNT(*) > 1)
            SET @Recusa = N'A mesma parcela foi escolhida mais de uma vez.';
        IF @Recusa = N'' AND @DtPagamento IS NULL
            SET @Recusa = CASE @Tipo WHEN 'P' THEN N'Informe a data do pagamento.' ELSE N'Informe a data do recebimento.' END;

        SELECT @IdEmpresaConta = c.ID_EMPRESA, @ContaAtiva = c.ATIVO FROM BANCO.Conta c WHERE c.ID_CONTA = @IdConta;
        IF @Recusa = N'' AND @ContaAtiva IS NULL
            SET @Recusa = N'Escolha a conta (banco ou caixa).';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID,
                   CAST(NULL AS BIGINT) AS ID_MOVIMENTO, CAST(NULL AS BIGINT) AS ID_LOTE, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #I;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        UPDATE i
           SET i.SUG_JUROS = s.JUROS, i.SUG_MULTA = s.MULTA, i.CALCULA = s.CALCULA, i.DESC_LIMITE = s.DESCONTO_LIMITE
        FROM #I i
        CROSS APPLY FIN.fn_FIN_Baixa_Sugerir(i.ID_PARCELA, @DtPagamento, i.PRINCIPAL) s;

        ---------------------------------------------------------------------
        -- 2) Regras
        ---------------------------------------------------------------------
        IF @ContaAtiva = 0
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO) VALUES ('CONTA_INATIVA', 'BLOQUEIO', N'A conta escolhida está desativada.', 'idConta');

        IF @Forma NOT IN ('PIX', 'BOLETO', 'TED', 'DOC', 'DEBITO', 'DINHEIRO', 'CHEQUE', 'PERMUTA', 'CARTAO', 'OUTRA')
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO) VALUES ('FORMA', 'BLOQUEIO', N'Escolha a forma de pagamento.', 'forma');

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'PARCELA_SITUACAO', 'BLOQUEIO',
               N'Parcela ' + CONVERT(NVARCHAR(5), i.NUMERO) + N'/' + CONVERT(NVARCHAR(5), i.QTD) + N' de ' + ISNULL(i.PESSOA, N'')
               + CASE WHEN i.SITUACAO_LANC = 'CANCELADO' OR i.SITUACAO = 'CANCELADA' THEN N': está cancelada.'
                      WHEN SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', i.ID_LANCAMENTO) = 1 THEN N': o lançamento está na lixeira.'
                      WHEN i.PREVISAO = 1 THEN N': é uma previsão (tire a marca de previsão no lançamento antes de baixar).'
                      ELSE N': não tem saldo em aberto.' END,
               i.ID_PARCELA, 'itens'
        FROM #I i
        WHERE i.SITUACAO_LANC = 'CANCELADO' OR i.SITUACAO = 'CANCELADA' OR i.PREVISAO = 1 OR i.SALDO <= 0
           OR SIS.fn_SIS_Na_Lixeira(N'FIN.Lancamento', i.ID_LANCAMENTO) = 1;

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'VALOR', 'BLOQUEIO',
               N'Parcela ' + CONVERT(NVARCHAR(5), i.NUMERO) + N'/' + CONVERT(NVARCHAR(5), i.QTD) + N' de ' + ISNULL(i.PESSOA, N'')
               + CASE WHEN ISNULL(i.PRINCIPAL, 0) <= 0 THEN N': informe o valor a baixar.'
                      WHEN i.PRINCIPAL > i.SALDO THEN N': o valor ' + FORMAT(i.PRINCIPAL, 'N2', 'pt-BR') + N' passa do saldo em aberto ' + FORMAT(i.SALDO, 'N2', 'pt-BR') + N'.'
                      WHEN i.ABATIMENTO > i.PRINCIPAL THEN N': o abatimento passa do valor baixado.'
                      ELSE N': juros, multa, correção, desconto, abatimento, retenção e tarifa não podem ser negativos, e o valor líquido não pode ficar negativo.' END,
               i.ID_PARCELA, 'itens'
        FROM #I i
        WHERE i.SALDO > 0
          AND (ISNULL(i.PRINCIPAL, 0) <= 0 OR i.PRINCIPAL > i.SALDO OR i.ABATIMENTO > i.PRINCIPAL
               OR i.JUROS < 0 OR i.MULTA < 0 OR i.CORRECAO < 0 OR i.DESCONTO < 0 OR i.ABATIMENTO < 0 OR i.RETENCAO < 0 OR i.TARIFA < 0
               OR i.PRINCIPAL + i.JUROS + i.MULTA + i.CORRECAO - i.DESCONTO - i.ABATIMENTO - i.RETENCAO < 0);

        -- mês fechado (conta contábil; regime de caixa: mês do pagamento)
        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
        SELECT TOP 1 'MES_FECHADO', 'BLOQUEIO',
               N'O mês ' + RIGHT('0' + CONVERT(NVARCHAR(2), MONTH(m.MES)), 2) + N'/' + CONVERT(NVARCHAR(4), YEAR(m.MES))
               + N' está fechado para a empresa ' + ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL) + N' (conta contábil).', 'dtPagamento'
        FROM #I i
        INNER JOIN FIN.Mes_Fechado m  ON m.ID_EMPRESA = i.ID_EMPRESA AND m.MES = DATEFROMPARTS(YEAR(@DtPagamento), MONTH(@DtPagamento), 1) AND m.FECHADO = 1
        INNER JOIN CAD.Plano_Conta pc ON pc.ID_PLANO_CONTA = i.ID_PLANO_CONTA AND pc.CONTABIL = 1
        INNER JOIN CAD.Empresa e      ON e.ID_EMPRESA = i.ID_EMPRESA;

        -- caixa fechado
        IF BANCO.fn_BANCO_Caixa_Recusa(@IdConta, @DtPagamento) <> N''
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO) VALUES ('CAIXA_FECHADO', 'BLOQUEIO', BANCO.fn_BANCO_Caixa_Recusa(@IdConta, @DtPagamento), 'dtPagamento');

        -- trava de datas
        IF FIN.fn_FIN_Data_Recusa('BAIXA', @DtPagamento) <> N''
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('DATA_BAIXA', CASE WHEN SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'LANCAR_RETROATIVO') = 1 THEN 'MOTIVO' ELSE 'BLOQUEIO' END,
                    FIN.fn_FIN_Data_Recusa('BAIXA', @DtPagamento), 'dtPagamento');

        -- pendência que bloqueia a baixa (P27): liberação com justificativa
        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'PENDENCIA_BLOQUEIA',
               CASE WHEN SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'LIBERAR_PENDENCIA') = 1 THEN 'MOTIVO' ELSE 'BLOQUEIO' END,
               LEFT(N'Parcela ' + CONVERT(NVARCHAR(5), i.NUMERO) + N'/' + CONVERT(NVARCHAR(5), i.QTD) + N' de ' + ISNULL(i.PESSOA, N'')
                    + N': pendência que bloqueia a baixa (' + b.MOTIVO + N')'
                    + CASE WHEN SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'LIBERAR_PENDENCIA') = 1 THEN N'. Para liberar, informe a justificativa.'
                           ELSE N'. Resolva a pendência ou peça a quem pode liberar.' END, 400),
               i.ID_PARCELA, 'itens'
        FROM #I i
        CROSS APPLY FIN.fn_FIN_Pendencia_Bloqueia(i.ID_LANCAMENTO, i.ID_PARCELA) b
        WHERE b.BLOQUEIA = 1;

        -- desconto acima do limite (só a receber)
        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'DESCONTO_LIMITE',
               CASE WHEN SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'DESCONTO_LIMITE') = 1 THEN 'MOTIVO' ELSE 'BLOQUEIO' END,
               N'Parcela ' + CONVERT(NVARCHAR(5), i.NUMERO) + N'/' + CONVERT(NVARCHAR(5), i.QTD) + N': desconto de ' + FORMAT(i.DESCONTO, 'N2', 'pt-BR')
               + N' passa do limite de ' + FORMAT(i.DESC_LIMITE, 'N2', 'pt-BR')
               + CASE WHEN SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'DESCONTO_LIMITE') = 1 THEN N'. Informe o motivo.' ELSE N'. Peça a quem pode dar desconto maior.' END,
               i.ID_PARCELA, 'itens'
        FROM #I i
        WHERE i.DESC_LIMITE IS NOT NULL AND i.DESCONTO > i.DESC_LIMITE;

        -- avisos
        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'ENCARGO_AJUSTADO', 'AVISO',
               N'Parcela ' + CONVERT(NVARCHAR(5), i.NUMERO) + N'/' + CONVERT(NVARCHAR(5), i.QTD) + N': juros e multa informados ('
               + FORMAT(i.JUROS + i.MULTA, 'N2', 'pt-BR') + N') diferentes do calculado (' + FORMAT(i.SUG_JUROS + i.SUG_MULTA, 'N2', 'pt-BR') + N').',
               i.ID_PARCELA, 'itens'
        FROM #I i
        WHERE i.CALCULA = 1 AND i.JUROS + i.MULTA <> i.SUG_JUROS + i.SUG_MULTA;

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
        SELECT TOP 1 'CONTA_OUTRA_EMPRESA', 'AVISO', N'A conta escolhida é de outra empresa do grupo que não a do lançamento.', 'idConta'
        FROM #I i WHERE i.ID_EMPRESA <> @IdEmpresaConta;

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT TOP 1 'PAGTO_ANTES_EMISSAO', 'AVISO',
               N'A data ' + CASE @Tipo WHEN 'P' THEN N'do pagamento' ELSE N'do recebimento' END + N' é anterior à emissão do lançamento ('
               + CONVERT(NVARCHAR(10), i.DT_EMISSAO, 103) + N').', i.ID_PARCELA, 'dtPagamento'
        FROM #I i WHERE @DtPagamento < i.DT_EMISSAO ORDER BY i.ORDEM;

        ---------------------------------------------------------------------
        -- 3) Resultado das regras
        ---------------------------------------------------------------------
        SET @Avisos = ISNULL((SELECT r.CODIGO AS codigo, r.NIVEL AS nivel, r.MENSAGEM AS mensagem, r.ID_REFERENCIA AS idReferencia, r.CAMPO AS campo
                              FROM #Regra r
                              ORDER BY CASE r.NIVEL WHEN 'BLOQUEIO' THEN 0 WHEN 'MOTIVO' THEN 1 ELSE 2 END, r.ORDEM
                              FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]');

        IF EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'BLOQUEIO')
        BEGIN
            SELECT TOP 1 @Recusa = r.MENSAGEM FROM #Regra r WHERE r.NIVEL = 'BLOQUEIO' ORDER BY r.ORDEM;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID,
                   CAST(NULL AS BIGINT) AS ID_MOVIMENTO, CAST(NULL AS BIGINT) AS ID_LOTE, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #I;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        IF (EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') AND LEN(@Motivo) < 5)
           OR EXISTS (SELECT 1 FROM #Regra r WHERE r.NIVEL = 'AVISO'
                        AND NOT EXISTS (SELECT 1 FROM STRING_SPLIT(@AvisosConfirmados, N',') s WHERE LTRIM(RTRIM(s.value)) = r.CODIGO))
            SET @Pendente = 1;

        IF @SomenteConferir = 1 OR @Pendente = 1
        BEGIN
            SELECT CAST(CASE WHEN @SomenteConferir = 1 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
                   CAST(CASE WHEN @Pendente = 0 THEN N'Nada a confirmar.'
                             WHEN EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') AND LEN(@Motivo) < 5
                                  THEN N'Informe o motivo (justificativa) para gravar a baixa.'
                             ELSE N'Confira os avisos antes de gravar.' END AS NVARCHAR(400)) AS MENSAGEM,
                   CAST(NULL AS BIGINT) AS ID, CAST(NULL AS BIGINT) AS ID_MOVIMENTO, CAST(NULL AS BIGINT) AS ID_LOTE,
                   @Pendente AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #I;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        ---------------------------------------------------------------------
        -- 4) Gravação
        ---------------------------------------------------------------------
        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        SET @N       = (SELECT COUNT(*) FROM #I);
        SELECT @Liquido = SUM(i.PRINCIPAL + i.JUROS + i.MULTA + i.CORRECAO - i.DESCONTO - i.ABATIMENTO - i.RETENCAO), @Tarifa = SUM(i.TARIFA) FROM #I i;
        SET @Historico = LEFT(CASE @Tipo WHEN 'P' THEN N'Pagamento' ELSE N'Recebimento' END
                         + CASE WHEN @N = 1 THEN (SELECT N' - ' + ISNULL(i.PESSOA, N'') + N' - parc. ' + CONVERT(NVARCHAR(5), i.NUMERO) + N'/' + CONVERT(NVARCHAR(5), i.QTD)
                                                  + CASE WHEN i.DOCUMENTO <> N'' THEN N' - doc. ' + i.DOCUMENTO ELSE N'' END FROM #I i)
                                ELSE N' de ' + CONVERT(NVARCHAR(10), @N) + N' parcelas' END, 200);

        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        EXEC SIS.SIS_Lote_Gerar @IdUsuario = @IdUsuario, @Origem = 'BAIXA', @Descricao = @Historico,
             @TabelaReferencia = N'FIN.Baixa', @IdLote = @IdLote OUTPUT;

        -- trava as parcelas e confere o saldo de novo (concorrência)
        IF EXISTS (SELECT 1 FROM #I i INNER JOIN FIN.Parcela p WITH (UPDLOCK, HOLDLOCK) ON p.ID_PARCELA = i.ID_PARCELA
                   WHERE p.SALDO < i.PRINCIPAL OR p.SITUACAO = 'CANCELADA')
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Uma das parcelas foi alterada por outra pessoa. Abra a baixa de novo.' AS NVARCHAR(400)) AS MENSAGEM,
                   CAST(NULL AS BIGINT) AS ID, CAST(NULL AS BIGINT) AS ID_MOVIMENTO, CAST(NULL AS BIGINT) AS ID_LOTE, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #I;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        IF @Liquido <> 0
        BEGIN
            INSERT INTO BANCO.Movimento (ID_CONTA, DT_MOVIMENTO, VALOR, TIPO, HISTORICO, DOCUMENTO, ID_LOTE, USUARIO_CRIACAO)
            VALUES (@IdConta, @DtPagamento, CASE @Tipo WHEN 'P' THEN -@Liquido ELSE @Liquido END, 'BAIXA', @Historico, @Documento, @IdLote, ISNULL(@Usuario, N'sistema'));
            SET @IdMovimento = SCOPE_IDENTITY();
        END;

        IF @Tarifa > 0
            INSERT INTO BANCO.Movimento (ID_CONTA, DT_MOVIMENTO, VALOR, TIPO, HISTORICO, DOCUMENTO, ID_LOTE, USUARIO_CRIACAO)
            VALUES (@IdConta, @DtPagamento, -@Tarifa, 'TARIFA', LEFT(N'Tarifa - ' + @Historico, 200), @Documento, @IdLote, ISNULL(@Usuario, N'sistema'));

        DECLARE @Ids TABLE (ID_BAIXA BIGINT NOT NULL, ID_PARCELA BIGINT NOT NULL);

        INSERT INTO FIN.Baixa (ID_PARCELA, DT_PAGAMENTO, ID_CONTA, FORMA, VALOR_PRINCIPAL, JUROS, MULTA, CORRECAO, DESCONTO, ABATIMENTO,
                               TARIFA, RETENCAO, ID_MOVIMENTO, COMPENSADO, OBSERVACAO, ID_LOTE, USUARIO_CRIACAO)
        OUTPUT inserted.ID_BAIXA, inserted.ID_PARCELA INTO @Ids (ID_BAIXA, ID_PARCELA)
        SELECT i.ID_PARCELA, @DtPagamento, @IdConta, @Forma, i.PRINCIPAL, i.JUROS, i.MULTA, i.CORRECAO, i.DESCONTO, i.ABATIMENTO,
               i.TARIFA, i.RETENCAO, @IdMovimento, CASE WHEN @Forma = 'CHEQUE' THEN 0 ELSE 1 END, @Observacao, @IdLote, ISNULL(@Usuario, N'sistema')
        FROM #I i
        ORDER BY i.ORDEM;

        UPDATE i SET i.ID_BAIXA = d.ID_BAIXA FROM #I i INNER JOIN @Ids d ON d.ID_PARCELA = i.ID_PARCELA;
        SELECT TOP 1 @IdPrimeira = i.ID_BAIXA FROM #I i ORDER BY i.ORDEM;

        -- avisos confirmados e motivos (na baixa da parcela citada; os gerais na primeira)
        INSERT INTO SIS.Aviso_Confirmado (TABELA, ID_REGISTRO, CODIGO_REGRA, NIVEL, MENSAGEM, MOTIVO, ID_REFERENCIA, ID_USUARIO, USUARIO_CRIACAO)
        SELECT N'FIN.Baixa', ISNULL(i.ID_BAIXA, @IdPrimeira), r.CODIGO, r.NIVEL, r.MENSAGEM,
               CASE WHEN r.NIVEL = 'MOTIVO' THEN @Motivo ELSE N'' END, r.ID_REFERENCIA, @IdUsuario, ISNULL(@Usuario, N'sistema')
        FROM #Regra r
        LEFT JOIN #I i ON i.ID_PARCELA = r.ID_REFERENCIA
        WHERE r.NIVEL IN ('AVISO', 'MOTIVO');

        EXEC SIS.SIS_Lote_Concluir @IdLote = @IdLote, @QtdRegistros = @N;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(CASE WHEN @N = 1 THEN CASE @Tipo WHEN 'P' THEN N'Pagamento gravado.' ELSE N'Recebimento gravado.' END
                         ELSE CONVERT(NVARCHAR(10), @N) + CASE @Tipo WHEN 'P' THEN N' pagamentos gravados.' ELSE N' recebimentos gravados.' END END AS NVARCHAR(400)) AS MENSAGEM,
               @IdPrimeira AS ID, @IdMovimento AS ID_MOVIMENTO, @IdLote AS ID_LOTE, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;

        DROP TABLE IF EXISTS #I;
        DROP TABLE IF EXISTS #Regra;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        DROP TABLE IF EXISTS #I;
        DROP TABLE IF EXISTS #Regra;

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar a baixa. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(NULL AS BIGINT) AS ID, CAST(NULL AS BIGINT) AS ID_MOVIMENTO, CAST(NULL AS BIGINT) AS ID_LOTE, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Baixa_Estornar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Baixa_Estornar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : Estorna uma baixa (etapa 04g, aprovado em 26/11/2026). Nada é
                apagado: cada baixa estornada ganha uma baixa com os valores
                negativos (ID_BAIXA_ESTORNADA) e o movimento bancário ganha um
                movimento inverso; original e inverso ficam com SITUACAO
                ESTORNADO (o saldo soma os dois e zera). Pagamento em lote (um
                movimento para várias baixas) estorna inteiro, com a tarifa do
                mesmo lote. A parcela volta ao saldo anterior (gatilho do saldo).
                @DtEstorno (padrão hoje): data do estorno no banco/caixa;
                confere trava de datas (motivo com LANCAR_RETROATIVO), mês
                fechado (conta contábil) e caixa fechado nessa data.
                Motivo obrigatório (vai em OBSERVACAO das baixas de estorno e
                em SIS.Aviso_Confirmado, código ESTORNO).
                @SomenteConferir = 1: devolve, sem gravar, quantas baixas e o
                valor que serão estornados (prévia da tela).
                Permissão: ESTORNAR em FIN_PAGAR / FIN_RECEBER.
                Devolve SUCESSO, MENSAGEM, ID (baixa informada), QTD_BAIXAS,
                VALOR (líquido estornado), PENDENTE, AVISOS.
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04g).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Baixa_Estornar @IdUsuario = 2, @IdBaixa = 1, @Motivo = N'Baixa em dobro', @SomenteConferir = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Baixa_Estornar]
    @IdUsuario        INT,
    @IdBaixa          BIGINT,
    @Motivo           NVARCHAR(400)  = NULL,
    @DtEstorno        DATE           = NULL,
    @SomenteConferir  BIT            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[FIN].[FIN_Baixa_Estornar]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Validação';
    DECLARE @Recusa       NVARCHAR(400) = N'';
    DECLARE @Usuario      NVARCHAR(100);
    DECLARE @Tipo         CHAR(1);
    DECLARE @Item         VARCHAR(40);
    DECLARE @IdMovimento  BIGINT;
    DECLARE @IdLoteOrig   BIGINT;
    DECLARE @OrigemLote   VARCHAR(30);
    DECLARE @IdConta      INT;
    DECLARE @Estornada    BIGINT;
    DECLARE @IdLote       BIGINT;
    DECLARE @Qtd          INT;
    DECLARE @Valor        DECIMAL(18,2);
    DECLARE @Avisos       NVARCHAR(MAX) = N'[]';
    DECLARE @Pendente     BIT = 0;
    DECLARE @PodeRetro    BIT;

    CREATE TABLE #B (ID_BAIXA BIGINT NOT NULL PRIMARY KEY, ID_EMPRESA INT NULL, ID_PLANO_CONTA INT NULL, LIQUIDO DECIMAL(18,2) NOT NULL);
    CREATE TABLE #M (ID_MOVIMENTO BIGINT NOT NULL PRIMARY KEY);
    CREATE TABLE #Regra (ORDEM INT IDENTITY(1,1), CODIGO VARCHAR(40) NOT NULL, NIVEL VARCHAR(12) NOT NULL,
                         MENSAGEM NVARCHAR(400) NOT NULL, ID_REFERENCIA BIGINT NULL, CAMPO VARCHAR(40) NOT NULL DEFAULT (''));

    BEGIN TRY
        SET @Motivo    = LTRIM(RTRIM(ISNULL(@Motivo, N'')));
        SET @DtEstorno = ISNULL(@DtEstorno, CONVERT(DATE, SYSDATETIME()));

        SELECT @Tipo = l.TIPO, @IdMovimento = b.ID_MOVIMENTO, @IdLoteOrig = b.ID_LOTE, @IdConta = b.ID_CONTA, @Estornada = b.ID_BAIXA_ESTORNADA
        FROM FIN.Baixa b
        INNER JOIN FIN.Parcela p    ON p.ID_PARCELA = b.ID_PARCELA
        INNER JOIN FIN.Lancamento l ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
        WHERE b.ID_BAIXA = @IdBaixa;
        SET @Item = CASE @Tipo WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END;
        SELECT @OrigemLote = x.ORIGEM FROM SIS.Lote x WHERE x.ID_LOTE = @IdLoteOrig;

        IF @Tipo IS NULL
            SET @Recusa = N'Baixa não encontrada.';
        IF @Recusa = N'' AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'ESTORNAR') = 0
            SET @Recusa = N'Você não tem permissão para estornar baixas.';
        IF @Recusa = N'' AND @Estornada IS NOT NULL
            SET @Recusa = N'Este registro já é um estorno.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM FIN.Baixa x WHERE x.ID_BAIXA_ESTORNADA = @IdBaixa)
            SET @Recusa = N'Esta baixa já foi estornada.';
        IF @Recusa = N'' AND @SomenteConferir = 0 AND LEN(@Motivo) < 5
            SET @Recusa = N'Informe o motivo do estorno.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdBaixa AS ID, 0 AS QTD_BAIXAS,
                   CAST(0 AS DECIMAL(18,2)) AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #B; DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        -- o que vai junto: as baixas do mesmo movimento (pagamento em lote) ainda não estornadas
        INSERT INTO #B (ID_BAIXA, ID_EMPRESA, ID_PLANO_CONTA, LIQUIDO)
        SELECT b.ID_BAIXA, l.ID_EMPRESA, l.ID_PLANO_CONTA, b.VALOR_LIQUIDO
        FROM FIN.Baixa b
        INNER JOIN FIN.Parcela p    ON p.ID_PARCELA = b.ID_PARCELA
        INNER JOIN FIN.Lancamento l ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
        WHERE (b.ID_BAIXA = @IdBaixa OR (@IdMovimento IS NOT NULL AND b.ID_MOVIMENTO = @IdMovimento))
          AND b.ID_BAIXA_ESTORNADA IS NULL
          AND NOT EXISTS (SELECT 1 FROM FIN.Baixa x WHERE x.ID_BAIXA_ESTORNADA = b.ID_BAIXA);

        -- movimentos: o da baixa e a tarifa do mesmo lote de baixa
        INSERT INTO #M (ID_MOVIMENTO)
        SELECT m.ID_MOVIMENTO
        FROM BANCO.Movimento m
        WHERE m.SITUACAO = 'ATIVO'
          AND (m.ID_MOVIMENTO = @IdMovimento
               OR (@OrigemLote = 'BAIXA' AND m.ID_LOTE = @IdLoteOrig AND m.TIPO = 'TARIFA'));

        SELECT @Qtd = COUNT(*), @Valor = SUM(LIQUIDO) FROM #B;

        -- regras na data do estorno
        SET @PodeRetro = SIS.fn_SIS_Tem_Permissao(@IdUsuario, @Item, 'LANCAR_RETROATIVO');
        IF FIN.fn_FIN_Data_Recusa('BAIXA', @DtEstorno) <> N''
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('DATA_BAIXA', CASE WHEN @PodeRetro = 1 THEN 'MOTIVO' ELSE 'BLOQUEIO' END, FIN.fn_FIN_Data_Recusa('BAIXA', @DtEstorno), 'dtEstorno');

        IF BANCO.fn_BANCO_Caixa_Recusa(@IdConta, @DtEstorno) <> N''
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO) VALUES ('CAIXA_FECHADO', 'BLOQUEIO', BANCO.fn_BANCO_Caixa_Recusa(@IdConta, @DtEstorno), 'dtEstorno');

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
        SELECT TOP 1 'MES_FECHADO', 'BLOQUEIO',
               N'O mês ' + RIGHT('0' + CONVERT(NVARCHAR(2), MONTH(m.MES)), 2) + N'/' + CONVERT(NVARCHAR(4), YEAR(m.MES)) + N' está fechado (conta contábil).', 'dtEstorno'
        FROM #B b
        INNER JOIN FIN.Mes_Fechado m  ON m.ID_EMPRESA = b.ID_EMPRESA AND m.MES = DATEFROMPARTS(YEAR(@DtEstorno), MONTH(@DtEstorno), 1) AND m.FECHADO = 1
        INNER JOIN CAD.Plano_Conta pc ON pc.ID_PLANO_CONTA = b.ID_PLANO_CONTA AND pc.CONTABIL = 1;

        IF @Qtd > 1
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('ESTORNO_LOTE', 'INFO', N'Esta baixa faz parte de um pagamento em lote: as ' + CONVERT(NVARCHAR(10), @Qtd)
                    + N' baixas do mesmo movimento serão estornadas juntas (' + FORMAT(@Valor, 'N2', 'pt-BR') + N').', '');

        SET @Avisos = ISNULL((SELECT r.CODIGO AS codigo, r.NIVEL AS nivel, r.MENSAGEM AS mensagem, r.ID_REFERENCIA AS idReferencia, r.CAMPO AS campo
                              FROM #Regra r ORDER BY CASE r.NIVEL WHEN 'BLOQUEIO' THEN 0 WHEN 'MOTIVO' THEN 1 ELSE 2 END, r.ORDEM
                              FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]');

        IF EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'BLOQUEIO')
        BEGIN
            SELECT TOP 1 @Recusa = r.MENSAGEM FROM #Regra r WHERE r.NIVEL = 'BLOQUEIO' ORDER BY r.ORDEM;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdBaixa AS ID, @Qtd AS QTD_BAIXAS,
                   @Valor AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #B; DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        IF @SomenteConferir = 1
        BEGIN
            SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Prévia do estorno.' AS NVARCHAR(400)) AS MENSAGEM, @IdBaixa AS ID, @Qtd AS QTD_BAIXAS,
                   @Valor AS VALOR, CAST(CASE WHEN EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') THEN 1 ELSE 0 END AS BIT) AS PENDENTE,
                   CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #B; DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        ---------------------------------------------------------------------
        -- Gravação
        ---------------------------------------------------------------------
        SET @Usuario = SIS.fn_SIS_Usuario_Login(@IdUsuario);
        SET @EtapaAtual = 'Gravação';
        BEGIN TRANSACTION;

        EXEC SIS.SIS_Lote_Gerar @IdUsuario = @IdUsuario, @Origem = 'ESTORNO_BAIXA', @Descricao = @Motivo,
             @TabelaReferencia = N'FIN.Baixa', @IdReferencia = @IdBaixa, @IdLote = @IdLote OUTPUT;

        -- concorrência: alguém estornou no meio
        IF EXISTS (SELECT 1 FROM #B b INNER JOIN FIN.Baixa x WITH (UPDLOCK, HOLDLOCK) ON x.ID_BAIXA_ESTORNADA = b.ID_BAIXA)
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'A baixa foi estornada por outra pessoa. Abra a ficha de novo.' AS NVARCHAR(400)) AS MENSAGEM,
                   @IdBaixa AS ID, 0 AS QTD_BAIXAS, CAST(0 AS DECIMAL(18,2)) AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #B; DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        DECLARE @Mov TABLE (ID_ORIGINAL BIGINT NOT NULL, ID_INVERSO BIGINT NOT NULL);

        MERGE BANCO.Movimento AS t
        USING (SELECT m.ID_MOVIMENTO, m.ID_CONTA, m.VALOR, m.TIPO, m.HISTORICO, m.DOCUMENTO
               FROM BANCO.Movimento m INNER JOIN #M x ON x.ID_MOVIMENTO = m.ID_MOVIMENTO) AS s
        ON 1 = 0
        WHEN NOT MATCHED THEN
            INSERT (ID_CONTA, DT_MOVIMENTO, VALOR, TIPO, HISTORICO, DOCUMENTO, SITUACAO, ID_LOTE, USUARIO_CRIACAO)
            VALUES (s.ID_CONTA, @DtEstorno, -s.VALOR, s.TIPO, LEFT(N'Estorno: ' + s.HISTORICO, 200), s.DOCUMENTO, 'ESTORNADO', @IdLote, ISNULL(@Usuario, N'sistema'))
        OUTPUT s.ID_MOVIMENTO, inserted.ID_MOVIMENTO INTO @Mov (ID_ORIGINAL, ID_INVERSO);

        UPDATE m
           SET m.SITUACAO = 'ESTORNADO', m.DT_ALTERACAO = SYSDATETIME(), m.USUARIO_ALTERACAO = @Usuario
        FROM BANCO.Movimento m INNER JOIN #M x ON x.ID_MOVIMENTO = m.ID_MOVIMENTO;

        INSERT INTO FIN.Baixa (ID_PARCELA, DT_PAGAMENTO, ID_CONTA, FORMA, VALOR_PRINCIPAL, JUROS, MULTA, CORRECAO, DESCONTO, ABATIMENTO,
                               TARIFA, RETENCAO, ID_MOVIMENTO, COMPENSADO, DT_COMPENSACAO, ID_BAIXA_ESTORNADA, OBSERVACAO, ID_LOTE, USUARIO_CRIACAO)
        SELECT b.ID_PARCELA, @DtEstorno, b.ID_CONTA, b.FORMA, -b.VALOR_PRINCIPAL, -b.JUROS, -b.MULTA, -b.CORRECAO, -b.DESCONTO, -b.ABATIMENTO,
               -b.TARIFA, -b.RETENCAO, mv.ID_INVERSO, b.COMPENSADO, b.DT_COMPENSACAO, b.ID_BAIXA, LEFT(N'Estorno: ' + @Motivo, 400), @IdLote, ISNULL(@Usuario, N'sistema')
        FROM FIN.Baixa b
        INNER JOIN #B x ON x.ID_BAIXA = b.ID_BAIXA
        LEFT  JOIN @Mov mv ON mv.ID_ORIGINAL = b.ID_MOVIMENTO;

        INSERT INTO SIS.Aviso_Confirmado (TABELA, ID_REGISTRO, CODIGO_REGRA, NIVEL, MENSAGEM, MOTIVO, ID_REFERENCIA, ID_USUARIO, USUARIO_CRIACAO)
        SELECT N'FIN.Baixa', b.ID_BAIXA, 'ESTORNO', 'MOTIVO', N'Baixa estornada em ' + CONVERT(NVARCHAR(10), @DtEstorno, 103) + N'.', @Motivo, NULL, @IdUsuario, ISNULL(@Usuario, N'sistema')
        FROM #B b
        UNION ALL
        SELECT N'FIN.Baixa', @IdBaixa, r.CODIGO, r.NIVEL, r.MENSAGEM, @Motivo, NULL, @IdUsuario, ISNULL(@Usuario, N'sistema')
        FROM #Regra r WHERE r.NIVEL = 'MOTIVO';

        EXEC SIS.SIS_Lote_Concluir @IdLote = @IdLote, @QtdRegistros = @Qtd;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(CASE WHEN @Qtd = 1 THEN N'Baixa estornada.' ELSE CONVERT(NVARCHAR(10), @Qtd) + N' baixas estornadas.' END AS NVARCHAR(400)) AS MENSAGEM,
               @IdBaixa AS ID, @Qtd AS QTD_BAIXAS, @Valor AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;

        DROP TABLE IF EXISTS #B; DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        DROP TABLE IF EXISTS #B; DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível estornar a baixa. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               @IdBaixa AS ID, 0 AS QTD_BAIXAS, CAST(0 AS DECIMAL(18,2)) AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Baixa_Preparar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Baixa_Preparar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 26/11/2026
  Descrição   : Janela de baixa (04g): dados das parcelas escolhidas para a
                data de pagamento, com a sugestão de juros, multa e limite de
                desconto (FIN.fn_FIN_Baixa_Sugerir), a pendência que bloqueia
                (FIN.fn_FIN_Pendencia_Bloqueia), a conta prevista e o que o
                usuário pode fazer (liberar pendência, desconto acima do
                limite, data fora da trava). Só leitura.
                @Parcelas: IDs separados por vírgula. @DtPagamento NULL = hoje.
                Permissão: BAIXAR em FIN_PAGAR / FIN_RECEBER (parcelas de tipo
                sem permissão não aparecem; nenhuma = erro 50001).
  Changelog:
    v1.0 (26/11/2026) - Criação (etapa 04g).
    v1.1 (27/11/2026) - Etapa 04g3: ID_CONTA_SUGERIDA (conta prevista da
                        parcela; senão a conta padrão da empresa; só conta
                        ativa) e FORMA_PADRAO (parâmetro FIN_BAIXA_FORMA_PADRAO)
                        para a janela de baixa já vir preenchida.
  Homologação (LOCAL):
    -- EXEC FIN.FIN_Baixa_Preparar @IdUsuario = 2, @Parcelas = N'1,2', @DtPagamento = '2026-11-26';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Baixa_Preparar]
    @IdUsuario    INT,
    @Parcelas     NVARCHAR(4000),
    @DtPagamento  DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PodeP BIT = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_PAGAR', 'BAIXAR');
    DECLARE @PodeR BIT = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'FIN_RECEBER', 'BAIXAR');
    SET @DtPagamento = ISNULL(@DtPagamento, CONVERT(DATE, SYSDATETIME()));
    DECLARE @Forma VARCHAR(12) = UPPER(LTRIM(RTRIM(ISNULL(CONVERT(VARCHAR(12), SIS.fn_SIS_Parametro('FIN_BAIXA_FORMA_PADRAO')), ''))));

    IF @PodeP = 0 AND @PodeR = 0
        THROW 50001, N'Você não tem permissão para baixar contas a pagar nem a receber.', 1;

    SELECT p.ID_PARCELA, p.ID_LANCAMENTO, l.TIPO, l.ID_EMPRESA, ISNULL(NULLIF(pe.NOME_FANTASIA, N''), pe.NOME) AS PESSOA,
           l.DOCUMENTO, l.HISTORICO, p.NUMERO, p.QTD_PARCELAS, p.DT_VENCIMENTO, p.VALOR, p.VALOR_BAIXADO, p.SALDO, p.SITUACAO,
           l.SITUACAO AS SITUACAO_LANCAMENTO, l.PREVISAO, p.ID_CONTA_PREVISTA,
           s.DIAS_ATRASO, s.CALCULA, s.MULTA, s.JUROS, s.DESCONTO_LIMITE, s.MULTA_PERC, s.JUROS_PERC, s.CARENCIA,
           b.BLOQUEIA AS BLOQUEIA_BAIXA, b.MOTIVO AS MOTIVO_BLOQUEIO,
           SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE l.TIPO WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'LIBERAR_PENDENCIA') AS PODE_LIBERAR_PENDENCIA,
           SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE l.TIPO WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'DESCONTO_LIMITE') AS PODE_DESCONTO_LIMITE,
           SIS.fn_SIS_Tem_Permissao(@IdUsuario, CASE l.TIPO WHEN 'P' THEN 'FIN_PAGAR' ELSE 'FIN_RECEBER' END, 'LANCAR_RETROATIVO') AS PODE_RETROATIVO,
           cs.ID_CONTA AS ID_CONTA_SUGERIDA, @Forma AS FORMA_PADRAO
    FROM (SELECT DISTINCT TRY_CONVERT(BIGINT, LTRIM(RTRIM(v.value))) AS ID FROM STRING_SPLIT(@Parcelas, N',') v) x
    INNER JOIN FIN.Parcela p    ON p.ID_PARCELA = x.ID
    INNER JOIN FIN.Lancamento l ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
    LEFT  JOIN CAD.Pessoa pe    ON pe.ID_PESSOA = l.ID_PESSOA
    CROSS APPLY FIN.fn_FIN_Baixa_Sugerir(p.ID_PARCELA, @DtPagamento, NULL) s
    CROSS APPLY FIN.fn_FIN_Pendencia_Bloqueia(p.ID_LANCAMENTO, p.ID_PARCELA) b
    LEFT  JOIN CAD.Empresa e    ON e.ID_EMPRESA = l.ID_EMPRESA
    OUTER APPLY (SELECT TOP (1) c.ID_CONTA
                 FROM BANCO.Conta c WITH (NOLOCK)
                 WHERE c.ATIVO = 1 AND c.DT_EXCLUSAO IS NULL
                   AND c.ID_CONTA IN (p.ID_CONTA_PREVISTA, e.ID_CONTA_BANCARIA_PADRAO)
                 ORDER BY CASE WHEN c.ID_CONTA = p.ID_CONTA_PREVISTA THEN 0 ELSE 1 END) cs
    WHERE (l.TIPO = 'P' AND @PodeP = 1) OR (l.TIPO = 'R' AND @PodeR = 1)
    ORDER BY p.DT_VENCIMENTO, pe.NOME, p.NUMERO;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Transferencia_Gravar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Transferencia_Gravar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 27/11/2026
  Descrição   : Transferência entre duas contas (etapa 04g2, desenho aprovado
                em 26/11/2026). Gera um lote (origem TRANSFERENCIA), a
                FIN.Transferencia e dois BANCO.Movimento TIPO TRANSFERENCIA
                (saída na origem, entrada no destino). Tudo-ou-nada.
                Regras (mesmo contrato da baixa: BLOQUEIO, MOTIVO, AVISO;
                @SomenteConferir = 1 é a prévia), sempre nas duas pontas:
                  BLOQUEIO  conta inexistente, desativada ou na lixeira;
                            caixa fechado (BANCO.fn_BANCO_Caixa_Recusa); mês
                            fechado da empresa da conta; trava de datas para
                            quem não tem LANCAR_RETROATIVO; entre empresas
                            com FIN_TRANSF_ENTRE_EMPRESAS = BLOQUEIO;
                  MOTIVO    trava de datas com LANCAR_RETROATIVO;
                  AVISO     entre empresas do grupo (ENTRE_EMPRESAS, com
                            FIN_TRANSF_ENTRE_EMPRESAS = AVISO); saldo da
                            origem na data, mais o limite, menor que o valor
                            (SALDO_INSUFICIENTE).
                Avisos e motivos em SIS.Aviso_Confirmado (TABELA
                FIN.Transferencia).
                Permissão: INCLUIR em BANCO_TRANSFERENCIA.
                Devolve 1 linha: SUCESSO, MENSAGEM, ID, ID_LOTE, PENDENTE,
                AVISOS (JSON: codigo, nivel, mensagem, idReferencia, campo).
  Changelog:
    v1.0 (27/11/2026) - Criação (etapa 04g2).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Transferencia_Gravar @IdUsuario = 2, @DtTransferencia = '2026-11-27', @IdContaOrigem = 1,
    --      @IdContaDestino = 2, @Valor = 100, @SomenteConferir = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Transferencia_Gravar]
    @IdUsuario          INT,
    @DtTransferencia    DATE            = NULL,
    @IdContaOrigem      INT             = NULL,
    @IdContaDestino     INT             = NULL,
    @Valor              DECIMAL(18,2)   = NULL,
    @Historico          NVARCHAR(200)   = NULL,
    @Documento          NVARCHAR(40)    = NULL,
    @AvisosConfirmados  NVARCHAR(1000)  = NULL,
    @Motivo             NVARCHAR(400)   = NULL,
    @SomenteConferir    BIT             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[FIN].[FIN_Transferencia_Gravar]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Validação';
    DECLARE @Recusa       NVARCHAR(400) = N'';
    DECLARE @Usuario      NVARCHAR(100);
    DECLARE @Avisos       NVARCHAR(MAX) = N'[]';
    DECLARE @Pendente     BIT = 0;
    DECLARE @EntreEmp     VARCHAR(10);
    DECLARE @IdLote       BIGINT;
    DECLARE @Id           BIGINT;
    DECLARE @NomeOrigem   NVARCHAR(60);
    DECLARE @NomeDestino  NVARCHAR(60);
    DECLARE @HistOrigem   NVARCHAR(200);
    DECLARE @HistDestino  NVARCHAR(200);
    DECLARE @Saldo        DECIMAL(18,2);
    DECLARE @Limite       DECIMAL(18,2);
    DECLARE @TemSaldo     BIT;

    CREATE TABLE #C (PONTA VARCHAR(7) NOT NULL PRIMARY KEY, ID_CONTA INT NULL, ID_EMPRESA INT NULL, DESCRICAO NVARCHAR(60) NULL,
                     ATIVO BIT NULL, NA_LIXEIRA BIT NULL);
    CREATE TABLE #Regra (ORDEM INT IDENTITY(1,1), CODIGO VARCHAR(40) NOT NULL, NIVEL VARCHAR(12) NOT NULL,
                         MENSAGEM NVARCHAR(400) NOT NULL, ID_REFERENCIA BIGINT NULL, CAMPO VARCHAR(40) NOT NULL DEFAULT (''));

    BEGIN TRY
        SET @Historico         = LTRIM(RTRIM(ISNULL(@Historico, N'')));
        SET @Documento         = LTRIM(RTRIM(ISNULL(@Documento, N'')));
        SET @Motivo            = LTRIM(RTRIM(ISNULL(@Motivo, N'')));
        SET @AvisosConfirmados = ISNULL(@AvisosConfirmados, N'');

        INSERT INTO #C (PONTA, ID_CONTA, ID_EMPRESA, DESCRICAO, ATIVO, NA_LIXEIRA)
        SELECT v.PONTA, c.ID_CONTA, c.ID_EMPRESA, c.DESCRICAO, c.ATIVO, CAST(CASE WHEN c.DT_EXCLUSAO IS NULL THEN 0 ELSE 1 END AS BIT)
        FROM (VALUES (CAST('ORIGEM' AS VARCHAR(7)), @IdContaOrigem), ('DESTINO', @IdContaDestino)) v (PONTA, ID)
        LEFT JOIN BANCO.Conta c ON c.ID_CONTA = v.ID;

        SELECT @NomeOrigem  = ISNULL(DESCRICAO, N'') FROM #C WHERE PONTA = 'ORIGEM';
        SELECT @NomeDestino = ISNULL(DESCRICAO, N'') FROM #C WHERE PONTA = 'DESTINO';

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_TRANSFERENCIA', 'INCLUIR') = 0
            SET @Recusa = N'Você não tem permissão para incluir transferências.';
        IF @Recusa = N'' AND @DtTransferencia IS NULL
            SET @Recusa = N'Informe a data da transferência.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #C WHERE PONTA = 'ORIGEM' AND ID_CONTA IS NULL)
            SET @Recusa = N'Escolha a conta de origem (de onde sai o dinheiro).';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #C WHERE PONTA = 'DESTINO' AND ID_CONTA IS NULL)
            SET @Recusa = N'Escolha a conta de destino (para onde vai o dinheiro).';
        IF @Recusa = N'' AND @IdContaOrigem = @IdContaDestino
            SET @Recusa = N'A conta de origem e a de destino precisam ser diferentes.';
        IF @Recusa = N'' AND ISNULL(@Valor, 0) <= 0
            SET @Recusa = N'Informe o valor da transferência.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID,
                   CAST(NULL AS BIGINT) AS ID_LOTE, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #C; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        ---------------------------------------------------------------------
        -- Regras (nas duas pontas)
        ---------------------------------------------------------------------
        SET @EtapaAtual = 'Regras';

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'CONTA_INATIVA', 'BLOQUEIO',
               N'A conta ' + c.DESCRICAO + CASE WHEN c.NA_LIXEIRA = 1 THEN N' está na lixeira.' ELSE N' está desativada.' END,
               c.ID_CONTA, CASE c.PONTA WHEN 'ORIGEM' THEN 'idContaOrigem' ELSE 'idContaDestino' END
        FROM #C c WHERE c.ATIVO = 0 OR c.NA_LIXEIRA = 1;

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'CAIXA_FECHADO', 'BLOQUEIO', BANCO.fn_BANCO_Caixa_Recusa(c.ID_CONTA, @DtTransferencia), c.ID_CONTA, 'dtTransferencia'
        FROM #C c WHERE BANCO.fn_BANCO_Caixa_Recusa(c.ID_CONTA, @DtTransferencia) <> N'';

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'MES_FECHADO', 'BLOQUEIO',
               N'O mês ' + RIGHT('0' + CONVERT(NVARCHAR(2), MONTH(m.MES)), 2) + N'/' + CONVERT(NVARCHAR(4), YEAR(m.MES))
               + N' está fechado na empresa da conta ' + c.DESCRICAO + N'.', c.ID_CONTA, 'dtTransferencia'
        FROM #C c
        INNER JOIN FIN.Mes_Fechado m ON m.ID_EMPRESA = c.ID_EMPRESA AND m.FECHADO = 1
                                    AND m.MES = DATEFROMPARTS(YEAR(@DtTransferencia), MONTH(@DtTransferencia), 1);

        IF FIN.fn_FIN_Data_Recusa('BAIXA', @DtTransferencia) <> N''
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('DATA_TRANSFERENCIA',
                    CASE WHEN SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_TRANSFERENCIA', 'LANCAR_RETROATIVO') = 1 THEN 'MOTIVO' ELSE 'BLOQUEIO' END,
                    REPLACE(FIN.fn_FIN_Data_Recusa('BAIXA', @DtTransferencia), N'de pagamento', N'da transferência'), 'dtTransferencia');

        SET @EntreEmp = UPPER(ISNULL(NULLIF(LTRIM(RTRIM(SIS.fn_SIS_Parametro('FIN_TRANSF_ENTRE_EMPRESAS'))), N''), N'AVISO'));
        IF @EntreEmp IN ('AVISO', 'BLOQUEIO')
           AND (SELECT COUNT(DISTINCT ID_EMPRESA) FROM #C) > 1
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            SELECT 'ENTRE_EMPRESAS', @EntreEmp,
                   CASE WHEN @EntreEmp = 'BLOQUEIO'
                        THEN N'Transferência entre contas de empresas diferentes não é permitida (parâmetro FIN_TRANSF_ENTRE_EMPRESAS).'
                        ELSE N'As contas são de empresas diferentes do grupo (' + ISNULL(NULLIF(eo.NOME_FANTASIA, N''), eo.RAZAO_SOCIAL) + N' → ' + ISNULL(NULLIF(ed.NOME_FANTASIA, N''), ed.RAZAO_SOCIAL)
                             + N'). Confira com a contabilidade (empréstimo entre empresas).' END,
                   'idContaDestino'
            FROM #C o
            INNER JOIN #C d ON d.PONTA = 'DESTINO'
            LEFT  JOIN CAD.Empresa eo ON eo.ID_EMPRESA = o.ID_EMPRESA
            LEFT  JOIN CAD.Empresa ed ON ed.ID_EMPRESA = d.ID_EMPRESA
            WHERE o.PONTA = 'ORIGEM';

        SELECT @Saldo = s.SALDO, @Limite = s.LIMITE_CREDITO, @TemSaldo = s.TEM_SALDO
        FROM BANCO.fn_BANCO_Conta_Saldo(@IdContaOrigem, @DtTransferencia) s;
        IF @TemSaldo = 1 AND @Saldo + ISNULL(@Limite, 0) < @Valor
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
            VALUES ('SALDO_INSUFICIENTE', 'AVISO',
                    N'O saldo da conta ' + @NomeOrigem + N' em ' + CONVERT(NVARCHAR(10), @DtTransferencia, 103) + N' é de '
                    + FORMAT(@Saldo, 'N2', 'pt-BR') + CASE WHEN ISNULL(@Limite, 0) > 0 THEN N' (limite ' + FORMAT(@Limite, 'N2', 'pt-BR') + N')' ELSE N'' END
                    + N', menor que o valor transferido. A conta ficará negativa.', @IdContaOrigem, 'valor');

        SET @Avisos = ISNULL((SELECT r.CODIGO AS codigo, r.NIVEL AS nivel, r.MENSAGEM AS mensagem, r.ID_REFERENCIA AS idReferencia, r.CAMPO AS campo
                              FROM #Regra r
                              ORDER BY CASE r.NIVEL WHEN 'BLOQUEIO' THEN 0 WHEN 'MOTIVO' THEN 1 ELSE 2 END, r.ORDEM
                              FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]');

        IF EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'BLOQUEIO')
        BEGIN
            SELECT TOP 1 @Recusa = r.MENSAGEM FROM #Regra r WHERE r.NIVEL = 'BLOQUEIO' ORDER BY r.ORDEM;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID,
                   CAST(NULL AS BIGINT) AS ID_LOTE, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #C; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        IF (EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') AND LEN(@Motivo) < 5)
           OR EXISTS (SELECT 1 FROM #Regra r WHERE r.NIVEL = 'AVISO'
                        AND NOT EXISTS (SELECT 1 FROM STRING_SPLIT(@AvisosConfirmados, N',') s WHERE LTRIM(RTRIM(s.value)) = r.CODIGO))
            SET @Pendente = 1;

        IF @SomenteConferir = 1 OR @Pendente = 1
        BEGIN
            SELECT CAST(CASE WHEN @SomenteConferir = 1 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
                   CAST(CASE WHEN @Pendente = 0 THEN N'Nada a confirmar.'
                             WHEN EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') AND LEN(@Motivo) < 5
                                  THEN N'Informe o motivo (justificativa) para gravar a transferência.'
                             ELSE N'Confira os avisos antes de gravar.' END AS NVARCHAR(400)) AS MENSAGEM,
                   CAST(NULL AS BIGINT) AS ID, CAST(NULL AS BIGINT) AS ID_LOTE, @Pendente AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #C; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        ---------------------------------------------------------------------
        -- Gravação
        ---------------------------------------------------------------------
        SET @EtapaAtual = 'Gravação';
        SET @Usuario     = ISNULL(SIS.fn_SIS_Usuario_Login(@IdUsuario), N'sistema');
        SET @HistOrigem  = LEFT(N'Transferência para ' + @NomeDestino + CASE WHEN @Historico <> N'' THEN N': ' + @Historico ELSE N'' END, 200);
        SET @HistDestino = LEFT(N'Transferência de ' + @NomeOrigem + CASE WHEN @Historico <> N'' THEN N': ' + @Historico ELSE N'' END, 200);

        BEGIN TRANSACTION;

        EXEC SIS.SIS_Lote_Gerar @IdUsuario = @IdUsuario, @Origem = 'TRANSFERENCIA', @Descricao = @HistOrigem,
             @TabelaReferencia = N'FIN.Transferencia', @IdReferencia = NULL, @IdLote = @IdLote OUTPUT;

        INSERT INTO FIN.Transferencia (DT_TRANSFERENCIA, ID_CONTA_ORIGEM, ID_CONTA_DESTINO, VALOR, HISTORICO, DOCUMENTO, SITUACAO, ID_LOTE, USUARIO_CRIACAO)
        VALUES (@DtTransferencia, @IdContaOrigem, @IdContaDestino, @Valor, @Historico, @Documento, 'ATIVA', @IdLote, @Usuario);
        SET @Id = SCOPE_IDENTITY();

        INSERT INTO BANCO.Movimento (ID_CONTA, DT_MOVIMENTO, VALOR, TIPO, HISTORICO, DOCUMENTO, ID_TRANSFERENCIA, SITUACAO, ID_LOTE, USUARIO_CRIACAO)
        VALUES (@IdContaOrigem,  @DtTransferencia, -@Valor, 'TRANSFERENCIA', @HistOrigem,  @Documento, @Id, 'ATIVO', @IdLote, @Usuario),
               (@IdContaDestino, @DtTransferencia,  @Valor, 'TRANSFERENCIA', @HistDestino, @Documento, @Id, 'ATIVO', @IdLote, @Usuario);

        INSERT INTO SIS.Aviso_Confirmado (TABELA, ID_REGISTRO, CODIGO_REGRA, NIVEL, MENSAGEM, MOTIVO, ID_REFERENCIA, ID_USUARIO, USUARIO_CRIACAO)
        SELECT N'FIN.Transferencia', @Id, r.CODIGO, r.NIVEL, r.MENSAGEM, CASE WHEN r.NIVEL = 'MOTIVO' THEN @Motivo ELSE N'' END,
               r.ID_REFERENCIA, @IdUsuario, @Usuario
        FROM #Regra r
        WHERE r.NIVEL IN ('AVISO', 'MOTIVO');

        EXEC SIS.SIS_Lote_Concluir @IdLote = @IdLote, @QtdRegistros = 1;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Transferência gravada.' AS NVARCHAR(400)) AS MENSAGEM, @Id AS ID, @IdLote AS ID_LOTE,
               CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;

        DROP TABLE IF EXISTS #C; DROP TABLE IF EXISTS #Regra;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        DROP TABLE IF EXISTS #C; DROP TABLE IF EXISTS #Regra;

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível gravar a transferência. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(NULL AS BIGINT) AS ID, CAST(NULL AS BIGINT) AS ID_LOTE, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Transferencia_Estornar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Transferencia_Estornar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 27/11/2026
  Descrição   : Estorna uma transferência (etapa 04g2). Nada é apagado: os
                dois movimentos ganham um movimento inverso na data do estorno
                (lote ESTORNO_TRANSFERENCIA); originais e inversos ficam
                ESTORNADO (o saldo soma os quatro e zera) e a transferência
                fica ESTORNADA com data, motivo e quem estornou.
                @DtEstorno (padrão hoje): nas duas contas valem a trava de
                datas (motivo com LANCAR_RETROATIVO), o caixa fechado e o mês
                fechado da empresa. Movimento já conciliado bloqueia (desfazer
                a conciliação antes). Motivo obrigatório.
                @SomenteConferir = 1: prévia, sem gravar.
                Permissão: ESTORNAR em BANCO_TRANSFERENCIA.
                Devolve SUCESSO, MENSAGEM, ID, VALOR, PENDENTE, AVISOS.
  Changelog:
    v1.0 (27/11/2026) - Criação (etapa 04g2).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Transferencia_Estornar @IdUsuario = 2, @IdTransferencia = 1, @Motivo = N'Conta errada', @SomenteConferir = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Transferencia_Estornar]
    @IdUsuario        INT,
    @IdTransferencia  BIGINT,
    @Motivo           NVARCHAR(400)  = NULL,
    @DtEstorno        DATE           = NULL,
    @SomenteConferir  BIT            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[FIN].[FIN_Transferencia_Estornar]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Validação';
    DECLARE @Recusa      NVARCHAR(400) = N'';
    DECLARE @Usuario     NVARCHAR(100);
    DECLARE @Situacao    VARCHAR(10);
    DECLARE @Valor       DECIMAL(18,2);
    DECLARE @IdLote      BIGINT;
    DECLARE @Avisos      NVARCHAR(MAX) = N'[]';
    DECLARE @Linhas      INT;

    CREATE TABLE #M (ID_MOVIMENTO BIGINT NOT NULL PRIMARY KEY, ID_CONTA INT NOT NULL, ID_EMPRESA INT NOT NULL, DESCRICAO NVARCHAR(60) NOT NULL, CONCILIADO BIT NOT NULL);
    CREATE TABLE #Regra (ORDEM INT IDENTITY(1,1), CODIGO VARCHAR(40) NOT NULL, NIVEL VARCHAR(12) NOT NULL,
                         MENSAGEM NVARCHAR(400) NOT NULL, ID_REFERENCIA BIGINT NULL, CAMPO VARCHAR(40) NOT NULL DEFAULT (''));

    BEGIN TRY
        SET @Motivo    = LTRIM(RTRIM(ISNULL(@Motivo, N'')));
        SET @DtEstorno = ISNULL(@DtEstorno, CONVERT(DATE, SYSDATETIME()));

        SELECT @Situacao = t.SITUACAO, @Valor = t.VALOR FROM FIN.Transferencia t WHERE t.ID_TRANSFERENCIA = @IdTransferencia;

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_TRANSFERENCIA', 'ESTORNAR') = 0
            SET @Recusa = N'Você não tem permissão para estornar transferências.';
        IF @Recusa = N'' AND @Situacao IS NULL
            SET @Recusa = N'Transferência não encontrada.';
        IF @Recusa = N'' AND @Situacao = 'ESTORNADA'
            SET @Recusa = N'Esta transferência já foi estornada.';
        IF @Recusa = N'' AND @SomenteConferir = 0 AND LEN(@Motivo) < 5
            SET @Recusa = N'Informe o motivo do estorno.';

        IF @Recusa = N''
            INSERT INTO #M (ID_MOVIMENTO, ID_CONTA, ID_EMPRESA, DESCRICAO, CONCILIADO)
            SELECT m.ID_MOVIMENTO, m.ID_CONTA, c.ID_EMPRESA, c.DESCRICAO, m.CONCILIADO
            FROM BANCO.Movimento m
            INNER JOIN BANCO.Conta c ON c.ID_CONTA = m.ID_CONTA
            WHERE m.ID_TRANSFERENCIA = @IdTransferencia AND m.SITUACAO = 'ATIVO';

        IF @Recusa = N'' AND NOT EXISTS (SELECT 1 FROM #M)
            SET @Recusa = N'A transferência não tem movimentos ativos para estornar.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdTransferencia AS ID,
                   CAST(ISNULL(@Valor, 0) AS DECIMAL(18,2)) AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        ---------------------------------------------------------------------
        -- Regras na data do estorno, nas duas contas
        ---------------------------------------------------------------------
        SET @EtapaAtual = 'Regras';

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'CONCILIADO', 'BLOQUEIO', N'O movimento na conta ' + m.DESCRICAO + N' já foi conciliado com o extrato do banco: desfaça a conciliação antes de estornar.',
               m.ID_CONTA, ''
        FROM #M m WHERE m.CONCILIADO = 1;

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'CAIXA_FECHADO', 'BLOQUEIO', BANCO.fn_BANCO_Caixa_Recusa(m.ID_CONTA, @DtEstorno), m.ID_CONTA, 'dtEstorno'
        FROM #M m WHERE BANCO.fn_BANCO_Caixa_Recusa(m.ID_CONTA, @DtEstorno) <> N'';

        INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, ID_REFERENCIA, CAMPO)
        SELECT 'MES_FECHADO', 'BLOQUEIO',
               N'O mês ' + RIGHT('0' + CONVERT(NVARCHAR(2), MONTH(f.MES)), 2) + N'/' + CONVERT(NVARCHAR(4), YEAR(f.MES))
               + N' está fechado na empresa da conta ' + m.DESCRICAO + N'.', m.ID_CONTA, 'dtEstorno'
        FROM #M m
        INNER JOIN FIN.Mes_Fechado f ON f.ID_EMPRESA = m.ID_EMPRESA AND f.FECHADO = 1
                                    AND f.MES = DATEFROMPARTS(YEAR(@DtEstorno), MONTH(@DtEstorno), 1);

        IF FIN.fn_FIN_Data_Recusa('BAIXA', @DtEstorno) <> N''
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('DATA_ESTORNO',
                    CASE WHEN SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_TRANSFERENCIA', 'LANCAR_RETROATIVO') = 1 THEN 'MOTIVO' ELSE 'BLOQUEIO' END,
                    REPLACE(FIN.fn_FIN_Data_Recusa('BAIXA', @DtEstorno), N'de pagamento', N'do estorno'), 'dtEstorno');

        SET @Avisos = ISNULL((SELECT r.CODIGO AS codigo, r.NIVEL AS nivel, r.MENSAGEM AS mensagem, r.ID_REFERENCIA AS idReferencia, r.CAMPO AS campo
                              FROM #Regra r ORDER BY CASE r.NIVEL WHEN 'BLOQUEIO' THEN 0 WHEN 'MOTIVO' THEN 1 ELSE 2 END, r.ORDEM
                              FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]');

        IF EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'BLOQUEIO')
        BEGIN
            SELECT TOP 1 @Recusa = r.MENSAGEM FROM #Regra r WHERE r.NIVEL = 'BLOQUEIO' ORDER BY r.ORDEM;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, @IdTransferencia AS ID,
                   @Valor AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        IF @SomenteConferir = 1
        BEGIN
            SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Prévia do estorno.' AS NVARCHAR(400)) AS MENSAGEM, @IdTransferencia AS ID, @Valor AS VALOR,
                   CAST(CASE WHEN EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') THEN 1 ELSE 0 END AS BIT) AS PENDENTE,
                   CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        ---------------------------------------------------------------------
        -- Gravação
        ---------------------------------------------------------------------
        SET @EtapaAtual = 'Gravação';
        SET @Usuario = ISNULL(SIS.fn_SIS_Usuario_Login(@IdUsuario), N'sistema');
        BEGIN TRANSACTION;

        -- concorrência: alguém estornou no meio
        UPDATE t
           SET t.SITUACAO = 'ESTORNADA', t.DT_ESTORNO = @DtEstorno, t.MOTIVO_ESTORNO = @Motivo, t.USUARIO_ESTORNO = @Usuario,
               t.DT_HORA_ESTORNO = SYSDATETIME(), t.DT_ALTERACAO = SYSDATETIME(), t.USUARIO_ALTERACAO = @Usuario
        FROM FIN.Transferencia t WITH (UPDLOCK, HOLDLOCK)
        WHERE t.ID_TRANSFERENCIA = @IdTransferencia AND t.SITUACAO = 'ATIVA';
        SET @Linhas = @@ROWCOUNT;

        IF @Linhas = 0
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'A transferência foi estornada por outra pessoa. Abra a lista de novo.' AS NVARCHAR(400)) AS MENSAGEM,
                   @IdTransferencia AS ID, @Valor AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        EXEC SIS.SIS_Lote_Gerar @IdUsuario = @IdUsuario, @Origem = 'ESTORNO_TRANSFERENCIA', @Descricao = @Motivo,
             @TabelaReferencia = N'FIN.Transferencia', @IdReferencia = @IdTransferencia, @IdLote = @IdLote OUTPUT;

        UPDATE t SET t.ID_LOTE_ESTORNO = @IdLote FROM FIN.Transferencia t WHERE t.ID_TRANSFERENCIA = @IdTransferencia;

        INSERT INTO BANCO.Movimento (ID_CONTA, DT_MOVIMENTO, VALOR, TIPO, HISTORICO, DOCUMENTO, ID_TRANSFERENCIA, SITUACAO, ID_LOTE, USUARIO_CRIACAO)
        SELECT m.ID_CONTA, @DtEstorno, -m.VALOR, m.TIPO, LEFT(N'Estorno: ' + m.HISTORICO, 200), m.DOCUMENTO, m.ID_TRANSFERENCIA, 'ESTORNADO', @IdLote, @Usuario
        FROM BANCO.Movimento m INNER JOIN #M x ON x.ID_MOVIMENTO = m.ID_MOVIMENTO;

        UPDATE m
           SET m.SITUACAO = 'ESTORNADO', m.DT_ALTERACAO = SYSDATETIME(), m.USUARIO_ALTERACAO = @Usuario
        FROM BANCO.Movimento m INNER JOIN #M x ON x.ID_MOVIMENTO = m.ID_MOVIMENTO;

        INSERT INTO SIS.Aviso_Confirmado (TABELA, ID_REGISTRO, CODIGO_REGRA, NIVEL, MENSAGEM, MOTIVO, ID_REFERENCIA, ID_USUARIO, USUARIO_CRIACAO)
        SELECT N'FIN.Transferencia', @IdTransferencia, 'ESTORNO', 'MOTIVO', N'Transferência estornada em ' + CONVERT(NVARCHAR(10), @DtEstorno, 103) + N'.',
               @Motivo, NULL, @IdUsuario, @Usuario
        UNION ALL
        SELECT N'FIN.Transferencia', @IdTransferencia, r.CODIGO, r.NIVEL, r.MENSAGEM, @Motivo, r.ID_REFERENCIA, @IdUsuario, @Usuario
        FROM #Regra r WHERE r.NIVEL = 'MOTIVO';

        EXEC SIS.SIS_Lote_Concluir @IdLote = @IdLote, @QtdRegistros = 1;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Transferência estornada.' AS NVARCHAR(400)) AS MENSAGEM, @IdTransferencia AS ID, @Valor AS VALOR,
               CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;

        DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        DROP TABLE IF EXISTS #M; DROP TABLE IF EXISTS #Regra;

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível estornar a transferência. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               @IdTransferencia AS ID, CAST(0 AS DECIMAL(18,2)) AS VALOR, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/FIN.FIN_Transferencia_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [FIN].[FIN_Transferencia_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 27/11/2026
  Descrição   : Lista das transferências (tela Bancos › Transferências,
                etapa 04g2). Filtros: período, conta (de um lado ou do outro),
                empresa, situação (ATIVA, ESTORNADA ou todas), só entre
                empresas, texto (histórico, documento, conta). Paginação
                (@Pagina, @PorPagina; padrão FIN_LISTA_POR_PAGINA).
                Cada linha traz TOTAL_LINHAS e TOTAL_VALOR (só das ativas) de
                todo o filtro e PODE_ESTORNAR.
                Permissão: VER em BANCO_TRANSFERENCIA (recusa por THROW 50001,
                como as outras listas).
  Changelog:
    v1.0 (27/11/2026) - Criação (etapa 04g2).

  Homologação (LOCAL):
    -- EXEC FIN.FIN_Transferencia_Listar @IdUsuario = 2, @DtDe = '2026-01-01', @DtAte = '2026-12-31';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [FIN].[FIN_Transferencia_Listar]
    @IdUsuario       INT,
    @DtDe            DATE           = NULL,
    @DtAte           DATE           = NULL,
    @IdConta         INT            = NULL,
    @IdEmpresa       INT            = NULL,
    @Situacao        VARCHAR(10)    = NULL,
    @EntreEmpresas   BIT            = 0,
    @Texto           NVARCHAR(100)  = NULL,
    @Pagina          INT            = 1,
    @PorPagina       INT            = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[FIN].[FIN_Transferencia_Listar]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Permissão';
    DECLARE @PodeEstornar BIT;

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_TRANSFERENCIA', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver as transferências.', 1;

        SET @EtapaAtual   = 'Consulta';
        SET @PodeEstornar = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_TRANSFERENCIA', 'ESTORNAR');
        SET @Situacao     = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@Situacao, '')))), '');
        SET @Texto        = NULLIF(LTRIM(RTRIM(ISNULL(@Texto, N''))), N'');
        SET @Pagina       = CASE WHEN ISNULL(@Pagina, 0) < 1 THEN 1 ELSE @Pagina END;
        SET @PorPagina    = ISNULL(@PorPagina, ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_LISTA_POR_PAGINA'), 100));
        IF @PorPagina NOT BETWEEN 10 AND 1000 SET @PorPagina = 100;

        ;WITH f AS
        (
            SELECT t.ID_TRANSFERENCIA, t.DT_TRANSFERENCIA, t.VALOR, t.SITUACAO, t.DT_CRIACAO,
                   COUNT(*) OVER () AS TOTAL_LINHAS,
                   SUM(CASE WHEN t.SITUACAO = 'ATIVA' THEN t.VALOR ELSE 0 END) OVER () AS TOTAL_VALOR
            FROM FIN.Transferencia t WITH (NOLOCK)
            INNER JOIN BANCO.Conta co WITH (NOLOCK) ON co.ID_CONTA = t.ID_CONTA_ORIGEM
            INNER JOIN BANCO.Conta cd WITH (NOLOCK) ON cd.ID_CONTA = t.ID_CONTA_DESTINO
            WHERE (@DtDe IS NULL OR t.DT_TRANSFERENCIA >= @DtDe)
              AND (@DtAte IS NULL OR t.DT_TRANSFERENCIA <= @DtAte)
              AND (@IdConta IS NULL OR t.ID_CONTA_ORIGEM = @IdConta OR t.ID_CONTA_DESTINO = @IdConta)
              AND (@IdEmpresa IS NULL OR co.ID_EMPRESA = @IdEmpresa OR cd.ID_EMPRESA = @IdEmpresa)
              AND (@Situacao IS NULL OR t.SITUACAO = @Situacao)
              AND (ISNULL(@EntreEmpresas, 0) = 0 OR co.ID_EMPRESA <> cd.ID_EMPRESA)
              AND (@Texto IS NULL OR t.HISTORICO LIKE N'%' + @Texto + N'%' OR t.DOCUMENTO LIKE N'%' + @Texto + N'%'
                   OR co.DESCRICAO LIKE N'%' + @Texto + N'%' OR cd.DESCRICAO LIKE N'%' + @Texto + N'%')
        ),
        pag AS
        (
            SELECT f.* FROM f
            ORDER BY f.DT_TRANSFERENCIA DESC, f.ID_TRANSFERENCIA DESC
            OFFSET (@Pagina - 1) * @PorPagina ROWS FETCH NEXT @PorPagina ROWS ONLY
        )
        SELECT t.ID_TRANSFERENCIA, t.DT_TRANSFERENCIA,
               t.ID_CONTA_ORIGEM,  co.DESCRICAO AS CONTA_ORIGEM,  co.ID_EMPRESA AS ID_EMPRESA_ORIGEM,
               ISNULL(NULLIF(eo.NOME_FANTASIA, N''), eo.RAZAO_SOCIAL) AS EMPRESA_ORIGEM,
               t.ID_CONTA_DESTINO, cd.DESCRICAO AS CONTA_DESTINO, cd.ID_EMPRESA AS ID_EMPRESA_DESTINO,
               ISNULL(NULLIF(ed.NOME_FANTASIA, N''), ed.RAZAO_SOCIAL) AS EMPRESA_DESTINO,
               CAST(CASE WHEN co.ID_EMPRESA <> cd.ID_EMPRESA THEN 1 ELSE 0 END AS BIT) AS ENTRE_EMPRESAS,
               t.VALOR, t.HISTORICO, t.DOCUMENTO, t.SITUACAO,
               ISNULL(CONVERT(VARCHAR(10), t.DT_ESTORNO, 23), '') AS DT_ESTORNO,
               ISNULL(t.MOTIVO_ESTORNO, N'') AS MOTIVO_ESTORNO, ISNULL(t.USUARIO_ESTORNO, N'') AS USUARIO_ESTORNO,
               t.USUARIO_CRIACAO, t.DT_CRIACAO, t.ID_LOTE,
               CAST(CASE WHEN t.CODIGO_ACCESS IS NULL THEN 0 ELSE 1 END AS BIT) AS MIGRADA,
               CAST(CASE WHEN @PodeEstornar = 1 AND t.SITUACAO = 'ATIVA' THEN 1 ELSE 0 END AS BIT) AS PODE_ESTORNAR,
               p.TOTAL_LINHAS, CAST(p.TOTAL_VALOR AS DECIMAL(18,2)) AS TOTAL_VALOR
        FROM pag p
        INNER JOIN FIN.Transferencia t WITH (NOLOCK) ON t.ID_TRANSFERENCIA = p.ID_TRANSFERENCIA
        INNER JOIN BANCO.Conta co WITH (NOLOCK) ON co.ID_CONTA = t.ID_CONTA_ORIGEM
        INNER JOIN BANCO.Conta cd WITH (NOLOCK) ON cd.ID_CONTA = t.ID_CONTA_DESTINO
        LEFT  JOIN CAD.Empresa eo WITH (NOLOCK) ON eo.ID_EMPRESA = co.ID_EMPRESA
        LEFT  JOIN CAD.Empresa ed WITH (NOLOCK) ON ed.ID_EMPRESA = cd.ID_EMPRESA
        ORDER BY t.DT_TRANSFERENCIA DESC, t.ID_TRANSFERENCIA DESC;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível listar as transferências. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/BANCO/BANCO.BANCO_Extrato_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [BANCO].[BANCO_Extrato_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 27/11/2026
  Descrição   : Extrato de uma conta no período (tela Bancos › Extrato e
                saldos, etapa 04g2). A 1ª linha é sempre o SALDO ANTERIOR
                (fim do dia anterior a @DtDe); se o saldo inicial da conta cai
                dentro do período, entra uma linha SALDO_INICIAL nessa data.
                Depois cada movimento, em ordem de data e de inclusão, com o
                SALDO_ACUMULADO. Regra de 19/11/2026: movimento com data
                anterior ao saldo inicial aparece como histórico
                (CONTA_SALDO = 0) e não mexe no saldo. Estornos entram (o par
                original + inverso zera); @OcultarEstornados = 1 só esconde
                as linhas (o saldo continua contando tudo).
                Origem de cada linha: baixa (lançamento, parceiro, quantas
                parcelas no pagamento em lote), transferência (a outra conta)
                ou o tipo do movimento.
                ENTRADA/SAIDA e os totais só contam os movimentos (o saldo
                inicial não é entrada). Todas as linhas trazem SALDO_ANTERIOR, TOTAL_ENTRADAS,
                TOTAL_SAIDAS e SALDO_FINAL do período.
                Período obrigatório, até BANCO_EXTRATO_MAX_DIAS dias.
                Permissão: VER em BANCO_EXTRATO (recusa por THROW 50001).
  Changelog:
    v1.0 (27/11/2026) - Criação (etapa 04g2).

  Homologação (LOCAL):
    -- EXEC BANCO.BANCO_Extrato_Listar @IdUsuario = 2, @IdConta = 1, @DtDe = '2026-11-01', @DtAte = '2026-11-30';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [BANCO].[BANCO_Extrato_Listar]
    @IdUsuario          INT,
    @IdConta            INT,
    @DtDe               DATE           = NULL,
    @DtAte              DATE           = NULL,
    @OcultarEstornados  BIT            = 0,
    @Texto              NVARCHAR(100)  = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[BANCO].[BANCO_Extrato_Listar]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Permissão';
    DECLARE @MaxDias      INT;
    DECLARE @DtSaldoIni   DATE;
    DECLARE @SaldoIni     DECIMAL(18,2);
    DECLARE @SaldoAnt     DECIMAL(18,2);
    DECLARE @DtAnterior   DATE;

    DROP TABLE IF EXISTS #L;

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_EXTRATO', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver o extrato das contas.', 1;

        SELECT @DtSaldoIni = c.DT_SALDO_INICIAL, @SaldoIni = c.SALDO_INICIAL FROM BANCO.Conta c WHERE c.ID_CONTA = @IdConta;
        IF @SaldoIni IS NULL
            THROW 50001, N'Escolha a conta.', 1;

        SET @DtAte   = ISNULL(@DtAte, CONVERT(DATE, SYSDATETIME()));
        SET @DtDe    = ISNULL(@DtDe, DATEFROMPARTS(YEAR(@DtAte), MONTH(@DtAte), 1));
        SET @MaxDias = ISNULL(SIS.fn_SIS_Parametro_Inteiro('BANCO_EXTRATO_MAX_DIAS'), 400);
        IF @DtDe > @DtAte
            THROW 50001, N'A data inicial é depois da final.', 1;
        IF DATEDIFF(DAY, @DtDe, @DtAte) + 1 > @MaxDias
            THROW 50001, N'Período grande demais para o extrato: escolha no máximo o número de dias do parâmetro BANCO_EXTRATO_MAX_DIAS.', 1;

        SET @Texto      = NULLIF(LTRIM(RTRIM(ISNULL(@Texto, N''))), N'');
        SET @DtAnterior = DATEADD(DAY, -1, @DtDe);

        SET @EtapaAtual = 'Saldo anterior';
        SELECT @SaldoAnt = s.SALDO FROM BANCO.fn_BANCO_Conta_Saldo(@IdConta, @DtAnterior) s;
        SET @SaldoAnt = ISNULL(@SaldoAnt, 0);

        SET @EtapaAtual = 'Linhas';
        CREATE TABLE #L
        (
            SEQ               INT            NOT NULL,
            DT_MOVIMENTO      DATE           NOT NULL,
            ID_MOVIMENTO      BIGINT         NULL,
            TIPO              VARCHAR(15)    NOT NULL,
            HISTORICO         NVARCHAR(200)  NOT NULL,
            DOCUMENTO         NVARCHAR(40)   NOT NULL,
            VALOR             DECIMAL(18,2)  NOT NULL,
            CONTA_SALDO       BIT            NOT NULL,
            SITUACAO          VARCHAR(10)    NOT NULL,
            CONCILIADO        BIT            NOT NULL,
            ID_TRANSFERENCIA  BIGINT         NULL,
            ID_LOTE           BIGINT         NULL,
            USUARIO_CRIACAO   NVARCHAR(100)  NOT NULL
        );

        INSERT INTO #L (SEQ, DT_MOVIMENTO, ID_MOVIMENTO, TIPO, HISTORICO, DOCUMENTO, VALOR, CONTA_SALDO, SITUACAO, CONCILIADO, ID_TRANSFERENCIA, ID_LOTE, USUARIO_CRIACAO)
        SELECT 0, @DtAnterior, NULL, 'SALDO_ANTERIOR', N'Saldo anterior', N'', @SaldoAnt, 0, 'ATIVO', 0, NULL, NULL, N''
        UNION ALL
        SELECT 1, @DtSaldoIni, NULL, 'SALDO_INICIAL', N'Saldo inicial da conta', N'', @SaldoIni, 1, 'ATIVO', 0, NULL, NULL, N''
        WHERE @DtSaldoIni BETWEEN @DtDe AND @DtAte
        UNION ALL
        SELECT 2, m.DT_MOVIMENTO, m.ID_MOVIMENTO, m.TIPO, m.HISTORICO, m.DOCUMENTO, m.VALOR,
               CAST(CASE WHEN @DtSaldoIni IS NULL OR m.DT_MOVIMENTO >= @DtSaldoIni THEN 1 ELSE 0 END AS BIT),
               m.SITUACAO, m.CONCILIADO, m.ID_TRANSFERENCIA, m.ID_LOTE, m.USUARIO_CRIACAO
        FROM BANCO.Movimento m WITH (NOLOCK)
        WHERE m.ID_CONTA = @IdConta AND m.DT_MOVIMENTO BETWEEN @DtDe AND @DtAte;

        SET @EtapaAtual = 'Consulta';
        ;WITH a AS
        (
            SELECT l.*,
                   CAST(@SaldoAnt + SUM(CASE WHEN l.SEQ > 0 AND l.CONTA_SALDO = 1 THEN l.VALOR ELSE 0 END)
                        OVER (ORDER BY l.DT_MOVIMENTO, l.SEQ, l.ID_MOVIMENTO ROWS UNBOUNDED PRECEDING) AS DECIMAL(18,2)) AS SALDO_ACUMULADO,
                   CAST(SUM(CASE WHEN l.SEQ = 2 AND l.CONTA_SALDO = 1 AND l.VALOR > 0 THEN l.VALOR ELSE 0 END) OVER () AS DECIMAL(18,2)) AS TOTAL_ENTRADAS,
                   CAST(SUM(CASE WHEN l.SEQ = 2 AND l.CONTA_SALDO = 1 AND l.VALOR < 0 THEN -l.VALOR ELSE 0 END) OVER () AS DECIMAL(18,2)) AS TOTAL_SAIDAS,
                   CAST(@SaldoAnt + SUM(CASE WHEN l.SEQ > 0 AND l.CONTA_SALDO = 1 THEN l.VALOR ELSE 0 END) OVER () AS DECIMAL(18,2)) AS SALDO_FINAL
            FROM #L l
        )
        SELECT a.DT_MOVIMENTO, a.ID_MOVIMENTO, a.TIPO, a.HISTORICO, a.DOCUMENTO, a.VALOR,
               CAST(CASE WHEN a.SEQ = 2 AND a.VALOR > 0 THEN a.VALOR ELSE 0 END AS DECIMAL(18,2)) AS ENTRADA,
               CAST(CASE WHEN a.SEQ = 2 AND a.VALOR < 0 THEN -a.VALOR ELSE 0 END AS DECIMAL(18,2)) AS SAIDA,
               a.SALDO_ACUMULADO, a.CONTA_SALDO, a.SITUACAO, a.CONCILIADO, a.ID_TRANSFERENCIA, a.ID_LOTE, a.USUARIO_CRIACAO,
               ISNULL(b.ID_LANCAMENTO, 0) AS ID_LANCAMENTO, ISNULL(b.LANC_TIPO, '') AS LANCAMENTO_TIPO, ISNULL(b.PESSOA, N'') AS PESSOA,
               ISNULL(b.QTD, 0) AS QTD_BAIXAS, ISNULL(oc.DESCRICAO, N'') AS OUTRA_CONTA,
               CAST(@SaldoAnt AS DECIMAL(18,2)) AS SALDO_ANTERIOR, a.TOTAL_ENTRADAS, a.TOTAL_SAIDAS, a.SALDO_FINAL
        FROM a
        OUTER APPLY (SELECT TOP 1 l.ID_LANCAMENTO, l.TIPO AS LANC_TIPO, ISNULL(NULLIF(pe.NOME_FANTASIA, N''), pe.NOME) AS PESSOA,
                            COUNT(*) OVER () AS QTD
                     FROM FIN.Baixa bx WITH (NOLOCK)
                     INNER JOIN FIN.Parcela p    WITH (NOLOCK) ON p.ID_PARCELA = bx.ID_PARCELA
                     INNER JOIN FIN.Lancamento l WITH (NOLOCK) ON l.ID_LANCAMENTO = p.ID_LANCAMENTO
                     LEFT  JOIN CAD.Pessoa pe    WITH (NOLOCK) ON pe.ID_PESSOA = l.ID_PESSOA
                     WHERE a.ID_MOVIMENTO IS NOT NULL AND bx.ID_MOVIMENTO = a.ID_MOVIMENTO
                     ORDER BY bx.ID_BAIXA) b
        OUTER APPLY (SELECT TOP 1 c.DESCRICAO
                     FROM FIN.Transferencia t WITH (NOLOCK)
                     INNER JOIN BANCO.Conta c WITH (NOLOCK) ON c.ID_CONTA = CASE WHEN t.ID_CONTA_ORIGEM = @IdConta THEN t.ID_CONTA_DESTINO ELSE t.ID_CONTA_ORIGEM END
                     WHERE a.ID_TRANSFERENCIA IS NOT NULL AND t.ID_TRANSFERENCIA = a.ID_TRANSFERENCIA
                     ORDER BY t.ID_TRANSFERENCIA) oc
        WHERE a.SEQ < 2
           OR ((ISNULL(@OcultarEstornados, 0) = 0 OR a.SITUACAO = 'ATIVO')
               AND (@Texto IS NULL OR a.HISTORICO LIKE N'%' + @Texto + N'%' OR a.DOCUMENTO LIKE N'%' + @Texto + N'%'
                    OR ISNULL(b.PESSOA, N'') LIKE N'%' + @Texto + N'%'))
        ORDER BY a.DT_MOVIMENTO, a.SEQ, a.ID_MOVIMENTO;

        DROP TABLE IF EXISTS #L;
    END TRY
    BEGIN CATCH
        DROP TABLE IF EXISTS #L;
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível montar o extrato. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/BANCO/BANCO.BANCO_Saldo_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [BANCO].[BANCO_Saldo_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 27/11/2026
  Descrição   : Saldos por conta numa data (tela Bancos › Extrato e saldos,
                etapa 04g2). Por padrão só as contas ativas marcadas "mostra
                saldo"; @Todas = 1 traz também as outras ativas e
                @IncluirInativas = 1 as desativadas. Saldo pela
                BANCO.fn_BANCO_Conta_Saldo (fonte única), disponível = saldo +
                limite, último movimento, movimentos não conciliados (contas
                que conciliam) e, para os tipos de FIN_CAIXA_FECHAMENTO_TIPOS,
                o último fechamento e se está atrasado (movimento em dia
                ainda não fechado há mais de FIN_CAIXA_FECHAMENTO_ATRASO_DIAS
                dias; 0 = não avisa).
                Permissão: VER em BANCO_EXTRATO ou BANCO_CAIXA (recusa por
                THROW 50001).
  Changelog:
    v1.0 (27/11/2026) - Criação (etapa 04g2).

  Homologação (LOCAL):
    -- EXEC BANCO.BANCO_Saldo_Listar @IdUsuario = 2, @Data = '2026-11-27';
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [BANCO].[BANCO_Saldo_Listar]
    @IdUsuario        INT,
    @Data             DATE  = NULL,
    @IdEmpresa        INT   = NULL,
    @Todas            BIT   = 0,
    @IncluirInativas  BIT   = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[BANCO].[BANCO_Saldo_Listar]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Permissão';
    DECLARE @Tipos       NVARCHAR(400);
    DECLARE @Atraso      INT;
    DECLARE @Hoje        DATE = CONVERT(DATE, SYSDATETIME());

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_EXTRATO', 'VER') = 0
           AND SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_CAIXA', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver os saldos das contas.', 1;

        SET @Data   = ISNULL(@Data, @Hoje);
        SET @Tipos  = N',' + REPLACE(UPPER(ISNULL(SIS.fn_SIS_Parametro('FIN_CAIXA_FECHAMENTO_TIPOS'), N'')), N' ', N'') + N',';
        SET @Atraso = ISNULL(SIS.fn_SIS_Parametro_Inteiro('FIN_CAIXA_FECHAMENTO_ATRASO_DIAS'), 1);

        SET @EtapaAtual = 'Consulta';
        SELECT c.ID_CONTA, c.ID_EMPRESA, ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL) AS EMPRESA,
               c.DESCRICAO, c.TIPO, ISNULL(b.NOME, N'') AS BANCO, c.AGENCIA, c.NUMERO, c.ORDEM, c.ATIVO, c.MOSTRA_SALDO, c.CONCILIA,
               s.SALDO, s.LIMITE_CREDITO, CAST(s.SALDO + s.LIMITE_CREDITO AS DECIMAL(18,2)) AS DISPONIVEL, s.TEM_SALDO,
               ISNULL(CONVERT(VARCHAR(10), s.DT_SALDO_INICIAL, 23), '') AS DT_SALDO_INICIAL,
               ISNULL(CONVERT(VARCHAR(10), um.DT, 23), '') AS DT_ULTIMO_MOVIMENTO,
               CAST(CASE WHEN c.CONCILIA = 1 THEN ISNULL(nc.QTD, 0) ELSE 0 END AS INT) AS QTD_NAO_CONCILIADOS,
               CAST(CASE WHEN CHARINDEX(N',' + c.TIPO + N',', @Tipos) > 0 THEN 1 ELSE 0 END AS BIT) AS USA_FECHAMENTO,
               ISNULL(CONVERT(VARCHAR(10), f.DT_FECHAMENTO, 23), '') AS DT_ULTIMO_FECHAMENTO,
               CAST(CASE WHEN CHARINDEX(N',' + c.TIPO + N',', @Tipos) > 0 AND @Atraso > 0 AND pf.DT IS NOT NULL
                              AND DATEDIFF(DAY, pf.DT, @Hoje) >= @Atraso THEN 1 ELSE 0 END AS BIT) AS FECHAMENTO_ATRASADO,
               ISNULL(CONVERT(VARCHAR(10), pf.DT, 23), '') AS DT_PRIMEIRO_SEM_FECHAR
        FROM BANCO.Conta c WITH (NOLOCK)
        INNER JOIN CAD.Empresa e WITH (NOLOCK) ON e.ID_EMPRESA = c.ID_EMPRESA
        LEFT  JOIN BANCO.Banco b WITH (NOLOCK) ON b.ID_BANCO = c.ID_BANCO
        CROSS APPLY BANCO.fn_BANCO_Conta_Saldo(c.ID_CONTA, @Data) s
        OUTER APPLY (SELECT MAX(m.DT_MOVIMENTO) AS DT FROM BANCO.Movimento m WITH (NOLOCK) WHERE m.ID_CONTA = c.ID_CONTA AND m.DT_MOVIMENTO <= @Data) um
        OUTER APPLY (SELECT COUNT(*) AS QTD FROM BANCO.Movimento m WITH (NOLOCK)
                     WHERE m.ID_CONTA = c.ID_CONTA AND m.CONCILIADO = 0 AND m.SITUACAO = 'ATIVO' AND m.DT_MOVIMENTO <= @Data
                       AND (c.DT_SALDO_INICIAL IS NULL OR m.DT_MOVIMENTO >= c.DT_SALDO_INICIAL)) nc
        OUTER APPLY (SELECT MAX(x.DT_FECHAMENTO) AS DT_FECHAMENTO FROM BANCO.Caixa_Fechamento x WITH (NOLOCK)
                     WHERE x.ID_CONTA = c.ID_CONTA AND x.SITUACAO = 'FECHADO') f
        OUTER APPLY (SELECT MIN(m.DT_MOVIMENTO) AS DT FROM BANCO.Movimento m WITH (NOLOCK)
                     WHERE m.ID_CONTA = c.ID_CONTA AND m.DT_MOVIMENTO < @Hoje
                       AND (f.DT_FECHAMENTO IS NULL OR m.DT_MOVIMENTO > f.DT_FECHAMENTO)
                       AND (c.DT_SALDO_INICIAL IS NULL OR m.DT_MOVIMENTO >= c.DT_SALDO_INICIAL)) pf
        WHERE c.DT_EXCLUSAO IS NULL
          AND (@IdEmpresa IS NULL OR c.ID_EMPRESA = @IdEmpresa)
          AND (c.ATIVO = 1 OR ISNULL(@IncluirInativas, 0) = 1)
          AND (c.MOSTRA_SALDO = 1 OR ISNULL(@Todas, 0) = 1 OR ISNULL(@IncluirInativas, 0) = 1)
        ORDER BY ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL), c.ORDEM, c.DESCRICAO;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível listar os saldos. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/BANCO/BANCO.BANCO_Caixa_Fechar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [BANCO].[BANCO_Caixa_Fechar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 27/11/2026
  Descrição   : Fechamento de caixa de uma conta até uma data (etapa 04g2,
                desenho aprovado em 26/11/2026). Compara o saldo do sistema
                no fim do dia (BANCO.fn_BANCO_Conta_Saldo) com o saldo
                contado. Diferença exige motivo; com @GerarAjuste = 1 (ação
                AJUSTE_CAIXA) grava um movimento AJUSTE pela diferença na
                data do fechamento, e o saldo do sistema passa a ser o
                contado. Fechado, a conta não aceita baixa, estorno,
                transferência nem ajuste com data até a do fechamento
                (BANCO.fn_BANCO_Caixa_Recusa).
                Regras: só os tipos de conta de FIN_CAIXA_FECHAMENTO_TIPOS;
                conta ativa; data até hoje, depois do último fechamento e não
                anterior ao saldo inicial; o ajuste segue a trava de datas.
                Mesmo contrato da baixa (BLOQUEIO, MOTIVO; @SomenteConferir = 1
                é a prévia: com @SaldoContado vazio devolve só o saldo do
                sistema e o movimento desde o último fechamento).
                Motivo e ajuste em SIS.Aviso_Confirmado (TABELA
                BANCO.Caixa_Fechamento, código DIFERENCA_CAIXA).
                Permissão: INCLUIR em BANCO_CAIXA (+ AJUSTE_CAIXA para o
                ajuste).
                Devolve 1 linha: SUCESSO, MENSAGEM, ID, SALDO_SISTEMA,
                SALDO_CONTADO, DIFERENCA, DT_ULTIMO_FECHAMENTO, ENTRADAS,
                SAIDAS, QTD_MOVIMENTOS (desde o último fechamento), PODE_AJUSTE,
                ID_MOVIMENTO_AJUSTE, PENDENTE, AVISOS.
  Changelog:
    v1.0 (27/11/2026) - Criação (etapa 04g2).

  Homologação (LOCAL):
    -- EXEC BANCO.BANCO_Caixa_Fechar @IdUsuario = 2, @IdConta = 1, @DtFechamento = '2026-11-26', @SomenteConferir = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [BANCO].[BANCO_Caixa_Fechar]
    @IdUsuario        INT,
    @IdConta          INT,
    @DtFechamento     DATE            = NULL,
    @SaldoContado     DECIMAL(18,2)   = NULL,
    @Motivo           NVARCHAR(400)   = NULL,
    @GerarAjuste      BIT             = 0,
    @Observacao       NVARCHAR(400)   = NULL,
    @SomenteConferir  BIT             = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[BANCO].[BANCO_Caixa_Fechar]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Validação';
    DECLARE @Recusa      NVARCHAR(400) = N'';
    DECLARE @Usuario     NVARCHAR(100);
    DECLARE @Hoje        DATE = CONVERT(DATE, SYSDATETIME());
    DECLARE @Tipos       NVARCHAR(400);
    DECLARE @TipoConta   VARCHAR(10);
    DECLARE @Ativa       BIT;
    DECLARE @NaLixeira   BIT;
    DECLARE @NomeConta   NVARCHAR(60);
    DECLARE @Ultimo      DATE;
    DECLARE @Sistema     DECIMAL(18,2);
    DECLARE @TemSaldo    BIT;
    DECLARE @Diferenca   DECIMAL(18,2) = 0;
    DECLARE @Entradas    DECIMAL(18,2) = 0;
    DECLARE @Saidas      DECIMAL(18,2) = 0;
    DECLARE @QtdMov      INT = 0;
    DECLARE @PodeAjuste  BIT;
    DECLARE @Avisos      NVARCHAR(MAX) = N'[]';
    DECLARE @Pendente    BIT = 0;
    DECLARE @IdLote      BIGINT;
    DECLARE @IdAjuste    BIGINT;
    DECLARE @Id          BIGINT;
    DECLARE @Hist        NVARCHAR(200);

    CREATE TABLE #Regra (ORDEM INT IDENTITY(1,1), CODIGO VARCHAR(40) NOT NULL, NIVEL VARCHAR(12) NOT NULL,
                         MENSAGEM NVARCHAR(400) NOT NULL, ID_REFERENCIA BIGINT NULL, CAMPO VARCHAR(40) NOT NULL DEFAULT (''));

    BEGIN TRY
        SET @Motivo      = LTRIM(RTRIM(ISNULL(@Motivo, N'')));
        SET @Observacao  = LTRIM(RTRIM(ISNULL(@Observacao, N'')));
        SET @GerarAjuste = ISNULL(@GerarAjuste, 0);
        SET @Tipos       = N',' + REPLACE(UPPER(ISNULL(SIS.fn_SIS_Parametro('FIN_CAIXA_FECHAMENTO_TIPOS'), N'')), N' ', N'') + N',';
        SET @PodeAjuste  = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_CAIXA', 'AJUSTE_CAIXA');

        SELECT @TipoConta = c.TIPO, @Ativa = c.ATIVO, @NomeConta = c.DESCRICAO, @NaLixeira = CAST(CASE WHEN c.DT_EXCLUSAO IS NULL THEN 0 ELSE 1 END AS BIT)
        FROM BANCO.Conta c WHERE c.ID_CONTA = @IdConta;
        SELECT @Ultimo = MAX(f.DT_FECHAMENTO) FROM BANCO.Caixa_Fechamento f WHERE f.ID_CONTA = @IdConta AND f.SITUACAO = 'FECHADO';

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_CAIXA', 'INCLUIR') = 0
            SET @Recusa = N'Você não tem permissão para fechar o caixa.';
        IF @Recusa = N'' AND @TipoConta IS NULL
            SET @Recusa = N'Escolha a conta.';
        IF @Recusa = N'' AND CHARINDEX(N',' + @TipoConta + N',', @Tipos) = 0
            SET @Recusa = N'Esta conta não usa o fechamento de caixa (tipos no parâmetro FIN_CAIXA_FECHAMENTO_TIPOS).';
        IF @Recusa = N'' AND (@Ativa = 0 OR @NaLixeira = 1)
            SET @Recusa = N'A conta ' + @NomeConta + N' está desativada.';
        IF @Recusa = N'' AND @DtFechamento IS NULL
            SET @Recusa = N'Informe a data do fechamento.';
        IF @Recusa = N'' AND @DtFechamento > @Hoje
            SET @Recusa = N'Não dá para fechar o caixa de um dia que ainda não chegou.';
        IF @Recusa = N'' AND @Ultimo IS NOT NULL AND @DtFechamento <= @Ultimo
            SET @Recusa = N'O caixa da conta ' + @NomeConta + N' já está fechado até ' + CONVERT(NVARCHAR(10), @Ultimo, 103) + N'.';

        IF @Recusa = N''
        BEGIN
            SELECT @Sistema = s.SALDO, @TemSaldo = s.TEM_SALDO FROM BANCO.fn_BANCO_Conta_Saldo(@IdConta, @DtFechamento) s;
            IF @TemSaldo = 0
                SET @Recusa = N'A data é anterior ao saldo inicial da conta: não há saldo oficial para fechar.';
        END;

        IF @Recusa = N'' AND @SomenteConferir = 0 AND @SaldoContado IS NULL
            SET @Recusa = N'Informe o saldo contado.';

        IF @Recusa <> N''
        BEGIN
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(@Recusa AS NVARCHAR(400)) AS MENSAGEM, CAST(NULL AS BIGINT) AS ID,
                   CAST(ISNULL(@Sistema, 0) AS DECIMAL(18,2)) AS SALDO_SISTEMA, CAST(ISNULL(@SaldoContado, 0) AS DECIMAL(18,2)) AS SALDO_CONTADO,
                   CAST(0 AS DECIMAL(18,2)) AS DIFERENCA, ISNULL(CONVERT(VARCHAR(10), @Ultimo, 23), '') AS DT_ULTIMO_FECHAMENTO,
                   CAST(0 AS DECIMAL(18,2)) AS ENTRADAS, CAST(0 AS DECIMAL(18,2)) AS SAIDAS, 0 AS QTD_MOVIMENTOS, ISNULL(@PodeAjuste, CAST(0 AS BIT)) AS PODE_AJUSTE,
                   CAST(NULL AS BIGINT) AS ID_MOVIMENTO_AJUSTE, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        -- movimento desde o último fechamento (ou do saldo inicial)
        SELECT @Entradas = ISNULL(SUM(CASE WHEN m.VALOR > 0 THEN m.VALOR ELSE 0 END), 0),
               @Saidas   = ISNULL(SUM(CASE WHEN m.VALOR < 0 THEN -m.VALOR ELSE 0 END), 0),
               @QtdMov   = COUNT(*)
        FROM BANCO.Movimento m
        INNER JOIN BANCO.Conta c ON c.ID_CONTA = m.ID_CONTA
        WHERE m.ID_CONTA = @IdConta AND m.DT_MOVIMENTO <= @DtFechamento
          AND (@Ultimo IS NULL OR m.DT_MOVIMENTO > @Ultimo)
          AND (c.DT_SALDO_INICIAL IS NULL OR m.DT_MOVIMENTO >= c.DT_SALDO_INICIAL);

        SET @Diferenca = CAST(ISNULL(@SaldoContado, @Sistema) - @Sistema AS DECIMAL(18,2));
        IF @Diferenca = 0 SET @GerarAjuste = 0;

        ---------------------------------------------------------------------
        -- Regras
        ---------------------------------------------------------------------
        SET @EtapaAtual = 'Regras';
        IF @Diferenca <> 0
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('DIFERENCA_CAIXA', 'MOTIVO',
                    N'Diferença de ' + FORMAT(@Diferenca, 'N2', 'pt-BR') + N' entre o saldo contado (' + FORMAT(@SaldoContado, 'N2', 'pt-BR')
                    + N') e o do sistema (' + FORMAT(@Sistema, 'N2', 'pt-BR') + N'): informe o motivo.', 'saldoContado');

        IF @GerarAjuste = 1 AND @PodeAjuste = 0
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('AJUSTE_SEM_PERMISSAO', 'BLOQUEIO', N'Você não tem permissão para ajustar a diferença do caixa: feche sem o ajuste ou peça a um administrador.', 'gerarAjuste');

        IF @GerarAjuste = 1 AND FIN.fn_FIN_Data_Recusa('BAIXA', @DtFechamento) <> N''
            INSERT INTO #Regra (CODIGO, NIVEL, MENSAGEM, CAMPO)
            VALUES ('DATA_AJUSTE', 'BLOQUEIO', REPLACE(FIN.fn_FIN_Data_Recusa('BAIXA', @DtFechamento), N'de pagamento', N'do ajuste'), 'dtFechamento');

        SET @Avisos = ISNULL((SELECT r.CODIGO AS codigo, r.NIVEL AS nivel, r.MENSAGEM AS mensagem, r.ID_REFERENCIA AS idReferencia, r.CAMPO AS campo
                              FROM #Regra r ORDER BY CASE r.NIVEL WHEN 'BLOQUEIO' THEN 0 WHEN 'MOTIVO' THEN 1 ELSE 2 END, r.ORDEM
                              FOR JSON PATH, INCLUDE_NULL_VALUES), N'[]');

        IF EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'BLOQUEIO')
            SELECT TOP 1 @Recusa = r.MENSAGEM FROM #Regra r WHERE r.NIVEL = 'BLOQUEIO' ORDER BY r.ORDEM;
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM #Regra WHERE NIVEL = 'MOTIVO') AND LEN(@Motivo) < 5
            SET @Pendente = 1;

        IF @Recusa <> N'' OR @SomenteConferir = 1 OR @Pendente = 1
        BEGIN
            SELECT CAST(CASE WHEN @Recusa = N'' AND @SomenteConferir = 1 THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
                   CAST(CASE WHEN @Recusa <> N'' THEN @Recusa
                             WHEN @Pendente = 1 THEN N'Informe o motivo da diferença para fechar o caixa.'
                             ELSE N'Prévia do fechamento.' END AS NVARCHAR(400)) AS MENSAGEM,
                   CAST(NULL AS BIGINT) AS ID, @Sistema AS SALDO_SISTEMA, CAST(ISNULL(@SaldoContado, @Sistema) AS DECIMAL(18,2)) AS SALDO_CONTADO,
                   @Diferenca AS DIFERENCA, ISNULL(CONVERT(VARCHAR(10), @Ultimo, 23), '') AS DT_ULTIMO_FECHAMENTO,
                   CAST(@Entradas AS DECIMAL(18,2)) AS ENTRADAS, CAST(@Saidas AS DECIMAL(18,2)) AS SAIDAS, @QtdMov AS QTD_MOVIMENTOS, @PodeAjuste AS PODE_AJUSTE,
                   CAST(NULL AS BIGINT) AS ID_MOVIMENTO_AJUSTE, @Pendente AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        ---------------------------------------------------------------------
        -- Gravação
        ---------------------------------------------------------------------
        SET @EtapaAtual = 'Gravação';
        SET @Usuario = ISNULL(SIS.fn_SIS_Usuario_Login(@IdUsuario), N'sistema');
        SET @Hist    = LEFT(N'Ajuste do fechamento de caixa de ' + CONVERT(NVARCHAR(10), @DtFechamento, 103) + N': ' + @Motivo, 200);

        BEGIN TRANSACTION;

        -- concorrência: outro fechamento da mesma conta no meio
        IF EXISTS (SELECT 1 FROM BANCO.Caixa_Fechamento f WITH (UPDLOCK, HOLDLOCK)
                   WHERE f.ID_CONTA = @IdConta AND f.SITUACAO = 'FECHADO' AND f.DT_FECHAMENTO >= @DtFechamento)
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'O caixa desta conta acabou de ser fechado por outra pessoa. Abra a tela de novo.' AS NVARCHAR(400)) AS MENSAGEM,
                   CAST(NULL AS BIGINT) AS ID, @Sistema AS SALDO_SISTEMA, @SaldoContado AS SALDO_CONTADO, @Diferenca AS DIFERENCA,
                   ISNULL(CONVERT(VARCHAR(10), @Ultimo, 23), '') AS DT_ULTIMO_FECHAMENTO, CAST(@Entradas AS DECIMAL(18,2)) AS ENTRADAS,
                   CAST(@Saidas AS DECIMAL(18,2)) AS SAIDAS, @QtdMov AS QTD_MOVIMENTOS, @PodeAjuste AS PODE_AJUSTE,
                   CAST(NULL AS BIGINT) AS ID_MOVIMENTO_AJUSTE, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;
            DROP TABLE IF EXISTS #Regra;
            RETURN;
        END;

        EXEC SIS.SIS_Lote_Gerar @IdUsuario = @IdUsuario, @Origem = 'CAIXA_FECHAMENTO', @Descricao = @NomeConta,
             @TabelaReferencia = N'BANCO.Caixa_Fechamento', @IdReferencia = NULL, @IdLote = @IdLote OUTPUT;

        IF @GerarAjuste = 1
        BEGIN
            INSERT INTO BANCO.Movimento (ID_CONTA, DT_MOVIMENTO, VALOR, TIPO, HISTORICO, SITUACAO, ID_LOTE, USUARIO_CRIACAO)
            VALUES (@IdConta, @DtFechamento, @Diferenca, 'AJUSTE', @Hist, 'ATIVO', @IdLote, @Usuario);
            SET @IdAjuste = SCOPE_IDENTITY();
        END;

        INSERT INTO BANCO.Caixa_Fechamento (ID_CONTA, DT_FECHAMENTO, SALDO_SISTEMA, SALDO_CONTADO, MOTIVO_DIFERENCA, ID_MOVIMENTO_AJUSTE, OBSERVACAO, SITUACAO, USUARIO_CRIACAO)
        VALUES (@IdConta, @DtFechamento, @Sistema, @SaldoContado, CASE WHEN @Diferenca <> 0 THEN @Motivo ELSE N'' END, @IdAjuste, @Observacao, 'FECHADO', @Usuario);
        SET @Id = SCOPE_IDENTITY();

        INSERT INTO SIS.Aviso_Confirmado (TABELA, ID_REGISTRO, CODIGO_REGRA, NIVEL, MENSAGEM, MOTIVO, ID_REFERENCIA, ID_USUARIO, USUARIO_CRIACAO)
        SELECT N'BANCO.Caixa_Fechamento', @Id, r.CODIGO, r.NIVEL,
               LEFT(r.MENSAGEM + CASE WHEN @IdAjuste IS NOT NULL THEN N' Ajuste gravado.' ELSE N' Sem ajuste.' END, 400),
               @Motivo, @IdAjuste, @IdUsuario, @Usuario
        FROM #Regra r WHERE r.NIVEL = 'MOTIVO';

        EXEC SIS.SIS_Lote_Concluir @IdLote = @IdLote, @QtdRegistros = 1;

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO,
               CAST(N'Caixa da conta ' + @NomeConta + N' fechado até ' + CONVERT(NVARCHAR(10), @DtFechamento, 103)
                    + CASE WHEN @IdAjuste IS NOT NULL THEN N', com ajuste de ' + FORMAT(@Diferenca, 'N2', 'pt-BR') ELSE N'' END + N'.' AS NVARCHAR(400)) AS MENSAGEM,
               @Id AS ID, @Sistema AS SALDO_SISTEMA, @SaldoContado AS SALDO_CONTADO, @Diferenca AS DIFERENCA,
               ISNULL(CONVERT(VARCHAR(10), @Ultimo, 23), '') AS DT_ULTIMO_FECHAMENTO, CAST(@Entradas AS DECIMAL(18,2)) AS ENTRADAS,
               CAST(@Saidas AS DECIMAL(18,2)) AS SAIDAS, @QtdMov AS QTD_MOVIMENTOS, @PodeAjuste AS PODE_AJUSTE,
               @IdAjuste AS ID_MOVIMENTO_AJUSTE, CAST(0 AS BIT) AS PENDENTE, CAST(@Avisos AS NVARCHAR(MAX)) AS AVISOS;

        DROP TABLE IF EXISTS #Regra;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        DROP TABLE IF EXISTS #Regra;

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível fechar o caixa. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               CAST(NULL AS BIGINT) AS ID, CAST(0 AS DECIMAL(18,2)) AS SALDO_SISTEMA, CAST(0 AS DECIMAL(18,2)) AS SALDO_CONTADO,
               CAST(0 AS DECIMAL(18,2)) AS DIFERENCA, CAST('' AS VARCHAR(10)) AS DT_ULTIMO_FECHAMENTO, CAST(0 AS DECIMAL(18,2)) AS ENTRADAS,
               CAST(0 AS DECIMAL(18,2)) AS SAIDAS, 0 AS QTD_MOVIMENTOS, CAST(0 AS BIT) AS PODE_AJUSTE,
               CAST(NULL AS BIGINT) AS ID_MOVIMENTO_AJUSTE, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/BANCO/BANCO.BANCO_Caixa_Reabrir.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [BANCO].[BANCO_Caixa_Reabrir]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 27/11/2026
  Descrição   : Reabre um fechamento de caixa (etapa 04g2). Só o último
                fechamento da conta (para voltar mais, reabrir um de cada
                vez, do mais novo para o mais antigo). Motivo obrigatório.
                Se o fechamento gravou um AJUSTE, o ajuste é desfeito
                (movimento inverso na mesma data; os dois ficam ESTORNADO),
                para o próximo fechamento partir do saldo real. Ajuste já
                conciliado bloqueia. O registro fica REABERTO com data, quem
                e motivo (nada é apagado).
                @SomenteConferir = 1: prévia (diz se há ajuste a desfazer).
                Permissão: REABRIR em BANCO_CAIXA.
                Devolve SUCESSO, MENSAGEM, ID, VALOR_AJUSTE, PENDENTE, AVISOS.
  Changelog:
    v1.0 (27/11/2026) - Criação (etapa 04g2).

  Homologação (LOCAL):
    -- EXEC BANCO.BANCO_Caixa_Reabrir @IdUsuario = 2, @IdCaixaFechamento = 1, @Motivo = N'Recebimento esquecido', @SomenteConferir = 1;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [BANCO].[BANCO_Caixa_Reabrir]
    @IdUsuario          INT,
    @IdCaixaFechamento  BIGINT,
    @Motivo             NVARCHAR(400)  = NULL,
    @SomenteConferir    BIT            = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc    NVARCHAR(128) = N'[BANCO].[BANCO_Caixa_Reabrir]';
    DECLARE @EtapaAtual  VARCHAR(100)  = 'Validação';
    DECLARE @Recusa      NVARCHAR(400) = N'';
    DECLARE @Usuario     NVARCHAR(100);
    DECLARE @IdConta     INT;
    DECLARE @Data        DATE;
    DECLARE @Situacao    VARCHAR(10);
    DECLARE @IdAjuste    BIGINT;
    DECLARE @ValorAjuste DECIMAL(18,2) = 0;
    DECLARE @AjusteConc  BIT = 0;
    DECLARE @AjusteSit   VARCHAR(10);
    DECLARE @IdLote      BIGINT;
    DECLARE @Linhas      INT;
    DECLARE @Avisos      NVARCHAR(MAX) = N'[]';

    BEGIN TRY
        SET @Motivo = LTRIM(RTRIM(ISNULL(@Motivo, N'')));

        SELECT @IdConta = f.ID_CONTA, @Data = f.DT_FECHAMENTO, @Situacao = f.SITUACAO, @IdAjuste = f.ID_MOVIMENTO_AJUSTE
        FROM BANCO.Caixa_Fechamento f WHERE f.ID_CAIXA_FECHAMENTO = @IdCaixaFechamento;
        SELECT @ValorAjuste = m.VALOR, @AjusteConc = m.CONCILIADO, @AjusteSit = m.SITUACAO FROM BANCO.Movimento m WHERE m.ID_MOVIMENTO = @IdAjuste;

        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_CAIXA', 'REABRIR') = 0
            SET @Recusa = N'Você não tem permissão para reabrir o caixa.';
        IF @Recusa = N'' AND @Situacao IS NULL
            SET @Recusa = N'Fechamento não encontrado.';
        IF @Recusa = N'' AND @Situacao = 'REABERTO'
            SET @Recusa = N'Este fechamento já foi reaberto.';
        IF @Recusa = N'' AND EXISTS (SELECT 1 FROM BANCO.Caixa_Fechamento f WHERE f.ID_CONTA = @IdConta AND f.SITUACAO = 'FECHADO' AND f.DT_FECHAMENTO > @Data)
            SET @Recusa = N'Há um fechamento mais novo nesta conta: reabra primeiro o mais novo.';
        IF @Recusa = N'' AND @AjusteConc = 1
            SET @Recusa = N'O ajuste deste fechamento já foi conciliado: desfaça a conciliação antes de reabrir.';
        IF @Recusa = N'' AND @SomenteConferir = 0 AND LEN(@Motivo) < 5
            SET @Recusa = N'Informe o motivo da reabertura.';

        IF @AjusteSit = 'ESTORNADO' SET @ValorAjuste = 0;

        IF @Recusa = N'' AND @ValorAjuste <> 0
            SET @Avisos = (SELECT 'AJUSTE_DESFEITO' AS codigo, 'INFO' AS nivel,
                                  N'O ajuste de ' + FORMAT(@ValorAjuste, 'N2', 'pt-BR') + N' gravado neste fechamento será desfeito.' AS mensagem,
                                  @IdAjuste AS idReferencia, '' AS campo
                           FOR JSON PATH, INCLUDE_NULL_VALUES);

        IF @Recusa <> N'' OR @SomenteConferir = 1
        BEGIN
            SELECT CAST(CASE WHEN @Recusa = N'' THEN 1 ELSE 0 END AS BIT) AS SUCESSO,
                   CAST(CASE WHEN @Recusa <> N'' THEN @Recusa ELSE N'Prévia da reabertura.' END AS NVARCHAR(400)) AS MENSAGEM,
                   @IdCaixaFechamento AS ID, CAST(ISNULL(@ValorAjuste, 0) AS DECIMAL(18,2)) AS VALOR_AJUSTE, CAST(0 AS BIT) AS PENDENTE,
                   CAST(ISNULL(@Avisos, N'[]') AS NVARCHAR(MAX)) AS AVISOS;
            RETURN;
        END;

        SET @EtapaAtual = 'Gravação';
        SET @Usuario = ISNULL(SIS.fn_SIS_Usuario_Login(@IdUsuario), N'sistema');
        BEGIN TRANSACTION;

        UPDATE f
           SET f.SITUACAO = 'REABERTO', f.DT_REABERTURA = SYSDATETIME(), f.USUARIO_REABERTURA = @Usuario, f.MOTIVO_REABERTURA = @Motivo,
               f.DT_ALTERACAO = SYSDATETIME(), f.USUARIO_ALTERACAO = @Usuario
        FROM BANCO.Caixa_Fechamento f WITH (UPDLOCK, HOLDLOCK)
        WHERE f.ID_CAIXA_FECHAMENTO = @IdCaixaFechamento AND f.SITUACAO = 'FECHADO';
        SET @Linhas = @@ROWCOUNT;

        IF @Linhas = 0
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'O fechamento foi reaberto por outra pessoa. Abra a tela de novo.' AS NVARCHAR(400)) AS MENSAGEM,
                   @IdCaixaFechamento AS ID, CAST(0 AS DECIMAL(18,2)) AS VALOR_AJUSTE, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
            RETURN;
        END;

        IF @ValorAjuste <> 0
        BEGIN
            EXEC SIS.SIS_Lote_Gerar @IdUsuario = @IdUsuario, @Origem = 'CAIXA_REABERTURA', @Descricao = @Motivo,
                 @TabelaReferencia = N'BANCO.Caixa_Fechamento', @IdReferencia = @IdCaixaFechamento, @IdLote = @IdLote OUTPUT;

            INSERT INTO BANCO.Movimento (ID_CONTA, DT_MOVIMENTO, VALOR, TIPO, HISTORICO, SITUACAO, ID_LOTE, USUARIO_CRIACAO)
            SELECT m.ID_CONTA, m.DT_MOVIMENTO, -m.VALOR, m.TIPO, LEFT(N'Estorno (caixa reaberto): ' + m.HISTORICO, 200), 'ESTORNADO', @IdLote, @Usuario
            FROM BANCO.Movimento m WHERE m.ID_MOVIMENTO = @IdAjuste;

            UPDATE m SET m.SITUACAO = 'ESTORNADO', m.DT_ALTERACAO = SYSDATETIME(), m.USUARIO_ALTERACAO = @Usuario
            FROM BANCO.Movimento m WHERE m.ID_MOVIMENTO = @IdAjuste;

            EXEC SIS.SIS_Lote_Concluir @IdLote = @IdLote, @QtdRegistros = 1;
        END;

        INSERT INTO SIS.Aviso_Confirmado (TABELA, ID_REGISTRO, CODIGO_REGRA, NIVEL, MENSAGEM, MOTIVO, ID_REFERENCIA, ID_USUARIO, USUARIO_CRIACAO)
        VALUES (N'BANCO.Caixa_Fechamento', @IdCaixaFechamento, 'REABERTURA_CAIXA', 'MOTIVO',
                N'Caixa reaberto (fechamento de ' + CONVERT(NVARCHAR(10), @Data, 103) + N')' + CASE WHEN @ValorAjuste <> 0 THEN N', ajuste desfeito.' ELSE N'.' END,
                @Motivo, @IdAjuste, @IdUsuario, @Usuario);

        COMMIT TRANSACTION;

        SELECT CAST(1 AS BIT) AS SUCESSO, CAST(N'Caixa reaberto.' AS NVARCHAR(400)) AS MENSAGEM, @IdCaixaFechamento AS ID,
               CAST(@ValorAjuste AS DECIMAL(18,2)) AS VALOR_AJUSTE, CAST(0 AS BIT) AS PENDENTE, CAST(ISNULL(@Avisos, N'[]') AS NVARCHAR(MAX)) AS AVISOS;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        SELECT CAST(0 AS BIT) AS SUCESSO, CAST(N'Não foi possível reabrir o caixa. O erro foi registrado para análise.' AS NVARCHAR(400)) AS MENSAGEM,
               @IdCaixaFechamento AS ID, CAST(0 AS DECIMAL(18,2)) AS VALOR_AJUSTE, CAST(0 AS BIT) AS PENDENTE, CAST(N'[]' AS NVARCHAR(MAX)) AS AVISOS;
    END CATCH;
END;
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/BANCO/BANCO.BANCO_Caixa_Listar.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : [BANCO].[BANCO_Caixa_Listar]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 27/11/2026
  Descrição   : Histórico dos fechamentos de caixa (tela Bancos › Fechamento
                de caixa, etapa 04g2): conta, data, saldo do sistema,
                contado, diferença com motivo, ajuste, quem fechou e a
                reabertura. Filtros: conta, empresa, período, situação
                (FECHADO, REABERTO ou todos), só com diferença.
                PODE_REABRIR: o último fechamento FECHADO da conta, para
                quem tem REABRIR. As contas que faltam fechar vêm da
                BANCO_Saldo_Listar (FECHAMENTO_ATRASADO).
                Permissão: VER em BANCO_CAIXA (recusa por THROW 50001).
  Changelog:
    v1.0 (27/11/2026) - Criação (etapa 04g2).

  Homologação (LOCAL):
    -- EXEC BANCO.BANCO_Caixa_Listar @IdUsuario = 2;
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

CREATE OR ALTER PROCEDURE [BANCO].[BANCO_Caixa_Listar]
    @IdUsuario       INT,
    @IdConta         INT          = NULL,
    @IdEmpresa       INT          = NULL,
    @DtDe            DATE         = NULL,
    @DtAte           DATE         = NULL,
    @Situacao        VARCHAR(10)  = NULL,
    @SoComDiferenca  BIT          = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @NomeProc     NVARCHAR(128) = N'[BANCO].[BANCO_Caixa_Listar]';
    DECLARE @EtapaAtual   VARCHAR(100)  = 'Permissão';
    DECLARE @PodeReabrir  BIT;

    BEGIN TRY
        IF SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_CAIXA', 'VER') = 0
            THROW 50001, N'Você não tem permissão para ver os fechamentos de caixa.', 1;

        SET @EtapaAtual  = 'Consulta';
        SET @PodeReabrir = SIS.fn_SIS_Tem_Permissao(@IdUsuario, 'BANCO_CAIXA', 'REABRIR');
        SET @Situacao    = NULLIF(UPPER(LTRIM(RTRIM(ISNULL(@Situacao, '')))), '');

        SELECT f.ID_CAIXA_FECHAMENTO, f.ID_CONTA, c.DESCRICAO AS CONTA, c.ID_EMPRESA, ISNULL(NULLIF(e.NOME_FANTASIA, N''), e.RAZAO_SOCIAL) AS EMPRESA,
               f.DT_FECHAMENTO, f.SALDO_SISTEMA, f.SALDO_CONTADO, f.DIFERENCA, f.MOTIVO_DIFERENCA, f.OBSERVACAO,
               ISNULL(f.ID_MOVIMENTO_AJUSTE, 0) AS ID_MOVIMENTO_AJUSTE, CAST(ISNULL(m.VALOR, 0) AS DECIMAL(18,2)) AS VALOR_AJUSTE,
               CAST(CASE WHEN m.SITUACAO = 'ESTORNADO' THEN 1 ELSE 0 END AS BIT) AS AJUSTE_DESFEITO,
               f.SITUACAO, f.USUARIO_CRIACAO, f.DT_CRIACAO,
               ISNULL(CONVERT(VARCHAR(19), f.DT_REABERTURA, 120), '') AS DT_REABERTURA, ISNULL(f.USUARIO_REABERTURA, N'') AS USUARIO_REABERTURA,
               ISNULL(f.MOTIVO_REABERTURA, N'') AS MOTIVO_REABERTURA,
               CAST(CASE WHEN @PodeReabrir = 1 AND f.SITUACAO = 'FECHADO'
                              AND NOT EXISTS (SELECT 1 FROM BANCO.Caixa_Fechamento x WITH (NOLOCK)
                                              WHERE x.ID_CONTA = f.ID_CONTA AND x.SITUACAO = 'FECHADO' AND x.DT_FECHAMENTO > f.DT_FECHAMENTO)
                         THEN 1 ELSE 0 END AS BIT) AS PODE_REABRIR
        FROM BANCO.Caixa_Fechamento f WITH (NOLOCK)
        INNER JOIN BANCO.Conta c   WITH (NOLOCK) ON c.ID_CONTA = f.ID_CONTA
        INNER JOIN CAD.Empresa e   WITH (NOLOCK) ON e.ID_EMPRESA = c.ID_EMPRESA
        LEFT  JOIN BANCO.Movimento m WITH (NOLOCK) ON m.ID_MOVIMENTO = f.ID_MOVIMENTO_AJUSTE
        WHERE (@IdConta IS NULL OR f.ID_CONTA = @IdConta)
          AND (@IdEmpresa IS NULL OR c.ID_EMPRESA = @IdEmpresa)
          AND (@DtDe IS NULL OR f.DT_FECHAMENTO >= @DtDe)
          AND (@DtAte IS NULL OR f.DT_FECHAMENTO <= @DtAte)
          AND (@Situacao IS NULL OR f.SITUACAO = @Situacao)
          AND (ISNULL(@SoComDiferenca, 0) = 0 OR f.DIFERENCA <> 0)
        ORDER BY f.DT_FECHAMENTO DESC, c.DESCRICAO, f.ID_CAIXA_FECHAMENTO DESC;
    END TRY
    BEGIN CATCH
        IF ERROR_NUMBER() = 50001 THROW;

        IF XACT_STATE() <> -1
            INSERT INTO SIS.Log_Erro (ROTINA, ETAPA, NUMERO_ERRO, MENSAGEM, LINHA, DT_ERRO)
            VALUES (@NomeProc, @EtapaAtual, ERROR_NUMBER(), ERROR_MESSAGE(), ERROR_LINE(), SYSDATETIME());

        THROW 50001, N'Não foi possível listar os fechamentos de caixa. O erro foi registrado para análise.', 1;
    END CATCH;
END;
GO
GO

