-- Arquivo: sql/objetos/SIS/Carga_SIS_Novidades.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : carga do aviso de versões (grupo de e-mail VERSAO_AVISO e
                ponto de partida do "O que há de novo")
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 23/11/2026
  Descrição   : (1) Grupo de e-mail VERSAO_AVISO, que recebe a nota da versão
                depois de cada atualização: nasce com o e-mail interno do
                sistema; a CMJ ajusta na tela Grupos de e-mail.
                (2) Usuários ativos sem registro em SIS.Usuario_Novidade
                nascem com a versão instalada ANTES deste MASTER (este arquivo
                roda antes de Carga_SIS_Versao.sql), para verem as novidades da
                versão que está sendo instalada. Na instalação do zero a versão
                ainda é vazia: o administrador vê as últimas versões.
                Idempotente: não mexe em quem já tem registro.
  Changelog:
    v1.0 (23/11/2026) - Criação (etapa 04c, P22).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

INSERT INTO SIS.Grupo_Email (CODIGO, NOME, DESCRICAO, USUARIO_CRIACAO)
SELECT 'VERSAO_AVISO', N'Nota da versão', N'Recebem a nota da versão (o que é novo e o que foi corrigido) depois de cada atualização do sistema.', N'instalacao'
WHERE NOT EXISTS (SELECT 1 FROM SIS.Grupo_Email g WHERE g.CODIGO = 'VERSAO_AVISO');

INSERT INTO SIS.Grupo_Email_Destinatario (ID_GRUPO_EMAIL, EMAIL, NOME, USUARIO_CRIACAO)
SELECT g.ID_GRUPO_EMAIL, N'construtora.m.judice@gmail.com', N'Administração do sistema', N'instalacao'
FROM SIS.Grupo_Email g
WHERE g.CODIGO = 'VERSAO_AVISO'
  AND NOT EXISTS (SELECT 1 FROM SIS.Grupo_Email_Destinatario d WHERE d.ID_GRUPO_EMAIL = g.ID_GRUPO_EMAIL);

INSERT INTO SIS.Usuario_Novidade (ID_USUARIO, VERSAO_VISTA)
SELECT u.ID_USUARIO, ISNULL(SIS.fn_SIS_Versao_Banco(), '')
FROM SIS.Usuario u
WHERE u.ATIVO = 1
  AND NOT EXISTS (SELECT 1 FROM SIS.Usuario_Novidade n WHERE n.ID_USUARIO = u.ID_USUARIO);
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/CAD/Carga_CAD_Parceiro_Tipo.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : carga de [CAD].[Parceiro_Tipo] e [CAD].[Pessoa_Tipo]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Tipos de fábrica (SISTEMA = 1): NA ("N/A", para classificar
                depois), CLIENTE, FORNECEDOR, FUNCIONARIO e CORRETOR. Nunca
                muda a descrição que a CMJ editou.
                Completa os tipos de cada parceiro a partir das marcas antigas
                de CAD.Pessoa (só o que falta) e põe N/A em quem ficou sem tipo
                ativo. Idempotente.
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04d, P12).
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

INSERT INTO CAD.Parceiro_Tipo (CODIGO, DESCRICAO, SISTEMA, ORDEM, USUARIO_CRIACAO)
SELECT v.CODIGO, v.DESCRICAO, 1, v.ORDEM, N'instalacao'
FROM (VALUES ('NA', N'N/A (a classificar)', 1),
             ('CLIENTE', N'Cliente', 10),
             ('FORNECEDOR', N'Fornecedor', 20),
             ('FUNCIONARIO', N'Funcionário', 30),
             ('CORRETOR', N'Corretor', 40)) v (CODIGO, DESCRICAO, ORDEM)
WHERE NOT EXISTS (SELECT 1 FROM CAD.Parceiro_Tipo t WHERE t.CODIGO = v.CODIGO);

UPDATE CAD.Parceiro_Tipo SET SISTEMA = 1, ATIVO = 1
WHERE CODIGO IN ('NA', 'CLIENTE', 'FORNECEDOR', 'FUNCIONARIO', 'CORRETOR') AND (SISTEMA = 0 OR ATIVO = 0);
GO

INSERT INTO CAD.Pessoa_Tipo (ID_PESSOA, ID_PARCEIRO_TIPO, USUARIO_CRIACAO)
SELECT p.ID_PESSOA, t.ID_PARCEIRO_TIPO, N'instalacao'
FROM CAD.Pessoa p
CROSS APPLY (VALUES ('CLIENTE', p.CLIENTE), ('FORNECEDOR', p.FORNECEDOR), ('FUNCIONARIO', p.FUNCIONARIO), ('CORRETOR', p.CORRETOR)) m (CODIGO, MARCA)
INNER JOIN CAD.Parceiro_Tipo t ON t.CODIGO = m.CODIGO
WHERE m.MARCA = 1
  AND NOT EXISTS (SELECT 1 FROM CAD.Pessoa_Tipo x WHERE x.ID_PESSOA = p.ID_PESSOA AND x.ID_PARCEIRO_TIPO = t.ID_PARCEIRO_TIPO);

INSERT INTO CAD.Pessoa_Tipo (ID_PESSOA, ID_PARCEIRO_TIPO, USUARIO_CRIACAO)
SELECT p.ID_PESSOA, t.ID_PARCEIRO_TIPO, N'instalacao'
FROM CAD.Pessoa p
INNER JOIN CAD.Parceiro_Tipo t ON t.CODIGO = 'NA'
WHERE NOT EXISTS (SELECT 1 FROM CAD.Pessoa_Tipo x WHERE x.ID_PESSOA = p.ID_PESSOA AND x.ATIVO = 1)
  AND NOT EXISTS (SELECT 1 FROM CAD.Pessoa_Tipo x WHERE x.ID_PESSOA = p.ID_PESSOA AND x.ID_PARCEIRO_TIPO = t.ID_PARCEIRO_TIPO);
GO
GO

-- -----------------------------------------------------------------------------
-- Arquivo: sql/objetos/FIN/Carga_FIN_Parametro.sql
-- -----------------------------------------------------------------------------
/*******************************************************************************
  Objeto      : carga dos parâmetros do financeiro em [SIS].[Parametro]
  Autor       : Celso de Freitas
  Refatorado  : Claude
  Criação     : 25/11/2026
  Descrição   : Trava de datas (aprovada em 18/11/2026) e proteções contra
                erro de digitação nos lançamentos (P17, aprovado em 25/11/2026).
                Regras FIN_REGRA_*: AVISO (pede confirmação, que fica
                registrada), BLOQUEIO (não deixa gravar) ou NAO (desligada).
                Só insere o que falta (regra 39): nunca sobrescreve o valor
                que a CMJ já alterou. NIVEL_MINIMO e OPCOES são da instalação
                e são acertados sempre. Os parâmetros de uso têm NIVEL_MINIMO
                1 (os dois administradores alteram em "Parâmetros de uso").
  Changelog:
    v1.0 (25/11/2026) - Criação (etapa 04f).
    v1.1 (25/11/2026) - Etapa 04f2a: parâmetros da lista (dias "a vencer",
                        situação e visão ao abrir, canceladas em "todas").
    v1.2 (26/11/2026) - Etapa 04f2c (P27): regras das pendências automáticas
                        FIN_PEND_* (todas só para lançamentos em aberto;
                        data de corte e valor do anexo alteráveis pela
                        administradora, pedido do Celso em 26/11/2026).
    v1.3 (26/11/2026) - Etapa 04g: baixa (juros, multa, carência, cálculo
                        no a pagar, limite de desconto) e fechamento de caixa
                        (tipos de conta, aviso na transferência entre
                        empresas). Aprovado pelo Celso em 26/11/2026.
    v1.4 (27/11/2026) - Etapa 04g2: BANCO_EXTRATO_MAX_DIAS (período máximo do
                        extrato) e FIN_CAIXA_FECHAMENTO_ATRASO_DIAS (dias sem
                        fechar o caixa até a conta aparecer como atrasada).
    v1.5 (27/11/2026) - Etapa 04g3: FIN_BAIXA_FORMA_PADRAO (forma de pagamento
                        que a janela de baixa já traz escolhida). Aprovado
                        pelo Celso em 27/11/2026.
*******************************************************************************/
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

DROP TABLE IF EXISTS #CargaParametro;

SELECT v.CHAVE, v.VALOR, v.TIPO, v.DESCRICAO, v.NIVEL, v.OPCOES
INTO #CargaParametro
FROM (VALUES
        (CAST('FIN_TRAVA_DATAS_ATIVA' AS VARCHAR(60)), CAST(N'S' AS NVARCHAR(4000)), CAST('SN' AS VARCHAR(10)),
         CAST(N'Liga a trava de datas dos lançamentos (datas muito antigas ou futuras são recusadas; quem tem a permissão "Lançar fora da trava de datas" grava informando o motivo).' AS NVARCHAR(400)),
         CAST(1 AS TINYINT), CAST(N'' AS NVARCHAR(200))),
        ('FIN_DIAS_TOLERANCIA_MES_ANTERIOR', N'5', 'INTEIRO',
